export function tacHeroClassChange() {
  const sel = tacById('tac-hero-class');
  const skillsEl = tacById('tac-hero-class-skills');
  const abilEl = tacById('tac-hero-faction-ability');
  tacHero.cls = sel.value;
  tacRenderHeroTile();
  if (sel.value === 'elf') {
    skillsEl.style.display = 'block';
    skillsEl.textContent = '✦ Заклятый враг: +5%/ур. шанс крита против не-эльфов';
  } else {
    skillsEl.style.display = 'none';
  }
  if (sel.value && FACTION_ABILITY_INFO[sel.value as keyof typeof FACTION_ABILITY_INFO]) {
    const info = FACTION_ABILITY_INFO[sel.value as keyof typeof FACTION_ABILITY_INFO];
    abilEl.innerHTML = `<span style="color:var(--gold)">${info.icon} ${info.text}</span>`;
  } else {
    abilEl.innerHTML = '';
  }
  // Набор колеса привязан к классу: сменили класс — строка о навыках должна
  // сразу сказать, подходит ли собранный билд.
  tacUpdateHeroPerksCount();
  // Фигура героя на поле и фишка в ленте — по новому классу.
  tacRenderHeroFigures();
  tacRenderInitiative();
}


/** Ключи артефактов, надетых в Примерочной. Сервер надевает их герою (build_hero →
 * Hero.equip), откуда берутся прибавки к атаке/защите/удаче/морали и процентная
 * защита от стрелков. Кукла в Примерочной одна, поэтому артефакты достаются только
 * герою ИГРОКА — врагу их взять неоткуда. */
export function tacHeroArtifactKeys(): string[] {
  const on = tacById('tac-hero-use-arts');
  if (on && !on.checked) return [];
  const keys = [];
  for (const slot in fittingEquipment) {
    const a = fittingEquipment[slot];
    if (a && a.key) keys.push(a.key);
  }
  return keys;
}

/** Навыки из колеса, которые уедут в бой (`Hero.perks` на сервере).
 *
 * Колесо собирается для КОНКРЕТНОГО класса, поэтому набор чужой фракции не
 * применяется: перки там свои, и «Надзор» рыцаря у некроманта — не билд, а
 * ошибка. Класс героя в бою задаётся отдельным списком, отсюда и сверка. */
export function tacHeroPerkKeys(): string[] {
  const on = tacById('tac-hero-use-perks');
  if (on && !on.checked) return [];
  const build = swGetBattleBuild();
  if (!build || !build.perks.length) return [];
  if (tacHero.cls && build.faction && build.faction !== tacHero.cls) return [];
  return build.perks.slice();
}

/** Прибавка от навыков колеса к удаче или морали.
 *
 * Те же ступени, что у сервера (battle/hero_perks.py, LEVELED): `luck1..3` →
 * +1..3, `leadership1..3` → +1..3. Нужна карточке отряда ВНЕ боя: в запрос
 * навыки уезжают отдельным списком (`perks`), и `luck_bonus` в данных героя
 * несёт только то, что вбито руками в панели. Пока бой идёт, значения берутся
 * из состояния сервера и этот расчёт не используется.
 */
export function tacHeroPerkBonus(kind: 'luck' | 'leadership'): number {
  let best = 0;
  for (const key of tacHeroPerkKeys()) {
    const m = new RegExp('^' + kind + '([123])$').exec(key);
    if (m) best = Math.max(best, Number(m[1]));
  }
  return best;
}

/** Строка о наборе рядом с флажком: сколько навыков уедет и почему не уедут. */
export function tacUpdateHeroPerksCount() {
  const el = tacById('tac-hero-perks-count');
  const note = tacById('tac-hero-perks-note');
  if (!el) return;
  const build = swGetBattleBuild();
  const on = tacById('tac-hero-use-perks');
  const n = tacHeroPerkKeys().length;
  el.textContent = n ? `— ${n} шт.` : '— пусто';
  if (!note) return;
  if (!build || !build.perks.length) {
    note.textContent = 'Наберите билд во вкладке «Колёса навыков».';
  } else if (on && !on.checked) {
    note.textContent = '';
  } else if (tacHero.cls && build.faction && build.faction !== tacHero.cls) {
    const built = FACTIONS_META[build.faction]?.nameRu || build.faction;
    const now = FACTIONS_META[tacHero.cls]?.nameRu || tacHero.cls;
    note.textContent = `Набор собран для класса «${built}», а герой — «${now}»: навыки не применяются.`;
  } else {
    note.textContent = '';
  }
}

/**
 * Отчёт сервера по набору навыков (`perks` в ответе /api/simulate).
 *
 * Показывает ровно то, что движок с набором сделал: применил, пропустил как
 * внебоевой навык или пока не умеет. Ничего не показывать нельзя — иначе
 * выученный перк, которого движок не считает, выглядит сломанным.
 */
export function tacShowPerkReport(report: any) {
  const note = tacById('tac-hero-perks-note');
  if (!note) return;
  if (!report) { tacUpdateHeroPerksCount(); return; }
  const name = (k: string) => HERO_SKILL_DESCS[k]?.name || k;
  const parts: string[] = [];
  if (report.applied?.length) parts.push(`применено ${report.applied.length}`);
  if (report.hero_attack?.length) {
    parts.push(`прямая атака героя: ${report.hero_attack.map(name).join(', ')}`);
  }
  if (report.atb?.length) {
    parts.push(`шкала ATB героя: ${report.atb.map(name).join(', ')}`);
  }
  if (report.out_of_battle?.length) {
    parts.push(`вне боя: ${report.out_of_battle.map(name).join(', ')}`);
  }
  if (report.unsupported?.length) {
    parts.push(`движок пока не считает: ${report.unsupported.map(name).join(', ')}`);
  }
  if (report.unknown?.length) parts.push(`неизвестно серверу: ${report.unknown.join(', ')}`);
  note.textContent = parts.join('; ');
}

/** Показать в панели героя, сколько артефактов реально уедет в бой. Без этого связь с
 * Примерочной была бы невидимой: игрок туда мог не заходить, и бой молча шёл бы без
 * снаряжения. */
export function tacUpdateHeroArtsCount() {
  const el = tacById('tac-hero-arts-count');
  if (!el) return;
  const n = tacHeroArtifactKeys().length;
  el.textContent = n ? `— ${n} шт.` : '— пусто';
}

export function tacGetHeroData(): HeroData | null {
  tacHero.atk = parseInt(tacById('tac-hero-atk').value) || 0;
  tacHero.def = parseInt(tacById('tac-hero-def').value) || 0;
  tacHero.ini = parseInt(tacById('tac-hero-ini').value) || 0;
  tacHero.luck = parseInt(tacById('tac-hero-luck').value) || 0;
  tacHero.morale = parseInt(tacById('tac-hero-morale').value) || 0;
  const sp = parseInt(tacById('tac-hero-sp').value) || 0;
  const mana = parseInt(tacById('tac-hero-mana').value) || 0;
  const flvl = parseInt(tacById('tac-hero-flvl').value) || 1;
  if (!tacHero.cls) return null;
  const spells = Object.keys(allData.magics! || {});
  return {
    name: FACTIONS_META[tacHero.cls]?.nameRu || '',
    faction: tacHero.cls,
    attack_bonus: tacHero.atk,
    defense_bonus: tacHero.def,
    initiative_bonus_pct: tacHero.ini,
    luck_bonus: tacHero.luck,
    morale_bonus: tacHero.morale,
    spell_power: sp,
    mana_max: mana,
    spells: spells,
    faction_lvl: flvl,
    // «Тёмная сила» и «Сияние Луны и Солнца» отдельными галочками не задаются:
    // это перки колеса навыков (battle/hero_perks.py, FLAGS), и приходят они
    // вместе с `perks`. Альтернативный класс редактор тоже не выставляет —
    // сервер без поля берёт основной (battle/service.py).
    // «Вся магия»: снимает серверный запрет NOT_HERO_SPELLS (Армагеддон и т.п.).
    allow_all_magic: !!tacById<HTMLInputElement>('tac-hero-all-magic')?.checked,
    favoured_enemy_crit_chance: tacHero.cls === 'elf' ? 5 + 5 * flvl : 0,
    artifacts: tacHeroArtifactKeys(),
    // Навыки из колеса: сервер разбирает их в battle/hero_perks.py.
    perks: tacHeroPerkKeys(),
  };
}

