import { loadData } from './data.js';
import { toggleTheme, updateThemeBtn, initTheme } from './theme.js';
import { navigateTo, toggleMenu, init } from './navigation.js';
import * as Creatures from './creatures.js';
import * as Abilities from './abilities.js';
import * as Stubs from './stubs.js';
import * as Battle from './battle.js';
import * as BattleTestPanel from './battleTestPanel.js';
import * as BattleMagic from './battleMagic.js';
import * as BattleCode from './battleCode.js';
import * as BattleHotseat from './battleHotseatCycle.js';
import * as BattleSpellBook from './battleSpellBook.js';
import * as BattleRunes from './battleRunes.js';
import * as BattlePalette from './battlePalette.js';
import * as BattleFieldSprites from './battleFieldSprites.js';
import * as BattleStep from './battleStep.js';
import * as BattleHero from './battleHero.js';
import * as BattleGrid from './battleGrid.js';
import * as Replay from './replay.js';
import * as Fitting from './fitting.js';
import * as Skillwheels from './skillwheels.js';
import { initTooltips } from './tooltip.js';
import { initStaticNotice } from './staticNotice.js';

// ===== Assign all needed symbols to window (for inline HTML event handlers) =====

// Theme
(window as any).toggleTheme = toggleTheme;
(window as any).updateThemeBtn = updateThemeBtn;

// Navigation
(window as any).navigateTo = navigateTo;
(window as any).toggleMenu = toggleMenu;
(window as any).init = init;

/** Expose a module's exports as LIVE window globals (for index.html inline handlers).
 * Object.assign(window, Module) copied `export let` VALUES once at startup — battle.ts
 * reassigns several of them later (tacData = [] in tacClearAll/tacDecode, ...),
 * so the window copies silently went stale (window.tacData showed an
 * empty board while stacks stood on the field). ES module namespace objects have live
 * bindings, so a getter that reads through the namespace is always current.
 *
 * READ-ONLY by design: module namespaces reject property writes, so no setter is
 * possible — `window.tacData = x` now throws in strict/module code (it silently
 * no-opped under Object.assign's stale copies, which was worse). Nothing assigns
 * to these globals today (battle.ts only writes _movLines and the battle-log
 * which aren't exports); mutate state via the exported functions instead. */
function exposeLive(ns: object): void {
  for (const key of Object.keys(ns)) {
    Object.defineProperty(window, key, {
      get: () => (ns as Record<string, unknown>)[key],
      configurable: true,
    });
  }
}

// Creatures
exposeLive(Creatures);

// Abilities
(window as any).buildAbilityCreatureMap = Abilities.buildAbilityCreatureMap;
(window as any).renderAbilities = Abilities.renderAbilities;
(window as any).filterAbilities = Abilities.filterAbilities;
(window as any).initAbilities = Abilities.initAbilities;
(window as any).renderAbilityDetail = Abilities.renderAbilityDetail;
(window as any).closeAbilityDetail = Abilities.closeAbilityDetail;

// Заглушки
exposeLive(Stubs);

// Battle
exposeLive(Battle);
// Панель проверки способностей вынесена из battle.ts, но её кнопки в index.html
// по-прежнему вызываются как глобальные — выставляем тем же способом.
exposeLive(BattleTestPanel);
exposeLive(BattleMagic);
exposeLive(BattleCode);
exposeLive(BattleHotseat);
// Книга магии героя в бою: её кнопки в index.html — те же инлайновые обработчики.
exposeLive(BattleSpellBook);
// Свиток рун гнома — тот же способ: кнопки в index.html инлайновые.
exposeLive(BattleRunes);
exposeLive(BattlePalette);
exposeLive(BattleFieldSprites);
exposeLive(BattleStep);
exposeLive(BattleHero);
exposeLive(BattleGrid);

// Replay
exposeLive(Replay);

// Fitting
exposeLive(Fitting);

// Skillwheels
(window as any).swGetWheelsForFaction = Skillwheels.swGetWheelsForFaction;
(window as any).swInit = Skillwheels.swInit;
(window as any).swOnFactionChange = Skillwheels.swOnFactionChange;
(window as any).swRenderWheel = Skillwheels.swRenderWheel;
(window as any).swShowSkill = Skillwheels.swShowSkill;
(window as any).swToggleSkill = Skillwheels.swToggleSkill;
(window as any).swResetBuild = Skillwheels.swResetBuild;

// Флаг «бандл выполнился» для спасательного круга в sw-register.js: без него
// отравленный кэш (HTML вместо .js) оставлял живую оболочку без приложения, и
// обычная перезагрузка ничего не меняла.
(window as any).__appBooted = true;

// Предупреждение о разделах, которых нет на опубликованной статике.
initStaticNotice();

// Init tooltips
initTooltips();

// Init theme
initTheme();

// Start app. The 544-creature animation preload is NOT started here anymore — it only
// serves the battle palette and the creature-card modal, so navigation.ts kicks it off
// on the first activation of a tab that actually needs it (battle/creatures/factions),
// instead of downloading ~1100 asset files on every visit to any route.
loadData();
