export function tacById<K extends keyof TacDom & string>(id: K): TacDom[K];
export function tacById<T extends HTMLElement = HTMLElement>(id: string): T | null;
export function tacById(id: string): HTMLElement | null {
  return document.getElementById(id);
}

/** Первый элемент по селектору — то же соглашение, что и у tacById. */
export function tacQuery<T extends HTMLElement = HTMLElement>(sel: string): T | null {
  return document.querySelector(sel);
}

// Animated engine sprites currently mounted on standing (non-moving) grid cells, keyed by
// "row_col". Separate from creatureAnim's own movement-transient handles — these persist for
// as long as the stack stays put, giving the field its "living creatures" look instead of a
// flat portrait, matching the real client rather than just the walk-cycle during moves.
export const tacFieldSprites = new Map();

/** Mount (or replace) an idle animated sprite on top of a placed stack's cell. Falls back to
 * doing nothing if the engine/animUnit isn't available — the existing portrait backgroundImage
 * on the <td> stays visible underneath in that case.
 *
 * This runs during battle replay too (tacPutUnit at a move's destination, at battle start,
 * after deaths) — stacks stay animated on the field for the whole fight instead of flipping
 * back to flat portraits between actions. That used to be disabled (`if (tacPlaybackRunning())
 * return`) because mounting hung for seconds — but the hang was the asset pipeline (cold loads
 * starved behind a preload flood + a retry-URL bug that broke atlases permanently, see
 * CHANGES.md 32–33), not the mount itself: with warm engine caches a mount is a couple of ms.
 * tacApplyStackState updates counts in place, so stationary stacks are never remounted. */
// One-shot handoff slot: tacWalkStack parks the mover's live sprite handle here right before
// re-placing the stack, and the tacPutUnit → tacMountFieldSprite call it triggers ADOPTS that
// handle instead of building a new engine object. This is what keeps a creature animated
// continuously through stand → walk → stand: recreating the sprite at the destination (a new
// Konva stage + engine init) took long enough to flash the portrait fallback on every single
// move — the "переключение с анимации на портреты".
/** Рукоять живого спрайта движка (см. creatureAnim) — усыновляется на новой клетке.
 *  Внутренности спрайта движок держит в закрытом виде; наружу (проверки и демонтаж
 *  при неудавшемся усыновлении) смотрят только перечисленные здесь поля/методы. */
export interface SpriteHandoff {
  handle: { failed?: boolean; scene?: unknown; destroy?: () => void } & Record<string, unknown>;
  pic: string;
}
let tacSpriteHandoff: SpriteHandoff | null = null;

/** Pull a mounted sprite off its cell WITHOUT destroying it (the caller takes ownership —
 * e.g. tacWalkStack re-parents it into the sliding mover box). */
export function tacToggleMute() {
  sndToggleMute();
  tacUpdateMuteBtn();
}

export function tacUpdateMuteBtn() {
  // Звук управляется галкой «Звуки в бою» в настройках боя (кнопка ⚙ в нижнем левом углу)
  const cb = tacById('tac-sound-checkbox');
  if (cb) cb.checked = !sndIsMuted();
  const btn = tacById('tac-mute-btn');
  if (btn) btn.textContent = sndIsMuted() ? '🔇' : '🔊';
}

/** Грунты арены: текстура из оригинального клиента + набор звуков шагов под неё.
 *
 * `key` — имя полотна на CDN (`lands/land_<key><N>.jpg`, вариантов минимум 12 у
 * каждого). `step` — грунт для звуков шагов: их наборов всего семь
 * (step/<материал>_<грунт>-<NN>.mp3), поэтому лёд звучит как снег, лава и пещера —
 * как камень, пепел — как земля. */
// Грунты и число полотен у каждого. Оригинал в сентябре 2026 переделал
// ландшафты: у прежних десяти стало по 20 вариантов вместо 12, и добавились
// четыре новых («Замок», «Мох», «Пляж», «Осень»). Числа получены прозвоном CDN,
// и они РАЗНЫЕ — у пляжа 17; общая граница в 20 давала бы 404 и поле без
// текстуры, поэтому счётчик хранится у каждого грунта свой.
// `line`/`alpha` — цвет и прозрачность линий сетки: `f_lcolor`/`f_lalpha` из
// `statix['land_*']` (anim_data30/land_*.js), их читает `init_land_const` оригинала.
// Они РАЗНЫЕ: на тёмных грунтах (лава, пепел, замок, лёд) линии светлые, на траве —
// тёмно-зелёные; одна чёрная сетка на всех тонула в лаве. Умолчание оригинала —
// чёрный, 50 (пляж альфы не задаёт).
const TAC_LANDS = [
  { key: 'grass',  label: 'Трава',   step: 'grass',  n: 20, line: '#002200', alpha: 60 },
  { key: 'dirt',   label: 'Земля',   step: 'dirt',   n: 20, line: '#151515', alpha: 50 },
  { key: 'snow',   label: 'Снег',    step: 'snow',   n: 20, line: '#333399', alpha: 60 },
  { key: 'swamp',  label: 'Болото',  step: 'swamp',  n: 20, line: '#000000', alpha: 40 },
  { key: 'desert', label: 'Пустыня', step: 'sand',   n: 20, line: '#3C2622', alpha: 60 },
  { key: 'road',   label: 'Дорога',  step: 'gravel', n: 20, line: '#002200', alpha: 70 },
  { key: 'cave',   label: 'Пещера',  step: 'stone',  n: 20, line: '#56AAFF', alpha: 50 },
  { key: 'ice',    label: 'Лёд',     step: 'snow',   n: 20, line: '#FFFFFF', alpha: 70 },
  { key: 'lava',   label: 'Лава',    step: 'stone',  n: 20, line: '#A2A2A2', alpha: 50 },
  { key: 'ash',    label: 'Пепел',   step: 'dirt',   n: 20, line: '#A2A2A2', alpha: 50 },
  { key: 'castle', label: 'Замок',   step: 'stone',  n: 20, line: '#BBBBBB', alpha: 70 },
  { key: 'moss',   label: 'Мох',     step: 'grass',  n: 20, line: '#99FF99', alpha: 50 },
  { key: 'beach',  label: 'Пляж',    step: 'sand',   n: 17, line: '#574C2C', alpha: 50 },
  { key: 'autumn', label: 'Осень',   step: 'dirt',   n: 20, line: '#220000', alpha: 50 },
];

/** Цвет линий сетки грунта в виде `rgba(...)` — как `f_lcolor` + `f_lalpha/100` оригинала. */
export function tacLandGridLine(key: string): string {
  const land = TAC_LANDS.find(l => l.key === key) || TAC_LANDS[0];
  const n = parseInt(land.line.slice(1), 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${land.alpha / 100})`;
}

const TAC_LAND_KEY = 'tacLand';   // '' — случайный грунт на каждый бой

/** Постелить грунт: текстура поля + звуки шагов под неё. */
export function tacApplyLand(key: string, variant?: number) {
  const land = TAC_LANDS.find(l => l.key === key) || TAC_LANDS[0];
  const n = variant || (1 + Math.floor(Math.random() * land.n));
  const url = `url('/api/cache/i/png30/lands/land_${land.key}${n}.jpg')`;
  // Полотно стелется ПОД доску — в арене под всё окно, в редакторе под обёртку
  // поля (оба читают переменную). Сама доска прозрачна: своя, скошенная
  // перспективой копия текстуры внутри рамки давала шов по краю против плоского
  // грунта вокруг — доска выглядела картинкой в раме, а не куском земли.
  document.body.style.setProperty('--tac-land', url);
  document.body.style.setProperty('--tac-grid-line', tacLandGridLine(land.key));
  // Растительность вокруг доски — отдельными спрайтами поверх грунта, как в
  // оригинале: в самом полотне её нет (см. battleDecor.ts).
  void tacRollDecor(land.key);
  sndSetTerrain(land.step);
  return land.key;
}

/** Грунт на новый бой: либо закреплённый в настройках, либо случайный. */
export function tacRollLand() {
  let pinned = '';
  try { pinned = localStorage.getItem(TAC_LAND_KEY) || ''; } catch { /* ignore */ }
  const key = pinned || TAC_LANDS[Math.floor(Math.random() * TAC_LANDS.length)].key;
  return tacApplyLand(key);
}

/** Селектор грунта: «Случайно» (по умолчанию — новый грунт на каждый бой) либо
 * закреплённый. Оригинал берёт грунт из карты боя; у нас карты нет, поэтому выбор
 * либо за случаем, либо за игроком. */
export function tacInitTerrainSelect(rollLand = true) {
  const sel = tacById('tac-terrain-select');
  if (!sel) return;
  let pinned = '';
  try { pinned = localStorage.getItem(TAC_LAND_KEY) || ''; } catch { /* ignore */ }
  sel.innerHTML = '<option value="">🎲 Случайно</option>'
    + TAC_LANDS.map(l => `<option value="${l.key}">${l.label}</option>`).join('');
  sel.value = pinned;
  // Грунт стелется СРАЗУ, не с началом боя: расстановка должна выглядеть так же,
  // как бой, — кнопки боя его только начинают. Без этого вокруг доски в
  // редакторе оставался фон страницы, а под ней — фиксированная трава из CSS.
  // Перестройка той же доски (rollLand=false) грунт трогать не должна: повторный
  // tacRollLand() перевыбирал бы и тип грунта (при «Случайно»), и вариант
  // картинки даже при закреплённом типе (см. tacApplyLand — случайные номера
  // текстур), и фон менялся бы от переключения галочек.
  if (rollLand) tacRollLand();
  sel.onchange = () => {
    try { localStorage.setItem(TAC_LAND_KEY, sel.value); } catch { /* ignore */ }
    // Показываем выбор сразу, не дожидаясь боя.
    tacApplyLand(sel.value || TAC_LANDS[Math.floor(Math.random() * TAC_LANDS.length)].key);
  };
}

