export let tacCfg: TacConfig = { field_type: 1, row: 10, col: 12 };
/** Индекс существа, которое тащат ИЗ ПАЛИТРЫ (не с доски). Нужен для предпросмотра
 * следа 2x2 под курсором: dataTransfer во время dragenter/dragover читать нельзя —
 * браузер отдаёт данные только на drop, — поэтому запоминаем на dragstart. */

/** Помещается ли существо размера big с якорем в (row, col): в пределах поля и все
 * клетки следа свободны. `ignore` — клетка-якорь отряда, который сам же и переезжает
 * (его старые клетки освободятся). Одно правило на предпросмотр, drop и клик — раньше
 * каждый проверял по-своему, и подсветка могла обещать посадку, которой не будет. */
export function tacFootprintFits(row: any, col: any, big: any, ignore?: any) {
  const span = big ? 2 : 1;
  if (row + span - 1 > tacCfg.row || col + span - 1 > tacCfg.col) return false;
  const ignored = new Set<string>();
  if (ignore) {
    const src = battleBoard.data[ignore.row]?.[ignore.col];
    const srcBig = src && src.id !== undefined && TACTIC_UNITS[src.id]?.big;
    const s = srcBig ? 2 : 1;
    for (let dr = 0; dr < s; dr++) for (let dc = 0; dc < s; dc++) ignored.add((ignore.row + dr) + ',' + (ignore.col + dc));
  }
  for (let dr = 0; dr < span; dr++) {
    for (let dc = 0; dc < span; dc++) {
      if (ignored.has((row + dr) + ',' + (col + dc))) continue;
      if (battleBoard.data[row + dr]?.[col + dc]) return false; // и стек, и маркер хвоста 2x2
    }
  }
  return true;
}
/** Выбранный в редакторе отряд — клетка, а не индекс: аннотация `number` была
 *  ошибочной, присваивают сюда `{ row, col }`. */
/** Множитель скорости реплея. Кнопки у него больше нет — бой играет в темпе
 * оригинала (x1); значение осталось единой точкой, через которую делят задержки
 * все анимации (battleAnim, hotseat), а не россыпью магических чисел. */
export const tacAnimSpeed: number = 1;

export function getCell(r: number, c: number) { return tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`); }

/** Классы бейджа с числом отряда: цвет команды + с какой стороны от существа стоять.
 *
 * Оригинал (references/legacy-client/show_polep.js, draw_number) ставит число НЕ под существом, а сбоку:
 * бокс числа начинается от якоря существа (низ-центр футпринта) и уходит по направлению
 * взгляда — `tx = 0` при взгляде вправо, `tx = -ширина_текста` при взгляде влево, плюс
 * `kletka_width * view * 0.4` наружу у 2x2. Направление взгляда у нас задаёт команда
 * (нечётные — слева, смотрят вправо), той же формулой, что и `mirror` в
 * tacMountFieldSprite, — число и разворот существа обязаны совпадать. */
export function tacToggleFullField(on?: boolean) {
  const want = on === undefined ? !document.body.classList.contains('tac-full-field') : !!on;
  document.body.classList.toggle('tac-full-field', want);
  const btn = tacById('tac-fs-btn');
  if (btn) {
    btn.textContent = want ? '⤢' : '⛶';
    btn.title = want
      ? 'Выйти из полноэкранного режима (F или Esc)'
      : 'Во весь экран — арена как в оригинале (F)';
  }
  // Сцена логическая и в арене, и в редакторе — меняется только масштаб k и
  // место окна; доска, якоря и спрайты остаются как были.
  tacFitArenaScale();
}

// ── Столбик боевых кнопок у левого верхнего угла поля ──
// В оригинале ВСЕ круглые кнопки боя стоят одним столбиком слева сверху. У нас
// они были разбросаны: «В бой» и «Автобой» — в ряду под палитрой, кнопки хода —
// в панели под доской у правого края. Теперь все живут в одном столбике
// (#tac-arena-controls), а он сам меняет привязку: в редакторе абсолютный по
// контейнеру поля, в арене фиксированный по окну. Перенос УЗЛОВ, а не клоны:
// id должны остаться уникальными, а inline-обработчики — живыми.
// `tac-hs-spells` — список умений/заклинаний, который РАСКРЫВАЕТ кнопка книги.
// Он обязан ехать в столбик вместе с ней: кнопки уехали в левый верхний угол
// ПОЛЯ, а список остался в панели хода под лентой очереди — нажатие открывало
// панель за тысячу пикселей от нажатой кнопки, и «Стрельбу навесом» просто не
// находили глазами («выбрал навес» = нажал круглую кнопку, а сам пункт списка
// так и остался ненажатым).
const TAC_DOCK_IDS = ['tac-simulate-btn', 'tac-auto-btn', 'tac-hs-actions', 'tac-hs-spells'];

/** Собрать столбик. Идемпотентна: зовётся один раз на старте, но повторный
 *  вызов ничего не ломает — `appendChild` просто переставит те же узлы. */
export function tacDockBattleButtons(): void {
  const dock = tacById('tac-arena-controls');
  if (!dock) return;
  for (const id of TAC_DOCK_IDS) {
    const el = tacById(id);
    if (el && el.parentElement !== dock) dock.appendChild(el);
  }
  dock.style.display = 'flex';
}

/** Кнопки хода — в столбик у левого верхнего угла поля, на всё время боя.
 *
 * Столбик один и тот же в обоих видах (в редакторе он абсолютный по контейнеру
 * поля, в арене — фиксированный по окну), поэтому переносить их при входе в
 * арену и обратно больше не нужно: узел просто живёт в столбике, пока идёт бой.
 * Вне боя столбик прячется — иначе «Оборона» и «Прервать» торчали бы над
 * пустой расстановкой. */
export function tacDockTurnButtons(on: boolean): void {
  const row = tacById('tac-hs-actions');
  // Прячем/показываем ОТДЕЛЬНЫЕ узлы столбика, а не столбик целиком: до боя
  // нужен старт, в бою — кнопки хода. «Автобой» нужен всегда и остаётся.
  if (row) row.style.display = on ? 'flex' : 'none';
  // «В бой» в бою не нужен: бой уже идёт, а кнопка стоит вплотную к «Прервать».
  const start = tacById('tac-simulate-btn');
  if (start) start.style.display = on ? 'none' : '';
}

// ── Полный экран на время боя больше НЕ включается сам ──
// Он был нужен, пока расстановка и бой были разными видами: поле в редакторе
// считалось своим способом и выходило вдвое мельче. Теперь оба идут через одни
// формулы оригинала и отличаются только размером сцены, так что разворачивать
// окно на старте боя незачем — бой начинается там же, где игрок его собирал.
// Полный экран остаётся ручным: клавиша F и кнопка ⛶.
export function tacEnterBattleArena() { /* см. комментарий выше */ }
export function tacLeaveBattleArena() { /* см. комментарий выше */ }

export function tacToggleSettings() {
  const panel = tacById('tac-settings-panel');
  if (!panel) return;
  const hidden = panel.style.display === 'none';
  panel.style.display = hidden ? '' : 'none';
}

// ── Настройки боя (кнопка ⚙ в нижнем левом углу) ──
// Окно оригинала (`btn_settings` → «НАСТРОЙКИ»): ряд переключателей и два ползунка
// громкости. Здесь только те пункты, которые у нас действительно на что-то влияют;
// «узкое поле», «классический интерфейс» и «аппаратное ускорение» оригинала своего
// смысла в этом клиенте не имеют, и фальшивая галка была бы хуже её отсутствия.
//
// Обе галки-«показывать» гасят своё через класс на <body>, а не правкой стилей узлов:
// журнал и всплывающие цифры показываются из десятка мест по ходу боя, и каждое из
// них пришлось бы учить настройке. CSS с !important перебивает их все разом.
const TAC_SHOW_LOG_KEY = 'tacShowLog';
const TAC_SHOW_DMG_KEY = 'tacShowDamage';
// Размер фишек ленты инициативы. По умолчанию крупные — во всю высоту полосы,
// как ATB-шкала оригинала; мелкие держат в ленте вдвое больше ходов, и на узком
// экране очередь видна целиком без прокрутки.
const TAC_INIT_BIG_KEY = 'tacInitBig';
// Полоска здоровья верхнего существа под отрядом. В оригинале её нет вовсе:
// остаток здоровья смотрят в карточке отряда — поэтому по умолчанию выключена,
// включает тот, кому она нужна.
const TAC_SHOW_HP_KEY = 'tacShowHp';
// Препятствия на поле. В оригинале пустых полей не бывает: камни и ёлки стоят
// отдельными «отрядами» (в данных игры это юниты rock1 uID 13 «Препятствие»,
// rock2x2 «Булыжник», rockelka «Ёлка»), и обойти их — часть тактики.
const TAC_OBSTACLES_KEY = 'tacObstacles';
// Вращающееся кольцо под ходящим отрядом (`show_ring` оригинала). В оригинале
// его не выключить, но там доска и крупнее, и чище: у нас кольцо на мелкой
// клетке заметно перекрывает соседей — по умолчанию выключено.
const TAC_SHOW_RING_KEY = 'tacShowRing';
// Вероятности удачи/морали под отрядом (как battleHelper luckMoraleProbability).
const TAC_SHOW_BH_PROBS_KEY = 'tacShowBhProbs';
// Тултип эффектов под курсором при наведении на отряд: тот же список, что в
// развороте «Эффекты» карточки (tacEffectLines), только у мыши. Расписан
// отдельно от battleHelper: раньше оба жили под одной галкой, и игроку, которому
// нужны были одни проценты, эффекты висеть у курсора мешали, и наоборот.
const TAC_SHOW_EFFECTS_TIP_KEY = 'tacShowEffectsTip';
// Картинки курсоров оригинала (меч, лук, порванная тетива, «не дотянуться»).
// В оригинале они включены и выключить их нельзя, но там доска крупная и игрок
// сразу знает, что к чему: у нас курсоры показывались всем без спроса, и часть
// игроков читала их как глюк. Поэтому по умолчанию выключено — включается той
// же галочкой, что и остальные настройки боя (логика в battleCursor.ts).
const TAC_CURSORS_KEY = 'tacBattleCursors';

function tacReadFlag(key: string, dflt: boolean): boolean {
  try {
    const v = localStorage.getItem(key);
    return v === null ? dflt : v === '1';
  } catch { return dflt; }
}

export let tacShowLog = tacReadFlag(TAC_SHOW_LOG_KEY, true);
export let tacShowDamage = tacReadFlag(TAC_SHOW_DMG_KEY, false);
export let tacInitBig = tacReadFlag(TAC_INIT_BIG_KEY, true);
export let tacShowHpBars = tacReadFlag(TAC_SHOW_HP_KEY, false);
export let tacObstacles = tacReadFlag(TAC_OBSTACLES_KEY, true);
export let tacShowRing = tacReadFlag(TAC_SHOW_RING_KEY, false);
export let tacShowBhProbs = tacReadFlag(TAC_SHOW_BH_PROBS_KEY, false);
export let tacShowEffectsTip = tacReadFlag(TAC_SHOW_EFFECTS_TIP_KEY, false);
export let tacBattleCursors = tacReadFlag(TAC_CURSORS_KEY, false);

function tacApplyBattleSettings() {
  document.body.classList.toggle('tac-no-log', !tacShowLog);
  document.body.classList.toggle('tac-no-dmg', !tacShowDamage);
  document.body.classList.toggle('tac-init-small', !tacInitBig);
  document.body.classList.toggle('tac-no-hp', !tacShowHpBars);
  document.body.classList.toggle('tac-no-ring', !tacShowRing);
  document.body.classList.toggle('tac-show-bh-probs', tacShowBhProbs);
  setCursorsEnabled(tacBattleCursors);
}
// Класс нужен с первого кадра, а не с первого захода в настройки: лента
// строится раньше, чем игрок откроет окно.
tacApplyBattleSettings();

/** Раскрыть/свернуть журнал боя.
 *
 * В арене журнал — узкая полоса на верхнем поле, в ней видны последние строки.
 * В оригинале эту полосу можно раскрыть в свиток во весь экран и пролистать
 * весь бой (`.log_short_container` там с `cursor: pointer`, а закрывается
 * кнопкой «Закрыть лог»). Строки для этого никуда не переносятся: свёрнутый и
 * раскрытый вид — один и тот же узел с разной геометрией, поэтому раскрытие
 * ничего не перерисовывает и не теряет прокрутку.
 *
 * Раскрывается в ЛЮБОМ размере поля, а не только в арене: свиток и в обычном
 * бою нарисован тем же двухстрочным огрызком с курсором-пальцем и подписью
 * «клик раскрывает его целиком», и пока раскрытие было завязано на арену, клик
 * по нему просто ничего не делал — прочитать бой было негде. Условие — идёт
 * бой (`tac-on-battle`): в редакторе журнала-огрызка нет вовсе. */
export function tacToggleLogOpen(force?: boolean) {
  if (!document.body.classList.contains('tac-on-battle')) return;
  const log = tacById('tac-result');
  if (!log) return;
  const open = force !== undefined ? force : !document.body.classList.contains('tac-log-open');
  if (open === document.body.classList.contains('tac-log-open')) return;
  document.body.classList.toggle('tac-log-open', open);
  const btn = tacById('tac-log-close');
  if (btn) btn.style.display = open ? '' : 'none';
  // Открываем на последних строках: интересен конец боя, а не его начало.
  if (open) log.scrollTop = log.scrollHeight;
}

