/** Открыть/закрыть окно настроек боя. Перед показом сверяем все поля с настоящим
 * состоянием: полноэкранный режим включают ещё и кнопкой ⛶, и клавишей Esc, а
 * звук — кнопкой заглушки, и окно не должно врать о том, что сейчас включено. */
export function tacToggleBattleSettings(force?: boolean) {
  const win = tacById('tac-battle-settings');
  if (!win) return;
  const show = force !== undefined ? force : win.style.display === 'none';
  if (show) tacSyncBattleSettings();
  win.style.display = show ? '' : 'none';
  const btn = tacById('tac-battle-settings-btn');
  if (btn) btn.setAttribute('aria-expanded', String(show));
}

/** Привести поля окна к текущему состоянию. */
export function tacSyncBattleSettings() {
  const set = (id: string, on: boolean) => {
    const box = document.getElementById(id) as HTMLInputElement | null;
    if (box) box.checked = on;
  };
  set('tac-numbers-top', tacNumbersOnTop);
  set('tac-full-field-box', document.body.classList.contains('tac-full-field'));
  set('tac-show-log', tacShowLog);
  set('tac-init-big', tacInitBig);
  set('tac-show-hp', tacShowHpBars);
  set('tac-obstacles', tacObstacles);
  set('tac-show-ring', tacShowRing);
  set('tac-show-damage', tacShowDamage);
  set('tac-show-bh-probs', tacShowBhProbs);
  set('tac-show-effects-tip', tacShowEffectsTip);
  set('tac-battle-cursors', tacBattleCursors);
  set('tac-sound-checkbox', !sndIsMuted());
  const sfx = document.getElementById('tac-sfx-volume') as HTMLInputElement | null;
  if (sfx) sfx.value = String(Math.round(sndGetSfxVolume() * 100));
  const music = document.getElementById('tac-music-volume') as HTMLInputElement | null;
  if (music) music.value = String(Math.round(sndGetMusicVolume() * 100));
}

// ── Числа поверх объектов ──
// Оригинал держит число отряда в ДВУХ режимах (references/legacy-client/show_polep.js, switch_numbers):
// put_number_outside — число уезжает в общий слой поля и рисуется поверх всех объектов;
// put_number_inside — возвращается в слой самого существа и прячется за спрайтами.
// У нас спрайты живут на едином канвасе (.tac-scene, z-index 5), который лежит поверх
// ВСЕЙ таблицы поля: у таблицы свой контекст наложения из-за transform, поэтому число
// внутри клетки никаким z-index канвас не перебьёт. Значит «поверх» — это отдельный
// слой #tac-numbers над сценой, ровно как в оригинале.
const TAC_NUMBERS_TOP_KEY = 'tacNumbersOnTop';
export let tacNumbersOnTop = true;
try {
  tacNumbersOnTop = localStorage.getItem(TAC_NUMBERS_TOP_KEY) !== '0';
} catch { /* приватный режим — остаёмся на умолчании */ }

export function tacToggleNumbersTop() {
  const box = tacById('tac-numbers-top') as HTMLInputElement | null;
  tacNumbersOnTop = box ? box.checked : !tacNumbersOnTop;
  try { localStorage.setItem(TAC_NUMBERS_TOP_KEY, tacNumbersOnTop ? '1' : '0'); } catch { /* ignore */ }
  tacSyncNumbers();
}

/** Перерисовать слой чисел над сценой (или убрать его, если настройка выключена).
 * Дёшево: узлов ровно столько, сколько отрядов на поле. */
export function tacSyncNumbers() {
  const wrap = tacById('tac-field-wrap');
  const field = tacById('tac-field');
  let layer = tacById('tac-numbers');
  if (!tacNumbersOnTop || !wrap || !field) {
    if (layer) layer.remove();
    document.body.classList.remove('tac-numbers-top');
    return;
  }
  document.body.classList.add('tac-numbers-top'); // CSS прячет бейджи внутри клеток
  // Обёртку пересоздаёт tacCreateGrid (innerHTML-replace) — старый слой при этом
  // осиротеет вместе с полем, как и сцена (см. sceneEnsure).
  if (!layer || layer.parentElement !== wrap) {
    if (layer) layer.remove();
    layer = document.createElement('div');
    layer.id = 'tac-numbers';
    wrap.appendChild(layer);
  }
  layer.textContent = '';
  const cellW = parseFloat(getComputedStyle(field).getPropertyValue('--cellw')) || 104;
  for (let r = 0; r < battleBoard.data.length; r++) {
    if (!battleBoard.data[r]) continue;
    for (let c = 0; c < battleBoard.data[r].length; c++) {
      const cell = battleBoard.data[r][c];
      if (!cell || cell === true || cell === false || cell.id === undefined) continue;
      const td = getCell(r, c);
      if (!td) continue;
      const rect = td.getBoundingClientRect();
      if (!rect.width && !rect.height) continue;
      const u = TACTIC_UNITS[cell.id];
      const team = cell.team || 1;
      const facingRight = (team === 1 || team === 3 || team === 5);
      // Якорь берётся ТЕМ ЖЕ вызовом, что и у спрайта на сцене, а не считается
      // здесь во второй раз: у большого существа низ футпринта не совпадает с
      // низом его слитой клетки (см. `footprintBottom` в fieldScene), и
      // повторённая руками формула снова уводила бы число на 4–5px вниз.
      const a = sceneCellAnchor(td);
      if (!a) continue;
      const x = a.x + (u?.big ? cellW * 0.4 * (facingRight ? 1 : -1) : 0);
      const y = a.y - 2;
      const badge = document.createElement('div');
      badge.className = 'tac-num t' + team;
      badge.textContent = String(cell.cnt);
      badge.style.left = x + 'px';
      badge.style.top = y + 'px';
      badge.style.transform = `translate(${facingRight ? '0' : '-100%'}, -100%) rotateX(-16deg)`;
      layer.appendChild(badge);
    }
  }
}

export function tacClearAll() {
  if (tacPlaybackRunning()) return;
  const keys = [];
  for (let r = 0; r < battleBoard.data.length; r++) {
    if (!battleBoard.data[r]) continue;
    for (let c = 0; c < battleBoard.data[r].length; c++) {
      const cell = battleBoard.data[r][c];
      if (!cell || cell === true || cell === false) continue;
      keys.push({ r, c });
    }
  }
  for (const { r, c } of keys) {
    tacRemoveUnit(r, c, true);
  }
  // tacRemoveUnit сносит только спрайты, числящиеся в tacFieldSprites; трупы прошлого
  // боя (заморожены sceneDieFreeze) в этой карте не лежат и иначе остались бы висеть
  // призраками. Полная зачистка сцены.
  sceneReset();
  battleBoard.data = [];
  document.querySelectorAll<HTMLElement>('#tac-field td.tac-has-unit, #tac-field td.tac-big-tail').forEach(td => {
    td.style.backgroundImage = '';
    td.classList.remove('tac-has-unit', 'tac-big-anchor', 'tac-big-tail');
    const num = td.querySelector('div');
    if (num) { num.textContent = ''; num.className = ''; }
    td.removeAttribute('data-cnt');
  });
  tacRenderInitiative();
}

/** Заголовок панели героя сворачивает и разворачивает её. */
export function tacHeroHeaderClick(side: any) {
  if (side === 'enemy') return;   // панели героя противника больше нет
  else tacToggleHero();
}

/** Карточка отряда живёт дольше одного клика: у неё есть кнопки, а разворот
 * «Эффекты» перерисовывает её на месте. Поэтому цель (клетка + якорь) и текущий
 * разворот хранятся отдельно от DOM — иначе кнопке нечего было бы показывать.
 *
 * Разворот вернули по просьбе игрока: на поле отряд подписан только именем, и
 * без него не видно ни срока наложения, ни того, что именно бафф меняет. */
let tacInfoTarget: { r: number; c: number; anchor: any } | null = null;
let tacInfoTab: 'stats' | 'effects' = 'stats';
/** Взведены ли слушатели «закрыть по Esc / клику мимо». Флаг нужен, потому что
 * вешаются они отложенно (см. tacArmInfoDismiss) и к моменту срабатывания
 * таймера окно может быть уже закрыто. */
let tacInfoDismissArmed = false;

export function tacCloseUnitInfo() {
  const el = tacById('tac-unit-tooltip');
  if (el) el.remove();
  tacHideAbilHint();   // подсказка живёт вне карточки и сама бы не ушла
  tacInfoTarget = null;
  tacInfoTab = 'stats';
  tacInfoDismissArmed = false;
  document.removeEventListener('mousedown', tacInfoDismiss, true);
  document.removeEventListener('keydown', tacInfoDismiss, true);
}

/** Esc и клик мимо карточки закрывают её — кроме кликов по ней самой. */
function tacInfoDismiss(e: any) {
  if (e.type === 'keydown' && e.key !== 'Escape') return;
  if (e.target?.closest?.('#tac-unit-tooltip')) return;
  tacCloseUnitInfo();
}

/** Слушатели вешаются СЛЕДУЮЩИМ тиком: карточку открывает тот же клик (или
 * mousedown правой кнопки), и подписка «здесь и сейчас» поймала бы его самого и
 * закрыла окно раньше, чем игрок его увидит. */
function tacArmInfoDismiss() {
  if (tacInfoDismissArmed) return;
  tacInfoDismissArmed = true;
  setTimeout(() => {
    if (!tacInfoDismissArmed) return;   // успели закрыть до срабатывания таймера
    document.addEventListener('mousedown', tacInfoDismiss, true);
    document.addEventListener('keydown', tacInfoDismiss, true);
  }, 0);
}

/** Отряд из боевого состояния, стоящий в этой клетке, — источник ЖИВЫХ чисел
 * (остаток здоровья, маны, наложенные статусы). В расстановке боя ещё нет, и
 * карточка показывает паспортные данные существа. */
function tacInfoLiveStack(r: number, c: number): any {
  if (!hs.state) return null;
  return (hs.state.stacks || []).find((s: any) => {
    const p = battleBoard.stackPositions[s.idx];
    return p && p.row === r && p.col === c;
  }) || null;
}

/** «3 хода» / «1 ход» / «5 ходов» — длительность статуса словами. */
function tacTurnsWord(n: number): string {
  const mod100 = n % 100;
  const mod10 = n % 10;
  if (mod100 >= 11 && mod100 <= 14) return `${n} ходов`;
  if (mod10 === 1) return `${n} ход`;
  if (mod10 >= 2 && mod10 <= 4) return `${n} хода`;
  return `${n} ходов`;
}

/** Окно характеристик отряда — карточка из оригинала (`window_relative`):
 * заголовок с названием и численностью, два столбца параметров, строка умений
 * и две кнопки внизу.
 *
 * `anchor` — элемент, рядом с которым встанет окно; по умолчанию сама клетка.
 * Нужен фишке в ленте очереди: существо стоит на поле, а рассматривают его с
 * ленты, и окно должно открыться У ФИШКИ, а не в другом конце экрана.
 */
export function tacUnitTooltip(e: any, anchor?: any) {
  const td = e.currentTarget || e;
  const r = parseInt(td.dataset.row || '');
  const c = parseInt(td.dataset.col || '');
  const cell = battleBoard.data[r]?.[c];
  if (!cell || cell === true || cell === false || cell.id === undefined) return;
  tacInfoTarget = { r, c, anchor: anchor || td };
  tacInfoTab = 'stats';
  tacRenderUnitInfo();
}

/** Кнопка «Эффекты» — второй разворот той же карточки. В оригинале
 * (`btn_effects_info_creature`) она так же перекидывает окно между
 * характеристиками и наложенными заклинаниями, а не открывает третье окно. */
export function tacUnitInfoEffects() {
  if (!tacInfoTarget) return;
  tacInfoTab = tacInfoTab === 'effects' ? 'stats' : 'effects';
  tacRenderUnitInfo();
}

/** Перерисовать карточку по текущей цели и развороту. */
export function tacRenderUnitInfo() {
  if (!tacInfoTarget) return;
  const { r, c } = tacInfoTarget;
  const cell = battleBoard.data[r]?.[c];
  if (!cell || cell === true || cell === false || cell.id === undefined) { tacCloseUnitInfo(); return; }
  const tu = TACTIC_UNITS[cell.id];
  const sysName = PIC_TO_SYSNAME[tu.pic] || tu.pic;
  const ud = allData.units!?.[sysName];
  if (!ud) return;
  const live = tacInfoLiveStack(r, c);
  const title = `<div class="tac-info-title">&laquo;${ud.nameRu || tu.name}&raquo;`
    + `<span class="tac-info-cnt">[${live ? live.count : cell.cnt}]</span></div>`
    + '<div class="hwm-sep"></div>';
  // Вклад героя («От героя») виден в обоих разворотах: он объясняет, откуда в
  // цифрах взялись бонусы, а не является эффектом существа. В «Эффектах» он
  // печатается самим tacUnitEffectsHtml (там же, где был в оригинале).
  const body = tacInfoTab === 'effects'
    ? tacUnitEffectsHtml(live)
    : tacUnitStatsHtml(ud, tu, cell, live, r, c) + (live ? tacHeroBonusHtml(live) : '');
  // Кнопки — как в оригинале: слева переключение разворота, справа закрытие.
  const actions = '<div class="hwm-sep"></div><div class="tac-info-actions">'
    + `<button type="button" class="hwm-btn" onclick="tacUnitInfoEffects()">`
    + `${tacInfoTab === 'effects' ? 'Свойства' : 'Эффекты'}</button>`
    + '<button type="button" class="hwm-btn" onclick="tacCloseUnitInfo()">Закрыть</button>'
    + '</div>';

  const old = tacById('tac-unit-tooltip');
  if (old) old.remove();
  tacHideAbilHint();
  const tip = document.createElement('div');
  tip.id = 'tac-unit-tooltip';
  tip.className = 'hwm-window tac-info-window tac-info-card';
  tip.innerHTML = title + body + actions;
  tip.addEventListener('mousemove', tacInfoHover);
  tip.addEventListener('mouseleave', tacHideAbilHint);
  document.body.appendChild(tip);
  // Якорь мог уйти из документа: лента очереди перерисовывается каждый ход
  // целиком, и фишка, у которой открыли карточку, к следующей отрисовке уже
  // другая. У оторванного элемента прямоугольник нулевой — карточка уехала бы в
  // левый верхний угол, поэтому откатываемся на клетку отряда.
  const anchor = tacInfoTarget.anchor?.isConnected
    ? tacInfoTarget.anchor : (getCell(r, c) || tacById('tac-field'));
  tacPlaceInfoWindow(tip, anchor);
  tacArmInfoDismiss();
}

/** Разворот характеристик: два столбца, как в карточке оригинала. Слева —
 * нападение/защита/жизни/выстрелы/дальность, справа — урон/скорость/инициатива/
 * дух/удача. Мана есть только у колдунов: у остальных строка в оригинале
 * скрывается целиком (`cre_info_no_mana`), а не показывает прочерк. */
function tacUnitStatsHtml(ud: any, tu: any, cell: any, live: any, r: number, c: number): string {
  // В БОЮ числа берутся у сервера (`stack_display_stats`): только он знает про
  // артефакты (клиент шлёт их ключами, складывает бонусы `Hero.equip`), навыки
  // колеса, ауры соседей и наложенные заклинания. Пока боя нет, считаем сами —
  // по бонусам из панели героя, других данных в расстановке и не существует.
  // Прибавка «(+N)» в обоих случаях выводится ОДИНАКОВО: действующее минус
  // паспортное, а не «сколько дал герой», — иначе бафф в бою в неё не попадал.
  const hero = tacGetHeroData();
  const atkBase = ud.attack;
  const defBase = ud.defense;
  const effAtk = live ? live.atk : atkBase + (hero?.attack_bonus || 0);
  const effDef = live ? live.def_ : defBase + (hero?.defense_bonus || 0);
  const atkDelta = effAtk - atkBase;
  const defDelta = effDef - defBase;
  const baseMorale = (ud.skills || []).some((s: string) =>
    s === 'undead' || s === 'elemental' || s === 'mechanical') ? 0 : 1;
  // Вне боя к панели героя добавляются навыки колеса: удачу и мораль они дают
  // не полем `luck_bonus`, а перками (`luck3` и т.п.), и без этого карточка
  // показывала «Удача 0» игроку, который только что выбрал третью ступень.
  const luckVal = live ? live.luck : (hero?.luck_bonus || 0) + tacHeroPerkBonus('luck');
  const moraleTotal = live ? live.morale
    : baseMorale + (hero?.morale_bonus || 0) + tacHeroPerkBonus('leadership');
  const moraleDelta = moraleTotal - baseMorale;
  const iniBase = ud.ini || 0;
  const iniPct = hero?.initiative_bonus_pct || 0;
  const effIniVal = live ? live.ini : Math.round(iniBase * (1 + iniPct / 100) * 10) / 10;
  const iniDelta = Math.round((effIniVal - iniBase) * 10) / 10;
  const speedVal = live ? live.speed : (ud.speed || 0);
  const minDmg = live && live.min_dmg !== undefined ? live.min_dmg : ud.minDmg;
  const maxDmg = live && live.max_dmg !== undefined ? live.max_dmg : ud.maxDmg;
  const shots = live && live.shots !== undefined ? live.shots : (ud.shoots || 0);
  const dist = ud.distance || 0;
  // Мана отряда-колдуна. У существ она СВОЯ и считается за каждого в отряде
  // (у дриады 10 на существо, десяток носит 100) — без этой строки игрок видел
  // книгу магии, но не видел, на сколько ещё заклинаний ему хватит. В бою
  // показываем остаток из состояния, в редакторе — полный запас.
  const perCreature = ud.mana || 0;
  const isCaster = perCreature > 0 && (ud.skills || []).includes('caster');
  const manaMax = perCreature * (cell.cnt || 0);
  // Здоровье — верхнего существа в отряде: в бою остаток из состояния, в
  // расстановке отряд цел, и обе половины равны паспортной.
  const hpNow = live && live.hp !== undefined ? live.hp : ud.hp;
  const hpMax = live && live.max_hp !== undefined ? live.max_hp : ud.hp;

  const row = (icon: string, label: string, val: string, delta?: number) => {
    const d = delta && delta !== 0
      ? `<span class="tac-info-delta">(${delta > 0 ? '+' : ''}${delta})</span>` : '';
    return `<div class="tac-info-row"><img src="${ICON_BASE}${icon}" alt="">`
      + `<span>${label}</span><span class="tac-info-val">${val}${d}</span></div>`;
  };
  // Все строки карточки одним списком — столбцы режутся из него пополам.
  // Раньше состав столбцов был жёстким, и снятые у рукопашника «Выстрелы» с
  // «Дальностью» оставляли в левом дыру в две строки.
  const rows: string[] = [
    row('attr_attack.png', 'Нападение', String(effAtk), atkDelta),
    row('attr_defense.png', 'Защита', String(effDef), defDelta),
    row('attr_hit_points.png', 'Ед. жизни', `${hpNow}/${hpMax}`),
    row('attr_damage.png', 'Урон', `${minDmg} - ${maxDmg}`),
    row('attr_speed.png', 'Скорость', String(speedVal), speedVal - (ud.speed || 0)),
    // Целую инициативу пишем целой: «8.0» выглядит как точность, которой нет —
    // дробная часть появляется только от процентных прибавок героя.
    row('attr_initiative.png', 'Инициатива',
        Number.isInteger(effIniVal) ? String(effIniVal) : effIniVal.toFixed(1), iniDelta),
    row('attr_morale.png', 'Боевой дух', String(moraleTotal), moraleDelta),
    row('attr_fortune.png', 'Удача', String(luckVal), luckVal),
  ];
  // battleHelper: текущие вероятности срабатывания удачи/морали с учётом
  // счётчиков (luckMoraleProbability -> luck_misses/hitcount). Сервер считает
  // их только для боёв; вне боя их нет и быть не может.
  if (tacShowBhProbs && live) {
    if (live.morale_chance_pct > 0) {
      rows.push(`<div class="tac-info-row tac-info-bhprob"><img src="${ICON_BASE}attr_morale.png" alt="">`
        + `<span>Шанс морали</span><span class="tac-info-val">${tacPct(live.morale_chance_pct)}</span></div>`);
    }
    if (live.luck_chance_pct > 0) {
      rows.push(`<div class="tac-info-row tac-info-bhprob"><img src="${ICON_BASE}attr_fortune.png" alt="">`
        + `<span>Шанс удачи</span><span class="tac-info-val">${tacPct(live.luck_chance_pct)}</span></div>`);
    }
  }
  // Выстрелы и дальность — только стрелку: у рукопашника это прочерки, которые
  // читаются как характеристика.
  if (isShooterUnit(ud)) {
    rows.push(row('attr_shoots.png', 'Выстрелы', shots > 0 ? String(shots) : '-'));
    rows.push(row('attr_distance.png', 'Дальность', dist > 0 ? String(dist) : '-'));
  }
  if (isCaster) {
    rows.push(row('attr_mana.png', 'Мана', live && live.mana != null
      ? `${live.mana}/${live.mana_max ?? manaMax}` : String(manaMax)));
  }
  // battleHelper: интеграл-показ под галкой — попадания/промахи
  // бестелесности и остаток контроля (оболванивание/гипноз).
  if (tacShowBhProbs && live) {
    const im = live.incorporeal_misses || 0;
    const ih = live.incorporeal_hits || 0;
    if (im > 0 || ih > 0) {
      rows.push(`<div class="tac-info-row"><span class="tac-info-label">Промахи/Попадания:</span> `
        + `<span class="tac-info-bhprob">${im} / ${ih}</span></div>`);
    }
    const cd = live.control_duration || 0;
    if (cd > 0) {
      rows.push(`<div class="tac-info-row"><span class="tac-info-label">Контроль:</span> `
        + `<span class="tac-info-bhprob">${cd} ход.</span></div>`);
    }
    // battleHelper: урон боевых абилок — множитель и шанс для грома
    // (0.5× 25%), ярлы (1.2× 100%), удар бури (×2).
    const abs = (live as any).ability_damage || [];
    if (abs.length) {
      for (const ab of abs) {
        const name = (allData.abilities || {} as any)[ab.sys]?.name || ab.sys;
        const ch = ab.pick ? ` · ${Math.round(ab.pick * 100)}%` : '';
        rows.push(`<div class="tac-info-row"><span class="tac-info-label">${name}:</span> `
          + `<span class="tac-info-bhprob">${ab.mult}×</span>${ch}</div>`);
      }
    }
    if ((live.damage_dealt || 0) > 0 || (live.kills || 0) > 0) {
      rows.push(`<div class="tac-info-row"><span class="tac-info-label">Урон / Убито:</span> `
        + `<span class="tac-info-bhprob">${live.damage_dealt || 0} / ${live.kills || 0}</span></div>`);
    }
  }
  const half = Math.ceil(rows.length / 2);
  const left = rows.slice(0, half);
  const right = rows.slice(half);

  const abilName = (k: string) => allData.abilities?.[k]?.name || k;
  const abilDesc = (k: string) => {
    const a = allData.abilities?.[k];
    // Описание уходит в data-атрибут, а не в `title`: подсказку рисуем свою
    // (см. tacAbilHint) — системная выжидает секунду и рисуется шрифтом ОС.
    // Атрибут не любит кавычек и угловых скобок — чистим после снятия тегов.
    return stripHtml((a?.desc || a?.info || '') as string)
      .replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
  };
  // Умения одной строкой через точку — как подпись под параметрами в оригинале
  // («Летающее существо. Большое существо. Переносчик.»).
  const abils = (ud.skills || []).length
    ? `<div class="tac-info-abils">${ud.skills.map((k: string) =>
        `<span class="tac-info-skill" data-desc="${abilDesc(k)}">${abilName(k)}.</span>`).join(' ')}</div>`
    : '';
  return `<div class="tac-info-cols">`
    + `<div class="tac-info-col">${left.join('')}</div>`
    + `<div class="tac-info-col">${right.join('')}</div>`
    + `</div>${abils ? '<div class="hwm-sep"></div>' + abils : ''}`;
}

/** Формат процента: 32.5 → «32.5%», 30 → «30%»; 0/undefined → «—». */
export function tacPct(v: number | undefined | null): string {
  if (v === undefined || v === null || v === 0) return '—';
  const r = Math.round(v * 10) / 10;
  return (Number.isInteger(r) ? String(r) : r.toFixed(1)) + '%';
}

/** Итоговая таблица урона за бой (battleHelper damage summary).
 *
 * Строки приходят от сервера уже отсортированными по урону (damage_table в
 * get_state) — здесь только раскладка по командам и подписи. Убийства сервер
 * пишет целыми из total_kills, урон — из total_damage_dealt. */
export function tacDamageTableHtml(rows: any[]): string {
  if (!rows || !rows.length) return '';
  const team = (side: number) => `<span style="color:${tacTeamColor(side)}">`
    + (side === 0 ? '⚔ Игрок' : '☠ Противник') + '</span>';
  let html = '<div class="tac-dmg-table" style="margin:4px 0 8px;padding:8px 10px;'
    + 'border:1px solid var(--border);border-radius:8px;font-size:13px">'
    + '<div style="color:var(--gold);font-weight:700;margin-bottom:6px">📊 Урон за бой</div>';
  for (const r of rows) {
    const pct = r.damage_dealt > 0
      ? `<span class="tac-info-bhprob" style="font-weight:700">${r.damage_dealt}</span>`
      : '<span style="color:var(--text-dim)">0</span>';
    html += `<div style="display:flex;justify-content:space-between;gap:8px;padding:2px 0">`
      + `<span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">`
      + `<span style="color:${tacTeamColor(r.side)};font-weight:600">▍</span> ${r.name}`
      + ` <span style="color:var(--text-dim)">×${r.count_initial}</span>` + `</span>`
      + `<span style="white-space:nowrap">${pct} · ☠ ${r.kills} ${team(r.side)}</span>`
      + '</div>';
  }
  return html + '</div>';
}

/** Эффекты отряда ОДНИМ СПИСКОМ — и для разворота «Эффекты», и для тултипа у
 * курсора. Список и расшифровку («−3 к скорости») готовит сервер: полей
 * StatusEffect у клиента нет, и разбирать `dmg_taken_mult: 0.8` здесь нечем.
 *
 * Сначала МЕТКИ СТЕКА (`summoned`/`phantom` из снапшота): у них нет срока, но
 * отличить фантом от оригинала и увидеть, что отряд создан заклинанием, надо
 * именно здесь — на поле отряд подписан только именем. Дальше наложенные
 * заклинания и статусы, у каждого срок и расшифровка. Порядок в разделе важен:
 * флагов обычно ноль или один, статусы — десятки строк.
 */
export function tacEffectLines(live: any): Array<{ name: string; duration: number | null; what: string[] }> {
  const marks: Array<{ name: string; duration: number | null; what: string[] }> = [];
  if (live?.summoned) marks.push({ name: 'Призвано', duration: null, what: [] });
  if (live?.phantom) marks.push({ name: 'Фантом', duration: null, what: ['дубль, тает от любого урона'] });
  const spells = (live?.effects || [])
    .filter((ef: any) => ef && ef.name)
    .map((ef: any) => ({ name: String(ef.name), duration: ef.duration ?? null, what: ef.what || [] }));
  return [...marks, ...spells];
}

/** Строка эффекта: имя, срок (когда он есть) и расшифровка от сервера. */
function tacEffectRow(ef: { name: string; duration: number | null; what: string[] }): string {
  const turns = ef.duration === null ? ''
    : (ef.duration > 0 ? tacTurnsWord(ef.duration) : 'до конца боя');
  return '<div class="tac-info-effect">'
    + `<span class="tac-info-eff-name">${ef.name}</span>`
    + (turns ? `<span class="tac-info-eff-turns">${turns}</span>` : '')
    + (ef.what.length ? `<div class="tac-info-eff-what">${ef.what.join(' · ')}</div>` : '')
    + '</div>';
}

/** Разворот «Эффекты»: метки стека, наложенные заклинания и статусы с остатком
 * ходов. Вне боя эффектов не бывает вовсе. */
function tacUnitEffectsHtml(live: any): string {
  const lines = tacEffectLines(live);
  const spells = lines.length
    ? '<div class="tac-info-effects">' + lines.map(tacEffectRow).join('') + '</div>'
    : '<div class="tac-info-note">'
        + (hs.state ? 'Наложенных заклинаний нет.' : 'Бой не идёт — заклинаний нет.')
        + '</div>';
  return spells + tacHeroBonusHtml(live);
}

/** Вклад героя под характеристиками карточки.
 *
 * Артефакты не ложатся на отряд статусом — они складываются в самого героя, и в
 * наложенных эффектах существа им места нет (в оригинале их там тоже нет). Но
 * невидимыми они быть не должны: игрок надел кольцо и вправе увидеть, откуда в
 * характеристиках взялось «(+4)». Раскладки по конкретному артефакту не будет —
 * в герое бонусы уже сложены с ручными и с навыками колеса, и разобрать сумму
 * обратно, ничего не выдумав, нельзя; поэтому рядом просто перечислено надетое. */
function tacHeroBonusHtml(live: any): string {
  const stats = live && hs.state?.hero_stats?.[String(live.side)];
  if (!stats) return '';
  const rows: string[] = [];
  const add = (v: number, label: string, suffix = '') => {
    if (v) rows.push(`${v > 0 ? '+' : '−'}${Math.abs(v)}${suffix} ${label}`);
  };
  add(stats.attack, 'к нападению');
  add(stats.defense, 'к защите');
  add(stats.ini_pct, 'к инициативе', '%');
  add(stats.morale, 'к боевому духу');
  add(stats.luck, 'к удаче');
  // battleHelper showuron: «Ярость орды» — единственный урон-клич; показываем
  // его урон с текущей силой магии. Строка только под галкой battleHelper, как
  // остальные его числа (см. `ability_damage` выше), и только когда клич
  // фракционный: сервер уже отсек героев чужих фракций (hero_stats.horde_damage).
  if (tacShowBhProbs) {
    const hord = stats.horde_damage || 0;
    if (hord > 0) rows.push(`<span class="tac-info-bhprob">Ярость орды: ${hord} урона</span>`);
  }
  const arts = stats.artifacts || [];
  if (!rows.length && !arts.length) return '';
  return '<div class="tac-info-effects">'
    + '<div class="tac-info-effect">'
    + `<span class="tac-info-eff-name">От героя${stats.name ? ` (${stats.name})` : ''}</span>`
    + (rows.length ? `<div class="tac-info-eff-what">${rows.join(' · ')}</div>` : '')
    + (arts.length
        ? `<div class="tac-info-eff-what">🎒 ${arts.join(', ')}</div>` : '')
    + '</div></div>';
}

/** Подсказка к умению — своя, а не системный `title`.
 *
 * Системная всплывашка появляется через секунду, рисуется шрифтом ОС и не
 * поддаётся оформлению; в оригинале же это плашка `hwm_hint_css` рядом с тем,
 * на что навели. Слушатели висят на самой карточке (делегирование), а не на
 * каждом умении: карточка перерисовывается целиком на каждом развороте, и
 * подписка на узлы умирала бы вместе с ними.
 */
function tacAbilHintEl(): HTMLElement {
  let el = document.getElementById('tac-abil-hint');
  if (!el) {
    el = document.createElement('div');
    el.id = 'tac-abil-hint';
    el.className = 'hwm-hint';
    document.body.appendChild(el);
  }
  return el;
}

export function tacHideAbilHint() {
  document.getElementById('tac-abil-hint')?.remove();
}

/** Показать подсказку у умения. Встаёт СНИЗУ СПРАВА от него, как в оригинале, и
 * поджимается к краю экрана, если не влезает. */
function tacShowAbilHint(skill: HTMLElement) {
  const text = skill.dataset.desc;
  if (!text) { tacHideAbilHint(); return; }
  const el = tacAbilHintEl();
  el.textContent = text;   // текст, а не innerHTML: описание пришло из данных
  const r = skill.getBoundingClientRect();
  // Размеры меряем у уже вставленной плашки: ширина зависит от длины описания.
  let x = r.left;
  let y = r.bottom + 6;
  if (x + el.offsetWidth > window.innerWidth - 4) x = window.innerWidth - el.offsetWidth - 4;
  if (y + el.offsetHeight > window.innerHeight - 4) y = r.top - el.offsetHeight - 6;
  el.style.left = Math.max(4, x) + 'px';
  el.style.top = Math.max(4, y) + 'px';
}

/** Наведение внутри карточки: на умении — подсказка, мимо — прячем. */
function tacInfoHover(e: any) {
  const skill = e.target?.closest?.('.tac-info-skill');
  if (skill) tacShowAbilHint(skill);
  else tacHideAbilHint();
}

/** Поставить окно у якоря: справа, а если не влезает — слева; по вертикали
 * прижимается к экрану. Размеры берутся у УЖЕ вставленного окна, иначе
 * карточка с эффектами (она выше) уезжала бы за нижний край. */
function tacPlaceInfoWindow(tip: HTMLElement, anchor: any) {
  const rect = (anchor || tacById('tac-field')).getBoundingClientRect();
  const w = tip.offsetWidth;
  const h = tip.offsetHeight;
  let tx = rect.right + 10;
  if (tx + w > window.innerWidth) tx = rect.left - w - 10;
  if (tx < 4) tx = Math.max(4, (window.innerWidth - w) / 2);
  let ty = rect.top;
  if (ty + h > window.innerHeight) ty = window.innerHeight - h - 6;
  tip.style.left = Math.max(4, tx) + 'px';
  tip.style.top = Math.max(4, ty) + 'px';
}

export function tacCloseModal() {
  tacById('tac-modal').style.display = 'none';
}

export function tacCopyLog() {
  const resultDiv = tacById('tac-result');
  if (!resultDiv) return;
  const text = Array.from(resultDiv.children)
    .filter((el: any) => el.tagName === 'DIV' && !el.querySelector('button'))
    .map((el: any) => el.textContent)
    .join('\n');
  navigator.clipboard.writeText(text).then(() => {
    const btn = resultDiv.querySelector('button');
    if (btn) { const orig = btn.textContent; btn.textContent = '✅ Скопировано!'; setTimeout(() => { btn.textContent = orig; }, 2000); }
  }).catch(() => {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.left = '-9999px';
    document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
  });
}

export function tacOpenCreatureInfo() {
  var btn = tacById('tac-creature-info-btn');
  var sysName = btn.dataset.sysname;
  if (sysName) {
    tacById('tac-modal').style.display = 'none';
    if (typeof stage !== 'undefined' && stage['tac_show_army']) {
      try { clearInterval(stage['tac_show_army'].interval); } catch(e) {}
    }
    navigateTo('/units/' + sysName);
  }
}

// Base cell size (px). tacFitField shrinks cells proportionally so the whole grid fits the
// viewport — like the original client, where the battlefield never needs scrolling.
export const TAC_CELL_W = 104;
export const TAC_CELL_H = 86;

// Стабильность раскладки: пересчитываем только при РЕАЛЬНОМ изменении окна/конфига
// или крупном (>8%) сдвиге масштаба. Раньше вход брался из wrap.clientWidth (меняется
// при появлении скроллбара страницы — например, когда лог боя дорастает до прокрутки)
// и viewport-relative top (меняется при ПРОКРУТКЕ) — и любое изменение контента через
// ResizeObserver дёргало пересчёт: поле «дышало» от установки существ и скролла.
// Гистерезис (а не жёсткий ключ): первый расчёт после активации вкладки может пройти
// по ещё не устоявшейся раскладке — большой сдвиг масштаба при том же окне это
// легальный повод пересчитать; скроллбар (~1-2%) и рост контента — нет.
// Оригинальный клиент масштабирует поле один раз от размеров экрана — так же и тут.
export function tacPutUnit(r: any, c: any, idx: any, cnt: any, team: any) {
  cnt = cnt || 1;
  const u = TACTIC_UNITS[idx];
  if (!u) return;
  const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
  if (!td) return;
  // Любое truthy-значение в battleBoard.data — занято: объект стека ИЛИ маркер `true` хвостовой
  // клетки большого существа. Старая проверка `id !== undefined` пропускала маркеры,
  // и отряды вставали прямо на 2x2-существ.
  if (battleBoard.data[r] && battleBoard.data[r][c]) return;
  if (u.big) {
    if (r + 1 > tacCfg.row || c + 1 > tacCfg.col) return;
    for (let dr = 0; dr <= 1; dr++) {
      for (let dc = 0; dc <= 1; dc++) {
        if (battleBoard.data[r + dr]?.[c + dc]) return;
      }
    }
  }

  team = team || 1;
  if (!battleBoard.data[r]) battleBoard.data[r] = [];
  battleBoard.data[r][c] = { id: idx, cnt, team };
  td.style.backgroundImage = `url(${tacPortraitUrl(u.pic)})`;
  // Клетки под существом 2×2 НЕ сливаются: в оригинале сетка под ним сплошная —
  // существо просто стоит на четырёх клетках, а линии между ними видны. Слияние
  // (rowspan/colspan + display:none у хвостов) эти линии съедало, и вдобавок
  // ломало геометрию: слитая клетка живёт в проекции ОДНОГО ряда, а рядов под
  // ней два, и её низ уезжал на 4–5px ниже настоящего низа футпринта.
  //
  // Логика занятости остаётся прежней: хвосты помечены `true` в battleBoard, а
  // якорь помнит их список (`big_cells`). Кто владеет хвостом, ищет `tacAnchorAt`.
  // Классы нужны разметке: по `tac-big-anchor` якорь спрайта считается по всему
  // футпринту (sceneCellAnchor), а хвост не должен изображать пустую клетку.
  td.classList.toggle('tac-big-anchor', !!u.big);
  if (u.big) {
    if (!battleBoard.data[r+1]) battleBoard.data[r+1] = [];
    battleBoard.data[r][c+1] = true; battleBoard.data[r+1][c] = true; battleBoard.data[r+1][c+1] = true;
    const cells = [[r, c+1], [r+1, c], [r+1, c+1]];
    battleBoard.data[r][c].big_cells = cells;
    for (const [br, bc] of cells) {
      const btd = tacQuery(`#tac-field td[data-row="${br}"][data-col="${bc}"]`);
      if (btd) btd.classList.add('tac-big-tail');
    }
  }
  tacMountFieldSprite(r, c, u.pic, td, team, u.big);
  td.classList.add('tac-has-unit');
  { const hpb = td.querySelector('.tac-hp-bar'); if (hpb) hpb.remove(); }
  td.draggable = true;
  const doDragStart = (e: any) => {
    e.dataTransfer!.setData('text/plain', 'move');
    tacSetDragImage(e, u.pic);
    editor.dragSrc = { row: r, col: c };
  };
  const doDragEnd = () => {
    document.querySelectorAll<HTMLElement>('#tac-field td.tac-over').forEach(t => t.classList.remove('tac-over'));
  };
  td.addEventListener('dragstart', doDragStart);
  td.addEventListener('dragend', doDragEnd);
  // Показа по наведению здесь больше нет: окно характеристик выскакивало на каждый
  // проход курсора над отрядом и закрывало собой поле — а курсор ходит над отрядами
  // постоянно и при расстановке, и в бою. Теперь карточку открывают Shift+клик,
  // правая кнопка и фишка в ленте очереди.
  td.querySelector('div')!.textContent = cnt;
  td.querySelector('div')!.className = tacNumClass(team, u.big);
  td.setAttribute('data-cnt', cnt);
  td.dataset.pl = team;
  // (Расширение 2x2 выполнено выше, до маунта спрайта — см. комментарий там.)
  tacRenderInitiative();
  tacSyncNumbers();
  tacSyncCode();
}

/** Убрать отряд из клетки, для которой открыто окно правки.
 *
 * Кнопка в index.html раньше звала tacRemoveUnit(tacCur.row, tacCur.col) —
 * разметка лезла прямо в состояние редактора. Теперь состояние спрятано за
 * этой функцией, и вынос обвязки клеток перестал тянуть за собой HTML.
 */
export function tacRemoveCurrentUnit() {
  tacRemoveUnit(editor.cur.row, editor.cur.col, false);
}

/** Открыть окно правки отряда на клетке — общий вход для клика и правой кнопки.
 *
 * Раньше оба обработчика в `battleGrid` заполняли поля окна сами, слово в слово;
 * появление строки разделения потребовало бы третьей копии. */
export function tacOpenUnitModal(row: any, col: any, td: any) {
  editor.cur.row = row;
  editor.cur.col = col;
  tacById('tac-cnt').value = td.getAttribute('data-cnt') || '1';
  tacById('tac-team').value = td.getAttribute('data-pl');
  tacSyncSplitRow();
  tacById('tac-modal').style.display = 'flex';
}

/** Строка разделения отряда: ползунок «сколько отделить» и подпись «столько
 * останется». Оригинал (`prepare_separate`, show_polep.js :18999) показывает
 * два портрета и общий ползунок на сумму; здесь та же арифметика в одну строку
 * окна отряда, потому что отделяемая половина уезжает на свободную клетку, а не
 * в заранее выбранный слот.
 *
 * Отряд из одного существа делить нечем — строка прячется. */
export function tacSyncSplitRow() {
  const box = tacById('tac-split-row');
  if (!box) return;
  const cnt = parseInt(tacById('tac-cnt').value) || 1;
  const slider = tacById('tac-split-n') as HTMLInputElement | null;
  if (cnt < 2 || !slider) { box.style.display = 'none'; return; }
  box.style.display = 'block';
  slider.max = String(cnt - 1);
  const val = Math.min(Math.max(1, parseInt(slider.value) || 1), cnt - 1);
  slider.value = String(val);
  tacSplitPreview();
}

/** Подпись под ползунком: «останется N — отделится M». */
export function tacSplitPreview() {
  const out = tacById('tac-split-info');
  const slider = tacById('tac-split-n') as HTMLInputElement | null;
  if (!out || !slider) return;
  const cnt = parseInt(tacById('tac-cnt').value) || 1;
  const n = Math.min(Math.max(1, parseInt(slider.value) || 1), Math.max(1, cnt - 1));
  out.textContent = `останется ${cnt - n} · отделится ${n}`;
}

/** Ближайшая свободная клетка той же зоны высадки, куда влезет след существа.
 * Порядок обхода — по расстоянию от исходной клетки, как ставит отделённый
 * отряд оригинал: рядом с родительским. */
function tacNearestFreeCell(row: number, col: number, team: any, big: any): { row: number; col: number } | null {
  const cells: { row: number; col: number; d: number }[] = [];
  for (const td of document.querySelectorAll<HTMLElement>(`#tac-field td.drop[data-pl="${team}"]`)) {
    const r = parseInt(td.dataset.row || ''), c = parseInt(td.dataset.col || '');
    if (!Number.isFinite(r) || !Number.isFinite(c)) continue;
    if (r === row && c === col) continue;
    if (!tacFootprintFits(r, c, !!big)) continue;
    // Ход короля, как и везде на поле: клетка по диагонали — такая же соседняя,
    // как прямая, и отделённому отряду незачем уезжать дальше неё.
    cells.push({ row: r, col: c, d: Math.max(Math.abs(r - row), Math.abs(c - col)) });
  }
  cells.sort((a, b) => a.d - b.d);
  return cells.length ? { row: cells[0].row, col: cells[0].col } : null;
}

/** Разделить отряд: часть остаётся, часть встаёт на ближайшую свободную клетку.
 *
 * Обратная операция — слияние: перенести отряд на такой же (то же существо и та
 * же команда), см. `battleGrid`. */
export function tacSplitUnit() {
  const r = editor.cur.row, c = editor.cur.col;
  const cell = battleBoard.data[r]?.[c];
  if (!cell || cell.id === undefined) return;
  // Количество берём из поля окна: игрок мог поправить его, не нажав «Применить».
  const cnt = parseInt(tacById('tac-cnt').value) || cell.cnt;
  const team = parseInt(tacById('tac-team').value) || cell.team;
  const slider = tacById('tac-split-n') as HTMLInputElement | null;
  const n = Math.min(Math.max(1, parseInt(slider?.value || '1') || 1), cnt - 1);
  if (cnt < 2 || n < 1) return;
  const u = TACTIC_UNITS[cell.id];
  const dest = tacNearestFreeCell(r, c, team, u?.big);
  if (!dest) {
    const st = tacById('tac-status');
    if (st) st.textContent = '❌ Разделить некуда: в зоне высадки нет свободного места';
    return;
  }
  tacRemoveUnit(r, c, true);
  tacPutUnit(r, c, cell.id, cnt - n, team);
  tacPutUnit(dest.row, dest.col, cell.id, n, team);
  tacCloseModal();
}

export function tacApplyModal() {
  const r = editor.cur.row, c = editor.cur.col;
  const cell = battleBoard.data[r] && battleBoard.data[r][c];
  if (!cell) return;
  cell.cnt = parseInt(tacById('tac-cnt').value) || 1;
  cell.team = parseInt(tacById('tac-team').value) || 1;
  const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
  if (td) {
    td.querySelector('div')!.textContent = cell.cnt;
    td.querySelector('div')!.className = tacNumClass(cell.team, TACTIC_UNITS[cell.id]?.big);
    td.setAttribute('data-cnt', cell.cnt);
    td.dataset.pl = cell.team;
  }
  tacCloseModal();
  tacRenderInitiative();
  tacSyncNumbers();
  tacSyncCode();
}

export function tacRemoveUnit(r: number, c: number, silent?: boolean) {
  const cell = battleBoard.data[r] && battleBoard.data[r][c];
  if (!cell) return;
  const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
  tacDestroyFieldSprite(r, c);
  if (!td) return;
  if (cell.big_cells) {
    td.classList.remove('tac-big-anchor');
    for (const [br, bc] of cell.big_cells) {
      const btd = tacQuery(`#tac-field td[data-row="${br}"][data-col="${bc}"]`);
      if (btd) btd.classList.remove('tac-big-tail');
      if (battleBoard.data[br]) battleBoard.data[br][bc] = undefined;
    }
  }
  if (td) { td.style.backgroundImage = ''; td.classList.remove('tac-has-unit'); td.querySelector('div')!.textContent = ''; td.querySelector('div')!.className = ''; td.removeAttribute('data-cnt'); const hpb = td.querySelector('.tac-hp-bar'); if (hpb) hpb.remove(); }
  battleBoard.data[r][c] = undefined;
  if (!silent) tacCloseModal();
  tacRenderInitiative();
  tacSyncNumbers();
  tacSyncCode();
}

/** Фигуры героев у поля боя — как в оригинале, где герой стоит у ВЕРХНЕГО угла
 * своей половины (слева — игрок, справа — противник), ростом примерно в
 * полторы клетки, и виден весь бой. Рисуются куклой по классу из панелей
 * героев. Идемпотентна: пересоздаёт только изменившиеся фигуры.
 *
 * Размер и место считаются от КЛЕТКИ, а не задаются в пикселях: поле
 * подгоняется под окно (tacFitField меняет --cellw/--cellh, в полноэкранной
 * арене клетка вырастает почти вдвое), и фигура с фиксированным ростом на
 * большом поле превращалась бы в фишку, а на маленьком лезла бы на отряды.
 * Верхний угол берётся у самой клетки первого ряда: поле нарисовано в
 * перспективе, его верхняя кромка уже нижней, и «прижать к краю обёртки»
 * означало бы оставить героя висеть в стороне от угла.
 *
 * Подсветка приходит из двух источников, потому что режимы боя знают о герое
 * разное. Хотсит и пошаговый бой держат живую сессию и получают от движка
 * `hero_ready` — там подсвечено «шкала налилась, книга открыта». Цельный реплей
 * (`/api/simulate`, поля крупнее 12×10) состояния шкалы не отдаёт вовсе: у него
 * есть только поток действий, и момент героя в нём один — его собственный ход
 * `hero_skill` в очереди. Поэтому там подсвечивается ровно ход героя
 * (`tacHeroActing`), а не наполнение шкалы; выдумывать промежуточные проценты
 * из потока действий нельзя — их там нет. */
export function tacRenderHeroFigures() {
  const wrap = tacById('tac-field-wrap');
  if (!wrap) return;
  for (const side of ['player', 'enemy'] as const) {
    const id = `tac-hero-figure-${side}`;
    let fig = wrap.querySelector<HTMLElement>(`#${id}`);
    const info = heroChipInfo(side);
    if (!info) {
      if (fig) fig.remove();
      tacDestroyHeroSprite(side);
      continue;
    }
    if (!fig) {
      fig = document.createElement('div');
      fig.id = id;
      fig.className = `tac-hero-figure tac-hero-figure--${side}`;
      // Клик: в бою хотсита — книга магии героя (быстрее тянуться к кнопке),
      // в расстановке — та же панель, что открывает шапка сайдбара.
      fig.addEventListener('click', () => {
        if (hs.session) (window as any).tacHsToggleHeroBook?.();
        else if (side === 'player') tacToggleHero();
      });
      wrap.appendChild(fig);
    }
    const key = side === 'player' ? '0' : '1';
    const ready = !!(window as any).tacHeroReady?.[key];
    const acting = String((window as any).tacHeroActing ?? '') === key;
    fig.classList.toggle('tac-hero-figure--ready', ready || acting);
    if (fig.dataset.faction !== info.faction) {
      fig.dataset.faction = info.faction;
      // Кукла из оригинала (i/kukla_png — её же рисует Примерочная). Если куклы
      // у класса нет или картинка не дошла, на её место встаёт герб фракции:
      // фигура без изображения превратилась бы в пустую подпись.
      fig.innerHTML =
        `<img src="${info.doll || info.icon}" alt=""`
        + ` onerror="this.onerror=null;this.src='${info.icon}';this.classList.add('tac-hero-figure-fallback')">`
        + `<span class="tac-hero-figure-name">${info.name}</span>`;
    }
    const note = acting ? ' · ходит' : ready ? ' · шкала готова (магия доступна)' : '';
    fig.title = `${info.name} — герой${note}`;
    tacPlaceHeroFigure(fig, side);
  }
}

/** Общий жест героя: спрайт играет настоящий `doing` из данных анимации героя,
 * кукла — синтезированный CSS-класс. Молча уходит, если не нашлось ни того, ни
 * другого. Повторный запуск класса снимается и вынуждается перерасчёт стиля —
 * иначе два жеста подряд проиграют один раз. */
function tacHeroFigureGesture(side: 0 | 1 | 'player' | 'enemy', doing: string,
                              cssClass: string) {
  const key = (side === 0 || side === 'player') ? 'player' : 'enemy';
  // Есть живой спрайт — играет НАСТОЯЩИЙ жест из данных анимации героя,
  // тот же, что у существ. CSS-подскок ниже — запасной путь для куклы,
  // у которой кадров нет.
  const sprite = tacHeroSprite(key);
  if (sprite) {
    sprite.setDoing(doing);
    const ms = animGestureMs((sprite.obj && sprite.obj.filename) || '', doing) || 900;
    setTimeout(() => { if (tacHeroSprite(key) === sprite) sprite.setDoing(''); }, ms);
    return;
  }
  const fig = document.getElementById(`tac-hero-figure-${key}`);
  if (!fig) return;
  fig.classList.remove(cssClass);
  void fig.offsetWidth;
  fig.classList.add(cssClass);
  const off = () => { fig.classList.remove(cssClass); };
  fig.addEventListener('animationend', off, { once: true });
}

/** Жест героя: фигура подаётся вперёд и вспыхивает золотом на своём действии.
 *
 * Кадров у куклы нет — в игре это одна статичная картинка (её же показывает
 * Примерочная и окно героя), поэтому «анимация действия» здесь синтезированная,
 * а не разобранная из оригинала: наклон, подскок и вспышка по контуру. */
export function tacHeroFigureCast(side: 0 | 1 | 'player' | 'enemy') {
  tacHeroFigureGesture(side, 'cast', 'tac-hero-figure--cast');
}

/** Жест прямого удара героя. В оригинале у атакующего героя включается анимация
 * атаки (attackmonster.js → calccomsp.js:1648, `donow='a'`), а не каста, поэтому
 * это отдельный жест, а не подмена каста. Разворот спрайта не трогаем: герой
 * смонтирован лицом к полю (см. tacMountHeroSprite), так что удар уходит в ту
 * же сторону, куда смотрит фигура. */
export function tacHeroFigureAttack(side: 0 | 1 | 'player' | 'enemy') {
  tacHeroFigureGesture(side, 'attack', 'tac-hero-figure--attack');
}

/** Рост фигуры героя в высотах УГЛОВОЙ клетки — по пропорции из настоящего боя,
 * где герой у верхнего угла примерно вдвое выше клетки под собой. Считать от
 * `--cellh` нельзя: поле нарисовано в перспективе, и верхний ряд на экране
 * заметно ниже своей переменной (69px в стиле против 49px на экране). */
const HERO_FIGURE_CELLS = 2.0;
/** Ширина окна куклы к её росту: холст обрезан по фигуре (см. battle.css). */
const HERO_FIGURE_RATIO = 0.72;

/** Ставит фигуру у верхнего угла своей половины и задаёт ей рост от клетки.
 * Без клеток (сетка ещё не построена) — молча уходит: размеры тогда остаются
 * дефолтными из CSS, и фигура не прыгает в случайное место. */
function tacPlaceHeroFigure(fig: HTMLElement, side: 'player' | 'enemy') {
  const wrap = tacById('tac-field-wrap');
  const field = wrap && wrap.querySelector<HTMLElement>('#tac-field');
  if (!wrap || !field) return;
  const anchor = wrap.querySelector<HTMLElement>(
    `#tac-field td[data-row="1"][data-col="${side === 'player' ? 1 : tacCfg.col}"]`);
  if (!anchor) return;
  // Клетка — в ЛОГИЧЕСКИХ координатах сцены (обёртка масштабирована CSS scale,
  // см. sceneRectInArena): фигура ставится инлайновыми left/top в тех же единицах.
  const cell = sceneRectInArena(anchor);
  if (!cell || !cell.height || !wrap.offsetWidth) return;   // вкладка скрыта — мерить нечего
  const h = Math.round(cell.height * HERO_FIGURE_CELLS);
  const w = Math.round(h * HERO_FIGURE_RATIO);
  fig.style.setProperty('--hero-fig-h', h + 'px');
  // Ноги героя — на нижней линии первого ряда: так он стоит НА поле, а не висит
  // над ним. Отступ в 4px не даёт фигуре наехать на угловую клетку.
  const top = cell.bottom - h;
  // Герой стоит в СОСЕДНЕЙ с доской колонке. В оригинале это не украшение сбоку:
  // поле там объявлено на две колонки шире игрового (`defxn` при 12 играбельных),
  // и герой — обычный объект сцены с координатой x=0 слева и x=defxn-1 справа
  // (show_polep.js, getxa). Поэтому фигура центрируется на клетке-призраке шириной
  // в клетку первого ряда, а не приставляется к рамке с зазором в 4px.
  const ghost = cell.width || w;
  const rawLeft = side === 'player'
    ? cell.left - ghost / 2 - w / 2
    : cell.right + ghost / 2 - w / 2;
  // Обёртка прокручиваемая: вылезшая за неё фигура растянула бы scrollWidth и
  // добавила поперечную прокрутку на ровном месте.
  const left = Math.max(0, Math.min(rawLeft, wrap.scrollWidth - w));
  fig.style.left = Math.round(left) + 'px';
  fig.style.top = Math.round(Math.max(0, top)) + 'px';

  // Живой спрайт на месте куклы. Якорь — низ-центр фигуры, в тех же координатах
  // обёртки, что отдаёт sceneCellAnchor для клеток. Размер — как у отряда: герой
  // не крупнее существа, стоящего рядом.
  const info = heroChipInfo(side);
  const anim = info ? info.anim : '';
  if (!anim) { tacDestroyHeroSprite(side); fig.classList.remove('tac-hero-figure--live'); return; }
  // Данные анимации — в кэш заранее: первый каст не должен ждать загрузки
  // четверти мегабайта. Повторный вызов ничего не грузит (промис кэширован).
  preloadCreatureAnim(anim);
  const sprite = tacMountHeroSprite(side, anim, anchor,
    tacSpriteSize(false), { x: left + w / 2, y: Math.max(0, top) + h });
  // Кукла прячется, только когда спрайт реально нарисовался: до этого она —
  // видимая заглушка, как портрет на клетке до появления существа.
  if (!sprite) { fig.classList.remove('tac-hero-figure--live'); return; }
  tacHideDollWhenSpritePaints(fig, sprite, side);
}

/** Спрятать куклу, когда спрайт героя нарисует первый кадр. Тот же приём, что у
 * портрета на клетке (tacClearPortraitWhenPainting): пока движок грузит данные
 * анимации, на месте героя должно что-то стоять. */
function tacHideDollWhenSpritePaints(fig: HTMLElement, sprite: any, side: 'player' | 'enemy') {
  (async () => {
    const sleep = (ms: number) => new Promise(res => setTimeout(res, ms));
    const t0 = performance.now();
    while (!sprite.ready && !sprite.failed && performance.now() - t0 < 5000) await sleep(32);
    if (!sprite.ready || sprite.failed || tacHeroSprite(side) !== sprite) return;
    await sleep(80);
    if (tacHeroSprite(side) !== sprite) return;
    fig.classList.add('tac-hero-figure--live');
  })();
}

export function tacRenderInitiative() {
  const container = tacById('tac-initiative');
  if (!container) return;
  // During a replay the strip shows the real ATB turn queue (see tacRenderTurnRibbon);
  // per-put/remove re-renders here would keep overwriting it with the static ini view.
  if (tacPlaybackRunning()) return;
  const units = [];
  const maxIni = 20;
  for (let r = 0; r < battleBoard.data.length; r++) {
    if (!battleBoard.data[r]) continue;
    for (let c = 0; c < battleBoard.data[r].length; c++) {
      const cell = battleBoard.data[r][c];
      if (!cell || cell === true || cell === false || cell.id === undefined) continue;
      const tu = TACTIC_UNITS[cell.id];
      const sysName = PIC_TO_SYSNAME[tu.pic] || tu.pic;
      const ud = allData.units!?.[sysName];
      const ini = ud?.ini ?? 0;
      const name = ud?.nameRu || tu.name;
      units.push({ name, pic: tu.pic, count: cell.cnt, team: cell.team, ini, r, c });
    }
  }
  if (!units.length && !tacGetHeroData() && !tacGetEnemyHeroData()) { container.innerHTML = ''; return; }
  units.sort((a, b) => b.ini - a.ini || a.name.localeCompare(b.name));
  // Фишка как в оригинале: портрет + число, рамка И ФОН по цвету команды. Фон
  // виден вокруг портрета (тот не квадратный и не закрывает ячейку целиком) —
  // по нему в ленте и читается, чей ход следующий; тёмная подложка эту метку
  // съедала. Имя и цифра инициативы ушли на подсказку: на самой фишке их в
  // оригинале нет.
  let html = units.map(u =>
    `<div class="tac-init-unit" data-pos="${u.r}_${u.c}"
          style="${tacTeamChipStyle(u.team)}"
          title="${u.name} ×${u.count} · инициатива ${u.ini}">
      <img src="${tacPortraitUrl(u.pic)}" alt="">
      <span class="tac-init-cnt">${u.count}</span>
    </div>`).join('');
  // Фишки героев — в начале ряда, у них нет хода отряда, а своя шкала ATB.
  // Кликабельных data-pos/data-idx у фишки нет: осмотр героя — по панелям.
  for (const side of ['player', 'enemy'] as const) {
    const info = heroChipInfo(side);
    if (!info) continue;
    const team = side === 'player' ? 1 : 2;
    html = `<div class="tac-init-unit tac-init-hero" data-hero-side="${side}"
                  style="${tacTeamChipStyle(team)}"
                  title="${info.name} · герой (ход — по шкале ATB)">
      ${heroChipFace(info)}
      <span class="tac-init-cnt">⚔</span>
    </div>` + html;
  }
  container.innerHTML = html;
  tacUpdateInitScroll();
  // Лента перестраивается при каждой смене расстановки/класса героя —
  // сюда же переносим синхронизацию фигур героев на поле.
  tacRenderHeroFigures();
}

/** Прокрутка ленты кнопками ◀ ▶ — на одну фишку за нажатие, как в оригинале
 * (atb_next_release/atb_prev_release сдвигают ровно на ширину фишки). */
/** Шаг ленты — РОВНО одна фишка: её ширина плюс зазор между фишками. */
function tacInitPitch(cont: HTMLElement): number {
  const chip = cont.querySelector('.tac-init-unit');
  if (!chip) return 48;
  // Зазор читаем у контейнера, а не держим числом: он задан в CSS и там же
  // меняется, а зашитая двойка тихо разъезжалась бы с разметкой.
  const gap = parseFloat(getComputedStyle(cont).columnGap) || 0;
  return chip.getBoundingClientRect().width + gap;
}

export function tacInitScroll(dir: any) {
  const cont = tacById('tac-initiative');
  if (!cont) return;
  cont.scrollBy({ left: dir * tacInitPitch(cont), behavior: 'smooth' });
}

/** Кнопки показываются по отдельности и только когда им есть что делать: ◀ — лишь
 * если лента уже отмотана вправо (иначе возвращаться некуда), ▶ — пока справа
 * остались ходы. Стрелка в никуда сбивает с толку сильнее, чем её отсутствие. */
export function tacUpdateInitScroll() {
  const cont = tacById('tac-initiative');
  const bar = tacById('tac-init-bar');
  if (!cont || !bar) return;
  tacFitInitWidth(cont);
  bar.classList.toggle('tac-can-prev', cont.scrollLeft > 1);
  bar.classList.toggle('tac-can-next', cont.scrollLeft + cont.clientWidth < cont.scrollWidth - 1);
}

/** Ширина ленты — ЦЕЛОЕ число фишек.
 *
 * Лента растягивалась на всё свободное место, и с краю всегда торчал обрезанный
 * пополам портрет; листание на одну фишку тоже никогда не попадало в край. Здесь
 * доступная ширина округляется вниз до целых фишек, и остаток отдаётся полосе —
 * тогда видны только целые портреты, а шаг листания ровно по ним.
 *
 * Свободное место считается ПО СОСЕДЯМ в полосе, а не по собственной ширине
 * ленты: та уже ограничена прошлым расчётом. Снимать ограничение перед замером
 * нельзя — функцию зовёт и обработчик прокрутки, и сброс ширины на каждом кадре
 * плавной прокрутки сбивал её в ноль: лента вообще не листалась. */
function tacFitInitWidth(cont: HTMLElement): void {
  const bar = cont.parentElement;
  const chip = cont.querySelector('.tac-init-unit');
  if (!bar || !chip) return;
  const cs = getComputedStyle(cont);
  const pad = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
  const gap = parseFloat(cs.columnGap) || 0;
  const pitch = chip.getBoundingClientRect().width + gap;
  const barCs = getComputedStyle(bar);
  const barGap = parseFloat(barCs.columnGap) || 0;
  let used = barGap * Math.max(0, bar.children.length - 1);
  for (const el of Array.from(bar.children)) {
    if (el !== cont) used += el.getBoundingClientRect().width;
  }
  const avail = bar.clientWidth
    - (parseFloat(barCs.paddingLeft) || 0) - (parseFloat(barCs.paddingRight) || 0)
    - used - pad;
  if (pitch <= 0 || avail <= 0) return;
  const n = Math.max(1, Math.floor((avail + gap) / pitch));
  const want = (n * pitch - gap + pad).toFixed(2) + 'px';
  // Пишем только на изменение: присвоение той же ширины всё равно роняет
  // раскладку, а функция вызывается на каждое событие прокрутки.
  if (cont.style.maxWidth !== want) cont.style.maxWidth = want;
}

/** Клетка существа из фишки ленты: в расстановке фишка помнит клетку
 * (`data-pos`), в бою — номер отряда (`data-idx`), а клетку знает доска. */
function tacInitChipCell(chip: any) {
  const pos = chip.dataset.pos;
  if (pos) {
    const [r, c] = pos.split('_').map(Number);
    return getCell(r, c);
  }
  const idx = chip.dataset.idx;
  if (idx === undefined || idx === '') return null;
  const p = battleBoard.stackPositions[Number(idx)];
  return p ? getCell(p.row, p.col) : null;
}

/** Позиция отряда, которому принадлежит фишка. Та же развилка, что у
 * `tacInitChipCell`: в расстановке фишка помнит клетку (`data-pos`), в бою —
 * номер отряда (`data-idx`), а его клетку знает `stackPositions`. */
function tacRibbonChipPos(chip: any): { row: number; col: number } | null {
  const pos = chip.dataset.pos;
  if (pos) {
    const [row, col] = pos.split('_').map(Number);
    return { row, col };
  }
  const idx = chip.dataset.idx;
  if (idx === undefined || idx === '') return null;
  return battleBoard.stackPositions[Number(idx)] || null;
}

/** Клик по фишке в ленте очереди — осмотр отряда, тот же, что и по существу на
 * поле: в оригинале миниатюру из строки инициативы тоже рассматривают, и это
 * единственный способ увидеть отряд, который прячется под анимацией или уехал
 * за край поля.
 *
 * Подробный режим больше не условие: карточку закрывают её собственная кнопка,
 * Esc и клик мимо, поэтому держать под неё отдельный переключатель незачем — а
 * требовать его от игрока значило прятать единственный способ осмотреть отряд
 * за кнопкой, о которой он не знает. */
/** Погасить ленту очереди: бой окончен, очереди больше нет.
 *
 * После победы `tacRenderInitiative` пересобирал ленту по ДОСКЕ, а на доске
 * остались одни победители — строка целиком заполнялась ими и читалась как
 * «сейчас ходят вот эти». Очередь вернётся сама, как только игрок тронет
 * расстановку: любая правка поля перерисовывает ленту. */
export function tacClearInitiative() {
  const cont = tacById('tac-initiative');
  if (cont) cont.innerHTML = '';
  tacUpdateInitScroll();
}

export function tacInitRibbonClick(e: any) {
  const chip = e.target?.closest?.('.tac-init-unit');
  if (!chip) return;
  e.preventDefault();
  e.stopPropagation();
  // Фишка героя: в хотсите открывает книгу магии (клик по герою в ATB-ряду
  // оригинала тоже ведёт к книге), в расстановке — раскрывает панель героя.
  const heroSide = chip.dataset.heroSide;
  if (heroSide !== undefined) {
    if (chip.dataset.heroBook) (window as any).tacHsToggleHeroBook?.();
    else if (heroSide === 'player') tacToggleHero();
    else tacCloseUnitInfo();
    return;
  }
  const td = tacInitChipCell(chip);
  if (td) tacUnitTooltip(td, chip);
  else tacCloseUnitInfo();
}

export function tacHighlightInitiative(r: any, c: any) {
  const cont = tacById('tac-initiative');
  if (!cont) return;
  const chip = cont.querySelector<HTMLDivElement>(`.tac-init-unit[data-pos="${r}_${c}"]`);
  // No matching chip (e.g. the ribbon is in ATB-queue mode during a replay, where chips
  // aren't keyed by position) — leave the current highlight alone instead of clearing it.
  if (!chip) return;
  cont.querySelectorAll('.tac-init-unit.tac-init-active').forEach((e: any) => e.classList.remove('tac-init-active'));
  chip.classList.add('tac-init-active');
  const target = chip.offsetLeft - cont.clientWidth / 2 + chip.offsetWidth / 2;
  try { cont.scrollTo({ left: Math.max(0, target), behavior: 'smooth' }); }
  catch { cont.scrollLeft = Math.max(0, target); }
}


// Hero panel state
export function tacExtendUnits() {
  // Добавляем всех существ, которых нет в TACTIC_UNITS (нейтральные и пр.)
  const seenPics = new Set();
  for (const tu of TACTIC_UNITS) {
    seenPics.add(tu.pic);
  }

  const newEntries = [];
  for (const [sysName, u] of Object.entries(allData.units!)) {
    const portrait = u.portrait || '';
    const m = portrait.match(/\/portraits\/(.+?)anip/);
    const pic = m ? m[1] : sysName;

    // Пропускаем уже добавленных по pic или sysName
    if (seenPics.has(pic)) continue;
    seenPics.add(pic);

    // Убеждаемся что PIC_TO_SYSNAME знает про этот pic
    if (!PIC_TO_SYSNAME[pic]) {
      PIC_TO_SYSNAME[pic] = sysName;
    }

    const isBig = u.skills && u.skills.indexOf('big') !== -1;
    newEntries.push({ name: u.nameRu || sysName, pic: pic, big: isBig ? 1 : 0, r: 11 });
  }

  if (newEntries.length > 0) {
    TACTIC_UNITS.push(...newEntries);
    console.log('TACTIC_UNITS extended with', newEntries.length, 'neutral creatures');
  }
}

export function initBattle() {
  tacExtendUnits();
  tacApplyBattleSettings();   // «показывать лог/урон» — до первого боя, а не по клику
  tacTestPreload(); // предзагрузка списка существ для теста способностей
  tacRenderUnits();
  // Галка в разметке стоит по умолчанию — привести её к сохранённому выбору ДО отрисовки
  // поля (tacCreateGrid сам вызовет tacSyncNumbers и построит слой чисел по флагу).
  const numBox = tacById('tac-numbers-top') as HTMLInputElement | null;
  if (numBox) numBox.checked = tacNumbersOnTop;
  tacCreateGrid();
  // Populate hero class selectors from FACTIONS_META
  const heroSelect = tacById('tac-hero-class');
  if (heroSelect) {
    // Только играбельные: у нейтральных и событийных наборов существ героя
    // не бывает, а в списке они были — вплоть до «Грибов» и «Фермеров».
    // Класс, а не народ: герой один, и «Рыцари» во множественном числе читались
    // как выбор фракции — тем более что рядом стоит фильтр палитры, который
    // фракции и выбирает.
    const opts = PLAYABLE_FACTIONS.map(k =>
      `<option value="${k}">${FACTIONS_META[k]?.heroRu || FACTIONS_META[k]?.nameRu || k}</option>`
    ).join('');
    heroSelect.innerHTML = '<option value="">👤 Без героя</option>' + opts;
  }

  tacById('tac-modal').addEventListener('click', function(e: any) {
    if (e.target === e.currentTarget) tacCloseModal();
  });
  // Координаты клетки под курсором — как в оригинале, белыми цифрами в нижнем
  // поле. Слушатель делегированный и висит на ОБЁРТКЕ, а не на клетках:
  // `tacCreateGrid` пересоздаёт таблицу целиком (innerHTML), и подписки на
  // клетках умирали бы вместе с ней при каждой смене размера поля.
  // Лицо плитки героя в палитре — с первого кадра, а не с первой смены класса.
  tacRenderHeroTile();
  // Все круглые кнопки боя — в один столбик у левого верхнего угла поля.
  tacDockBattleButtons();
  tacDockTurnButtons(false);   // «Оборона»/«Прервать» до боя не нужны
  const fieldWrap = tacById('tac-field-wrap');
  if (fieldWrap) {
    const coords = () => tacById('tac-cell-coords');
    fieldWrap.addEventListener('mousemove', (e: any) => {
      const box = coords();
      if (!box) return;
      const td = e.target?.closest?.('#tac-field td[data-row]');
      // Порядок как у оригинала — сначала колонка, потом ряд (`getxa(x, y)`).
      box.textContent = td ? `${td.dataset.col}:${td.dataset.row}` : '';
      tacSetVitals(td ? tacVitalsHtml(Number(td.dataset.row), Number(td.dataset.col)) : '');
      // Зона хода под курсором: при наведении на отряд затемняются клетки, куда
      // он может походить в свой ход (метрика серверной get_reachable_tiles —
      // см. tacShowStackReach). Для ходящего сейчас отряда не рисуем: его зона
      // уже белая (сервер прислал move.cells), тёмная поверх перечеркнула бы её.
      let hoveredStack: any = null;
      if (td) {
        const s = tacInfoLiveStack(Number(td.dataset.row), Number(td.dataset.col));
        if (s && s.idx !== hs.state?.active_stack) hoveredStack = s;
      }
      tacShowStackReach(hoveredStack);
      // battleHelper: сводка бафов/дебафов под курсором — лёгкий тултип у
      // мыши вместо раскрытия карточки. Те же effects, что в развороте
      // «Эффекты», только без клика и без помещения в карточку.
      tacShowEffectsTooltip(e, td);
    });
    fieldWrap.addEventListener('mouseleave', () => {
      const box = coords();
      if (box) box.textContent = '';
      tacSetVitals('');
      tacHideEffectsTooltip();
      tacClearStackReach();
    });
  }
  // Лента очереди живёт весь бой и перерисовывается целиком — обработчик вешаем
  // на контейнер один раз, а не на каждую фишку.
  tacById('tac-initiative')?.addEventListener('click', tacInitRibbonClick);
  // Наведение на фишку показывает ту же тройку, что и наведение на доску:
  // очередь — это тот же отряд, только в другом месте экрана. Обработчик на
  // контейнере: фишки перерисовываются каждый ход целиком.
  const ribbon = tacById('tac-initiative');
  if (ribbon) {
    ribbon.addEventListener('mousemove', (e: any) => {
      const chip = e.target?.closest?.('.tac-init-unit');
      const pos = chip && tacRibbonChipPos(chip);
      tacSetVitals(pos ? tacVitalsHtml(pos.row, pos.col) : '');
    });
    ribbon.addEventListener('mouseleave', () => tacSetVitals(''));
  }
}

/** Цвета команд для бейджей с числом отряда. */
const TAC_TEAM_COLORS = ['', '#ff4444', '#4488ff', '#cc2222', '#22aaff', '#f47b02', '#bb24fd'];

export function tacTeamColor(team: any) { return TAC_TEAM_COLORS[team] || '#888'; }

/** Здоровье / мана / выстрелы отряда под курсором — правый угол полосы ATB.
 *
 * В оригинале эта тройка (сердце, склянка, стрела) стоит справа от шкалы и
 * читается на ходу, не открывая карточку отряда: карточка — это отдельное окно
 * поверх доски, а посмотреть остаток выстрелов у стрелка нужно каждый ход.
 *
 * Значения БОЕВЫЕ, когда бой идёт (`hs.state.stacks` — там и остаток здоровья
 * верхнего существа, и потраченная мана, и выстрелы), и паспортные в
 * расстановке, где отряд ещё цел. Мана только у колдунов, выстрелы только у
 * стрелков — как в карточке: у остальных это прочерки, которые читаются как
 * характеристика. */
function tacVitalsHtml(row: number, col: number): string {
  // По хвосту 2×2 курсор ходит так же, как по якорю: отряд там тот же самый.
  const at = tacAnchorAt(row, col);
  if (!at) return '';
  const cell = battleBoard.data[at.row]?.[at.col];
  if (!cell || cell === true || cell.id === undefined) return '';
  const tu = TACTIC_UNITS[cell.id];
  const ud = allData.units?.[PIC_TO_SYSNAME[tu.pic] || tu.pic];
  if (!ud) return '';
  const live = tacInfoLiveStack(at.row, at.col);

  const rows: string[] = [];
  const hp = live && live.hp !== undefined ? live.hp : ud.hp;
  const hpMax = live && live.max_hp !== undefined ? live.max_hp : ud.hp;
  rows.push(vitalRow('attr_hit_points.png', 'Здоровье', `${hp}/${hpMax}`));

  const perCreature = ud.mana || 0;
  if (perCreature > 0 && (ud.skills || []).includes('caster')) {
    const manaMax = live && live.mana_max != null ? live.mana_max : perCreature * (cell.cnt || 0);
    const mana = live && live.mana != null ? live.mana : manaMax;
    rows.push(vitalRow('attr_mana.png', 'Мана', `${mana}/${manaMax}`));
  }
  if (isShooterUnit(ud)) {
    const shots = live && live.shots !== undefined ? live.shots : (ud.shoots || 0);
    rows.push(vitalRow('attr_shoots.png', 'Выстрелы', String(shots)));
  }
  return rows.join('');
}

function vitalRow(icon: string, label: string, val: string): string {
  return `<div class="tac-vital" title="${label}">`
    + `<img src="${ICON_BASE}${icon}" alt=""><span>${val}</span></div>`;
}

/** Показать/убрать тройку. Пустая строка гасит блок целиком: пустая рамка в
 * углу полосы читалась бы как сломанный элемент. */
function tacSetVitals(html: string): void {
  const box = tacById('tac-init-vitals');
  if (box && box.innerHTML !== html) box.innerHTML = html;
}

/** Сводка бафов/дебафов под курсором (наведение на отряд).
 *
 * Лёгкий тултип у мыши: тот же список, что в развороте «Эффекты» карточки
 * (tacEffectLines — вместе с метками «Призвано»/«Фантом»), но без клика.
 * Опция своя (tacShowEffectsTip), от battleHelper не зависит. */
function tacShowEffectsTooltip(e: any, td: any): void {
  tacHideEffectsTooltip();
  if (!tacShowEffectsTip || !td || !hs.state) return;
  const row = parseInt(td.dataset.row, 10);
  const col = parseInt(td.dataset.col, 10);
  if (Number.isNaN(row) || Number.isNaN(col)) return;
  const at = tacAnchorAt(row, col);
  const live = at ? tacInfoLiveStack(at.row, at.col) : null;
  const lines = tacEffectLines(live);
  if (!lines.length) return;
  const tip = document.createElement('div');
  tip.id = 'tac-effect-tooltip';
  tip.className = 'tac-effect-tooltip';
  tip.innerHTML = `<b>Эффекты</b>` + lines.map((x) => {
    const tail = x.duration === null ? ''
      : (x.duration > 0 ? ` · ${tacTurnsWord(x.duration)}` : ' · до конца боя');
    return `<div class="tac-effect-line">${x.name}${tail}`
      + (x.what.length ? `<div class="tac-effect-what">${x.what.join(', ')}</div>` : '') + '</div>';
  }).join('');
  document.body.appendChild(tip);
  const pad = 14;
  const x = Math.min(e.clientX + pad, window.innerWidth - tip.offsetWidth - 8);
  const y = Math.min(e.clientY + pad, window.innerHeight - tip.offsetHeight - 8);
  tip.style.left = `${Math.max(8, x)}px`;
  tip.style.top = `${Math.max(8, y)}px`;
}

function tacHideEffectsTooltip(): void {
  const old = tacById('tac-effect-tooltip');
  if (old) old.remove();
}

/** Стиль фишки ленты очереди: ЯРКАЯ рамка цветом команды и ПРИГЛУШЁННЫЙ фон
 * того же цвета.
 *
 * В оригинале вокруг существа стоит фон его стороны, но рамка там заметно ярче
 * заливки — кайма читается как кайма. Когда рамка и фон красились одним цветом,
 * рамка сливалась с заливкой и фишка выглядела сплошным цветным квадратом:
 * чистого цвета команды на ней было вдвое больше, чем в оригинале.
 *
 * Стиль собирается в одном месте: фишку рисуют четыре разных места (лента
 * редактора, реплей, хотсит и фишки героев), и раньше каждое повторяло
 * `border-color` своими словами. */
export function tacTeamChipStyle(team: any): string {
  const color = tacTeamColor(team);
  return `border-color:${color};background:${tacMuteColor(color, 0.45)}`;
}

/** Тот же цвет, но БЛЕКЛЫЙ: подмешиваем нейтральный серый, оставляя долю `keep`.
 *
 * Серый, а не чёрный: заливка должна выцвести, а не потемнеть — тёмный вариант
 * читался как тень под портретом, а нужен выгоревший фон, на котором чистый
 * цвет рамки виден как рамка.
 *
 * Считаем в JS, а не через `color-mix`: цвет уходит в инлайновый `style`, и
 * функция даёт готовую строку без второго прохода по CSS-переменным. */
function tacMuteColor(hex: string, keep: number): string {
  const m = /^#([0-9a-f]{6})$/i.exec(hex);
  if (!m) return hex;
  const n = parseInt(m[1], 16);
  const mix = (c: number) => Math.round(c * keep + 0x77 * (1 - keep));
  return `rgb(${mix((n >> 16) & 255)},${mix((n >> 8) & 255)},${mix(n & 255)})`;
}
/** Имя отряда в журнале — цветом команды.
 *
 * Класс `tac-log-name tm<N>` нужен арене: там журнал лежит на светлом полотне и
 * повторяет оригинал буквально — чистый #FF0000 у первой команды и #0000FF у
 * второй, без полужирного (`<font color>` в разметке оригинала). В редакторе на
 * тёмной карточке эти цвета нечитаемы, поэтому там остаются мягкие оттенки из
 * инлайнового стиля. */
export function tacNameSpan(pos: any) {
  return `<span class="tac-log-name tm${pos.team}"`
    + ` style="color:${tacTeamColor(pos.team)};font-weight:600">${pos.nameRu}</span>`;
}
export function tacLogLine(html: any) {
  const rdiv = tacById('tac-result');
  if (!rdiv || rdiv.style.display === 'none') return null;
  const el = document.createElement('div');
  el.style.cssText = 'font-size:13px;padding:2px 0;color:var(--text-dim)';
  el.innerHTML = html;
  rdiv.appendChild(el);
  rdiv.scrollTop = rdiv.scrollHeight;
  return el;
}


// ── Post-action stack state (count + top-creature HP) ──
/** Apply server-reported state to a stack on the board: badge count, battleBoard.data count,
 * and a thin HP bar for the top creature (rendered only when it's wounded). */
export function tacApplyStackState(pos: any, countAfter: any, hpAfter: any) {
  if (!pos) return;
  const td = getCell(pos.row, pos.col);
  const cell = battleBoard.data[pos.row]?.[pos.col];
  if (countAfter !== undefined && countAfter > 0) {
    if (cell && cell.id !== undefined) cell.cnt = countAfter;
    pos.cnt = countAfter;
    if (td) {
      td.setAttribute('data-cnt', countAfter);
      const badge = td.querySelector('div:not(.tac-hp-bar):not(.tac-dmg-float)');
      if (badge) badge.textContent = countAfter;
    }
    tacSyncNumbers(); // отряд поредел — обновить и число в слое поверх сцены
  } else if (countAfter === 0) {
    // Отряд выбили под ноль: серверная гибель до того, как по ней придёт
    // действие `destroyed` (урон зоны, огонь). Счёт до нуля и без таблички
    // мигает раньше, чем труп унесут с доски — иначе щель между «урон» и
    // «уничтожен» оставляет на поле отряд, которому больше нечего дать.
    pos.cnt = 0;
    if (cell && cell.id !== undefined) cell.cnt = 0;
    if (td) {
      td.setAttribute('data-cnt', '0');
      const badge = td.querySelector('div:not(.tac-hp-bar):not(.tac-dmg-float)');
      if (badge) badge.textContent = '0';
    }
    tacSyncNumbers();
  }
  if (hpAfter !== undefined) {
    pos.hp = hpAfter;
    if (td) tacUpdateHpBar(pos, td);
  }
}

function tacUpdateHpBar(pos: any, td: any) {
  const maxHp = allData.units![pos.sysName]?.hp || 0;
  let bar = td.querySelector('.tac-hp-bar');
  if (!maxHp || pos.hp === undefined || pos.hp >= maxHp || pos.hp <= 0) {
    if (bar) bar.remove(); // full or dead — no bar, like the original
    return;
  }
  if (!bar) {
    bar = document.createElement('div');
    bar.className = 'tac-hp-bar';
    bar.innerHTML = '<span></span>';
    td.appendChild(bar);
  }
  const pct = Math.max(2, Math.round((pos.hp / maxHp) * 100));
  const fill = bar.querySelector('span');
  fill.style.width = pct + '%';
  fill.style.background = pct > 50 ? '#4caf50' : pct > 25 ? '#ffb300' : '#f44336';
  bar.title = `HP: ${pos.hp}/${maxHp}`;
}


/** Класс разметки объекта поля. Огонь без стороны — «Огненная стена» (полоса на
 * канвасе), огонь со стороной — горящая клетка; врата различаются открытые и
 * уже пройденные (след). */
function tacFieldObjectClass(obj: any): string | null {
  if (obj.kind === 'fire') return obj.side == null ? 'tac-firewall' : 'tac-fire';
  if (obj.kind === 'trap') return 'tac-trap';
  if (obj.kind === 'cloud') return 'tac-cloud';
  if (obj.kind === 'mist') return 'tac-mist';
  if (obj.kind === 'ice') return 'tac-ice';
  if (obj.kind === 'gate') return obj.spent ? 'tac-gate-spent' : 'tac-gate';
  return null;
}

/** Клетки объекта поля как [row, col]. Врата 2×2 занимают ВЕСЬ след (`size` в
 * снапшоте), а не клетку-якорь: иначе перерисовка доски схлопнула бы метку в
 * одну клетку, а снятие оставило бы хвост класса на остальных трёх. */
function tacFieldObjectCells(obj: any): [number, number][] {
  if (obj.kind !== 'gate' || !(obj.size > 1)) return [[obj.y, obj.x]];
  return tacHsFootprint(obj.y, obj.x, obj.size);
}

/** Типы действий, за которые дёргается и подсвечивается фигура ГЕРОЯ.
 *
 * `spell_damage` стоит здесь ради СОБСТВЕННЫХ заклинаний героя: единственный
 * тип, который встречается и у существ, — но у тех носитель назван явно и
 * фигура героя тут ни при чём (см. `tacHeroActionSide`).
 *
 * Прямая атака героя. Сторону несёт она же (движок кладёт `side` во все три
 * места, где бьёт герой: свой ход ИИ, удар человека в окне хода и «Надзор»),
 * но жест у неё ударной, а не кастовой. */
const HERO_ATTACK_TYPES = ['hero_attack'];

/** Каст героя: активируемое умение либо ЛЮБОЕ `spell_*`-действие.
 *
 * Список из двух имён (`hero_skill`, `spell_damage`) покрывал меньше половины
 * книги: оригинал ставит `donow="c"` в обработчике каждой школы — и бафф
 * (`rof`, usemagicp.js:135), и щит (`dsh`, :108), и урон, — так что молчали
 * ровно те касты, где герой ничего не делает: «Ускорение», «Благословение»,
 * «Снятие магии», «Клич». В реплее такие заклинания проходили без жеста.
 *
 * Именно поэтому здесь предикат, а не список: семейство `spell_*` пополняется
 * (`spell_luck`, `spell_area`, `spell_power_bonus`), и каждый новый тип должен
 * требовать отдельной правки, чтобы герой не остался немым на нём. */
function isHeroCastType(type: any): boolean {
  const t = String(type || '');
  return t === 'hero_skill' || t.startsWith('spell_');
}

/** Стоит ли figuro героя жестить именно этим действием.
 *
 * Отдельный вопрос от `tacHeroActionSide`, потому что свечение и жест хотят
 * разного: фигура должна гореть ВСЕ время своего заклинания, а жестить — один
 * раз. Площадной каст — это несколько `spell_*`-действий на одну книгу:
 * перебор всех 94 заклинаний показал, что «Армагеддон», «Цепная молния» и
 * «Незлобивое слово» дают по три `spell_damage` на попавшие отряды, так что без
 * этого гейта герой жестил бы трижды подряд на одном заклинании. Метку
 * `area_first` ставит движок на первом действии среза (`_cast_area_spell`,
 * `_spell_pipeline.py`) — тем же способом, каким анимация области берёт ровно
 * одну крупную картинку.
 *
 * Существо сюда не попадает: его `spell_*` отсекает уже `tacHeroActionSide`. */
export function tacHeroCastGestureWanted(a: any): boolean {
  return !(a.area && !a.area_first);
}

/** Сторона героя, если это действие — его собственное рукопожатие, иначе null.
 * Единый признак для жеста и свечения: и то, что подсвечивается, и то, что
 * дёргается, — это ровно те касты и та атака, что перечислены выше.
 *
 * Отдельная оговорка — каст СУЩЕСТВА. Действия общей ветки заклинаний
 * (`battle/abilities/unit_casting.py::cast_via_hero_path`) лежат в потоке
 * вперемешку с геройскими и отличаются только меткой носителя `stack_idx`.
 * Без этой оговорки «Огненный шар» архимага дёргал фигуру героя и зажигал её
 * подсветку: кастовало существо, а жестил герой. */
export function tacHeroActionSide(a: any): 0 | 1 | null {
  if (String(a.type || '').startsWith('spell_') && a.stack_idx !== undefined
      && a.stack_idx !== null) return null;
  if ((isHeroCastType(a.type) || HERO_ATTACK_TYPES.indexOf(a.type) >= 0)
      && (a.side === 0 || a.side === 1)) return a.side;
  return null;
}

export function setupTacSimulate(windowObj: any) {
  // Постоянная разметка объектов поля: ловушка/туча/огонь на клетке. Ставится
  // и анимацией действия (battleAnim), и снапшотом сервера (field_objects).
  windowObj.tacMarkFieldObject = function(obj: any) {
    if (!obj || typeof obj.x !== 'number' || typeof obj.y !== 'number') return;
    const cls = tacFieldObjectClass(obj);
    if (!cls) return;
    for (const [r, c] of tacFieldObjectCells(obj)) {
      const td = getCell(r, c);
      if (td) td.classList.add(cls);
    }
  };
  windowObj.tacUnmarkFieldObject = function(obj: any) {
    if (!obj || typeof obj.x !== 'number' || typeof obj.y !== 'number') return;
    for (const [r, c] of tacFieldObjectCells(obj)) {
      const td = getCell(r, c);
      if (!td) continue;
      if (obj.kind === 'gate') {
        td.classList.remove('tac-gate');
        td.classList.remove('tac-gate-spent');
      } else {
        td.classList.remove(tacFieldObjectClass(obj)!);
      }
    }
  };
  /** Привести разметку объектов поля к снапшоту сервера (`field_objects`).
   *
   * Раньше её ставила ТОЛЬКО анимация действия и не снимал никто: «Огненная
   * стена» горит три хода, а нарисованной оставалась до конца боя — сервер
   * давно её погасил, игрок же видел на поле полосу огня и обходил пустое
   * место. Обратная ошибка того же корня: список приходил третьим аргументом
   * `tacRenderWalls` и не читался вовсе, поэтому любая перерисовка доски
   * стирала стену, которая ещё горит.
   *
    * Огонь героя (`side: null` — «Огненная стена») и след «Выжигающей поступи»
    * рисуются по-разному: стена — сплошной полосой, след — тлеющей клеткой.
    *
    * Врата большого демона — объект 2×2: в снапшоте у них `size`, и на доске
    * берётся весь след (`tacFieldObjectCells`), иначе перерисовка поля оставила
    * бы одну клетку вместо четырёх, а снятие метки — огрызок на остальных.
    */
  windowObj.tacSyncFieldObjects = function(objs: any) {
    const want: Record<string, Set<string>> = {
      'tac-firewall': new Set(), 'tac-fire': new Set(),
      'tac-trap': new Set(), 'tac-cloud': new Set(),
      'tac-mist': new Set(), 'tac-ice': new Set(),
      // Открытые врата сюда НЕ попадают: их рисует портал-спрайт (см. блок
      // врать ниже), а `tac-gate` остаётся запасным вариантом на случай, когда
      // атлас недоступен. Потраченные врата — всегда CSS-метка на месте выхода.
      'tac-gate-spent': new Set(),
    };
    for (const o of (objs || [])) {
      if (!o || typeof o.x !== 'number' || typeof o.y !== 'number') continue;
      const cls = tacFieldObjectClass(o);
      if (!cls) continue;
      for (const [r, c] of tacFieldObjectCells(o)) want[cls].add(`${r}:${c}`);
    }
    for (const [cls, cells] of Object.entries(want)) {
      for (const td of document.querySelectorAll<HTMLElement>(`#tac-field td.${cls}`)) {
        if (!cells.has(`${td.dataset.row}:${td.dataset.col}`)) td.classList.remove(cls);
      }
      for (const key of cells) {
        const [row, col] = key.split(':').map(Number);
        const td = getCell(row, col);
        if (td) td.classList.add(cls);
      }
    }
    // Сценные объекты «Огненной стены» живут ровно столько, сколько клетка
    // есть в снапшоте: погасла (firewall пропал из field_objects) — надо снять
    // и burn-объект, иначе полоса огня на канвасе висит до конца боя, хотя
    // сервер её давно погасил. Клетки, где стена ещё горит, перемонтируются
    // при перерисовке доски (tacRenderWalls снесла сцену сценуReset'ом) —
    // sceneMountFirewall идемпотентен по row:col и дублей не плодит.
    const burning = sceneFirewallCells();
    for (const key of burning) {
      if (!want['tac-firewall'].has(key)) sceneUnmountFirewall(key);
    }
    const wantWall = want['tac-firewall'];
    for (const key of wantWall) {
      if (!burning.has(key)) {
        const [row, col] = key.split(':').map(Number);
        const td = getCell(row, col);
        if (td) sceneMountFirewall(td, tacSpriteSize(false));
      }
    }
    // Грозовая туча «Призывающего бурю» — объект на КАЖДОЙ клетке зоны 3×3
    // (все `kind: 'cloud'` из field_objects): урон бури накрывает всю зону,
    // и видна она должна вся, а не только средний столбец. Ушла из снапшота
    // (буря кончилась) — снять объект; новая — смонтировать (идемпотентно по
    // row:col).
    const stormCellsWant = new Set<string>();
    for (const o of (objs || [])) {
      if (o && o.kind === 'cloud'
          && typeof o.x === 'number' && typeof o.y === 'number') {
        stormCellsWant.add(`${o.y}:${o.x}`);
      }
    }
    const standing = sceneStormCells();
    for (const key of standing) {
      if (!stormCellsWant.has(key)) sceneUnmountStorm(key);
    }
    for (const key of stormCellsWant) {
      if (!standing.has(key)) {
        const [row, col] = key.split(':').map(Number);
        const td = getCell(row, col);
        if (td) sceneMountStorm(td, tacSpriteSize(false));
      }
    }
    // Врата ада «Открытия врат Ада» — портал на клетке-якоре следа: у большого
    // демона это след 2×2, и спрайт оригинала (magic_spell spellname='demongate',
    // showdemongate usemagicp.js:7238) шириной во весь след. Ключ — якорная
    // клетка (obj.x/obj.y), а не весь след: один портал, одна клетка. Потраченные
    // врата (spent) портала не имеют — их рисует CSS-метка tac-gate-spent.
    // Портал в гашении (sceneGateClose) не переставляется вторым объектом.
    const gateWant = new Map<string, any>();
    for (const o of (objs || [])) {
      if (o && o.kind === 'gate' && !o.spent
          && typeof o.x === 'number' && typeof o.y === 'number') {
        gateWant.set(`${o.y}:${o.x}`, o);
      }
    }
    const gatesUp = sceneGateCells();
    for (const key of gatesUp) {
      if (!gateWant.has(key)) sceneUnmountGate(key);
    }
    // Запасная CSS-подсветка открытых врат набирается заново каждый раз: если в
    // прошлом снапшоте атлас был недоступен, а теперь доступен, подсветка должна
    // уступить место спрайту.
    document.querySelectorAll<HTMLElement>('#tac-field td.tac-gate')
      .forEach((td) => td.classList.remove('tac-gate'));
    for (const [key, o] of gateWant) {
      if (gatesUp.has(key) || sceneGateDying(key)) continue;
      const [row, col] = key.split(':').map(Number);
      const td = getCell(row, col);
      if (!td) continue;
      // Спрайт недоступен (нет движка, оффлайн без кэша атласа) — оставляем
      // прежнюю пульсирующую подсветку: молча пропущенные врата игрок принял бы
      // за «заклинание не сработало».
      if (!sceneMountGate(td, tacSpriteSize(false), o.size > 1)) {
        for (const [r, c] of tacFieldObjectCells(o)) {
          const cTd = getCell(r, c);
          if (cTd) cTd.classList.add('tac-gate');
        }
      }
    }
  };
  // Экспорты battle.ts НЕ присваиваем: main.ts выставляет их живыми getter-only
  // глобалами (exposeLive), и запись поверх роняет страницу («Cannot set property
  // ... which has only a getter») ещё до initFieldSprites.
  windowObj.tacRenderWalls = function(walls: any, terrain: any, fieldObjects?: any) {
    // Перерисовка — ПОЛНАЯ: старые пометки и спрайты снимаются с доски прежде,
    // чем ставятся новые. Раньше функция только добавляла, а сетка между боями
    // не пересоздаётся — и камни прошлого боя оставались на поле. На них
    // ложилась новая раскладка: булыжник 2×2 накрывал клетку, где с прошлого
    // раза висел камень 1×1, и препятствия наезжали друг на друга.
    document.querySelectorAll<HTMLElement>('#tac-field td.tac-wall').forEach(td => {
      td.classList.remove('tac-wall', 'tac-wall-big');
      td.querySelectorAll('img.tac-wall-sprite').forEach(img => img.remove());
    });
    // Клетки под большими препятствиями метим отдельно: спрайт у квадрата 2×2
    // ОДИН, и рисовать в каждой из четырёх клеток по камню нельзя.
    const bigCells = new Set<string>();
    for (const o of tacObstacleLayout) {
      if (o.kind === 'rock') continue;
      for (const [dr, dc] of [[0, 0], [0, 1], [1, 0], [1, 1]]) {
        bigCells.add(`${o.row + dr}:${o.col + dc}`);
      }
    }
    for (const w of (walls || [])) {
      const td = getCell(w.y, w.x);
      if (!td) continue;
      td.classList.add('tac-wall');
      td.classList.remove('drop', 'pl1', 'pl2', 'pl3', 'pl4', 'pl5', 'pl6');
      if (bigCells.has(`${w.y}:${w.x}`)) {
        // Своей картинки у клетки нет — её накрывает общий спрайт квадрата.
        td.classList.add('tac-wall-big');
        continue;
      }
      // Спрайт частокола из оригинала (i/png40/spike.png, 79×87) через кэш-прокси.
      // Если спрайт недоступен (offline без предзагрузки) — остаётся CSS-эмодзи.
      if (!td.querySelector('img.tac-wall-sprite')) {
        const img = document.createElement('img');
        img.className = 'tac-wall-sprite';
        // Камень оригинала: статический спрайт препятствия (юнит rock1,
        // «Препятствие» — тот самый, что стоит на полях боя heroeswm).
        img.src = '/api/cache/i/statics/rock1ani_stat100.png';
        img.alt = '';
        img.addEventListener('error', () => img.remove(), { once: true });
        td.appendChild(img);
      }
    }
    for (const t of (terrain || [])) {
      const td = getCell(t.y, t.x);
      if (td) {
        if (t.type === 200) td.classList.add('tac-fire');
        else if (t.type === 250) td.classList.add('tac-ash');
      }
    }
    // Перерисовка — новая раскладка: якоря клеток могли уехать (tacFitField),
    // и старые burn-объекты стены остались бы висеть на старых позициях. Сносим
    // все объекты стены; клетки, где она ещё горит, заново смонтирует
    // tacSyncFieldObjects ниже (идемпотентен по row:col и тянет свежие якоря).
    sceneUnmountAllFirewalls();
    sceneUnmountAllStorms();
    sceneUnmountAllGates();
    windowObj.tacSyncBigObstacles();
    // Объекты поля приходили третьим аргументом и не читались вовсе — огонь,
    // ловушки и тучи, уже стоящие на поле, после перерисовки пропадали.
    if (fieldObjects) windowObj.tacSyncFieldObjects(fieldObjects);
  };

  /** Нарисовать большие препятствия (булыжник 2×2 и ёлка 2×2).
   *
   * Обычной картинкой, а не спрайтом сцены. Сцена умеет ставить существ: бокс
   * отсчитывается от якоря клетки по формулам оригинала для АНИМАЦИЙ, а у
   * statix-объектов своя внутренняя раскладка со сдвигом — тот же якорь уводил
   * рисунок на пару клеток от своего квадрата. Здесь же место считается прямо
   * по клеткам: низ картинки лежит на нижней грани квадрата, ширина равна его
   * ширине. Как у камня 1×1, только на четыре клетки.
   *
   * Ёлка берётся готовым статиком оригинала (`rockelkaani_stat100.png`), а
   * булыжника в статиках нет — он вырезается из его же атласа: валун занимает
   * там левый верхний угол (252×244 из 670×320), дальше идут обломки и пыль.
   */
  const OBSTACLE_ART: Record<string, { url: string; w: number; h: number; crop?: [number, number] }> = {
    boulder: {
      url: '/api/cache/i/png40/rock2x2ani.png',
      w: 252, h: 244, crop: [670, 320],
    },
  };

  windowObj.tacSyncBigObstacles = function() {
    const wrap = tacById('tac-field-wrap');
    if (!wrap) return;
    wrap.querySelectorAll('.tac-obstacle').forEach(el => el.remove());
    for (const o of tacObstacleLayout) {
      const art = OBSTACLE_ART[o.kind];
      if (!art) continue;
      const tds = [getCell(o.row, o.col), getCell(o.row, o.col + 1),
                   getCell(o.row + 1, o.col), getCell(o.row + 1, o.col + 1)];
      if (tds.some(td => !td)) continue;
      // Логические координаты сцены (см. sceneRectInArena) — препятствие
      // ставится инлайновыми left/top в тех же единицах, что и клетки.
      const rects = tds.map(td => sceneRectInArena(td!));
      if (rects.some(r => !r || !r.width)) continue;
      const left = Math.min(...rects.map(r => r!.left));
      const right = Math.max(...rects.map(r => r!.right));
      const bottom = Math.max(...rects.map(r => r!.bottom));
      const width = right - left;
      const height = width * (art.h / art.w);
      const el = document.createElement('div');
      el.className = 'tac-obstacle';
      el.style.left = left + 'px';
      el.style.top = (bottom - height) + 'px';
      el.style.width = width + 'px';
      el.style.height = height + 'px';
      el.style.backgroundImage = `url('${art.url}')`;
      if (art.crop) {
        // Из атласа показываем только валун: масштабируем весь лист так, чтобы
        // вырезка заняла ширину квадрата, и сдвигаем его левым верхним углом.
        const k = width / art.w;
        el.style.backgroundSize = `${art.crop[0] * k}px ${art.crop[1] * k}px`;
        el.style.backgroundPosition = '0 0';
      }
      wrap.appendChild(el);
    }
  };

  windowObj.tacClearTerrain = function() {
    document.querySelectorAll<HTMLElement>('#tac-field td.tac-wall, #tac-field td.tac-fire, #tac-field td.tac-ash, #tac-field td.tac-firewall, #tac-field td.tac-trap, #tac-field td.tac-cloud').forEach(td => {
      td.classList.remove('tac-wall', 'tac-wall-big', 'tac-fire', 'tac-ash',
                          'tac-firewall', 'tac-trap', 'tac-cloud');
      // Спрайт частокола — дочерний элемент клетки: снимаем вместе со стеной.
      td.querySelectorAll('img.tac-wall-sprite').forEach(img => img.remove());
    });
    // Большие препятствия — не классы клеток, а свои узлы поверх доски.
    document.querySelectorAll<HTMLElement>('#tac-field-wrap .tac-obstacle')
      .forEach(el => el.remove());
  };
  function tacClearCorpses() {
    document.querySelectorAll<HTMLElement>('#tac-field .tac-corpse').forEach(e => e.remove());
  }

  // Расстановка, какой она была ДО последнего боя, и флаг «на поле — конец боя».
  // После боя поле остаётся как есть (выжившие, трупы); сброс к исходной расстановке
  // происходит только при следующем нажатии «в бой».
  // Кто бил последним — для разворота трупа к убийце (оригинал: calccomsp.js donow 'd'
  // берёт b = -b_view атакующего). Сбрасывается любым действием, кроме атаки/смерти.
  function tacResetBoard(setup: any) {
    // Sweep ALL mounted sprites, not just cells listed in battleBoard.data — survivors of the
    // previous battle may stand on cells the new setup doesn't touch, and their live
    // sprites (plus wrapper divs) would otherwise stay on the board as ghosts.
    for (const key of [...tacFieldSprites.keys()]) {
      const [sr, sc] = key.split('_');
      tacDestroyFieldSprite(sr, sc);
    }
    // Трупы прошлого боя живут на сцене, не в tacFieldSprites.
    sceneReset();
    for (let r = 0; r < battleBoard.data.length; r++) {
      if (!battleBoard.data[r]) continue;
      for (let c = 0; c < battleBoard.data[r].length; c++) {
        const cell = battleBoard.data[r][c];
        if (!cell || cell === true || cell === false) continue;
        const td = getCell(r, c);
        if (td) {
          td.style.backgroundImage = '';
          td.classList.remove('tac-has-unit', 'tac-big-anchor');
          td.querySelector('div')!.textContent = '';
          td.querySelector('div')!.className = '';
          td.removeAttribute('data-cnt');
          // Хвосты 2×2 — свои клетки, их пометку снимаем отдельно.
          for (const [br, bc] of (cell.big_cells || [])) {
            getCell(br, bc)?.classList.remove('tac-big-tail');
          }
        }
        battleBoard.data[r][c] = undefined;
      }
    }
    tacClearCorpses();
    for (const s of setup) {
      tacPutUnit(s.row, s.col, s.id, s.cnt, s.team);
    }
  }

  /** Поле помещается в серверную сетку — можно слать позиции как есть.
   * Сервер принимает поле оригинала до 14×10 (см. FIELD_PRESETS в battle/grid/_constants.py);
   * экзотика выше (12×12 и т.п.) по-прежнему не помещается. */
  function tacFitsServerGrid() { return tacCfg.col <= 14 && tacCfg.row <= 10; }

  /** Снимок доски: отряды в СЕРВЕРНОМ порядке + расстановка для отката после боя.
   *
   * The server indexes stacks player-side first, then enemy (see service.build_stacks), and
   * every replay action references those indices. A row-by-row board scan interleaves the
   * sides, so re-partition into server order here — otherwise actions get attributed to the
   * wrong stacks on any layout with both sides in the same rows. Хотсит ходит по тем же
   * индексам, поэтому сканирование у него и у обычного боя обязано быть общим. */
  function tacScanBoard() {
    const positions = [];
    const original = [];
    for (let r = 0; r < battleBoard.data.length; r++) {
      if (!battleBoard.data[r]) continue;
      for (let c = 0; c < battleBoard.data[r].length; c++) {
        const cell = battleBoard.data[r][c];
        if (!cell || cell === true || cell === false || cell.id === undefined) continue;
        const u = TACTIC_UNITS[cell.id];
        const side = (cell.team === 1 || cell.team === 3 || cell.team === 5) ? 'player' : 'enemy';
        const sysName = PIC_TO_SYSNAME[u.pic] || u.pic;
        const nameRu = allData.units!?.[sysName]?.nameRu || u.name;
        // Сторона следа: у 2×2 отряд занимает четыре клетки, и всё, что
        // подсвечивает или ловит клик по отряду, считает попадание по квадрату
        // (см. markStack и tacHsStackAt) — с тех пор как клетки под ним не
        // сливаются, из одной координаты якоря этого уже не вывести.
        positions.push({ row: r, col: c, sysName, side, cnt: cell.cnt, team: cell.team,
                         pic: u.pic, nameRu, size: u.big ? 2 : 1 });
        original.push({ row: r, col: c, id: cell.id, cnt: cell.cnt, team: cell.team });
      }
    }
    return {
      positions: [
        ...positions.filter(p => p.side === 'player'),
        ...positions.filter(p => p.side === 'enemy'),
      ].map((p, i) => ({ ...p, idx: i })),
      original,
    };
  }

  /** Kick off sprite atlas/animation loading for every creature type on the field right away —
   * enginep.js caches this data at the module level (keyed by animUnit), so warming it here gives
   * it a head start (asset fetch + the engine's ~1s load-check poll) before the first movement's
   * short CSS-transition animation needs it, instead of racing that fetch from a cold start. */
  function tacPreloadBoardAnims(positions: any) {
    // Звуковую ветку движка поднимаем здесь же: enginep.js грузится отдельным async-тегом
    // (index.html), и раньше этого момента его `var soundeff = 0` затёр бы наш флаг.
    sndInstallEngineHook();
    // Анимации удачи/духа — единый объект 'effs' (png40/effs.png + anim_data40/effs.js),
    // греем его заодно с существами: первый прок не должен ловить сетевую задержку.
    sceneWarmEffs();
    // Atlas'ы заклинаний, которые накладывают УМЕНИЯ («Слабость», «Скорбь»,
    // «Ослепление», «Замедление», «Разложение», «Проклятие», «Забывчивость»,
    // «Берсерк»): накладка статуса случается в середине очереди действий, и
    // холодный fetch png40/xxxx.png там стоил секунд задержки — бой выглядел
    // замершим. Список закрытый и короткий (spellAnim.ts), геройская книга по
    // нему не греется.
    warmStatusSpellAnims();
    const seen = new Set();
    for (const sp of positions) {
      const au = allData.units![sp.sysName]?.animUnit;
      if (au && !seen.has(au)) {
        seen.add(au);
        // sounds['<animUnit>'] объявляет сам <animUnit>ani.js, поэтому греем звуки
        // только после того, как анимация существа догрузилась.
        preloadCreatureAnim(au).then(() => sndPreloadUnitSounds(au));
      }
    }
  }

  /** Отряды одной стороны в формате запроса к API. */
  function tacSidePayload(positions: any, side: any, sendPositions: any) {
    return positions.filter((p: any) => p.side === side).map((p: any) => {
      const override = tacTestOverrides()[p.sysName];
      const disabled = override ? Object.keys(override).filter(k => override[k] === false) : undefined;
      return {
        sysName: p.sysName,
        count: p.cnt,
        ...(sendPositions ? { position: [p.col, p.row] } : {}),
        ...(disabled?.length ? { abilities_override: disabled } : {}),
      };
    });
  }

  /** «В бой» — единственная кнопка старта. Бой всегда начинается как сессия хода
   * (управление у человека), а автобой включается кнопкой в любой момент.
   *
   * Исключение — экзотические поля крупнее 12×10: серверная сессия на них не живёт
   * (tacFitsServerGrid), поэтому там остаётся старый цельный реплей /api/simulate.
   * Переключать режим на таком поле нельзя — бой считается разом. */
  windowObj.tacSimulate = async function() {
    if (tacStepMode) {
      await tacStartStepBattle();
      return;
    }
    if (tacFitsServerGrid()) {
      await windowObj.tacStartHotseat();
      return;
    }
    if (tacPlaybackRunning()) return;
    // На поле — итог прошлого боя: по нажатию «в бой» возвращаем исходную расстановку
    // (до включения проигрывания, чтобы tacPutUnit смонтировал живые спрайты).
    if (hs.endStateShown && hs.savedSetup) {
      tacResetBoard(hs.savedSetup);
      hs.endStateShown = false;
    }
    tacSetPlaybackRunning(true);
    tacClearCorpses(); // трупы прошлого боя
    // Грунт НЕ перекатываем: его уже постелили при входе в редактор
    // (tacInitTerrainSelect) — расстановка обязана выглядеть так же, как бой.
    // Повторный tacRollLand() перевыбирал бы и тип грунта (при «Случайно»), и
    // вариант картинки (даже при закреплённом типе — свой случайный номер
    // текстуры на каждый вызов, см. tacApplyLand), и арена боя расходилась с
    // тем, что игрок только что видел в превью.
    sndStartMusic();
    const status = tacById('tac-status');
    const resultDiv = tacById('tac-result');
    resultDiv.style.display = 'block';
    resultDiv.innerHTML = '<div class="tac-progress" style="color:var(--gold);font-size:12px">⏳ Воспроизведение...</div>';
    const scan = tacScanBoard();
    battleBoard.stackPositions = scan.positions;
    tacPreloadBoardAnims(battleBoard.stackPositions);
    const tacOriginalState = scan.original;
    if (!battleBoard.stackPositions.some(s => s.side === 'player') || !battleBoard.stackPositions.some(s => s.side === 'enemy')) {
      status.textContent = '❌ Добавьте отряды с обеих сторон';
      tacSetPlaybackRunning(false);
      return;
    }
    tacEnterBattleArena(); // бой идёт в полноэкранной арене, как в оригинале
    // Send each stack's board position so the server simulates on the user's actual layout
    // (its playable area matches the tactic pad's 1-based coords up to 14×10). Размер поля
    // передаём явно: на сервере под него строится своя сетка (battle/grid/_constants.py FIELD_PRESETS).
    const sendPositions = tacFitsServerGrid();
    const playerStacks = tacSidePayload(battleBoard.stackPositions, 'player', sendPositions);
    const enemyStacks = tacSidePayload(battleBoard.stackPositions, 'enemy', sendPositions);
    const playerHero = tacGetHeroData();
    const enemyHero = tacGetEnemyHeroData();
    const payload: any = { field: { cols: tacCfg.col, rows: tacCfg.row }, player: playerHero ? { hero: playerHero, stacks: playerStacks } : playerStacks };
    payload.enemy = enemyHero ? { hero: enemyHero, stacks: enemyStacks } : { stacks: enemyStacks };
    try {
      const res = await fetch('/api/simulate', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      const data = await res.json();
      if (data.error) {
        // Ошибка сервера может содержать эхо пользовательского ввода — только
        // как text: innerHTML здесь давал reflected XSS через invalid count.
        resultDiv.innerHTML = '';
        var errDiv = document.createElement('div');
        errDiv.style.color = '#ff6b6b';
        errDiv.textContent = data.error;
        resultDiv.appendChild(errDiv);
        status.textContent = '❌ Ошибка';
        tacSetPlaybackRunning(false);
        tacLeaveBattleArena();
        return;
      }
      // Что сервер сделал с набором навыков героя: применил, пропустил как
      // внебоевое или не умеет. Без этой строки перк «выучен, а в бою ничего»
      // читался бы как баг.
      tacShowPerkReport(data.perks && data.perks.player);
      // Render walls and terrain from server
      windowObj.tacClearTerrain();
      windowObj.tacRenderWalls(data.walls, data.terrain, data.field_objects);
      const baseDelay = 600;
      window._movLines = [];
      // NB: data.movement (out-of-band whole-battle move summary) is deliberately unused now —
      // the server emits ordered 'move' actions inside data.actions, replayed like any other.
      tacBuildTurnQueue(data.actions);
      // Клетки одного взмаха («Убийственные брызги») склеиваются в одно действие —
      // отсюда и счётчик ходов идёт по пачкам, а не по сырым записям сервера.
      const steps = tacCoalesceActions(data.actions);
      status.textContent = `⚔ Воспроизведение... 0/${steps.length}`;
      for (let i = 0; i < steps.length; i++) {
        // Отмена хореографии (выход из боя) обрывает реплей на текущем шаге:
        // досматривать хвост боя после выхода незачем.
        if (tacChainsCancelled()) break;
        const delay = baseDelay / tacAnimSpeed;
        const { a, also } = steps[i];
        status.textContent = `⚔ Ход ${i + 1}/${steps.length}`;
        await windowObj.tacAnimateAction(a, delay, also);
      }
      status.textContent = `✅ Завершён за ${data.rounds} раундов`;
      // Поле НЕ сбрасываем: остаются выжившие на конечных позициях и трупы павших.
      // Исходная расстановка вернётся при следующем нажатии «в бой».
      hs.savedSetup = tacOriginalState;
      hs.endStateShown = true;
      tacRenderUnits();
      // Добавляем итог во already visible resultDiv вместо замены
      let finalHtml = '<hr style="border-color:var(--gold-dim);margin:8px 0">';
      if (data.winner === 'draw') finalHtml += '<div style="color:#ff9800;font-weight:700;font-size:18px;text-align:center;padding:8px">НИЧЬЯ</div>';
      else finalHtml += `<div style="color:#4caf50;font-weight:700;font-size:18px;text-align:center;padding:8px">ПОБЕДА: ${data.winner === 'player' ? '⚔ Игрок' : '☠ Противник'}</div>`;
      finalHtml += `<div style="color:var(--text-dim);text-align:center;font-size:14px;margin-bottom:8px">Раундов: ${data.rounds}</div>`;
      // battleHelper: итоговая таблица урона по отрядам — под галкой, как
      // остальные вероятности. Сервер собирает её в damage_table; здесь только
      // рисуем строки (отряд, урон, убийства) по командам.
      if (tacShowBhProbs && data.damage_table && data.damage_table.length) {
        finalHtml += tacDamageTableHtml(data.damage_table);
      }
      // Единый лог уже построен по ходу реплея (цвета команд); повторный дамп
      // сырого серверного лога дублировал каждое событие вторым форматом.
      finalHtml += `<div style="text-align:center;padding:8px 0 4px;margin-top:8px"><button onclick="tacCopyLog()" style="padding:6px 16px;background:rgba(201,168,76,0.15);border:1px solid var(--gold);border-radius:6px;color:var(--gold);font-size:13px;cursor:pointer;font-family:inherit">📋 Копировать лог</button></div>`;
      resultDiv.insertAdjacentHTML('beforeend', finalHtml);
      resultDiv.scrollTop = resultDiv.scrollHeight;
    } catch (e) {
      status.textContent = '❌ Ошибка';
      resultDiv.insertAdjacentHTML('beforeend', `<hr style="border-color:var(--border);margin:8px 0"><div style="color:#ff6b6b">${(e as Error)?.message || e}</div>`);
      resultDiv.scrollTop = resultDiv.scrollHeight;
    }
    sndStopMusic();
    tacSetPlaybackRunning(false);
    // Возврат из полноэкранной арены; toggle сам форс-пересчитает раскладку, а если
    // арена была включена вручную — подхватываем отложенный ресайз обычным fit'ом.
    tacLeaveBattleArena();
    tacFitField();
    // The guarded tacRenderInitiative was a no-op during the replay (the strip showed the
    // ATB queue) — restore the regular by-initiative view now that the battle is over.
    tacTurnQueue = [];
    tacTurnPos = -1;
    // Бой кончился — гасим ход героя, иначе фигура осталась бы золотой в
    // расстановке следующего боя. Комментарий прежде обещал, что отрисовку
    // фигур дозовёт лента, но `tacClearInitiative` чистит только саму ленту —
    // свечение снимал только с `tacHeroActing`, а класс `--ready` на фигуре
    // оставался до следующей перерисовки. Стоило того: е2e «hero figure lights
    // up on his cast» ловил золотую фигуру в расстановке после боя, когда
    // последним действием реплея был каст героя.
    (window as any).tacHeroActing = null;
    tacRenderHeroFigures();
    // Ленту НЕ пересобираем: бой окончен, и очередь из уцелевших — не очередь.
    tacClearInitiative();
    tacReconcileSprites();
  };

  /** Сверить живые спрайты с доской НА МЕСТЕ — без пересоздания.
   *
   * Раньше после каждого хода человека все спрайты уничтожались и монтировались
   * заново (`tacRemountSprites`): отряды мигали портретом и сбрасывали позу —
   * то самое «поле дёргается». Пересборка была нужна только чтобы вернуть
   * «живое» поле к моменту хода: погасить зависший жест, развернуть отряд к
   * своей стороне, поднять idle. Всё это делается на существующих объектах;
   * переезды (handoff мувера), численность, трупы и фантомы обновляются в
   * своих местах и без неё. Спрайт создаётся, только если на клетке со стеком
   * его нет вовсе (сорвавшийся handoff), и уничтожается, если стека под ним
   * больше нет.
   *
   * Разворот ставится сразу, если отряд стоит; доигрывающему жесту (стрельба
   * в конце хода, `stopwalk` прибытия) даём закончиться и разворачиваем следом —
   * тот же приём, что у `tacArriveStopwalk`. */
  function tacReconcileSprites() {
    const alive = new Set<string>();
    for (let r = 0; r < battleBoard.data.length; r++) {
      if (!battleBoard.data[r]) continue;
      for (let c = 0; c < battleBoard.data[r].length; c++) {
        const cell = battleBoard.data[r][c];
        if (!cell || cell === true || cell === false || cell.id === undefined) continue;
        const u = TACTIC_UNITS[cell.id];
        const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
        if (!u || !td) continue;
        const key = r + '_' + c;
        alive.add(key);
        const h: any = tacFieldSprites.get(key);
        if (!h || h.failed || !h.scene) {
          tacMountFieldSprite(r, c, u.pic, td, cell.team || 1, u.big);
          continue;
        }
        const team = cell.team || 1;
        const mirror = (team === 1 || team === 3 || team === 5);
        const obj = h.obj;
        h.cell = { row: r, col: c };
        h.zBoost = 0;
        if (obj) {
          obj.attacker = 0;
          if (obj.doing && obj.doing !== 'free1' && obj.doing !== 'free2'
              && obj.doing !== 'stopwalk' && obj.doing.substr(0, 5) !== 'shoot'
              && obj.doing.substr(0, 6) !== 'attack' && obj.doing !== 'back' && obj.doing !== 'miss') {
            // Жест, которому нечего доигрывать (walk без мувера, cast без цели) — сброс.
            obj.doing = ''; obj.lastdoing = ''; obj.frame = 0;
          }
        }
        const a = sceneCellAnchor(td);
        if (a) h.setAnchor(a);
        h.enableIdle();
        if (!obj || !obj.doing || obj.doing === 'free1' || obj.doing === 'free2') {
          h.setMirror(mirror);
        } else {
          (async () => {
            const t0 = performance.now();
            while (h.obj && h.obj.doing && h.obj.doing !== 'free1' && h.obj.doing !== 'free2'
                   && performance.now() - t0 < 2500) {
              await new Promise(res => setTimeout(res, 50));
            }
            if (tacFieldSprites.get(key) === h) h.setMirror(mirror);
          })();
        }
        if (h.ready && td.style.backgroundImage) td.style.backgroundImage = '';
      }
    }
    for (const key of [...tacFieldSprites.keys()]) {
      if (!alive.has(key)) tacDestroyFieldSprite(...key.split('_').map(Number) as [number, number]);
    }
    tacSyncNumbers();
  }

  // Полная пересборка спрайтов — только когда сетка и вправду пересоздана
  // (tacResetBoard/смена поля). После хода боя её больше не зовут: см.
  // tacReconcileSprites — прежний ремаунт после КАЖДОГО хода мигал отрядами.
  function tacRemountSprites() {
    for (let r = 0; r < battleBoard.data.length; r++) {
      if (!battleBoard.data[r]) continue;
      for (let c = 0; c < battleBoard.data[r].length; c++) {
        const cell = battleBoard.data[r][c];
        if (!cell || cell === true || cell === false || cell.id === undefined) continue;
        const u = TACTIC_UNITS[cell.id];
        const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
        if (u && td) tacMountFieldSprite(r, c, u.pic, td, cell.team || 1, u.big);
      }
    }
  }

  // ── Real ATB turn queue for the initiative strip ──
  // Built from the ordered action stream (every acting stack's action carries round/turn),
  // so the strip shows the actual upcoming turn order — like the original ATB bar — instead
  // of a static by-initiative forecast.
  let tacTurnQueue: any[] = [];
  let tacTurnPos = -1;
  function tacBuildTurnQueue(actions: any) {
    tacTurnQueue = [];
    tacTurnPos = -1;
    let lastKey = null;
    for (const act of actions || []) {
      const actorIdx = act.attacker_idx !== undefined ? act.attacker_idx : act.stack_idx;
      const isHeroAct = act.type === 'hero_skill';
      // Ход героя — отдельная запись ленты: side в действии ставит движок.
      if (actorIdx === undefined && !isHeroAct) continue;
      if (act.round === undefined || act.turn === undefined) continue;
      const key = act.round + '_' + act.turn;
      // First action of each (round, turn) names the acting stack (moves/morale precede the
      // attack; retaliation shares the attacker's turn key and is correctly skipped here).
      if (key !== lastKey) {
        tacTurnQueue.push(isHeroAct
          ? { key, hero: act.side, round: act.round }
          : { key, idx: actorIdx, round: act.round });
        lastKey = key;
      }
    }
  }
  function tacRenderTurnRibbon() {
    const cont = tacById('tac-initiative');
    if (!cont || tacTurnPos < 0 || !tacTurnQueue.length) return;
    // The user may scroll the ribbon forward to peek at future turns — preserve that
    // position across per-turn re-renders and only auto-follow the current turn while
    // they're parked at the start. (Snapping to 0 on every render made the ribbon
    // effectively unscrollable during a replay.)
    const keepScroll = cont.scrollLeft > 10 ? cont.scrollLeft : 0;
    const upcoming = tacTurnQueue.slice(tacTurnPos, tacTurnPos + 120);
    // Подписи «Очередь:» тут больше нет — в оригинале лента без заголовка, а метки
    // раундов внутри ряда и так объясняют, что это очередь ходов.
    let html = '';
    let prevRound: any = null;
    upcoming.forEach((t, i) => {
      // Фишка героя: у него нет stackPositions — рисуем по фракции из панелей.
      if (t.hero !== undefined) {
        const info = heroChipInfo(t.hero as 0 | 1);
        html += `<div class="tac-init-unit tac-init-hero${i === 0 ? ' tac-init-active' : ''}"
                      data-hero-side="${t.hero}"
                      style="${tacTeamChipStyle(t.hero === 0 ? 1 : 2)}"
                      title="${info ? info.name : 'Герой'} · ход героя">
          ${info ? heroChipFace(info) : ''}
          <span class="tac-init-cnt">⚔</span>
        </div>`;
        return;
      }
      const p = battleBoard.stackPositions[t.idx];
      if (!p) return;
      if (t.round !== prevRound) {
        html += `<span class="tac-init-round">Р${t.round}</span>`;
        prevRound = t.round;
      }
      html += `<div class="tac-init-unit${i === 0 ? ' tac-init-active' : ''}" data-idx="${t.idx}"
                    style="${tacTeamChipStyle(p.team)}"
                    title="${p.nameRu} ×${p.cnt || ''}">
        <img src="${tacPortraitUrl(p.pic)}" alt="">
        <span class="tac-init-cnt">${p.cnt || '?'}</span>
      </div>`;
    });
    cont.innerHTML = html;
    cont.scrollLeft = keepScroll;
    tacUpdateInitScroll();
  }
  /** Свечение фигуры героя в цельном реплее.
   *
   * Наполнения шкалы в потоке действий нет — есть только сами касты, поэтому
   * фигура горит на КАСТЕ своего героя и гаснет, когда ход переходит к отряду.
   * Сторону каста ставит движок (`side` в `spell_damage`/`hero_skill`): без неё
   * непонятно, чей это герой, и раньше в реплее не подсвечивался никто.
   *
   * Тушим только по действию, которое несёт свой ход (round+turn) и не является
   * кастом: у каста есть хвост из последствий («destroyed», отброс по шкале),
   * и по нему свет гас бы прямо посреди собственного заклинания. */
  function tacHeroCastGesture(a: any) {
    const side = tacHeroActionSide(a);
    if (side === null) return;
    if (HERO_ATTACK_TYPES.indexOf(a.type) >= 0) { tacHeroFigureAttack(side); return; }
    if (!tacHeroCastGestureWanted(a)) return;
    tacHeroFigureCast(side);
  }
  function tacHeroGlowFromAction(a: any) {
    // Сессионные режимы ведут свечение по настоящему hero_ready от движка —
    // очередь там строит сервер, и tacTurnQueue пуст.
    if (!tacTurnQueue.length) return;
    const cur = (window as any).tacHeroActing ?? null;
    let next = cur;
    const side = tacHeroActionSide(a);
    if (side !== null) next = side;
    else if (a.round !== undefined && a.turn !== undefined) next = null;
    if (next === cur) return;
    (window as any).tacHeroActing = next;
    tacRenderHeroFigures();
  }

  function tacAdvanceTurnRibbon(a: any) {
    tacHeroCastGesture(a);
    tacHeroGlowFromAction(a);
    if (a.round === undefined || a.turn === undefined || !tacTurnQueue.length) return;
    const key = a.round + '_' + a.turn;
    for (let qi = Math.max(tacTurnPos, 0); qi < tacTurnQueue.length; qi++) {
      if (tacTurnQueue[qi].key === key) {
        if (qi !== tacTurnPos) {
          tacTurnPos = qi;
          tacRenderTurnRibbon();
        }
        return;
      }
    }
  }

  // Наложения выбора угла атаки вынесены в ./battleOverlay.js. Состояние они
  // берут из battleHotseatState напрямую, отсюда нужны футпринт 2×2 и клетка
  // доски по координате.
  initBattleOverlay({ tacHsFootprint, getCell });
  // Ввод вынесен в ./battleHotseatInput.js. Оттуда нужны только выходы хода и
  // помощники доски — всё прочее состояние обе стороны берут из battleHotseatState.
  // Игровой цикл вынесен в ./battleHotseatCycle.js. Оттуда нужны помощники
  // доски, оставшиеся здесь: сканирование, сброс, предзагрузка, сборка запроса.
  // Спрайты вынесены в ./battleFieldSprites.js. Оттуда нужен только обмен
  // живым спрайтом при переезде отряда — он переприсваивается, поэтому аксессор.
  initFieldSprites({
    get tacSpriteHandoff() { return tacSpriteHandoff; },
    set tacSpriteHandoff(v) { tacSpriteHandoff = v; },
    // Пересчёт раскладки двигает КЛЕТКИ, а спрайты и числа стоят по экранным
    // якорям, снятым при монтаже. Пока доска почти не двигалась, расхождение
    // было незаметно; теперь она ставится абсолютом по формулам оригинала и на
    // первом же расчёте уезжает на сотни пикселей — отряды оставались висеть
    // на старом месте. После смены геометрии оба слоя пересобираются по клеткам.
    tacReconcileSprites, tacRemountSprites, tacSyncNumbers,
  });
  initHotseatCycle({
    tacClearCorpses, tacFitsServerGrid, tacPreloadBoardAnims, tacReconcileSprites,
    tacResetBoard, tacScanBoard, tacSidePayload, tacCfg,
    // Помощники доски, нужные циклу: перечислены в battleHotseatCycle.ts до
    // статического импорта — теперь приходят внедрением (без двухсторонней
    // зависимости battle.ts ↔ battleHotseatCycle.ts).
    getCell, tacAnimSpeed, tacEnterBattleArena, tacLeaveBattleArena, tacDockTurnButtons,
    tacClearInitiative, tacHeroFigureCast, tacRenderHeroFigures, tacTeamColor, tacTeamChipStyle,
    tacUpdateInitScroll, tacRollObstacles,
    // Отрисовка стен и грунта живёт на windowObj: её зовёт и обычный реплей.
    tacRenderWalls: windowObj.tacRenderWalls,
    // Разметка огня/ловушек/туч по снапшоту — тоже общая с реплеем.
    tacSyncFieldObjects: windowObj.tacSyncFieldObjects,
  });
  initHotseatInput({ tacHsAct, tacHsRender, tacHsDefend, tacHsWait, tacHsArmHeroAttack, getCell, tacCfg, tacUnitTooltip });

  // Анимация вынесена в ./battleAnim.js. Здесь — единственная точка связи: список
  // имён, которые ей нужны от battle.ts. Изменяемые она читает через объект, а не
  // копией, иначе после переприсваивания видела бы старое значение.
  initBattleAnim({
    TACTIC_UNITS, getCell, tacAnimHas, tacApplyStackState, tacCfg,
    tacDestroyFieldSprite, tacDetachFieldSprite, tacFieldSprites, tacHighlightInitiative,
    tacLogLine, tacMountFieldSprite, tacNameSpan, tacPortraitUrl, tacPutUnit, tacRemoveUnit,
    tacRenderInitiative, tacRenderUnits, tacShootLaunchFraction, tacSpriteSize,
    tacUnitMsPerCell, tacAdvanceTurnRibbon,
    get tacAnimSpeed() { return tacAnimSpeed; },
    get tacSpriteHandoff() { return tacSpriteHandoff; },
    set tacSpriteHandoff(v) { tacSpriteHandoff = v; },
  });
  windowObj.tacAnimateAction = tacAnimateAction;
  // Мост для e2e: «идёт ли проигрывание» спрашивали у прежнего глобального
  // window.tacAnimating, которого больше нет. Статус берётся из состояния
  // (battleState), а не из глобальной переменной окна. (tacHsSurrender на
  // window уже есть — его выставляет exposeLive в main.ts, второй раз
  // присваивать нельзя: свойство только на чтение, и падение обрывало всю
  // инициализацию страницы.)
  windowObj.tacPlaybackRunning = tacPlaybackRunning;
}

