export let PIC_TO_SYSNAME: Record<string, string> = {};

/** Preload creature animation assets in background to speed up modal opening.
 * Iterates through all factions and their creatures, loading sprite sheets
 * and animation data into the browser/CDN cache.
 *
 * - Prioritizes the faction the user is currently viewing (from the URL), so
 *   the creatures they're most likely to open next warm up first instead of
 *   racing 30+ other factions for the same bandwidth.
 * - Schedules batches via requestIdleCallback (falling back to setTimeout in
 *   browsers without it, e.g. Safari) so this never steals main-thread/network
 *   time from the user's own clicks and scrolling.
 * - Backs off entirely on metered/slow connections (Network Information API:
 *   saveData or a 2G-class effectiveType), where preloading ~250 creatures'
 *   worth of sprite data unconditionally would just burn the user's data cap. */
let _preloadStarted = false;

export function preloadAllCreatureAnims(): void {
  // Idempotent: called from navigation on every activation of a tab that needs warm
  // sprite caches (battle/creatures/factions) — only the first call starts the sweep.
  if (_preloadStarted) return;
  _preloadStarted = true;
  var conn = (navigator as any).connection;
  if (conn && (conn.saveData || /(^|-)2g$/.test(conn.effectiveType || ''))) {
    console.log('[preload] Skipping creature animation preload (data saver / slow connection)');
    return;
  }

  // Import preloadCreatureAnim dynamically to avoid circular deps
  import('./creatureAnim.js').then(function(mod) {
    var preloadCreatureAnim = mod.preloadCreatureAnim;
    if (!allData.units || !allData.unitsByFaction) return;

    // Collect all unique animUnits, grouped by faction, so we can reorder
    // (not filter — everything still gets preloaded eventually) to put the
    // faction currently on screen first.
    var animUnitsByFaction: Record<string, string[]> = {};
    var seen = new Set<string>();

    for (var factionKey of Object.keys(allData.unitsByFaction)) {
      var tiers = allData.unitsByFaction[factionKey];
      var list: string[] = [];
      for (var tierKey of Object.keys(tiers)) {
        var cols = tiers[tierKey];
        for (var colKey of Object.keys(cols)) {
          var sysNames = cols[colKey];
          for (var sysName of sysNames) {
            var unit = allData.units[sysName];
            if (!unit) continue;
            var animUnit = (unit as any).animUnit || (unit as any).anim_unit || '';
            if (animUnit && !seen.has(animUnit) && !/^https?:\/\//i.test(animUnit) && !/\.(png|jpe?g|gif|webp)(\?.*)?$/i.test(animUnit)) {
              seen.add(animUnit);
              list.push(animUnit);
            }
          }
        }
      }
      if (list.length) animUnitsByFaction[factionKey] = list;
    }

    // Figure out which faction (if any) is currently being viewed from the URL.
    var currentFaction = '';
    var path = appPath();
    if (path.startsWith('/factions/')) {
      // The URL segment is FACTIONS_META[...].nameEn ("Necromancers" — see the faction
      // links built in creatures.ts/factions.ts), NOT the internal key ("necromance")
      // that animUnitsByFaction is keyed by. Resolve it the way renderFactionTable does,
      // otherwise the priority lookup below silently misses on every /factions/ route —
      // the one place the user is literally staring at that faction's creatures.
      var seg = decodeURIComponent(path.split('/factions/')[1] || '').toLowerCase();
      for (var fmKey of Object.keys(FACTIONS_META)) {
        if ((FACTIONS_META[fmKey].nameEn || '').toLowerCase() === seg) { currentFaction = fmKey; break; }
      }
      if (!currentFaction) currentFaction = seg; // already an internal key
    } else if (path.startsWith('/units/')) {
      var openSysName = path.split('/units/')[1] || '';
      currentFaction = (allData.units[openSysName] as any)?.fraction || '';
    }

    var animUnits: string[] = [];
    if (currentFaction && animUnitsByFaction[currentFaction]) {
      animUnits = animUnits.concat(animUnitsByFaction[currentFaction]);
    }
    for (var fk of Object.keys(animUnitsByFaction)) {
      if (fk === currentFaction) continue;
      animUnits = animUnits.concat(animUnitsByFaction[fk]);
    }

    // Preload in small batches, and — critically — wait for each batch's assets to actually
    // finish downloading before starting the next (preloadCreatureAnim returns a completion
    // promise). The previous version scheduled batches purely on requestIdleCallback timing
    // (~3 units/second regardless of network progress), which within a couple of minutes had
    // ~600 asset requests in flight. That saturated the browser's 6-connections-per-origin
    // budget for the whole page: sprites the user was actually looking at (battle field stacks,
    // movement animations) queued for 10+ seconds behind the preload firehose, and the resulting
    // transient failures fed enginep.js's (formerly URL-mangling) retry path, permanently
    // breaking the first ~60 creatures' atlases. Completion-gating keeps at most BATCH_SIZE
    // asset pipelines open, so on-screen sprites always have connections available.
    var BATCH_SIZE = 3;
    var index = 0;

    function loadBatch() {
      var batch: Promise<void>[] = [];
      while (index < animUnits.length && batch.length < BATCH_SIZE) {
        try {
          batch.push(preloadCreatureAnim(animUnits[index]));
        } catch (e) { /* ignore */ }
        index++;
      }
      Promise.all(batch).then(function() {
        if (index < animUnits.length) scheduleNext();
      });
    }

    function scheduleNext() {
      if (typeof (window as any).requestIdleCallback === 'function') {
        (window as any).requestIdleCallback(function() { loadBatch(); }, { timeout: 1000 });
      } else {
        setTimeout(function() { loadBatch(); }, 200);
      }
    }

    // Start preloading after a short delay to not block initial render.
    setTimeout(scheduleNext, 1000);
    console.log('[preload] Starting preload of', animUnits.length, 'creature animations' + (currentFaction ? ' ("' + currentFaction + '" first)' : ''));
  }).catch(function() {
    // creatureAnim.js not loaded yet or error — skip preload
  });
}

