import { allData, PIC_TO_SYSNAME, preloadAllCreatureAnims } from './data.js';
import { initCreatures, filterCreatures, tryOpenCreature, closeCreatureModal } from './creatures.js';
import { initArtifacts, filterArtifacts, openArtifactModal, closeArtifactModal, renderSetsGrid, renderSetDetail, resolveSetAnchor } from './artifacts.js';
import { initAbilities, filterAbilities, renderAbilityDetail } from './abilities.js';
import { initMagic, filterMagic, openMagicModal } from './magic.js';
import { initStubs } from './stubs.js';
import { initBattle, setupTacSimulate } from './battle.js';
import { tacApplyCodeFromURL } from './battleCode.js';
import { ensureFittingRoom, closeFittingPicker } from './fitting.js';
import { swInit } from './skillwheels.js';
import { renderFactions, renderFactionTable } from './factions.js';
import { appPath, siteUrl } from './basePath.js';
import { tacSetPlaybackRunning } from './battleState.js';

const ROUTES: Record<string, string> = {
  '/': 'creatures',
  '/units': 'creatures',
  '/factions': 'factions',
  '/artifacts': 'artifacts',
  '/sets': 'artifacts',
  '/book_of_magic': 'magic',
  '/abilities': 'abilities',
  '/stubs': 'stubs',
  '/battle': 'battle',
  '/replay': 'replay',
  '/fitting': 'fitting',
  '/fitting/': 'fitting',
  '/dressroom': 'fitting',
  '/dressroom/': 'fitting',
  '/n/dressroom': 'fitting',
  '/n/dressroom/': 'fitting',
  '/skillwheels': 'skillwheels',
};

function normalizeRoutePath(path: string): string {
  return (path || '/').replace(/\/+$/, '') || '/';
}

function routeTab(path: string): string {
  const cleanPath = normalizeRoutePath(path);
  if (cleanPath.startsWith('/abilities/')) return 'abilities';
  if (cleanPath.startsWith('/units/')) return 'creatures';
  if (cleanPath.startsWith('/factions/')) return 'factions';
  if (cleanPath.startsWith('/magics/')) return 'magic';
  if (cleanPath.startsWith('/artifacts/')) return 'artifacts';
  // Комплекты живут внутри артефактов; старые ссылки /sets/<якорь> работают.
  if (cleanPath.startsWith('/sets/')) return 'artifacts';
  if (cleanPath.startsWith('/skillwheels')) return 'skillwheels';
  // /battle и /battle/<код расстановки> — одна вкладка боя.
  if (cleanPath === '/battle' || cleanPath.startsWith('/battle/')) return 'battle';
  const tab = ROUTES[cleanPath];
  if (tab) return tab;
  const errPath = document.getElementById('error-path');
  if (errPath) errPath.textContent = path;
  return 'error';
}

// Lazy per-tab rendering. Tab content used to be built for EVERY tab at startup
// (init() → initCreatures/initArtifacts/initSets/initMagic/initBattle/initFitting all
// rendered their full grids eagerly), which put ~20 000 <img> in the DOM before the user
// saw anything — opening /battle also built the whole hidden bestiary (~16k imgs), the
// artifacts grid, sets, etc. Now each tab's default view renders once, on first activation;
// the init* functions only wire up filters/handlers. Route handlers (renderPath /
// handleInitialRoute) still re-render the active tab's specific view on top as before.
const renderedTabs = new Set<string>();
const TAB_RENDERERS: Record<string, () => void> = {
  creatures: () => {
    // Deep links to a single creature (/units/xxx) open a modal — don't build the full
    // grid behind it (same rule the old eager initCreatures applied).
    if (!appPath().match(/^\/units\/.+/)) filterCreatures(true);
  },
  artifacts: () => filterArtifacts(true),
  magic: () => filterMagic(),
  stubs: () => { void initStubs(); },
  fitting: () => ensureFittingRoom(),
  battle: () => {
    initBattle();
    // Применяем только после того, как геометрия вкладки боя устоялась. По
    // прямой ссылке /battle/<код> поле встаёт в несколько приёмов уже ПОСЛЕ
    // запуска приложения (шрифты, картинки, шапка сжимаются — `--arena-k` и
    // позиция канваса меняются). Если строить сетку в первый же тик, якоря
    // спрайтов снимаются на переходной геометрии и жёстко кэшируются
    // сдвинутыми на ВСЕ отряды — так URL-ссылка открывалась «сбитой разметкой»
    // (замер: применение к ≤200мс от старта — спрайты сдвинуты на −956/−126
    // логических px, к ≥400мс — точно). Событие load тут не рубеж: канвас
    // оседает ещё пару сотен миллисекунд после него.
    applyBattlePlacementWhenSettled();
  },
  skillwheels: () => swInit(),
};
// Tabs whose content actually benefits from warm creature-sprite caches: the battle
// palette and the creature-card modal (opened from creatures/factions). Other routes
// don't pay for the 544-creature background preload at all.
const PRELOAD_TABS = new Set(['battle', 'creatures', 'factions']);

/** Применить расстановку из адреса (/battle/<код>) после устаканивания
 * геометрии поля. Применение в первый же тик ловило канвас в переходном
 * состоянии (шапка сжимается, `--arena-k` доезжает до окна), якоря спрайтов
 * кэшировались сдвинутыми на все отряды — прямая ссылка открывалась «сбитой
 * разметкой». Ждём, пока ширина обёртки поля не перестанет меняться пару
 * кадров подряд — «геометрия устоялась» без магических таймаутов. */
function applyBattlePlacementWhenSettled(): void {
  let last = -1;
  let stable = 0;
  const tick = (): void => {
    const wrap = document.getElementById('tac-field-wrap');
    const w = wrap ? wrap.getBoundingClientRect().width : 0;
    if (w > 0 && Math.abs(w - last) <= 1) {
      if (++stable >= 2) {
        try { tacApplyCodeFromURL(); } catch (e) { console.error('apply battle code:', e); }
        return;
      }
    } else {
      stable = 0;
      last = w;
    }
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}

function ensureTabRendered(name: string): void {
  if (PRELOAD_TABS.has(name)) preloadAllCreatureAnims(); // idempotent
  if (renderedTabs.has(name)) return;
  renderedTabs.add(name);
  try { TAB_RENDERERS[name]?.(); } catch (e) { console.error('tab render failed:', name, e); }
}

function switchTab(name: string): void {
  document.querySelectorAll('.tab').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tab-content').forEach(tc => tc.classList.remove('active'));
  const tabEl = document.querySelector(`.tab[data-tab="${name}"]`);
  if (tabEl) tabEl.classList.add('active');
  const contentEl = document.getElementById('tab-' + name);
  if (contentEl) contentEl.classList.add('active');
  ensureTabRendered(name);
  // Кнопка «во весь экран» показывается только на вкладке боя; уходя с неё, обязательно
  // выключаем сам режим — иначе шапка и вкладки остались бы скрытыми на других вкладках.
  document.body.classList.toggle('tac-on-battle', name === 'battle');
  if (name !== 'battle' && document.body.classList.contains('tac-full-field')
      && typeof (window as any).tacToggleFullField === 'function') {
    (window as any).tacToggleFullField(false);
  }
  // The battle grid is created while its tab is hidden (widths read as 0), so the
  // fit-to-viewport pass must re-run once the tab actually becomes visible.
  if (name === 'battle' && typeof (window as any).tacFitField === 'function') {
    requestAnimationFrame(() => (window as any).tacFitField());
  }
}

function renderPath(path: string): void {
  if (path === '/units') {
    (document.getElementById('faction-filter') as HTMLSelectElement).value = '';
    (document.getElementById('creature-search') as HTMLInputElement).value = '';
    (document.getElementById('tier-filter') as HTMLSelectElement).value = '';
    filterCreatures(true);
    return;
  }
  if (path === '/artifacts') {
    (document.getElementById('artifact-search') as HTMLInputElement).value = '';
    (document.getElementById('slot-filter') as HTMLSelectElement).value = '';
    (document.getElementById('category-filter') as HTMLSelectElement).value = '';
    (document.getElementById('level-filter') as HTMLSelectElement).value = '';
    filterArtifacts(true);
    return;
  }
  if (path === '/abilities') {
    filterAbilities(true);
    return;
  }
  if (path.startsWith('/abilities/') && path !== '/abilities') {
    const key = path.split('/abilities/')[1];
    if (key && allData.abilities && allData.abilities[key]) { renderAbilityDetail(key); return; }
    filterAbilities();
    return;
  }
  if (path.startsWith('/artifacts/') && path !== '/artifacts') {
    const key = path.split('/artifacts/')[1];
    if (key && allData.artifacts) {
      const artifact = Array.isArray(allData.artifacts) 
        ? allData.artifacts.find(a => a.key === key)
        : allData.artifacts[key];
      if (artifact) { openArtifactModal(key); return; }
    }
    filterArtifacts();
    return;
  }
  if (path.startsWith('/units/')) {
    const name = path.split('/units/')[1];
    if (name && tryOpenCreature(name)) { 
      const gridEl = document.getElementById('creature-grid');
      const countEl = document.getElementById('creature-count');
      if (gridEl) gridEl.innerHTML = '';
      if (countEl) countEl.textContent = '';
      return; 
    }
    renderFactionTable(name);
    return;
  }
  if (path.startsWith('/magics/')) {
    const key = path.split('/magics/')[1];
    if (key && allData.magics && allData.magics[key]) { openMagicModal(key); return; }
    switchTab('magic');
    filterMagic();
    return;
  }
  if (path.startsWith('/factions/')) {
    // Имя фракции в адресе закодировано («Dark%20Elves»): без декодирования
    // двухсловные фракции не находились — открывалось «Фракция не найдена».
    const name = decodeURIComponent(path.split('/factions/')[1] || '');
    if (name) renderFactionTable(name);
    return;
  }
  // Старые адреса комплектов ведут в раздел артефактов, где они теперь и живут.
  if (path === '/sets') {
    filterArtifacts();
    return;
  }
  if (path.startsWith('/sets/') && path !== '/sets') {
    const idOrAnchor = path.split('/sets/')[1];
    const resolved = resolveSetAnchor(idOrAnchor);
    if (resolved !== null) { renderSetDetail(idOrAnchor); return; }
    filterArtifacts();
    return;
  }
  if (path === '/fitting' || path === '/fitting/' || path === '/dressroom' || path === '/dressroom/' || path === '/n/dressroom' || path === '/n/dressroom/') {
    ensureFittingRoom();
    return;
  }
  if (path === '/skillwheels' || path.startsWith('/skillwheels/')) {
    // /skillwheels/<фракция>[/<класс>] — колесо открывается прямо из адреса.
    var parts = path.split('/').filter(Boolean).slice(1);
    swInit(parts[0], parts[1] !== undefined ? parseInt(parts[1], 10) : undefined);
    return;
  }
  const tab = routeTab(path);
  if (tab === 'creatures') filterCreatures();
  else if (tab === 'factions') renderFactions();
  else if (tab === 'artifacts') filterArtifacts();
  else if (tab === 'abilities') filterAbilities();
  else if (tab === 'fitting') ensureFittingRoom();
  else if (tab === 'skillwheels') swInit();
}

function navigateTo(path: string): void {
  if (appPath() === path) return;
  if (path === '/creatures') { navigateTo('/units'); return; }
  try { closeCreatureModal(); } catch(e) {} 
  try { closeArtifactModal(); } catch(e) {}
  try { closeFittingPicker(); } catch(e) {}
  try {
    const tab = routeTab(path);
    switchTab(tab);
    history.pushState(null, '', siteUrl(path));
    if (tab === 'error') return;
  } catch(e) { return; }
  renderPath(path);
}

function handleInitialRoute(): void {
  const path = appPath();
  const tab = routeTab(path);
  switchTab(tab);
  if (tab === 'error') return;
  if (path.startsWith('/abilities/') && path !== '/abilities') {
    const key = path.split('/abilities/')[1];
    if (key && allData.abilities && allData.abilities[key]) {
      renderAbilityDetail(key);
    } else {
      filterAbilities(true);
    }
  } else if (path.startsWith('/artifacts/') && path !== '/artifacts') {
    const key = path.split('/artifacts/')[1];
    if (key && allData.artifacts) {
      const artifact = Array.isArray(allData.artifacts)
        ? allData.artifacts.find(a => a.key === key)
        : allData.artifacts[key];
      if (artifact) {
        openArtifactModal(key);
      } else {
        filterArtifacts(true);
      }
    } else {
      filterArtifacts(true);
    }
  } else if (path.startsWith('/units/')) {
    const name = path.split('/units/')[1];
    if (!name || !tryOpenCreature(name)) {
      if (tab === 'creatures') renderFactionTable(name);
    }
  } else if (path.startsWith('/factions/')) {
    // Имя фракции в адресе закодировано («Dark%20Elves»): без декодирования
    // двухсловные фракции не находились — открывалось «Фракция не найдена».
    const name = decodeURIComponent(path.split('/factions/')[1] || '');
    if (name) renderFactionTable(name);
  } else if (path.startsWith('/sets/') && path !== '/sets') {
    const idOrAnchor = path.split('/sets/')[1];
    const resolved = resolveSetAnchor(idOrAnchor);
    if (resolved !== null) {
      renderSetDetail(idOrAnchor);
    } else {
      filterArtifacts(true);
    }
  } else if (tab === 'abilities') {
    filterAbilities(true);
  } else if (tab === 'creatures' && !path.startsWith('/units/') && !path.startsWith('/factions/')) {
    filterCreatures(true);
  } else if (tab === 'fitting') {
    ensureFittingRoom();
  } else if (tab === 'skillwheels') {
    // Колесо из адреса: /skillwheels/<фракция>[/<класс>].
    const parts = path.split('/').filter(Boolean).slice(1);
    swInit(parts[0], parts[1] !== undefined ? parseInt(parts[1], 10) : undefined);
  }
}

function toggleMenu(): void {
  document.getElementById('tabs')?.classList.toggle('open');
}

function initNavigation(): void {
  document.querySelector('.tabs')!.addEventListener('click', function(e) {
    const tab = (e.target as Element).closest('.tab') as HTMLElement;
    if (!tab) return;
    const path = tab.dataset.tab === 'creatures' ? '/units' : (tab.dataset.tab === 'magic' ? '/book_of_magic' : '/' + tab.dataset.tab);
    // Выбор сделан — гамбургер закрываем. На узком экране открытое меню
    // занимает его целиком, и раздел открывался за ним: со стороны выглядело
    // так, будто нажатие не сработало.
    document.getElementById('tabs')?.classList.remove('open');
    navigateTo(path);
  });

  window.addEventListener('popstate', () => {
    const modal = document.getElementById('creature-modal');
    if (modal) modal.style.display = 'none';
    closeArtifactModal();
    closeFittingPicker();
    const path = appPath();
    const tab = routeTab(path);
    switchTab(tab);
    renderPath(path);
  });
}

function init(): void {
  for (const key of Object.keys(PIC_TO_SYSNAME)) delete PIC_TO_SYSNAME[key];
  if (allData.units) {
    for (const [sysName, u] of Object.entries(allData.units)) {
      const m = (u.portrait || '').match(/\/portraits\/(.+?)anip/);
      if (m) PIC_TO_SYSNAME[m[1]] = sysName;
    }
  }
  
  const sysToFaction: Record<string, string> = {};
  if (allData.unitsByFaction) {
    for (const [fkey, tiers] of Object.entries(allData.unitsByFaction)) {
      for (const [tier, cols] of Object.entries(tiers)) {
        for (const [col, units] of Object.entries(cols)) {
          for (const sysName of units) {
            sysToFaction[sysName] = fkey;
          }
        }
      }
    }
  }
  
  if (allData.units) {
    for (const [sysName, u] of Object.entries(allData.units)) {
      u.fraction = sysToFaction[sysName] || '';
    }
  }
  
  tacSetPlaybackRunning(false);
  if (typeof setupTacSimulate === 'function') setupTacSimulate(window);
  // Cheap wiring only (filter selects, handlers). The heavy grid renders moved to
  // TAB_RENDERERS above — each tab builds its content on first activation instead of
  // all of them at startup.
  initCreatures();
  renderFactions();
  initArtifacts();
  initAbilities();
  initMagic();
  initNavigation();
  handleInitialRoute();
}

export {
  ROUTES,
  normalizeRoutePath,
  routeTab,
  switchTab,
  renderPath,
  navigateTo,
  handleInitialRoute,
  toggleMenu,
  init,
};

(globalThis as any).navigateTo = navigateTo;
(globalThis as any).toggleMenu = toggleMenu;
(globalThis as any).init = init;
