/**
 * Книга магии: раскрытие панели, выбор заклинания и применение его по клику на
 * отряд прямо в редакторе расстановки (до боя).
 *
 * Собственное состояние — выбранное заклинание и таблица школ. Всё остальное
 * приходит из battle.ts: доска, отряды, журнал и лента инициативы. Записи в
 * общее состояние блок не делает — только читает и правит клетки, поэтому
 * импортированные привязки его устраивают.
 */
import { allData, PIC_TO_SYSNAME } from './data.js';
import { stripHtmlSimple } from './utils.js';
import { battleBoard } from './battleState.js';
import {
  TACTIC_UNITS, tacApplyStackState, tacLogLine, tacNameSpan, tacPutUnit,
  tacRemoveUnit, tacRenderInitiative, tacUpdateInitScroll,
} from './battle.js';
import { tacClearOver, tacPaletteSelected, tacSelectPaletteUnit } from './battlePalette.js';
import { playSpellAnim, warmSpellAnim } from './spellAnim.js';
import { tacHeroSprite, tacSpriteSize } from './battleFieldSprites.js';
import { sceneCellAnchor, sceneProjectileEdgeCaster } from './fieldScene.js';
import { tacFloatOverCell } from './battleAnim.js';
import { sndPlaySfx } from './battleSound.js';
import { BookEntry, renderBook, schoolSpread } from './spellBookView.js';

// Magic Book
export let tacSelectedSpell: string | null = null;

/** Заклинания переноса: целятся в отряд, а затем в КЛЕТКУ — как и в бою
 * (см. `CELL_TARGET_SPELLS` в `battle/hero_actions.py`). Здесь, в песочнице,
 * дальность не считается: редактор — стенд, отряд переносится в любую свободную
 * клетку, лишь бы поведение книги совпадало с боевым. */
const CELL_TARGET_SPELLS = new Set(['teleport', 'teleportother']);
/** Отряд, выбранный первым кликом для переноса: ждём клетку назначения. */
let tacTeleportFrom: { row: number; col: number } | null = null;

/** Клетки поля, по которым можно кликать при выбранном заклинании.
 *
 * Раньше здесь стоял селектор `.drop` — а это ТОЛЬКО зона расстановки (колонки
 * 1—2 и 11—12, 40 клеток из 120): книга редактора молча не работала по отрядам,
 * стоящим в центре поля, и переносить телепортом было бы некуда. Снятие
 * слушателей идёт по этому же списку — иначе он разошёлся бы с установкой. */
function tacMagicCells(): NodeListOf<HTMLElement> {
  return document.querySelectorAll<HTMLElement>('#tac-field td[data-row]');
}

export function tacToggleMagicBook() {
  const book = document.getElementById('tac-magic-book');
  if (!book) return;
  book.style.display = book.style.display === 'none' ? 'block' : 'none';
  const opened = book.style.display === 'block';
  sndPlaySfx(opened ? 'book_open' : 'book_closed');   // звуки книги оригинала
  if (opened) tacUpdateMagicBook();
}

// Full spellbook for sandbox testing: every spell from game data, grouped by school —
// no hero required (the old book demanded a hero class and listed a flat wall of buttons).
const TAC_SPELL_SCHOOLS = [
  // Названия школ — те же, что в боевой книге (battleSpellBook, SCHOOL_TITLES)
  // и в колесе навыков: школа `summon` называется «природы», а не «призыва».
  ['haos', '🔥 Магия хаоса'],
  ['light', '✨ Магия света'],
  ['mlight', '✨ Свет (базовые)'],
  ['dark', '🌑 Магия тьмы'],
  ['mdark', '🌑 Тьма (базовые)'],
  ['summon', '🌀 Магия природы'],
  ['klichi', '📯 Кличи'],
  ['skills', '⭐ Способности'],
  ['other', '📦 Прочее'],
];

/** Spell effect value at the highest mastery level for the current СМ (spell power)
 * from the hero panel input — same _const + mul*SP formula the server uses. */
function tacSpellEffectValue(sp: any) {
  const power = parseInt((document.getElementById('tac-hero-sp') as HTMLInputElement | null)?.value || '') || 0;
  const lvl = Array.isArray(sp.levels) && sp.levels.length ? (sp.levels[sp.levels.length - 1] || {}) : sp;
  const base = lvl._const || 0;
  const mul = lvl.mul || 0;
  if (base || mul) return Math.round(base + mul * power);
  return Math.round(lvl.stat || lvl.effect || 0);
}

/** Номер открытого разворота книги редактора. */
let tacBookPage = 0;

/** Обвязка книги редактора для общей вёрстки (`spellBookView.ts`). Отличия от
 * боевой ровно два: мана не тратится (это стенд), и доступны ВСЕ заклинания
 * игры, а не только те, что знает герой. */
const TAC_BOOK_CHROME = {
  title: 'Книга магии — расстановка',
  schools: TAC_SPELL_SCHOOLS as [string, string][],
  flask: '∞',
  pageFn: 'tacMagicBookPage',
  schoolFn: 'tacMagicBookSchool',
  closeFn: 'tacToggleMagicBook',
};

/** Записи книги: все заклинания игры со значениями под текущую силу магии. */
function tacBookEntries(): BookEntry[] {
  const power = parseInt((document.getElementById('tac-hero-sp') as HTMLInputElement | null)?.value || '') || 0;
  return Object.entries(allData.magics! || {}).map(([sys, sp]: [string, any]) => {
    // «Веселье» лежит в данных в школе света, но это умение сатиров: герой
    // получает его лишь «Флейтой сатира». В книге героя его нет вовсе
    // (NOT_HERO_SPELLS на сервере), а на стенде показываем среди способностей.
    const school = sys === 'satyrmorale' ? 'skills' : (sp.school || 'other');
    const eff = tacSpellEffectValue(sp);
    const effTxt = sp.type === 'damage' ? `${eff} урона` : sp.type === 'hp' ? `+${eff} HP` : eff ? `эффект ${eff}` : '';
    return {
      sys,
      name: sp.name || sys,
      school,
      mana: parseInt(sp.mana) || 0,
      effect: eff,
      percent: sp.type === 'buff_SE' || sp.type === 'buff_speed' || sp.type === 'buff_t',
      area: /zone\//.test(sp.desc || '') ? 'area' : null,
      castable: true,           // стенд: мана не тратится, каст всегда доступен
      active: tacSelectedSpell === sys,
      tip: [`${sp.name || sys} — ${sp.mana || 0} маны (СМ ${power})`, effTxt,
            stripHtmlSimple(sp.desc || '')].filter(Boolean).join('\n'),
      onclick: `tacSelectSpell('${sys}')`,
    } as BookEntry;
  });
}

/** Перелистнуть книгу редактора. */
export function tacMagicBookPage(delta: number) {
  tacBookPage += delta;
  sndPlaySfx('book_list');      // шелест страницы
  tacUpdateMagicBook();
}

/** Закладка школы в книге редактора. */
export function tacMagicBookSchool(school: string) {
  tacBookPage = schoolSpread(tacBookEntries(), TAC_BOOK_CHROME, school);
  sndPlaySfx('book_list');
  tacUpdateMagicBook();
}

/** Перерисовать книгу редактора — тем же разворотом, что и книга боя. */
export function tacUpdateMagicBook() {
  const box = document.getElementById('tac-magic-book');
  if (!box) return;
  const entries = tacBookEntries();
  box.onclick = (e: MouseEvent) => { if (e.target === box) tacToggleMagicBook(); };
  box.innerHTML = renderBook(entries, {
    ...TAC_BOOK_CHROME,
    note: tacSelectedSpell
      ? 'Выбрано — кликните по полю'
      : 'Стенд: мана не тратится, значения по полю «СМ»',
  }, tacBookPage);
}

export function tacSelectSpell(spellSys: any) {
  tacSelectedSpell = tacSelectedSpell === spellSys ? null : spellSys;
  tacTeleportFrom = null;
  document.querySelectorAll('#tac-field td.tac-spell-source')
    .forEach(td => td.classList.remove('tac-spell-source'));
  const mainStatus = document.getElementById('tac-status');
  if (tacSelectedSpell) {
    // Ассеты анимации — пока игрок целится, чтобы первый каст не ждал сеть.
    warmSpellAnim(tacSelectedSpell);
    const sp = allData.magics![tacSelectedSpell];
    // Close the book so the field is fully visible for targeting; feedback goes to the
    // main status line under the field (the book's own status is hidden with it).
    const book = document.getElementById('tac-magic-book');
  if (!book) return;
    if (book) book.style.display = 'none';
    const msg = `🔮 ${sp?.name || tacSelectedSpell}: кликните по отряду на поле (Esc — отмена)`;
    if (mainStatus) mainStatus.textContent = msg;
    // Заклинанию переноса нужен и второй клик — по ПУСТОЙ клетке, поэтому у него
    // кликабельно всё поле, а у остальных — только клетки с отрядами.
    const needsCell = CELL_TARGET_SPELLS.has(tacSelectedSpell);
    tacMagicCells().forEach(td => {
      if (!needsCell && !td.classList.contains('tac-has-unit')) return;
      td.style.cursor = 'crosshair';
      td.addEventListener('click', tacMagicTargetClick);
    });
  } else {
    if (mainStatus && mainStatus.textContent.startsWith('🔮')) mainStatus.textContent = '';
    tacMagicCells().forEach(td => {
      td.style.cursor = '';
      td.removeEventListener('click', tacMagicTargetClick);
    });
  }
  tacUpdateMagicBook();
}

// Esc cancels the pending manual cast (the book is closed at that point, so the
// "click the spell again to cancel" path isn't visible anymore).
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (tacSelectedSpell) tacSelectSpell(tacSelectedSpell);
  // Esc снимает и выбор существа в палитре — иначе взведённый выбор молча живёт
  // дальше и следующий клик по полю ставит существо там, где не ждали.
  if (tacPaletteSelected !== null) { tacSelectPaletteUnit(null); tacClearOver(); }
});

// The initiative strip is a fixed-height horizontal ribbon — translate the mouse wheel
// into horizontal scrolling over it, like the original client's ATB bar.
(function tacInitRibbonWheel() {
  const el = document.getElementById('tac-initiative');
  if (!el) { setTimeout(tacInitRibbonWheel, 500); return; }
  el.addEventListener('wheel', e => {
    if (el.scrollWidth <= el.clientWidth) return;
    e.preventDefault();
    el.scrollLeft += (Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX);
  }, { passive: false });
  // Видимость ◀ / ▶ зависит от положения прокрутки, поэтому пересчитываем её и при
  // прокрутке — колесом, кнопками и «умным» smooth-скроллом.
  el.addEventListener('scroll', () => tacUpdateInitScroll(), { passive: true });
})();

/** Перенос отряда в редакторе: первый клик — по отряду, второй — по свободной
 * клетке. Раньше «Телепорт» попадал в общую ветку усилений и лишь печатал число:
 * отряд оставался на месте и в песочнице, и в бою. */
async function tacMagicTeleportClick(td: any, r: number, c: number, sp: any): Promise<void> {
  const status = document.getElementById('tac-status');
  const cell = battleBoard.data[r]?.[c];
  const occupied = !!cell;
  const stack = (cell && cell !== true && cell !== false && cell.id !== undefined) ? cell : null;

  if (!tacTeleportFrom) {
    if (!stack) {
      if (status) status.textContent = `🔮 ${sp.name}: сначала выберите отряд`;
      return;
    }
    tacTeleportFrom = { row: r, col: c };
    td.classList.add('tac-spell-source');
    if (status) status.textContent = `🔮 ${sp.name}: теперь укажите свободную клетку (Esc — отмена)`;
    return;
  }

  if (occupied) {
    if (status) status.textContent = `🔮 ${sp.name}: клетка занята — укажите свободную`;
    return;
  }
  const from = tacTeleportFrom;
  const src = battleBoard.data[from.row]?.[from.col];
  if (!src || src === true || src === false || src.id === undefined) { tacTeleportFrom = null; return; }
  const u = TACTIC_UNITS[src.id];
  const nameRu = allData.units!?.[PIC_TO_SYSNAME[u.pic] || u.pic]?.nameRu || u.name;
  const srcTd = document.querySelector(`#tac-field td[data-row="${from.row}"][data-col="${from.col}"]`);
  const size = tacSpriteSize(!!u.big);
  const cnt = src.cnt, team = src.team, hp = src.hp;

  if (srcTd) await playSpellAnim(srcTd, tacSelectedSpell!, size);
  tacRemoveUnit(from.row, from.col, true);
  tacPutUnit(r, c, src.id, cnt, team);
  const moved = battleBoard.data[r]?.[c];
  if (moved && moved !== true && hp !== undefined) moved.hp = hp;
  await playSpellAnim(td, tacSelectedSpell!, size);

  if (srcTd) srcTd.classList.remove('tac-spell-source');
  tacTeleportFrom = null;
  // Без координат — как и остальные строки журнала (оригинал их не пишет вовсе).
  tacLogLine(`🌀 ${sp.name}: ${nameRu}`);
  // Координаты — колонка;ряд, как в журнале движения и превью (`getxa`: «х:у»).
  if (status) status.textContent = `🌀 ${sp.name}: ${nameRu} перенесён в (${c};${r})`;
  tacRenderInitiative();
}

/** Sandbox spell application: actually mutates the target stack on the editor board
 * (damage kills creatures, heals restore/resurrect), so spells are testable — the old
 * handler only printed a status line and deselected the spell. The spell STAYS selected
 * for repeated casts; deselect by clicking it again in the book. */
export async function tacMagicTargetClick(e: any) {
  if (!tacSelectedSpell) return;
  const td = e.currentTarget;
  const r = parseInt(td.dataset.row);
  const c = parseInt(td.dataset.col);
  const cell = battleBoard.data[r]?.[c];
  const sp = allData.magics![tacSelectedSpell];
  if (!sp) return;
  if (CELL_TARGET_SPELLS.has(tacSelectedSpell)) {
    await tacMagicTeleportClick(td, r, c, sp);
    return;
  }
  if (!cell || cell === true || cell === false || cell.id === undefined) return;
  const u = TACTIC_UNITS[cell.id];
  // Та же анимация, что в бою: книга в редакторе — стенд для проверки заклинаний,
  // и смотреть на них здесь хочется ровно так же, как они выглядят в бою.
  // Заклинатель — герой, чья это книга: снарядные заклинания стартуют в его
  // дуле и летят к цели (как в show_direct_magic), а не разворачиваются на
  // месте. Справа от поля герой ещё не смонтирован (стенд открывают до боя) —
  // тогда рой влетает с края, но в любом случае ДОЛЕТЕВАЕТ до существа.
  const big = !!u.big;
  const size = tacSpriteSize(big);
  const hero = tacHeroSprite('player');
  const anchor = sceneCellAnchor(td, big);
  const caster = (hero && hero.anchor)
    ? { anchor: hero.anchor, size: tacSpriteSize(false) }
    : (anchor ? sceneProjectileEdgeCaster(anchor, size, true) : null);
  await playSpellAnim(td, tacSelectedSpell, size, caster);
  const sysName = PIC_TO_SYSNAME[u.pic] || u.pic;
  const unitHp = allData.units![sysName]?.hp || 1;
  const nameRu = allData.units!?.[sysName]?.nameRu || u.name;
  const pos = { row: r, col: c, sysName, cnt: cell.cnt, team: cell.team, pic: u.pic, nameRu };
  const eff = tacSpellEffectValue(sp);
  const status = document.getElementById('tac-status');
  // The unified log lives in #tac-result, which is hidden outside battle — reveal it so
  // manual test casts are actually logged (tacLogLine no-ops on a hidden container).
  const rdiv = document.getElementById('tac-result');
  if (rdiv && rdiv.style.display === 'none') {
    rdiv.style.display = 'block';
    rdiv.innerHTML = '<div style="color:var(--text-dim);font-size:12px">— Ручные касты —</div>';
  }
  const float = (txt: any, color?: any) => {
    const el = document.createElement('div');
    el.className = 'tac-dmg-float';
    el.textContent = txt;
    if (color) el.style.color = color;
    tacFloatOverCell(td, el, 700);
  };
  if (sp.type === 'damage') {
    const dmg = Math.max(1, eff);
    const topHp = cell.hp || unitHp;
    const total = (cell.cnt - 1) * unitHp + topHp - dmg;
    float(String(dmg));
    if (total <= 0) {
      tacRemoveUnit(r, c, true);
      tacLogLine(`🔮 ${sp.name}: <span style="color:#ff6b6b">${dmg}</span> — ${tacNameSpan(pos)} уничтожены`);
      if (status) status.textContent = `🔮 ${sp.name}: ${dmg} урона — ${nameRu} уничтожены`;
      return;
    }
    const newCnt = Math.ceil(total / unitHp);
    let newHp = total - (newCnt - 1) * unitHp;
    if (newHp <= 0) newHp = unitHp;
    const killed = cell.cnt - newCnt;
    cell.hp = newHp;
    tacApplyStackState({ ...pos, hp: newHp }, newCnt, newHp);
    tacLogLine(`🔮 ${sp.name}: <span style="color:#ff6b6b">${dmg}</span> по ${tacNameSpan(pos)}${killed > 0 ? `. Погибло ${killed}.` : ''}`);
    if (status) status.textContent = `🔮 ${sp.name}: ${dmg} урона по ${nameRu}${killed > 0 ? `, погибло ${killed}` : ''} (HP верхнего: ${newHp}/${unitHp})`;
    tacRenderInitiative();
  } else if (sp.type === 'hp') {
    const heal = Math.max(1, eff);
    const topHp = cell.hp || unitHp;
    const total = (cell.cnt - 1) * unitHp + topHp + heal;
    const newCnt = Math.ceil(total / unitHp);
    let newHp = total - (newCnt - 1) * unitHp;
    if (newHp <= 0) newHp = unitHp;
    const raised = newCnt - cell.cnt;
    cell.hp = newHp;
    tacApplyStackState({ ...pos, hp: newHp }, newCnt, newHp);
    float('+' + heal, '#4caf50');
    tacLogLine(`✚ ${sp.name}: <span style="color:#4caf50">+${heal}</span> ${tacNameSpan(pos)}${raised > 0 ? `. Поднято ${raised}.` : ''}`);
    if (status) status.textContent = `✚ ${sp.name}: +${heal} HP ${nameRu}${raised > 0 ? `, поднято ${raised}` : ''}`;
    tacRenderInitiative();
  } else {
    // Buffs / summons / shouts have no board-state model in the sandbox — report the
    // computed effect value so the numbers are still testable.
    float(sp.name, '#ce93d8');
    tacLogLine(`📜 ${sp.name} на ${tacNameSpan(pos)}${eff ? ` (эффект: ${eff})` : ''} — вне боя только расчёт значения`);
    if (status) status.textContent = `📜 ${sp.name} на ${nameRu}${eff ? `: эффект ${eff}` : ''} (полноценно действует в бою у героя с магией)`;
  }
}
