/* ── «Открытие врат Ада»: портал на месте выхода подкрепления ──
 *
 * Оригинальная метка, а не самодельный CSS-маяк: клиент игрока ставит на клетку
 * демона постоянный объект `magic_spell` со spellname='demongate' (атлас
 * png40/demongate.png + anim_data40/demongate.js — ровно тот, что прислал
 * пользователь), проигрывает doing='cast' и оставляет последний кадр: портал
 * стоит, пока врата не закроются (showdemongate, usemagicp.js:7238-7296). При
 * закрытии ТОТ ЖЕ объект переводится в doing='die' с hide_after_use=1
 * (calccomsp.js:2093-2096), при смерти демона — снимается совсем
 * (calccomsp.js:1596-1599).
 *
 * Движок знает этот спрайт поимённо (enginep.ts:3139: `spellname=='demongate'`
 * не гасится по исчерпании кадров, кроме doing='die'), так что объект должен
 * быть именно magic_spell с этим именем — как в оригинале, а не картинкой.
 * Здесь hide_after_use=false на касте держит портал видимым, а на закрытии
 * включается: гейт сам спрячет mobject, когда die доиграет.
 *
 * Габарит. У большого демона врата 2×2: оригинал ставит полюс-позицию со
 * смещением +0.5 БОЛЬШОЙ клетки (= +1 обычная) по обеим осям
 * (usemagicp.js:7252-7254) и рисует спрайт шириной s_x=1.9, высотой s_y=0.9
 * клетки (там же); маленькие — 0.95×0.6. Тот же смысл дают раздельные
 * xscale/yscale в set_pos: 30 — ширина сценного спрайта в одну клетку (стена
 * «Огненной стены» и туча ставятся с set_pos(..., 30, 30)). Размер клетки в
 * `size` остаётся обычным: иначе спрайт растёт по обеим осям сразу.
 */
const gateHandles = new Map<string, SceneHandle & {
  firewallLoop: true; dying: boolean; dieTimer: any;
}>();

/** Ширина сценного спрайта в одну клетку (set_pos(..., 30, 30) у стены огня). */
const GATE_CELL_SCALE = 30;
/** Габарит врат в клетках по оригиналу (usemagicp.js:7252): маленькие — почти
 * клетка, большие (след 2×2) — две клетки в ширину и одна по высоте. */
const GATE_SPAN_SMALL = [0.95, 0.6];
const GATE_SPAN_BIG = [1.9, 0.9];
/** Сколько живёт объект после sceneGateClose: doing='die' — это 7 кадров
 * (13..19 в anim_data40/demongate.js) по 40мс, плюс запас на догоняющий тик. */
const GATE_DIE_MS = 600;

function gateKey(row: number, col: number): string {
  return `${row}:${col}`;
}

/** Поставить врата ада на клетку-якорь следа: объект движка magic_spell
 * spellname='demongate', кадры doing='cast'. Дальше движок сбрасывает doing=''
 * и оставляет последний кадр — портал стоит, пока врата открыты (клетка есть в
 * field_objects). Повторный вызов на ту же клетку не плодит объекты.
 *
 * `big` — след 2×2 (большой демон): спрайт шириной во весь след и полюс со
 * смещением на клетку, как в оригинале. Возвращает ключ row:col для снятия. */
export function sceneMountGate(td: Element, size: number, big = false): string | null {
  if (!sceneEnsure()) return null;
  const anchor = sceneCellAnchor(td);
  if (!anchor) return null;
  const ds = (td as HTMLElement).dataset || {};
  const row = Number(ds.row), col = Number(ds.col);
  if (!row && !col) return null;
  const key = gateKey(row, col);
  if (gateHandles.has(key)) return key;
  const seqKey = 'scene_gate_' + (++seq);
  const scaling = size / 300;
  const span = big ? GATE_SPAN_BIG : GATE_SPAN_SMALL;

  const obj: any = {
    container: SCENE_ID,
    scaling,
    x: anchor.x,
    y: anchor.y,
    doing: '',
    magic_spell: true,
    // Портал стоит, пока врата открыты: по исчерпании кадров cast объект
    // остаётся видимым (одноразовые заклинания движок гасит по hide_after_use,
    // а он здесь false). На закрытии флаг включается — см. sceneGateClose.
    hide_after_use: false,
    mvisible: true,
    nownumber: 1,
    spellname: 'demongate',
    active_spell: true,
    slow_spell: true,
    set_pole_pos() {},
    def_pos() {},
    get_obj_z() { return 0; },
    get_view_obj() { return 1; },
    get_obj_add_scale() { return 1; },
  };
  const h: any = {
    scene: true,
    key: seqKey,
    ready: false,
    failed: false,
    obj,
    unitLayer: sceneLayer,
    idleEnabled: false,
    containerEl: sceneDiv as HTMLDivElement,
    // Тот же флаг, что у «Огненной стены»: одноразовый каст без burn-loop и без
    // idle-жестов (движок гоняет его по одному кадру за тик, creatureAnim.ts:529).
    firewallLoop: true,
    dying: false,
    dieTimer: null,
    setDoing(d: string) { obj.doing = d; },
    destroy() {
      if (h.dieTimer) { clearTimeout(h.dieTimer); h.dieTimer = null; }
      unregisterLiveHandle(seqKey);
      sceneHandles.delete(h);
      gateHandles.delete(key);
      for (const part of ['layer', 'arrow_layer']) {
        try { if (obj[part]) obj[part].destroy(); } catch { /* ignore */ }
      }
      try { if (sceneLayer) sceneLayer.draw(); } catch { /* ignore */ }
    },
  };
  const applyPos = () => {
    try {
      // Полюс-позиция: точка земли спрайта, как у стены (`-size + 270*scaling`).
      // У больших врат к ней прибавляется целая клетка по обеим осям — сдвиг
      // +0.5 большой клетки оригинала (usemagicp.js:7252-7254).
      const shift = big ? size : 0;
      const feetY = anchor.y - size + 270 * scaling + shift;
      obj.set_pos(anchor.x + shift, feetY, span[0] * GATE_CELL_SCALE, span[1] * GATE_CELL_SCALE);
    } catch { /* engine not ready / torn down */ }
  };

  if (typeof (window as any).war_scr === 'undefined') (window as any).war_scr = SCENE_ID;
  installTeleportStub(sceneStage, obj);
  try {
    window.add_obj!.call(obj, 'unit', 'demongate', OBJ_VER, SUBPATH, false, function () {
      h.ready = true;
      applyPos();
      obj.doing = 'cast';
      // До первого кадра прячем кластер иконок (statix.demongate.nano_arts) —
      // первый же тик покажет кадр 1, как у стены и у тучи.
      try { (window as any).set_visible(obj.mobject, 0); } catch { /* ignore */ }
    }, true);
  } catch {
    return null;
  }
  gateHandles.set(key, h);
  sceneHandles.add(h);
  registerLiveHandle(seqKey, h);
  ensureAnimLoopStarted();
  sceneZSort();
  return key;
}

/** Закрыть врата (подкрепление вышло): тот же объект уходит в doing='die' с
 * hide_after_use — по исчерпании кадров движок спрячет mobject сам, ровно как в
 * оригинале (calccomsp.js:2093-2096). Объект остаётся в реестре помеченным
 * dying, чтобы снапшот не поставил на эту клетку второй портал; через
 * GATE_DIE_MS он снимается. */
export function sceneGateClose(key: string): void {
  const h = gateHandles.get(key);
  if (!h || h.dying) return;
  h.dying = true;
  h.obj.hide_after_use = true;
  h.obj.doing = 'die';
  h.dieTimer = setTimeout(() => h.destroy(), GATE_DIE_MS);
}

/** Портал в гашении? Синхронизация не должна ставить на его клетку новый. */
export function sceneGateDying(key: string): boolean {
  return !!gateHandles.get(key)?.dying;
}

/** Снять врата с клетки сразу, без кадров 'die' (перерисовка поля / сброс). */
export function sceneUnmountGate(key: string): void {
  const h = gateHandles.get(key);
  if (!h) return;
  h.destroy();
}

/** Погасить ВСЕ врата (перерисовка поля / конец боя). */
export function sceneUnmountAllGates(): void {
  for (const h of [...gateHandles.values()]) h.destroy();
}

/** Клетки-якори ОТКРЫТЫХ врат (row:col) — для синхронизации со снапшотом.
 * Гаснущие сюда не входят: их снимает таймер sceneGateClose. */
export function sceneGateCells(): Set<string> {
  const out = new Set<string>();
  for (const [key, h] of gateHandles) if (!h.dying) out.add(key);
  return out;
}

/**
 * Пересчёт сцены после смены раскладки поля.
 *
 * Живые спрайты переносит `tacFitField` по карте `tacFieldSprites`; трупов в
 * ней нет — их убирают оттуда ещё до `tacRemoveUnit`, иначе труп снесло бы
 * вместе с отрядом. Из-за этого павшие оставались в координатах и масштабе
 * ПРОШЛОЙ раскладки: после выхода из арены доска вдвое меньше, и труп оказывался
 * далеко от своей клетки — у правого края поля.
 */
export function sceneRelayout(size?: number): void {
  // Раскладка сменилась — кэш якорей (row,col) мёртв: клетки теперь на новых
  // местах. Сброс ДО переякорения трупов, чтобы они мерились свежими значениями.
  anchorCache.clear();
  sceneEnsure();
  for (const h of corpses) {
    if (!h.cell) continue;
    const td = sceneCellTd(h.cell.row, h.cell.col);
    const p = td ? sceneCellAnchor(td) : null;
    if (p) h.setAnchor(p);
    if (size && h.setScale) h.setScale(size);
  }
  sceneZSort();
  try { if (sceneLayer) sceneLayer.draw(); } catch { /* ignore */ }
}
