let dep: HotseatCycleDeps;

export function initHotseatCycle(deps: HotseatCycleDeps) {
  dep = deps;
  // Книга магии героя ходит через тот же цикл: отправляет действие и просит
  // перерисовать подсказки. Обратного импорта у неё нет — только эти вызовы.
  initSpellBook({ tacHsAct, tacHsRender, tacHsStatus });
  // Свиток рун ходит тем же путём: отправляет действие и просит перерисовать.
  initRunes({ tacHsAct, tacHsRender });
}


// ═══════════════════════════════════════════════════════════════
//  ХОТСИТ — два игрока за одним компьютером
// ═══════════════════════════════════════════════════════════════
// Обычный бой уходит на /api/simulate и проигрывается целиком. Здесь сервер держит
// сессию (/api/battle/step с hotseat: true) и останавливает бой на КАЖДОМ ходу —
// и своей стороны, и вражеской, — ожидая клика человека. Клиент подсвечивает на
// доске, куда можно пойти и кого ударить, отправляет выбор и проигрывает
// вернувшиеся действия той же анимацией, что и обычный реплей.

// Без цветных кружков: сторону красит tacTeamColor по КОМАНДЕ отряда (команда 1 —
// красная, 2 — синяя, и так до шести), а фиксированный эмодзи противоречил бы
// бейджам на поле на любой расстановке, кроме команд 1/2.


export async function tacStartHotseat() {
  if (tacPlaybackRunning() || hs.busy) return;
  if (!dep.tacFitsServerGrid()) {
    tacHsStatus('❌ Хотсит работает на поле до 14×10 — выберите поле 12×10, 13×10 или 14×10');
    return;
  }
  // На поле — итог прошлого боя: возвращаем исходную расстановку, как «в бой».
  if (hs.endStateShown && hs.savedSetup) {
    dep.tacResetBoard(hs.savedSetup);
    hs.endStateShown = false;
  }
  const scan = dep.tacScanBoard();
  if (!scan.positions.some((p: any) => p.side === 'player') || !scan.positions.some((p: any) => p.side === 'enemy')) {
    tacHsStatus('❌ Добавьте отряды с обеих сторон');
    return;
  }
  battleBoard.stackPositions = scan.positions;
  hs.setup = scan.original;
  // Грунт НЕ перекатываем: его уже постелили при входе в редактор
  // (tacInitTerrainSelect) — расстановка обязана выглядеть так же, как бой.
  // Повторный tacRollLand() перевыбирал бы и тип грунта (при «Случайно»), и
  // вариант картинки (даже при закреплённом типе — свой случайный номер
  // текстуры на каждый вызов, см. tacApplyLand), и арена боя расходилась с
  // тем, что игрок только что видел в превью. Звук шагов под преложенный
  // грунт уже настроен той же исходной tacApplyLand — предзагрузке греть
  // нечего заново.
  dep.tacPreloadBoardAnims(battleBoard.stackPositions);
  dep.tacClearCorpses();
  sndStartMusic();
  const resultDiv = tacHsEl('tac-result');
  if (resultDiv) {
    resultDiv.style.display = 'block';
    resultDiv.innerHTML = '';
  }
  tacHsStatus('⏳ Создание боя...');

  const playerHero = tacGetHeroData();
  const enemyHero = tacGetEnemyHeroData();
  const playerStacks = dep.tacSidePayload(battleBoard.stackPositions, 'player', true);
  const enemyStacks = dep.tacSidePayload(battleBoard.stackPositions, 'enemy', true);
  // Модели из панели пошагового режима СОЗНАТЕЛЬНО не читаются: хотсит — это две
  // живые руки за одной клавиатурой, ИИ здесь не участвует ни за одну из сторон.
  // (Селекторы tac-model-p1/p2 к тому же по умолчанию стоят не на «Человек», так что
  // чтение их отдавало бы сторону LLM без ведома игроков.)
  // Препятствия раскладывает клиент и отдаёт их полем `walls`: движок такие
  // клетки уже понимает (apply_walls), а расставить их было некому — поле всегда
  // выходило голым, чего в оригинале не бывает.
  const busy = battleBoard.stackPositions
    .filter((p: any) => p)
    .map((p: any) => `${p.row}:${p.col}`);
  const walls = dep.tacRollObstacles(dep.tacCfg.col, dep.tacCfg.row, busy);
  const payload = {
    hotseat: true,
    field: { cols: dep.tacCfg.col, rows: dep.tacCfg.row },
    walls,
    player: playerHero ? { hero: playerHero, stacks: playerStacks } : { stacks: playerStacks },
    enemy: enemyHero ? { hero: enemyHero, stacks: enemyStacks } : { stacks: enemyStacks },
  };

  hs.busy = true;
  try {
    const res = await fetch('/api/battle/step', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (data.error) { tacHsStatus(`❌ ${data.error}`); return; }
    hs.session = data.session_id;
    warmCursors();         // курсоры боя — в кэш до первого наведения
    dep.tacEnterBattleArena(); // бой идёт в полноэкранной арене, как в оригинале
    tacHsBindField(true);
    const bar = tacHsEl('tac-hotseat-bar');
    if (bar) bar.style.display = 'flex';
    dep.tacDockTurnButtons(true);
    dep.tacRenderWalls(data.walls, data.terrain, data.field_objects);
    await tacHsApply(data);
  } catch (e) {
    tacHsStatus(`❌ ${(e as Error)?.message || e}`);
  } finally {
    hs.busy = false;
  }
};

/** Отправить решение игрока и показать, что из этого вышло. */
export async function tacHsAct(action: any) {
  if (!hs.session || hs.busy) return;
  // Окно хода героя: у него своя шкала ATB, активного отряда нет, и сервер
  // принимает только каст, пропуск и автобой (turn_engine.step по
  // hero_turn_side). Ход отряда отсюда уходил впустую — приходило «Not
  // player's turn», а панель продолжала предлагать оборону и ожидание. Гвард
  // стоит здесь, а не на кнопках: тем же путём ходят горячие клавиши.
  if (hs.state && hs.state.hero_turn !== null && hs.state.hero_turn !== undefined
      && !HERO_TURN_ACTIONS.includes((action || {}).type)) {
    tacHsStatus('🧙 Ход героя: книга магии (B), ожидание или оборона');
    return;
  }
  // Ручной каст из книги: жест героя поднимаем ЗДЕСЬ, а не по ответу сервера.
  // Сторону в этот момент знает клиент (окно героя открыто именно ей), а в
  // действиях большинства заклинаний — лечения, щита, призыва — её нет вовсе:
  // по потоку жест поднимается только у каст-урона и умений колеса.
  if ((action || {}).type === 'hero_spell'
      && (hs.state?.hero_turn === 0 || hs.state?.hero_turn === 1)) {
    dep.tacHeroFigureCast(hs.state.hero_turn);
  }
  // Сброс взведённой атаки героя при ЛЮБОМ другом действии: ход уже выбран.
  if ((action || {}).type !== 'hero_attack') hs.heroAttackArmed = false;
  hs.busy = true;
  tacHsClearHints();
  try {
    const res = await fetch('/api/battle/step', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ session_id: hs.session, action }),
    });
    const data = await res.json();
    if (data.error) {
      // Ошибку нельзя просто показать и продолжить: в автобое следующий же кадр
      // цикла отправит такой же ход, получит ту же ошибку, а tacHsRender затрёт
      // текст статуса — получится безостановочный цикл запросов с виду «идущего»
      // боя. Поэтому автобой выключаем и отдаём управление человеку.
      if (hs.autoBattle) tacToggleAutoBattle();
      // Ход отклонён — состояние боя не изменилось, значит подсветка достижимых
      // клеток и кольцо под ходящим отрядом должны вернуться: без этого доска
      // после промаха мимо цели оставалась голой до следующего удачного хода.
      // Перерисовка ПЕРЕД статусом: `tacHsRender` пишет туда свою подсказку.
      tacHsRender();
      tacHsStatus(`❌ ${data.error}`);
      return;
    }
    await tacHsApply(data);
  } catch (e) {
    if (hs.autoBattle) tacToggleAutoBattle();
    tacHsStatus(`❌ ${(e as Error)?.message || e}`);
  } finally {
    hs.busy = false;
  }
}

/** Проиграть новые действия боя и перерисовать подсказки под следующий ход. */
/** Индикатор ярости степных варваров с иконкой attr_blood из оригинала.
 * Шкала принадлежит ОТРЯДУ (`rag` в логах адресует стек, поглощение тратит
 * шкалу защитника), поэтому сервер отдаёт `rage` по `stack_idx`, а не по
 * стороне: одна полоса на сторону врала бы, у кого именно накопилось.
 * Формат «Кентавры: 300 · ур.2». Иконка идёт через кэш-прокси — работает и в
 * local-only режиме. */
function renderStackRage(rage: any, stacks: any[]) {
  const el = tacHsEl('tac-hs-rage');
  if (!el) return;
  const byIdx: Record<string, any> = {};
  for (const s of stacks || []) byIdx[String(s.idx)] = s;
  const parts = Object.entries(rage || {}).map(([idx, info]: [string, any]) => {
    const stack = byIdx[idx];
    const who = stack
      ? `${stack.side === 0 ? 'P1' : 'P2'} ${stack.name}`
      : `отряд ${idx}`;
    const fury = info.fury > 0 ? ` · ур.${info.fury}` : '';
    return `<span class="tac-rage-side"><img src="/api/cache/i/combat/icons/attr_blood.png" alt="ярость" title="Ярость: ${who}">${who}: ${info.rage}${fury}</span>`;
  });
  if (!parts.length) {
    el.style.display = 'none';
    el.innerHTML = '';
    return;
  }
  el.innerHTML = parts.join(' ');
  el.style.display = '';
}

async function tacHsApply(data: any) {
  hs.state = data;
  renderStackRage(data.rage, data.stacks);
  // Ход героя: явное окно «каст или пропуск» — как в ленте очереди оригинала.
  const passBtn = document.getElementById('tac-hs-pass');
  if (passBtn) passBtn.style.display = data.hero_turn != null ? '' : 'none';
  const attackBtn = document.getElementById('tac-hs-hero-attack');
  if (attackBtn) attackBtn.style.display = data.hero_turn != null ? '' : 'none';
  // Мостики для e2e/отладки: чьё окно открыто и готовности героев.
  (window as any).tacHeroTurn = data.hero_turn ?? null;
  (window as any).tacHeroReady = data.hero_ready ?? {};
  (window as any).tacStacksInfo = data.stacks ?? [];
  // Фигуры героев на поле: классы могли смениться, свечение — по готовности.
  dep.tacRenderHeroFigures();
  if (data.hero_turn != null && !data.hero_ready?.[String(data.hero_turn)]) {
    tacHsStatus('🧙 Ход героя');
  }
  hs.scatter = false; // режим выстрела выбирается заново каждым отрядом
  hs.shiftBtn = false; // и режим Shift — тоже выбор одного хода
  hs.spell = null;
  hs.ability = null;   // взведённое умение принадлежит ходу, а не бою
  hs.abilityCellTarget = null;
  // Ход пике («Губительное пике»): отряд в воздухе, сервер предлагает одно —
  // полосу клеткой. Взводим сразу: поле светится, клик по клетке пикирует.
  const dive = (data.available_actions || []).find((a: any) => a.type === 'ability' && a.dive && !a.disabled);
  if (dive) hs.ability = dive.skill;
  hs.bookOpen = false;
  // Книга магии закрывается вместе с выбором: каст героя — один за раунд, и
  // после ответа сервера взведённое заклинание уже не применить.
  resetHeroBook();
  hs.heroAttackArmed = false; // взведённая атака принадлежит окну героя, не бою
  // Своя книга отряда — тем более принадлежит ходу: ходит уже другой отряд,
  // и взведённое им заклинание к следующему отношения не имеет.
  resetUnitBook();
  resetRunes();
  const actions = data.actions || [];
  if (actions.length) {
    // Тот же гвард, что и в реплее: пока идёт анимация, редактор и ремаунты спрайтов
    // отключены — иначе каждый шаг ходьбы пересобирал бы Konva-сцену.
    tacSetPlaybackRunning(true);
    try {
      for (const { a, also } of tacCoalesceActions(actions)) {
        // Отмена (выход из боя) обрывает раздачу: оставшиеся действия не
        // разыгрываются, иначе «вышел посреди боя» ждал бы весь хвост реплея.
        if (tacChainsCancelled()) break;
        await tacAnimateAction(a, 600 / dep.tacAnimSpeed, also);
      }
    } finally {
      tacSetPlaybackRunning(false);
      // Сверка спрайтов на месте (tacReconcileSprites): погасить зависший жест,
      // развернуть отряды к своей стороне, поднять idle — вернуть «живое» поле к
      // моменту, когда ходит человек. Раньше это была пересборка всей Konva-сцены,
      // от которой отряды мигали; теперь объекты те же. В автобое следующий ход
      // стартует сразу и снова поднимает проигрывание, так что сверка между двумя
      // машинными ходами не нужна — откладываем до возврата управления человеку
      // (см. tacToggleAutoBattle) или конца боя.
      const over = data.winner !== null && data.winner !== undefined;
      if (!hs.autoBattle || over) dep.tacReconcileSprites();
    }
  }
  // Огонь, ловушки и тучи — по снапшоту, а не по одной анимации каста: горящие
  // клетки живут дольше действия, которое их зажгло, и гаснут БЕЗ действия.
  // «Огненная стена» держится три хода, и до этой строки её разметку не снимал
  // никто — полоса огня оставалась нарисованной до конца боя.
  dep.tacSyncFieldObjects(data.field_objects);
  // Фантомы — по снапшоту, а не по действию призыва: дубль гибнет от любого
  // урона, и снимать пометку надо так же исправно, как ставить. Координаты
  // серверные: position = [col, row].
  tacMarkPhantomCells((data.stacks || [])
    .filter((s: any) => s && s.phantom && s.alive && Array.isArray(s.position))
    .map((s: any) => ({ row: s.position[1], col: s.position[0] })));
  tacHsRender();
  // Автобой включён — сразу заказываем следующий ход у ИИ. Цикл живёт снаружи
  // tacHsAct (см. tacAutoLoop), иначе рекурсивный вызов упёрся бы в hs.busy.
  if (hs.autoBattle) tacAutoLoop();
}

/** Автобой: пока флаг включён и бой не кончился, каждый ход отыгрывает сервер
 * действием {type:'auto'}. Ровно тот же ход, что человек делает кликом, —
 * поэтому режим переключается на любом ходу в обе стороны, без пересоздания боя. */
async function tacAutoLoop() {
  if (hs.autoLoopRunning) return;
  hs.autoLoopRunning = true;
  try {
    while (hs.autoBattle && hs.session && hs.state
           && hs.state.phase !== 'done'
           && (hs.state.winner === null || hs.state.winner === undefined)) {
      if (hs.busy || tacPlaybackRunning()) { await new Promise(r => setTimeout(r, 50)); continue; }
      if (!hs.autoBattle) break;
      await tacHsAct({ type: 'auto' });
    }
  } finally {
    hs.autoLoopRunning = false;
  }
}

/** Кнопка «Автобой». Переключается и до боя, и посреди него: включили — существа
 * доигрывают сами, выключили — управление возвращается на следующем же ходу. */
export function tacToggleAutoBattle() {
  hs.autoBattle = !hs.autoBattle;
  const btn = document.getElementById('tac-auto-btn');
  if (btn) {
    btn.classList.toggle('tac-ibtn-on', hs.autoBattle);
    btn.setAttribute('aria-pressed', String(hs.autoBattle));
    btn.title = hs.autoBattle ? 'Автобой включён — нажмите, чтобы вернуть управление' : 'Автобой: существа сражаются сами';
  }
  // Иконка из оригинала: перечёркнутый вариант означает «выключить автобой» — так
  // же, как `on` у книги магии и у кнопки умений.
  const img = document.getElementById('tac-auto-img');
  if (img) img.setAttribute('src', `/img/combat/btn_autobattle_${hs.autoBattle ? 'on' : 'off'}.png`);
  if (hs.autoBattle) {
    tacHsClearHints();      // подсказки хода человека больше не актуальны
    hs.spell = null;
    resetHeroBook();
    renderHeroBook();       // свернуть книгу: кастовать теперь некому
    resetUnitBook();
    renderUnitBook();       // и свою книгу отряда — ходом распоряжается ИИ
    resetRunes();
    renderRuneScroll();     // и свиток рун: рунами тоже распоряжается ИИ
    if (hs.session) tacAutoLoop();
  } else if (hs.state) {
    // Управление вернулось человеку — отдаём отложенную во время автобоя сверку,
    // иначе на поле остались бы спрайты в позах последнего машинного хода.
    if (!tacPlaybackRunning()) dep.tacReconcileSprites();
    tacHsRender();          // вернуть подсветку доступных ходов
  }
};

/** Подсветка доски и панель под текущий ход (или итог боя). */
/** Что сервер принимает, пока открыто окно хода героя (turn_engine.step). */
const HERO_TURN_ACTIONS = ['hero_pass', 'hero_wait', 'hero_defend',
                           'hero_spell', 'auto', 'hero_attack'];

/** Пометить отряд НА ВСЁМ ЕГО СЛЕДЕ.
 *
 * Пока клетки под 2×2 сливались в один `td`, хватало пометить якорь — слитая
 * клетка и была всем квадратом. Сетка под существом теперь сплошная (как в
 * оригинале), и пометка на одной клетке подсвечивала бы четверть отряда.
 * `tac-fp` говорит разметке, что пометка многоклеточная: рамка там заменяется
 * заливкой, иначе четыре рамки нарисовали бы крест посреди следа.
 */
function markStack(p: any, cls: string): void {
  if (!p) return;
  const size = p.size || 1;
  for (const [fr, fc] of tacHsFootprint(p.row, p.col, size)) {
    const td = dep.getCell(fr, fc);
    if (!td) continue;
    td.classList.add(cls);
    if (size > 1) td.classList.add('tac-fp');
  }
}

/** Отрисовка ОКНА ГЕРОЯ: шкала героя наполнилась, и ход достался ему.
 *
 * От хода отряда тут остаётся только прицел заклинания: ходить, бить, обороняться
 * и ждать в этом окне нечем — активного отряда нет. Кнопки хода отряда прячутся
 * (иначе они предлагают действия, на которые сервер отвечает отказом), кнопка
 * пропуска показана из tacHsApply, а книга магии — единственное, чем герой
 * распоряжается. Руны гнома сюда не относятся: они уходят ходом ОТРЯДА
 * (turn_engine: ветка `rune` живёт после проверки активного отряда). */
function tacHsRenderHeroTurn(st: any, side: number) {
  // Прицел: цели и клетки приходят вместе с книгой, своих правил у клиента нет.
  // Цели взведённой атаки героя подсвечиваются так же — список присылает сервер
  // (hero_attack.targets в снапшоте), своих правил прицеливания тут тоже нет.
  const attackOffer = st.hero_attack;
  for (const idx of (hs.heroAttackArmed ? (attackOffer?.targets || [])
                                         : heroSpellTargets())) {
    markStack(battleBoard.stackPositions[idx], 'tac-spell-target');
  }
  for (const [x, y] of heroSpellCells()) {
    const td = dep.getCell(y, x);
    if (td) td.classList.add('tac-spell-cell');
  }
  tacHsBindSpellQueuePreview();
  if (hs.heroSpellTarget !== null) markStack(battleBoard.stackPositions[hs.heroSpellTarget], 'tac-spell-source');

  const turnEl = tacHsEl('tac-hs-turn');
  if (turnEl) {
    const who = TAC_HS_SIDES[side] || `Сторона ${side}`;
    const info = heroChipInfo(side === 0 ? 0 : 1);
    const phase = (st.phases || {})[String(side)];
    const phaseTag = phase
      ? ` · <span title="${phase === 'night'
        ? 'Ночь: магия тьмы дешевле и сильнее' : 'День: магия света дешевле и сильнее'}">`
        + `${phase === 'night' ? '🌙' : '☀'}</span>`
      : '';
    turnEl.innerHTML = `<b style="color:${dep.tacTeamColor(side === 0 ? 1 : 2)}">${who}</b>`
      + ` · 🧙 ${info ? info.name : 'Герой'} · Р${st.round}${phaseTag}`;
  }
  // Кнопки, которым в окне героя действительно нечего делать: книги отряда,
  // руны, Shift-режим. «Ожидание» и «Оборона» остаются — в оригинале ряд
  // круглых кнопок один и тот же и в ход отряда, и в ход героя.
  for (const id of ['tac-hs-book', 'tac-hs-shift', 'tac-hs-unitbook-btn',
                    'tac-hs-runes-btn']) {
    const el = tacHsEl(id);
    if (el) el.style.display = 'none';
  }
  // Ожидание героя — те же полхода по шкале, что и прежний ⤼ (`hero_pass`,
  // п.6.2 руководства); оборона отдаёт ход целиком. Обработчик у кнопок общий и
  // жёстко зашит в разметке на ход ОТРЯДА, поэтому в окне героя тип действия
  // подменяется здесь.
  const heroBtn = (id: string, title: string) => {
    const btn = tacHsEl(id) as HTMLButtonElement | null;
    if (!btn) return;
    btn.style.display = '';
    btn.disabled = false;
    btn.title = title;
  };
  heroBtn('tac-hs-wait', 'Ожидание героя (W): половина хода по шкале — герой походит раньше');
  heroBtn('tac-hs-defend', 'Оборона героя (D): ход отдан целиком');
  // Отдельная ⤼ больше не нужна: её работу делает «Ожидание».
  const passBtn = tacHsEl('tac-hs-pass');
  if (passBtn) passBtn.style.display = 'none';
  tacHsRenderHeroAttackButton(st, side);
  renderHeroBook();
  tacHsRenderQueue(st);
  const heroSpellName = hs.heroSpell
    ? (allData.magics?.[hs.heroSpell]?.name || hs.heroSpell) : '';
  tacHsStatus(hs.heroAttackArmed
    ? '🗡 Атака героя: выберите врага (Esc — отмена)'
    : hs.heroSpell
    ? (hs.heroSpellTarget !== null
      ? `🔮 ${heroSpellName}: выберите клетку переноса (Esc — отмена)`
      : heroSpellAiming() === 'cell'
        ? `🔮 ${heroSpellName}: наведите область на клетку — накроет всех внутри (Esc — отмена)`
        : `🔮 ${heroSpellName}: выберите цель (Esc — отмена)`)
    : '🧙 Ход героя: книга магии (B) — каст, 🗡 — удар, W — ожидание, D — оборона');
}

/** Кнопка «Атака» в окне хода героя: удар самим героем без заклинания.
 *
 * Показывается только на его ходу и только когда удар вообще возможен
 * (offer от сервера: окно открыто, шкала полна, есть живые враги). Как и
 * у книги, выбор цели — клик по подсвеченному врагу; сама кнопка лишь
 * взводит режим, сервер валидирует окончательно.
 */
function tacHsRenderHeroAttackButton(st: any, side: number) {
  const btn = tacHsEl('tac-hs-hero-attack') as HTMLButtonElement | null;
  if (!btn) return;
  const offer = st.hero_attack;
  const canAttack = !!offer && offer.side === side && (offer.targets || []).length > 0;
  btn.style.display = canAttack ? '' : 'none';
  btn.classList.toggle('tac-ibtn-on', !!hs.heroAttackArmed);
  btn.title = hs.heroAttackArmed
    ? 'Атака героя взведена — выберите врага (Esc — отмена)'
    : 'Атака героя: удар без заклинания (полный ход)';
}

/** Кнопка «Атака» в окне хода героя: взвести прицел и ждать клик по врагу.
 *
 * Повторное нажатие снимает взвод (как повторный клик по книге). Взвод не
 * меняет состояние боя — сервер видит его только в отправленном действии.
 */
export function tacHsArmHeroAttack() {
  if (!hs.state || hs.state.hero_turn == null) return;
  hs.heroAttackArmed = !hs.heroAttackArmed;
  if (hs.heroAttackArmed) {
    // Книга и атака — взаимоисключающие прицелы: иначе клик по врагу ушёл
    // бы в каст из книги, а игрок ждал удар.
    resetHeroBook();
  }
  tacHsRender();
}

export function tacHsRender() {
  const st = hs.state;
  if (!st) return;
  tacHsClearHints();
  if (st.winner !== null && st.winner !== undefined) { tacHsFinish(st); return; }
  if (hs.autoBattle) {
    // Ход отыгрывает ИИ — подсказки «куда пойти / кого ударить» только мешали бы
    // (кликать всё равно нечего, см. гвард в tacHsFieldClick). Кольца тоже нет:
    // следующий ход заказывается сразу, `tacHsAct` снимает подсказки, и кольцо
    // успело бы только мигнуть — а на время ходьбы осталось бы на покинутой клетке.
    tacHsStatus(`🤖 Автобой — раунд ${st.round ?? '?'}`);
    return;
  }

  // Ход ГЕРОЯ — не ход отряда: активного отряда нет вовсе, и всё, что рисуется
  // ниже (кого ударить, куда пойти, оборона, ожидание), сервер в этом окне
  // отвергает. Раньше окно героя выглядело обычным ходом отряда, и игрок бил в
  // «Not player's turn» на каждый клик.
  if (st.hero_turn !== null && st.hero_turn !== undefined) {
    tacHsRenderHeroTurn(st, st.hero_turn);
    return;
  }

  const idx = st.active_stack;
  const pos = battleBoard.stackPositions[idx];
  const side = st.active_side || 0;
  const actions = st.available_actions || [];
  const serverStack = (st.stacks || []).find((s: any) => s.idx === idx);

  // Активный отряд
  markStack(pos, 'tac-active');
  tacRingUnderActive(st);

  // Куда можно пойти. Сервер присылает ЯКОРНЫЕ клетки (верх-левый угол следа), и
  // подсветка по одной клетке на якорь врала для 2x2: занимаемая площадь выглядела
  // как слот под маленькое существо, а правый/нижний край доступной зоны вовсе не
  // подсвечивался. Красим весь след — size приходит от сервера (grid.footprint:
  // якорь + (size-1) вправо и вниз, ровно как мержится td на доске).
  hs.activeSize = (serverStack && serverStack.size) || 1;
  // Пока выбрано заклинание героя, подсказки хода не рисуются: игрок целится.
  const heroTargets = heroSpellTargets();
  const heroCells = heroSpellCells();
  // Взведённый навес — тоже прицеливание: подсказки хода («куда пойти», «кого
  // ударить одной целью») в этот момент говорят не о том выстреле, который
  // случится по клику, и не дают увидеть, что цель у него теперь площадная.
  const aiming = hs.spell || !!hs.heroSpell || !!hs.ability || hs.scatter || unitSpellAiming();
  // Цели заклинания из СВОЕЙ книги отряда: список приходит вместе с книгой,
  // как и у героя, — клиент правил прицеливания не повторяет.
  for (const idx of unitSpellTargets()) markStack(battleBoard.stackPositions[idx], 'tac-spell-target');
  tacHsBindSpellQueuePreview();
  for (const idx of heroTargets) markStack(battleBoard.stackPositions[idx], 'tac-spell-target');
  // Второй шаг «Телепорта»: куда переносить. Клетки серверные — [x, y].
  for (const [x, y] of heroCells) {
    const td = dep.getCell(y, x);
    if (td) td.classList.add('tac-spell-cell');
  }
  if (hs.heroSpellTarget !== null) {
    const tp = battleBoard.stackPositions[hs.heroSpellTarget];
    const td = tp ? dep.getCell(tp.row, tp.col) : null;
    if (td) td.classList.add('tac-spell-source');
  }
  const move = actions.find((a: any) => a.type === 'move');
  if (!aiming && move) {
    for (const [x, y] of move.cells) {
      for (const [fr, fc] of tacHsFootprint(y, x, hs.activeSize)) {
        const td = dep.getCell(fr, fc);
        if (td) td.classList.add('tac-reach');
      }
    }
  }
  // Кого можно ударить
  if (!aiming) {
    for (const a of actions) {
      if (a.type !== 'attack') continue;
      markStack(battleBoard.stackPositions[a.target_idx], 'tac-targetable');
    }
  } else if (hs.spell) {
    // Выбрано умение отряда — подсвечиваем только его цели (цели заклинания
    // героя подсвечены выше: они приходят отдельным списком в книге).
    for (const a of actions) {
      if (a.type !== 'spell' || a.spell_name !== hs.spell) continue;
      markStack(battleBoard.stackPositions[a.target_idx], 'tac-spell-target');
    }
  } else if (hs.scatter) {
    // Взведён навес — свободный прицел, как в оригинале: подсвечиваем ТОЛЬКО
    // активного стрелка. Постоянные зоны 3х3 вокруг целей больше не рисуются:
    // область теперь следует за курсором (tac-area-preview в battleHotseatInput),
    // как красная рамка оригинала, — статичные зоны спорили с ней за одни клетки.
    markStack(battleBoard.stackPositions[st.active_stack], 'tac-spell-target');
  } else if (hs.ability) {
    // Взведено активируемое умение — светятся ровно те отряды, по которым
    // сервер его пропустит. Список целей приходит вместе с самим умением,
    // поэтому клиент не гадает о правилах прицеливания.
    const offer = actions.find((a: any) => a.type === 'ability' && a.skill === hs.ability);
    // Прицел по клетке (scope `cell`) статично не светится: как в оригинале,
    // подсветка идёт за курсором — клетка пике / полоса двух рядов
    // (tacHsFieldHover в battleHotseatInput).
    if (offer?.scope === 'ally_cell' && hs.abilityCellTarget !== null) {
      // Второй шаг «Переносчика»: выбранный отряд кольцуется, клетки
      // назначения (серверные, поле cells) подсвечиваются — как «Телепорт»
      // героя. Клики вне этих клеток ввод не принимает.
      markStack(battleBoard.stackPositions[hs.abilityCellTarget], 'tac-spell-source');
      for (const [x, y] of tacHsCarrierCells(offer, hs.abilityCellTarget)) {
        const td = dep.getCell(y, x);
        if (td) td.classList.add('tac-spell-cell');
      }
    } else if (offer?.scope === 'cell' && tacHsAbilityCells(offer).length
               && offer.skill !== 'gating') {
      // «Призыв пещерных владык»: прицел — клетки ТРУПОВ, и сервер присылает
      // их списком (`cells`). Подсвечиваем ровно их — так же, как в оригинале
      // горит клетка павшего отряда (onmousemovep.js:2098), — и клики мимо
      // ввод не отправит. Остальные клеточные умения прицелятся свободно,
      // подсветка за ними тянется за курсором.
      //
      // Исключение — «Открытие врат Ада» любого размера: там `cells` это якоря
      // габаритов, и статичная подсветка залила бы всё поле. Как в оригинале
      // (onmousemovep.js:2146, `setshad(0,0,bigx,bigy,true)`) — тень одного
      // габарита следует за курсором (battleHotseatInput).
      for (const [x, y] of tacHsAbilityCells(offer)) {
        const td = dep.getCell(y, x);
        if (td) td.classList.add('tac-spell-cell');
      }
    } else if (offer?.scope === 'cell' && tacHsAbilityCells(offer).length) {
      // Прицел по габариту: подсветки нет, зону рисует battleHotseatInput.
    } else {
      for (const t of (offer?.targets || [])) {
        markStack(battleBoard.stackPositions[t.idx], 'tac-spell-target');
      }
    }
  }

  // Панель хода
  const turnEl = tacHsEl('tac-hs-turn');
  if (turnEl) {
    const who = TAC_HS_SIDES[side] || `Сторона ${side}`;
    const name = pos ? pos.nameRu : (serverStack?.name || '—');
    const cnt = serverStack ? serverStack.count : (pos?.cnt ?? '');
    // Фаза суток фараона (☀/🌙): она меняет цену и силу заклинаний своей школы,
    // а раз в раунд переключается — без индикатора игрок не видит, что идёт.
    const phase = (st.phases || {})[String(side)];
    const phaseTag = phase
      ? ` · <span title="${phase === 'night'
        ? 'Ночь: магия тьмы дешевле и сильнее' : 'День: магия света дешевле и сильнее'}">`
        + `${phase === 'night' ? '🌙' : '☀'}</span>`
      : '';
    turnEl.innerHTML = `<b style="color:${dep.tacTeamColor(pos?.team ?? (side === 0 ? 1 : 2))}">${who}</b>`
      + ` · ${name} ×${cnt} · Р${st.round}${phaseTag}`;
  }
  // «Заклинание/Умение» — одна кнопка и на магию героя, и на активируемые умения
  // отряда (оригинал: «Нажмите кнопку "Заклинание/Умение", чтобы применить
  // активируемое умение. Чтобы отменить — нажмите повторно»). Появляется, только
  // если этому отряду есть что применить.
  const canScatter = actions.some((a: any) => a.type === 'attack' && a.can_scatter);
  // Заклинания отряда переехали в СВОЮ книгу магии (renderUnitBook) — здесь
  // остались только заклинания героя, которые приходят тем же типом действия в
  // автоматическом режиме. Своя книга рисуется разворотом, как у героя.
  const hasSpells = actions.some((a: any) => a.type === 'spell' && !a.unit_cast);
  // Активируемые умения ходящего отряда — «Дарующий удачу», «Оцепенение»,
  // капканы и прочие, которые нажимают. Сервер присылает их вместе с целями и
  // вместе с НЕДОСТУПНЫМИ (`disabled` + причина): «нет раненых» у «Воскрешения»,
  // кончились применения у «Колеса удачи». Показываем только применимые — как в
  // оригинале, где кнопки просто нет, пока нажать нечего: серая кнопка (и серая
  // строка в списке) объясняла ровно то, чего игрок и так не пытался сделать.
  const abilities = actions.filter((a: any) => a.type === 'ability' && !a.disabled);
  if (!canScatter) hs.scatter = false;
  if (!abilities.some((a: any) => a.skill === hs.ability)) {
    hs.ability = null;
    hs.abilityCellTarget = null;
  }
  const bookBtn = tacHsEl('tac-hs-book');
  const bookImg = tacHsEl('tac-hs-book-img');
  if (bookBtn) {
    const anything = canScatter || hasSpells || abilities.length > 0;
    if (!anything) hs.bookOpen = false;
    bookBtn.style.display = anything ? '' : 'none';
    // Раскрытый список или уже выбранное умение — кнопка «нажата» (…_on).
    const lit = hs.bookOpen || hs.scatter || !!hs.spell || !!hs.ability;
    // Картинка по содержимому: есть заклинания — это КНИГА МАГИИ (btn_book),
    // нет, одни активируемые умения — кнопка умений (btn_skills). Обе картинки
    // свои, из оригинала; раньше книга дриад открывалась под иконкой умений.
    const icon = hasSpells ? 'btn_book' : 'btn_skills';
    if (bookImg) bookImg.setAttribute('src', `/img/combat/${icon}_${lit ? 'on' : 'off'}.png`);
    // Когда предложение одно, список не раскрывается — кнопка взводит его
    // сразу (loneOffer), и название переезжает в её подсказку: иначе прочитать,
    // что именно взводится, было бы негде.
    const lone = loneOffer();
    bookBtn.title = lone
      ? `${loneOfferLabel(lone)} — умение отряда. Повторное нажатие отменяет.`
      : hasSpells ? 'Заклинание героя' : 'Умение отряда';
  }
  // Режим Shift. Смысл у него зависит от отряда — ровно как в оригинале, где
  // одна кнопка `shift_on` показывается и стрелку, и носителю «Удара и возврата»
  // (`shift_ok`, show_polep.js :12608): стрелок вместо выстрела подходит и бьёт
  // врукопашную, носитель умения бьёт и остаётся у цели. Кому нечего переключать —
  // кнопки нет. Клавишу Shift это не отменяет: работают оба способа.
  const canNoReturn = actions.some((a: any) => a.type === 'attack' && a.can_no_return);
  const canMelee = actions.some((a: any) => a.type === 'attack' && (a.melee_cells || []).length);
  if (!canNoReturn && !canMelee) hs.shiftBtn = false;
  const shiftBtn = tacHsEl('tac-hs-shift');
  if (shiftBtn) {
    shiftBtn.style.display = (canNoReturn || canMelee) ? '' : 'none';
    shiftBtn.classList.toggle('tac-ibtn-on', hs.shiftBtn);
    shiftBtn.setAttribute('aria-pressed', String(hs.shiftBtn));
    shiftBtn.title = canMelee
      ? (hs.shiftBtn
        ? 'В рукопашную (Shift): стрелок подойдёт и ударит мечом — нажмите, чтобы вернуть выстрел'
        : 'Выстрел. Нажмите (или бейте с Shift), чтобы вместо выстрела подойти и ударить врукопашную')
      : (hs.shiftBtn
        ? 'Без возврата (Shift): отряд ударит и останется у цели — нажмите, чтобы вернуть отход'
        : 'Удар и возврат: после удара отряд отходит назад. Нажмите (или бейте с Shift), чтобы остаться у цели');
  }
  // Оборона: её прячет окно героя (tacHsRenderHeroTurn), и вернуть её больше
  // некому — своей ветки видимости у кнопки нет, она всегда доступна отряду.
  const defendBtn = tacHsEl('tac-hs-defend');
  if (defendBtn) defendBtn.style.display = '';
  const waitAction = actions.find((a: any) => a.type === 'wait');
  const waitBtn = tacHsEl('tac-hs-wait');
  if (waitBtn) {
    // Ждать можно один раз за раунд — после возврата в очередь отряд ходит обычным ходом.
    (waitBtn as HTMLButtonElement).disabled = !waitAction?.requeue;
    waitBtn.title = waitAction?.requeue
      ? 'Ожидание (W): пропустить очередь — отряд походит позже в этом раунде'
      : 'В этом раунде отряд уже ждал';
    // Наведение показывает БУДУЩУЮ очередь — куда отряд встанет, если подождёт.
    // Так в оригинале: игрок видит цену ожидания до нажатия, а не после.
    // Очередь считает сервер тем же кодом, что и обычную (queue_if_wait), —
    // повторять правило «половина стоимости хода назад» на клиенте нельзя,
    // разойдётся с движком.
    tacHsBindWaitPreview(waitBtn as HTMLButtonElement, st);
  }
  tacHsRenderBook(actions, serverStack, canScatter);
  renderHeroBook();
  renderUnitBook();
  renderRuneScroll();
  tacHsRenderQueue(st);
  const heroSpellName = hs.heroSpell
    ? (allData.magics?.[hs.heroSpell]?.name || hs.heroSpell) : '';
  tacHsStatus(hs.heroSpell
    ? (hs.heroSpellTarget !== null
      ? `🔮 ${heroSpellName}: выберите клетку переноса (Esc — отмена)`
      : heroSpellAiming() === 'cell'
        ? `🔮 ${heroSpellName}: наведите область на клетку — накроет всех внутри (Esc — отмена)`
        : `🔮 ${heroSpellName}: выберите цель (Esc — отмена)`)
    : hs.unitSpell
    ? `📖 ${allData.magics?.[hs.unitSpell]?.name || hs.unitSpell}: `
      + (unitSpellAimingMode() === 'cell'
        ? 'наведите область на клетку — накроет всех внутри; каст потратит ход отряда (Esc — отмена)'
        : 'выберите цель — каст потратит ход отряда (Esc — отмена)')
    : hs.spell
    ? '🎯 Выберите цель заклинания (кнопка «Заклинание/Умение» — отмена)'
    : hs.ability
    ? `🎯 ${allData.abilities?.[hs.ability]?.name || hs.ability}: `
      + (hs.ability === 'rushdave'
        ? 'выберите клетку полосы — на следующем ходу пике накроет её ряд и ряд ниже во всю ширину поля, все враги в полосе получат 75% урона '
        : (hs.state?.available_actions || []).some((a: any) => a.type === 'ability' && a.skill === hs.ability && a.scope === 'ally_cell')
          ? hs.abilityCellTarget === null
            ? 'выберите отряд, который перенесём (повторный Esc — отмена всего умения) '
            : 'выберите клетку, куда перенесём — в радиусе движения носителя '
          : (hs.state?.available_actions || []).some((a: any) => a.type === 'ability' && a.skill === hs.ability && a.scope === 'cell')
            ? tacHsAbilityCells((hs.state?.available_actions || [])
                .find((a: any) => a.type === 'ability' && a.skill === hs.ability)).length
              // Призванные из трупа владыки встают на место павших: подсвечены
              // только клетки трупов (серверный список `cells`).
              ? 'выберите подсвеченную клетку павшего союзника — пещерные владыки оживут на ней '
              : 'выберите клетку поля — любую, даже пустую '
          : 'выберите цель ')
      + (hs.ability === 'rushdave' ? '' : '(кнопка «Заклинание/Умение» — отмена)')
    : hs.scatter
      ? '🎯 Навес: клик по любой клетке поля — красная рамка 3×3 следует за курсором, накрытые отряды (и СВОИ) получают половину урона. Esc — отмена'
      : hs.bookOpen
        ? '📖 Выберите заклинание или умение (повторное нажатие кнопки — отмена)'
        : '🎯 Клик по врагу — атака, по светлой клетке — ход. Или кнопки справа.');
}

/** Вращающееся кольцо под ходящим отрядом — `show_ring()` оригинала (:12129).
 *
 * Спрайты настоящие: `ring1` (золотое) и `ring2` (красное) вырезаны из атласа
 * `war_images` игры, тот же файл идёт через наш кэш-прокси.
 *
 * Цвет — по стороне: оригинал берёт второе кольцо, когда владелец отряда не
 * `playero` («золотое — мой отряд, красное — чужой»), а зритель у него всегда
 * один. За одной клавиатурой сидят двое, и единственное осмысленное чтение —
 * «игрок 1 (слева) свой, игрок 2 (справа) чужой»: в обычном пошаговом бою это
 * ровно человек против движка, а в хотсите цвет сразу говорит, чей сейчас ход.
 *
 * Рисуется псевдоэлементом клетки, поэтому лежит НИЖЕ спрайта существа (канвас
 * сцены перекрывает таблицу целиком) — как `ring.z` под юнитом в оригинале.
 */
function tacRingUnderActive(st: any): void {
  const pos = battleBoard.stackPositions[st.active_stack];
  const cell = pos ? dep.getCell(pos.row, pos.col) : null;
  if (!cell) return;
  cell.classList.add(st.active_side === 1 ? 'tac-ring-foe' : 'tac-ring-own');
  // След 2x2 шире клетки вдвое — и кольцо в оригинале тоже вдвое (`xs*=2`).
  // Размер берём из ответа сервера, а не из `hs.activeSize`: в ветке автобоя тот
  // ещё не переприсвоен и остался от прошлого хода.
  const size = (st.stacks || []).find((s: any) => s.idx === st.active_stack)?.size || 1;
  if (size > 1) cell.classList.add('tac-ring-big');
}

/** Раскрытая книга: заклинания героя и активируемые умения отряда одним списком. */
function tacHsRenderBook(actions: any, serverStack: any, canScatter: any) {
  const box = tacHsEl('tac-hs-spells');
  if (!box) return;
  if (!hs.bookOpen) { box.innerHTML = ''; box.style.display = 'none'; return; }
  // По одному предложению на заклинание: целей у каждого много, а кнопка одна.
  // Первое предложение несёт и цену — у заклинаний ОТРЯДА она своя (`mana_cost`)
  // и с геройской не совпадает: дриада платит за «Рассеивание» 20, герой — 10.
  const offers = new Map<string, any>();
  for (const a of actions) {
    // Заклинания САМОГО отряда сюда не попадают: у них своя книга-разворот.
    if (a.type === 'spell' && !a.unit_cast && !offers.has(a.spell_name)) offers.set(a.spell_name, a);
  }
  const names = [...offers.keys()];
  let html = '';
  if (canScatter) {
    html += `<button class="tac-hs-btn${hs.scatter ? ' tac-hs-btn-on' : ''}" onclick="tacHsPickAbility('scatter')"`
      + ` title="Свободный прицел, как в оригинале: клик по любой клетке поля — рамка 3×3 следует за курсором, каждый задетый отряд получает 50% урона, включая ваши собственные">`
      + `🏹 Стрельба навесом</button>`;
  }
  // Активируемые умения отряда идут первыми: это его собственные умения, а
  // заклинания ниже — героя. Подпись берётся из общего справочника способностей
  // (allData.abilities), поэтому русских имён в коде боя не заводится.
  // Недоступные (`disabled`) сюда не попадают: применить их нельзя, а серая
  // строка с причиной только удлиняла список тем, чего в нём делать нечего.
  for (const a of actions.filter((x: any) => x.type === 'ability' && !x.disabled)) {
    const on = hs.ability === a.skill;
    const label = allData.abilities?.[a.skill]?.name || a.skill;
    const hint = a.scope === 'none'
      ? 'Применить — цель не нужна'
      : a.scope === 'self' ? 'Применить на себя' : 'Выберите цель на поле';
    html += `<button class="tac-hs-btn${on ? ' tac-hs-btn-on' : ''}"`
      + ` onclick="tacHsPickAbility('skill:${a.skill}')"`
      + ` title="${hint}">`
      + `<img class="tac-hs-btn-icon" src="/img/combat/btn_skills_off.png" alt="">${label}</button>`;
  }
  html += names.map((n: string) => {
    const sp = allData.magics?.[n];
    const on = hs.spell === n;
    const offer = offers.get(n);
    const cost = offer?.mana_cost ?? sp?.mana;
    // Иконка заклинания — та же, что в книге магии героя (`spellIconUrl`,
    // кэш-прокси на картинки оригинала). Эмодзи здесь были ровно тем «похожим
    // значком», который не нужен, когда есть настоящий ассет.
    const art = spellIconUrl(n);
    const hint = offer?.unit_cast ? 'Заклинание отряда: тратит его ход' : 'Заклинание героя';
    return `<button class="tac-hs-btn${on ? ' tac-hs-btn-on' : ''}" onclick="tacHsPickSpell('${n}')"`
      + ` title="${hint}">`
      // У трёх заклинаний картинки в книге магии оригинала нет вовсе — они
      // существам-только («Небо и земля», «Гипноз»), и в данных помечены
      // `-fake.png`. Кэш отдаёт по ним 404, поэтому подставляем обложку книги:
      // без запасного варианта в списке висела бы битая картинка.
      + `<img class="tac-hs-btn-icon" src="${art}" alt=""`
      + ` onerror="this.onerror=null;this.src='/img/combat/btn_book_off.png'">`
      + `${sp?.name || n}${cost ? ` (${cost})` : ''}</button>`;
  }).join('');
  const mana = serverStack?.mana;
  if (names.length && mana !== null && mana !== undefined) {
    html += `<span style="color:var(--text-dim);font-size:12px;align-self:center">мана ${mana}</span>`;
  }
  box.innerHTML = html;
  box.style.display = 'flex';
}

/** Единственное предложение отряда, когда выбирать больше не из чего.
 *
 * У подавляющего большинства существ активируемое умение ровно одно (а у
 * стрелка — один навес), героя в бою может не быть вовсе. Раскрывать ради
 * одного пункта список — значит показать под круглой кнопкой её же копию: та же
 * картинка `btn_skills`, то же название, что и в её подсказке. Поэтому кнопка
 * взводит такое умение сразу, а список остаётся для настоящего выбора —
 * заклинания героя, навес вместе с умением, второе умение. Недоступного здесь
 * не бывает вовсе: его не показывает ни кнопка, ни список.
 */
function loneOffer(): string | null {
  const actions = hs.state?.available_actions || [];
  // Заклинания героя списку оставляем всегда: у них цена в мане и остаток её же
  // строкой ниже — под круглой кнопкой этого не покажешь.
  if (actions.some((a: any) => a.type === 'spell' && !a.unit_cast)) return null;
  const scatter = actions.some((a: any) => a.type === 'attack' && a.can_scatter);
  const abilities = actions.filter((a: any) => a.type === 'ability' && !a.disabled);
  if (scatter && !abilities.length) return 'scatter';
  if (!scatter && abilities.length === 1) return `skill:${abilities[0].skill}`;
  return null;
}

/** Название единственного предложения — для подсказки круглой кнопки. */
function loneOfferLabel(key: string): string {
  if (key === 'scatter') return 'Стрельба навесом';
  const skill = key.slice(6);
  return allData.abilities?.[skill]?.name || skill;
}

/** Кнопка «Заклинание/Умение»: раскрыть список, повторное нажатие — отмена выбора. */
export function tacHsToggleBook() {
  if (hs.bookOpen || hs.spell || hs.scatter || hs.ability) {
    hs.bookOpen = false;
    hs.spell = null;
    hs.scatter = false;
    hs.ability = null;
  } else {
    const lone = loneOffer();
    if (lone) { tacHsPickAbility(lone); return; }
    hs.bookOpen = true;
  }
  tacHsRender();
};

export function tacHsPickSpell(name: any) {
  hs.spell = hs.spell === name ? null : name;
  hs.scatter = false;
  hs.bookOpen = !hs.spell;
  tacHsRender();
};

/** Кнопка режима Shift (оригинал, :16209). Переключатель живёт до конца хода
 * отряда: как и `shift_button`, он не сбрасывается на каждом клике. Прицел под
 * неподвижной мышью пересчитывается сразу — у стрелка меняется и курсор, и
 * подсветка подхода. */
export function tacHsToggleShift() {
  hs.shiftBtn = !hs.shiftBtn;
  tacHsRender();
  tacHsRefreshAim();
}

/** «Ожидание» и «Оборона» — одни и те же кнопки и у отряда, и у героя.
 *
 * В оригинале ряд круглых кнопок один и тот же в оба хода, поэтому и здесь
 * кнопка одна, а тип действия выбирается по тому, чьё сейчас окно: у отряда
 * это `wait`/`defend`, у героя — `hero_wait` (полхода по шкале, п.6.2
 * руководства) и `hero_defend` (ход отдан целиком). Раньше в окне героя
 * «Оборона» пряталась, «Ожидание» гасло, а вместо них появлялась отдельная
 * кнопка ⤼ — в оригинале такой кнопки нет.
 */
function tacHsHeroWindow(): boolean {
  return !!hs.state && hs.state.hero_turn !== null && hs.state.hero_turn !== undefined;
}

export function tacHsWait() {
  tacHsAct({ type: tacHsHeroWindow() ? 'hero_wait' : 'wait' });
}

export function tacHsDefend() {
  tacHsAct({ type: tacHsHeroWindow() ? 'hero_defend' : 'defend' });
}

export function tacHsPickAbility(key: any) {
  if (key === 'scatter') {
    hs.scatter = !hs.scatter;
    hs.spell = null;
    hs.ability = null;
    // Список умений ОСТАЁТСЯ открытым, пока навес взведён: нажатая кнопка в нём —
    // постоянный признак режима, и закрывающийся список читался как «нажал, и
    // ничего не произошло». Снятие режима список закрывает. Когда же навес —
    // единственное предложение, списка нет вовсе: режим виден по загоревшейся
    // круглой кнопке и строке состояния.
    hs.bookOpen = hs.scatter && !loneOffer();
    tacHsRender();
    return;
  }
  if (typeof key === 'string' && key.startsWith('skill:')) {
    const skill = key.slice(6);
    if (hs.ability === skill) {
      hs.ability = null;
      hs.abilityCellTarget = null;
      tacHsRender();
      return;
    }
    const offer = (hs.state?.available_actions || [])
      .find((a: any) => a.type === 'ability' && a.skill === skill);
    // Серая кнопка не взводится: умение есть, но применить его сейчас нечем.
    if (!offer || offer.disabled) return;
    hs.spell = null;
    hs.scatter = false;
    hs.abilityCellTarget = null;
    // Умение без цели (капканы, взрыв, вопль) и умение на себя («Невидимость»)
    // применяются сразу: выбирать игроку нечего, а лишний клик по своей же
    // клетке выглядел бы как отдельный шаг, которого в оригинале нет.
    if (offer.scope === 'none' || offer.scope === 'self') {
      hs.ability = null;
      hs.bookOpen = false;
      const target = offer.scope === 'self' ? hs.state?.active_stack : undefined;
      // tacHsAct — функция ЭТОГО модуля; в `dep` (зависимости из battle.ts) её
      // нет, и вызов через dep падал «tacHsAct is not a function»: безцельные
      // умения (взрыв, вопль, капканы) с круглой кнопки не применялись вовсе.
      tacHsAct({ type: 'ability', skill, target_idx: target });
      return;
    }
    hs.ability = skill;
    hs.bookOpen = false;
    // Анимация нанесения у умения с прогнозом («Зов молний»): прогреваем атлас
    // вспышки ещё при взводе, чтобы первый удар не ждал загрузку спрайта —
    // щиток-то уже обещал, чем молния обойдётся.
    if (offer.anim) warmSpellAnim(offer.anim);
  }
  tacHsRender();
};

/** Подсказка очереди при прицеливании заклинанием.
 *
 * Наведение на цель показывает, какой станет лента: «Ускорение» поднимет отряд,
 * «Замедление» опустит, «Осиный рой» отбросит по шкале. Считает это сервер
 * (`queue_preview` — действие только на чтение, ход оно не делает): правила
 * инициативы сложены из процентов статусов, героя и аур, и повторять их здесь
 * значит рано или поздно соврать игроку.
 *
 * Слушатель делегированный и вешается ОДИН раз на поле: клетки перерисовываются
 * каждый ход, и обработчики на них копились бы десятками.
 */
let tacPreviewIdx: number | null = null;
function tacHsBindSpellQueuePreview(): void {
  const field = tacHsEl('tac-field');
  if (!field || (field as any)._tacQueuePreviewBound) return;
  (field as any)._tacQueuePreviewBound = true;

  const stackAt = (td: HTMLElement): number | null => {
    const row = Number(td.dataset.row), col = Number(td.dataset.col);
    for (const key in battleBoard.stackPositions) {
      const p = (battleBoard.stackPositions as any)[key];
      if (p && p.row === row && p.col === col) return Number(key);
    }
    return null;
  };

  field.addEventListener('mouseover', async (e: any) => {
    const td = e.target?.closest?.('#tac-field td.tac-spell-target') as HTMLElement | null;
    // Прицел бывает двух видов: книга героя (hs.heroSpell) и своя книга
    // отряда-колдуна (hs.unitSpell). Сервер разбирает оба одним действием —
    // кто колдует, он знает по фазе хода.
    const key = hs.heroSpell || hs.unitSpell;
    if (!td || !key || hs.busy || !hs.session || !hs.state) return;
    const idx = stackAt(td);
    if (idx === null || idx === tacPreviewIdx) return;
    tacPreviewIdx = idx;
    const sys = key.endsWith('#p') ? key.slice(0, -2) : key;
    const powered = key.endsWith('#p');
    try {
      const res = await fetch('/api/battle/step', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ session_id: hs.session,
                               action: { type: 'queue_preview', spell: sys,
                                         target_idx: idx, powered } }),
      });
      const data = await res.json();
      // Курсор мог уже уйти на другую цель, пока ответ был в пути.
      if (tacPreviewIdx !== idx || !data || !data.queue_preview) return;
      tacHsRenderQueue(hs.state, data.queue_preview, idx);
    } catch { /* подсказка не критична: молча остаёмся с текущей лентой */ }
  });

  field.addEventListener('mouseout', (e: any) => {
    const td = e.target?.closest?.('#tac-field td.tac-spell-target');
    if (!td || tacPreviewIdx === null) return;
    tacPreviewIdx = null;
    if (hs.state) tacHsRenderQueue(hs.state);
  });
}

/** Показ будущей очереди, пока курсор на кнопке «Ожидание».
 *
 * Слушатели вешаются один раз (флаг на самом узле): панель хода
 * перерисовывается каждый ход, и без флага на кнопке копились бы десятки
 * обработчиков. Состояние берётся свежее — его кладёт сюда каждая перерисовка.
 */
function tacHsBindWaitPreview(btn: HTMLButtonElement, st: any): void {
  (btn as any)._tacWaitState = st;
  if ((btn as any)._tacWaitBound) return;
  (btn as any)._tacWaitBound = true;
  const show = () => {
    const state = (btn as any)._tacWaitState;
    if (!state || btn.disabled || !state.queue_if_wait) return;
    tacHsRenderQueue(state, state.queue_if_wait);
  };
  const hide = () => {
    const state = (btn as any)._tacWaitState;
    if (state) tacHsRenderQueue(state);
  };
  btn.addEventListener('mouseenter', show);
  btn.addEventListener('mouseleave', hide);
  // Клавиатура и тач: фокус ведёт себя как наведение, а после нажатия панель
  // всё равно перерисуется с новой очередью.
  btn.addEventListener('focus', show);
  btn.addEventListener('blur', hide);
}

/** Лента очереди из серверного ATB-прогноза (в реплее её строит tacBuildTurnQueue). */
function tacHsRenderQueue(st: any, previewQueue?: any[], markIdx?: number) {
  const cont = tacHsEl('tac-initiative');
  if (!cont) return;
  const queue = previewQueue || st.queue || [];
  if (!queue.length) return;
  // В предпросмотре лента приглушена, а фишка того, кого он касается,
  // подсвечена: без пометки непонятно, что показанный порядок — ещё не
  // случившийся. У «Ожидания» это сам ходящий отряд, у заклинания — его цель.
  cont.classList.toggle('tac-init-preview', !!previewQueue);
  const waitingIdx = previewQueue
    ? (markIdx !== undefined ? markIdx : st.active_stack)
    : null;
  // Если игрок отмотал ленту вправо, чтобы посмотреть будущие ходы, — сохраняем
  // положение: очередь перестраивается каждый ход, и сброс в 0 делал ленту
  // фактически непрокручиваемой во время боя. Тот же приём, что в ленте реплея.
  const keepScroll = cont.scrollLeft > 10 ? cont.scrollLeft : 0;
  const counts: Record<string, number> = {};
  for (const s of (st.stacks || [])) counts[s.idx] = s.count;
  let html = '';
  queue.forEach((entry: any, i: any) => {
    // Ход героя приходит словарём {'hero': side}: его шкала (hero_tl) готова и
    // обогнала готовые отряды — в оригинале фишка героя так же встаёт в ATB-ряд.
    if (entry && typeof entry === 'object') {
      const info = heroChipInfo(entry.hero as 0 | 1);
      html += `<div class="tac-init-unit tac-init-hero tac-init-hero--click${i === 0 ? ' tac-init-active' : ''}"
                    data-hero-side="${entry.hero}" data-hero-book="1"
                    style="${dep.tacTeamChipStyle(entry.hero === 0 ? 1 : 2)}"
                    title="${info ? info.name : 'Герой'} · ход героя (магия) — клик открывает книгу">
        ${info ? heroChipFace(info) : ''}
        <span class="tac-init-cnt">⚔</span>
      </div>`;
      return;
    }
    const idx = entry;
    const p = battleBoard.stackPositions[idx];
    if (!p) return;
    const mark = idx === waitingIdx ? ' tac-init-waiting'
      : i === 0 && !previewQueue ? ' tac-init-active' : '';
    html += `<div class="tac-init-unit${mark}" data-idx="${idx}"
                  style="${dep.tacTeamChipStyle(p.team)}"
                  title="${p.nameRu} ×${counts[idx] ?? p.cnt ?? ''}">
      <img src="${tacPortraitUrl(p.pic)}" alt="">
      <span class="tac-init-cnt">${counts[idx] ?? p.cnt ?? '?'}</span>
    </div>`;
  });
  cont.innerHTML = html;
  cont.scrollLeft = keepScroll;
  dep.tacUpdateInitScroll();
}

function tacHsFinish(st: any) {
  const winner = st.winner;
  const msg = winner === 0 ? '⚔ Победа игрока 1 (слева)'
    : winner === 1 ? '☠ Победа игрока 2 (справа)' : '🤝 Ничья';
  tacHsStatus(`🏁 Бой окончен — ${msg}`);
  const resultDiv = tacHsEl('tac-result');
  if (resultDiv) {
    resultDiv.insertAdjacentHTML('beforeend',
      `<hr style="border-color:var(--gold-dim);margin:8px 0">`
      + `<div style="color:#4caf50;font-weight:700;font-size:18px;text-align:center;padding:8px">${msg}</div>`
      + `<div style="color:var(--text-dim);text-align:center;font-size:14px">Раундов: ${st.round}</div>`);
    resultDiv.scrollTop = resultDiv.scrollHeight;
  }
  // Поле остаётся как есть (выжившие и трупы); откат — по следующему «в бой».
  hs.savedSetup = hs.setup;
  hs.endStateShown = true;
  tacHsStop();
}

/** Выйти из боя: снять подсветку, отвязать клики, вернуть поле редактору. */
function tacHsStop() {
  // Живые хореографии гасим (task-005/5b): выход посреди анимации больше не
  // ждёт, пока отряд домашляет текущий жест, — очередь прерывается на текущем
  // шаге, а очередь раздачи действий увидит отмену и сойдёт с цикла.
  tacCancelAllChains();
  tacHsClearHints();
  tacHsBindField(false);
  hs.session = null;
  hs.state = null;
  hs.spell = null;
  hs.scatter = false;
  hs.bookOpen = false;
  resetHeroBook();
  renderHeroBook();
  resetUnitBook();
  renderUnitBook();
  resetRunes();
  renderRuneScroll();
  resetCursor();          // поле снова редактор — курсор системный
  const bar = tacHsEl('tac-hotseat-bar');
  if (bar) bar.style.display = 'none';
  dep.tacDockTurnButtons(false);
  sndStopMusic();
  dep.tacLeaveBattleArena(); // вернуть вид редактора; toggle сам форс-пересчитает раскладку
  tacFitField();
  // Бой окончен — ленту гасим: очередь из одних победителей занимала всю строку
  // и выглядела как чей-то ход. Вернётся с первой же правкой расстановки.
  dep.tacClearInitiative();
}
export { tacHsStop as tacHotseatStop };
export function tacHsSurrender() {
  // Раньше здесь стоял `if (tacPlaybackRunning()) return`: выход из боя был
  // невозможен ровно тогда, когда он нужнее всего — посреди автохода или
  // реплея, когда горит прогресс. Запрет держался потому, что очередь
  // действий не умела прерываться; теперь умеет (task-005/5b): tacHsStop гасит
  // живые хореографии, цикл раздачи видит отмену и сходит, а поле приводится
  // в порядок в его finally.
  tacHsStatus('⏹ Бой прерван');
  tacHsStop();
};
