import { allData, FACTIONS_META } from './data.js';

export const STAT_ICONS: Record<string, string> = {
  lvl: 'level', exp: 'exp', attack: 'attack', shoots: 'shoots',
  defense: 'defense', mana: 'mana', minDmg: 'damage', maxDmg: 'damage',
  range: 'distance', hp: 'hit_points', ini: 'initiative', speed: 'speed',
  leadership: 'leadership',
};

export const SKILL_ICONS: Record<string, string> = {
  'Нет навыка': 'https://dcdn.heroeswm.ru/i/magic/l0.gif',
  'Основы навыка': 'https://dcdn.heroeswm.ru/i/magic/l1.gif',
  'Развитый навык': 'https://dcdn.heroeswm.ru/i/magic/l2.gif',
  'Искусный навык': 'https://dcdn.heroeswm.ru/i/magic/l3.gif',
};

/** Route a CDN URL through the local proxy (/api/img → disk cache).
 *
 * The proxy serves from web/images/cache/ and, unless the server runs with
 * LOCAL_ONLY=1, downloads the asset on first miss. Routing everything through
 * it means the browser NEVER talks to the CDN directly — offline deployments
 * work from the pre-cached store alone. */
export function cdnImg(url: string): string {
  // Уже локальный путь (/api/...) — проксировать второй раз нельзя: /api/img
  // принимает только абсолютные http(s) и отвечает 400 на относительные.
  if (url.startsWith('/')) return url;
  return '/api/img?url=' + encodeURIComponent(url);
}

export function shuffleArray<T>(arr: T[]): T[] {
  for (var i = arr.length - 1; i > 0; i--) {
    var j = Math.floor(Math.random() * (i + 1));
    var tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
  }
  return arr;
}

export function statIcon(name: string): string {
  return '/api/img?url=https://daily-help.ru/img/stats-new/attr_' + name + '.png';
}

/** Стрелок ли существо.
 *
 * Признак — умение `shooter` в списке способностей; запас выстрелов проверяется
 * вторым, ради единственного исключения в данных: у скелета-пирата умения нет,
 * а метательные снаряды (`shoots`) есть. Строки «Выстрелы» и «Дальность» в
 * карточке показываются только этим существам: у рукопашника обе всегда нули и
 * значат лишь «не применимо».
 */
export function isShooterUnit(u: { skills?: unknown; shoots?: number } | null): boolean {
  if (!u) return false;
  const skills = Array.isArray(u.skills) ? u.skills : [];
  return skills.indexOf('shooter') !== -1 || (u.shoots || 0) > 0;
}

/** Дальность выстрела. Поле в данных называется `distance`; код долго читал
 * `range`, которого в units.json нет вовсе, и «Дальность» у всех была 0. */
export function unitDistance(u: Record<string, unknown> | null): number {
  if (!u) return 0;
  return Number(u.distance ?? u.range ?? 0) || 0;
}

export function stripHtml(s: string): string {
  const div = document.createElement('div');
  div.innerHTML = s;
  return div.textContent || div.innerText || '';
}

export function formatDesc(text: string): string {
  let html = text;
  for (const [name, url] of Object.entries(SKILL_ICONS)) {
    const re = new RegExp(name + ':+\\s*|' + name + '\\s', 'g');
    html = html.replace(re, `<img class="skill-icon" src="${cdnImg(url)}" title="${name}">`);
  }
  html = html.replace(
    /Изменение здоровья стека/g,
    '<img class="skill-icon" src="' + cdnImg('https://dcdn2.heroeswm.ru/i/icons/attr_hit_points.png') + '"> Изменение здоровья стека'
  );
  html = html.replace(/\n/g, '<br>');
  return html;
}

export function abilityName(key: string): string {
  var a = allData.abilities && allData.abilities[key];
  return a ? (a.name || key) : key;
}

export function abilityDesc(key: string): string {
  var a = allData.abilities && allData.abilities[key];
  if (!a || !a.desc) return '';
  return a.desc.replace(/<[^>]+>/g, '');
}

export function factionName(sys: string): string {
  return FACTIONS_META[sys] ? FACTIONS_META[sys].nameRu : sys;
}

export function isCreatureSysName(name: string): boolean {
  return !!(allData.units && allData.units[name]);
}

/** Текст без HTML-разметки: описания умений и заклинаний приходят с тегами. */
export function stripHtmlSimple(str: string | null | undefined): string {
  if (!str) return '';
  return str.replace(/<[^>]+>/g, '');
}
