declare const stage: any;
declare function init_army_info(...args: any[]): void;
declare function destroy_army_info(cont: string): void;

var _animScriptsLoaded = false;
var _animControlsTimer: ReturnType<typeof setTimeout> | null = null;
var _cardEffectsConfigured = false;

var CARD_ANIM_OBJ_VER = '1.4-14.bb2227';
var CARD_ANIM_FON_VER = '4.e7c6f8';
var CARD_ANIM_SUBPATH = '/api/cache/i/';

const ANIM_SOUND_KEY = 'animSoundMuted';
var animSoundOn = (function() {
  try { return localStorage.getItem(ANIM_SOUND_KEY) !== '1'; } catch { return true; }
})();
/** Глобалки движка, какими их застала открытая карточка. Звук кадров живёт в
 * window.playsound/window.soundeff; карточка поднимает их на время показа и
 * возвращает как было при закрытии — иначе звук продолжает играть и после
 * закрытия (playsound/soundeff навсегда остаются поднятыми). */
var _savedEngineSound: { playsound: unknown; soundeff: unknown } | null = null;

/** Тумблер звука анимаций в карточке существа.
 *
 * Звук кадров живёт в глобалках движка: enginep.js на кадре со «sound» зовёт
 * window.playsound() только при поднятом window.soundeff. Оба ставит
 * sndInstallEngineHook(). Выбор переживает перезагрузку в localStorage. */
function updateAnimSoundButton(): void {
  var btn = document.getElementById('animSoundToggle');
  if (!btn) return;
  btn.textContent = animSoundOn ? '🔊' : '🔇';
  btn.title = animSoundOn ? 'Выключить звук анимаций' : 'Включить звук анимаций';
  btn.setAttribute('aria-label', btn.title);
  btn.setAttribute('aria-pressed', String(animSoundOn));
}

function applyAnimSoundState(): void {
  var w = window as any;
  if (animSoundOn) {
    // Звать только когда движок поднялся: его верхнеуровневый
    // `var soundeff = 0` затёр бы любое более раннее присваивание.
    if (typeof w.add_obj === 'function') {
      // Запоминаем глобалки, какими их застала карточка: при закрытии вернём.
      if (!_savedEngineSound) _savedEngineSound = { playsound: w.playsound, soundeff: w.soundeff };
      sndInstallEngineHook();
    }
  } else {
    w.soundeff = 0;
  }
  updateAnimSoundButton();
}

/** Вернуть глобалки движка в состояние до открытия карточки. */
function restoreEngineSound(): void {
  if (!_savedEngineSound) return;
  var w = window as any;
  try { w.playsound = _savedEngineSound.playsound; } catch { /* ignore */ }
  try { w.soundeff = _savedEngineSound.soundeff; } catch { /* ignore */ }
  _savedEngineSound = null;
}

function toggleAnimationSound(): void {
  animSoundOn = !animSoundOn;
  try { localStorage.setItem(ANIM_SOUND_KEY, animSoundOn ? '0' : '1'); } catch { /* ignore */ }
  applyAnimSoundState();
}

function doAnimAction(action: string): void {
  var st = typeof stage !== 'undefined' && stage['show_army'];
  if (!st || !st.obj) return;
  var obj = st.obj[st.filename];
  if (!obj) return;
  obj.doing = action;
  obj.frame = 0;
}

function unitAnimAction(action: string): void { doAnimAction(action); }

function waitForShowArmyApis(callback: () => void, maxAttempts?: number): void {
  if (_animScriptsLoaded) {
    callback();
    return;
  }
  if (typeof maxAttempts === 'undefined') maxAttempts = 200;
  if (typeof init_army_info === 'function' && typeof Konva !== 'undefined') {
    _animScriptsLoaded = true;
    callback();
    return;
  }
  if (maxAttempts <= 0) {
    _animScriptsLoaded = true;
    callback();
    return;
  }
  setTimeout(function() { waitForShowArmyApis(callback, maxAttempts! - 1); }, 100);
}

function configureCardEffects(): void {
  var w = window as any;
  if (_cardEffectsConfigured || typeof w.show_info_effects_setup !== 'function') return;
  var nativeSetup = w.show_info_effects_setup;
  w.show_info_effects_setup = function(unit: any, filename: string, version: string, subpath: string) {
    nativeSetup(unit, filename, version, subpath);
    var options = unit && unit.hwm_show_info_effects_options;
    if (!options) return;
    options.configBase = CARD_ANIM_SUBPATH + 'effects/';
    options.atlasBase = CARD_ANIM_SUBPATH + 'effects/atlases/';
  };
  _cardEffectsConfigured = true;
}

function destroyCardAnimation(): void {
  if (typeof destroy_army_info === 'function') {
    destroy_army_info('show_army');
    return;
  }
  if (typeof stage !== 'undefined' && stage['show_army']) {
    try { cancelAnimationFrame(stage['show_army'].intervalId); } catch(e) {}
    try { stage['show_army'].destroy(); } catch(e) {}
    delete stage['show_army'];
  }
}

interface NanoState {
  atk: number;
  def: number;
  ini: number;
}

var nanoState: NanoState = { atk: 0, def: 0, ini: 0 };

function reloadAnimWithNano(): void {
  var inp = document.getElementById('creature-nav-input') as HTMLInputElement | null;
  if (!inp) return;
  var u = allData.units?.[inp.value];
  if (!u) return;
  var animUnit = (u as any).animUnit || (u as any).anim_unit || '';
  if (!animUnit || /^https?:\/\//i.test(animUnit) || /\.(png|jpe?g|gif|webp)(\?.*)?$/i.test(animUnit)) return;
  var nanoData = {naa:{effect:nanoState.atk}, nad:{effect:nanoState.def}, nai:{effect:nanoState.ini}};
  fullReinitAnim(animUnit, nanoData);
}

function fullReinitAnim(animUnit: string, nanoData: any): void {
  waitForShowArmyApis(function() {
    try {
      configureCardEffects();
      destroyCardAnimation();
      var sa = document.getElementById('show_army');
      if (sa) {
        sa.innerHTML = '';
        sa.classList.remove('loaded');
      }
      init_army_info("show_army", animUnit, CARD_ANIM_OBJ_VER, "0", CARD_ANIM_FON_VER,
        CARD_ANIM_SUBPATH, 300, 300, 2, nanoData);
      startArmyUiWatcher();
    } catch(e) { console.error('Nano anim error:', e); }
  });
}

interface NanoAvailability {
  hasAny: boolean;
  naa: boolean;
  nad: boolean;
  nai: boolean;
}

function getNanoAvailability(obj: any): NanoAvailability {
  var result: NanoAvailability = { hasAny: false, naa: false, nad: false, nai: false };
  try {
    if (!obj || !obj.statix_d || !obj.statix_d.nano_arts) return result;
    var map: Record<string, string> = { naa: 'w', nad: 'a', nai: 'i' };
    Object.keys(map).forEach(function (key) {
      var group = obj.statix_d.nano_arts[map[key]];
      if (group && Object.keys(group).length > 0) {
        result[key as keyof NanoAvailability] = true;
        result.hasAny = true;
      }
    });
  } catch (e) {}
  return result;
}

function startArmyUiWatcher(): void {
  var tries = 0;
  var maxTries = 120;
  var timer = setInterval(function () {
    tries++;
    var obj = null;
    var isInited = false;
    try {
      if (typeof stage !== 'undefined' && stage['show_army'] && stage['show_army'].obj) {
        var keys = Object.keys(stage['show_army'].obj);
        if (keys.length) {
          obj = stage['show_army'].obj[keys[0]];
          isInited = !!(obj && obj.inited);
        }
      }
    } catch(e) {}
    // Show loaded state when animation is ready
    var showArmyEl = document.getElementById('show_army');
    if (showArmyEl && isInited) {
      showArmyEl.classList.add('loaded');
    }
    var nanoStateInfo = getNanoAvailability(obj);
    var nano = document.getElementById('show_army_nano') || document.getElementById('creature-modal-nano');
    if (nano) nano.style.display = nanoStateInfo.hasAny ? '' : 'none';
    ['naa', 'nad', 'nai'].forEach(function (type) {
      var row = document.querySelector('[data-nano-row="' + type + '"]') as HTMLElement | null;
      if (row) row.style.display = (nanoStateInfo as any)[type] ? '' : 'none';
    });
    if ((obj && isInited) || tries >= maxTries) {
      clearInterval(timer);
    }
  }, 250);
}

function setNano(stat: keyof NanoState, val: number, noReload?: boolean): void {
  nanoState[stat] = val;
  document.querySelectorAll('.nano-btn[data-nano="' + stat + '"]').forEach(function(b) {
    b.classList.toggle('active', parseInt((b as HTMLElement).dataset.val || '') === val);
  });
  var nanoEl = document.getElementById('nano-' + stat);
  if (nanoEl) nanoEl.textContent = '+' + val;
  updateModalStats();
  if (!noReload) reloadAnimWithNano();
  saveNanoState();
}

function setNanoLevel(type: string, value: number): void {
  var map: Record<string, keyof NanoState> = { naa: 'atk', nad: 'def', nai: 'ini' };
  var stat = map[type];
  if (!stat) return;
  if (nanoState[stat] === value) return;
  nanoState[stat] = value;
  document.querySelectorAll('.nano-btn[data-type="' + type + '"]').forEach(function(b) {
    var v = parseInt(b.getAttribute('data-value') || '', 10);
    b.classList.toggle('active', v === value);
  });
  updateModalStats();
  reloadAnimWithNano();
  saveNanoState();
}

function saveNanoState(): void {
  var inp = document.getElementById('creature-nav-input') as HTMLInputElement | null;
  if (!inp) return;
  var name = inp.value;
  if (!name) return;
  try {
    fetch('/api/nano/save', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({name: name, state: nanoState})
    });
  } catch(e) {}
}

function loadNanoState(sysName: string, callback: (data: NanoState | null) => void): void {
  fetch('/api/nano/load?name=' + encodeURIComponent(sysName))
    .then(function(r) { return r.json(); })
    .then(function(data) {
      if (data && typeof data.atk === 'number' && typeof data.def === 'number' && typeof data.ini === 'number') {
        callback(data);
      } else {
        callback(null);
      }
    })
    .catch(function() { callback(null); });
}

function updateModalStats(): void {
  var inp = document.getElementById('creature-nav-input') as HTMLInputElement | null;
  if (!inp) return;
  var u = allData.units?.[inp.value];
  if (!u) return;
  var atk = (u.attack || 0) + nanoState.atk;
  var def = (u.defense || 0) + nanoState.def;
  var ini = (u.ini || 0) + nanoState.ini;
  var html = [
    {icon:'attack', label:'Нападение', val: atk},
    {icon:'defense', label:'Защита', val: def},
    {icon:'damage', label:'Урон', val: (u.minDmg||0) + '-' + (u.maxDmg||0)},
    {icon:'hit_points', label:'Ед. жизни', val: u.hp||0},
    {icon:'initiative', label:'Инициатива', val: ini},
    {icon:'speed', label:'Скорость', val: u.speed||0},
    {icon:'leadership', label:'Лидерство', val: u.leadership||0},
    {icon:'exp', label:'Опыт', val: u.exp||0},
    // Мана — только у колдующих существ: у остальных она ноль, и строка «Мана 0»
    // в карточке крестьянина ничего не значит. У колдуна это его запас на
    // заклинания, и считается он за каждого в отряде.
  // Выстрелы и дальность — только стрелкам: у рукопашника это нули, которые
  // читаются как характеристика, хотя означают «не применимо».
  ].concat(isShooterUnit(u) ? [
    {icon:'shoots', label:'Выстрелы', val: u.shoots||0},
    {icon:'distance', label:'Дальность', val: unitDistance(u as any) as any},
  ] : []
  ).concat(u.mana ? [{icon:'mana', label:'Мана', val: u.mana as any}] : []
  ).map(function(s) { return '<div class="modal-stat"><img src="'+statIcon(s.icon)+'" class="stat-icon"><span class="label">'+s.label+'</span><span class="value">'+s.val+'</span></div>'; }).join('');
  const statsEl = document.getElementById('creature-modal-stats');
  if (statsEl) statsEl.innerHTML = html;
}

function renderUnitStats(u: UnitRecord): string {
  var fields = [
    {key:'lvl',label:'Уровень',icon:'level',val:u.lvl||0},
    {key:'exp',label:'Опыт',icon:'exp',val:u.exp||0},
    {key:'attack',label:'Нападение',icon:'attack',val:u.attack||0},

    {key:'defense',label:'Защита',icon:'defense',val:u.defense||0},
    {key:'mana',label:'Мана',icon:'mana',val:u.mana||0},
    {key:'damage',label:'Урон',icon:'damage',val:(u.minDmg||(u as any).min_dmg||0)+'-'+(u.maxDmg||(u as any).max_dmg||0)},

    {key:'hp',label:'Ед. жизни',icon:'hit_points',val:u.hp||0},
    {key:'ini',label:'Инициатива',icon:'initiative',val:u.ini||0},
    {key:'speed',label:'Скорость',icon:'speed',val:u.speed||0},
    {key:'leadership',label:'Лидерство',icon:'leadership',val:u.leadership||0},
  ].concat(isShooterUnit(u) ? [
    {key:'shoots',label:'Выстрелы',icon:'shoots',val:u.shoots||0},
    {key:'range',label:'Дальность',icon:'distance',val:unitDistance(u as any)},
  ] : []);
  return fields.map(function(f) {
    return '<div class="stat"><img src="'+statIcon(f.icon)+'" class="stat-icon"><span class="label">'+f.label+'</span><span class="value">'+f.val+'</span></div>';
  }).join('');
}

function renderCreatureCard(u: UnitRecord | null): string {
  if (!u) return '<div class="creature-card empty">Данные недоступны</div>';
  const skills = Array.isArray(u.skills) ? u.skills : [];
  const fr = factionName(u.fraction || '') || (u.fraction || '');
  const animPortrait = ((u as any).animUnit || (u as any).anim_unit || '');
  // У объектов карты heroeswm.ru отдаёт прозрачный портрет-заглушку — вместо
  // него показываем кадр из боевого атласа (scripts/gen_statics_icons.mjs).
  const localPUrl = staticsIconUrl(animPortrait) || (animPortrait ? `/images/portraits/${animPortrait}p60.png` : '');
  const sysName = u.sysName || (u as any).sys_name || '';
  return `<div class="creature-card" data-sysname="${sysName}">
    <div class="card-row">
      ${localPUrl ? `<div class="card-portrait"><img src="${localPUrl}" class="portrait" loading="lazy" onerror="this.remove()"></div>` : `<div class="card-portrait"><div class="portrait-empty">?</div></div>`}
      <div class="card-info">
        <div class="name">${u.nameRu || sysName}</div>
        <div class="sub">${u.fraction && FACTIONS_META[u.fraction] ? '<span class="faction-link" onclick="event.stopPropagation();navigateTo(\'/factions/'+FACTIONS_META[u.fraction].nameEn+'\')">'+fr+'</span>' : fr}</div>
      </div>
    </div>
    <div class="stats">${renderUnitStats(u)}</div>
    ${skills.length ? `<div class="tags">${skills.map(function(s){var n=abilityName(s),d=abilityDesc(s);return '<span class="tag" onclick="event.stopPropagation();navigateTo(\'/abilities/'+s+'\')"'+(d?' data-label="'+d.replace(/"/g,'&quot;')+'"':'')+'>'+n+'</span>';}).join('')}</div>` : ''}
  </div>`;
}

function renderCreatures(units: UnitRecord[]): void {
  const grid = document.getElementById('creature-grid');
  const countEl = document.getElementById('creature-count');
  if (!grid || !countEl) return;
  countEl.textContent = units.length + ' существ';
  grid.className = 'creature-grid';
  grid.innerHTML = units.map(u => renderCreatureCard(u)).join('');
  grid.querySelectorAll('.creature-card').forEach(card => {
    card.addEventListener('click', function(this: HTMLElement, e) {
      var sn = this.dataset.sysname;
      if (sn) {
        try { openCreatureModal(sn); history.pushState(null, '', siteUrl('/units/' + sn)); }
        catch(ex) { console.error('openCreatureModal error:', ex); }
      }
    });
  });
}

function filterCreatures(shuffle?: boolean): void {
  const searchEl = document.getElementById('creature-search') as HTMLInputElement | null;
  const factionEl = document.getElementById('faction-filter') as HTMLSelectElement | null;
  const tierEl = document.getElementById('tier-filter') as HTMLSelectElement | null;
  if (!searchEl || !factionEl || !tierEl) return;
  
  const q = searchEl.value.toLowerCase();
  const faction = factionEl.value;
  const tier = tierEl.value;
  const isFactionPage = appPath().startsWith('/factions/');

  if (!isFactionPage && faction && !q && !tier) {
    const meta = FACTIONS_META[faction];
    if (meta) { navigateTo('/factions/' + meta.nameEn); return; }
  }

  if (isFactionPage) {
    if (!faction && !q && !tier) {
      navigateTo('/units');
      filterCreatures();
      return;
    }
    const currentKey = (() => {
      const nameToKey: Record<string, string> = {};
      for (const [k, meta] of Object.entries(FACTIONS_META)) {
        nameToKey[meta.nameEn.toLowerCase()] = k;
      }
      const p = decodeURIComponent(appPath().split('/factions/')[1] || '').toLowerCase();
      return nameToKey[p] || p;
    })();
    if (faction && faction !== currentKey) {
      const meta = FACTIONS_META[faction];
      if (meta) { navigateTo('/factions/' + meta.nameEn); return; }
    }
    if (!q && !tier) {
      const fname = decodeURIComponent(appPath().split('/factions/')[1] || '');
      renderFactionTable(fname);
      return;
    }
  }

  let list: UnitRecord[] = allData.units ? Object.values(allData.units) : [];
  if (shuffle) shuffleArray(list);
  if (faction) list = list.filter(u => u.fraction === faction);
  if (tier) list = list.filter(u => String((u as any).tier || u.lvl || '') === tier);
  if (q) {
    list = list.filter(u =>
      (u.nameRu || '').toLowerCase().includes(q) ||
      (u.nameEn || '').toLowerCase().includes(q) ||
      (u.sysName || (u as any).sys_name || '').toLowerCase().includes(q)
    );
  }
  list.sort((a, b) => ((a as any).tier || a.lvl || 99) - ((b as any).tier || b.lvl || 99));
  renderCreatures(list);
}

function initCreatures(): void {
  const sel = document.getElementById('faction-filter') as HTMLSelectElement | null;
  if (!sel) return;
  for (const [key, meta] of Object.entries(FACTIONS_META)) {
    const opt = document.createElement('option');
    opt.value = key;
    opt.textContent = meta.nameRu;
    sel.appendChild(opt);
  }
  var fm = appPath().match(/^\/factions\/(.+)/);
  if (fm) {
    var nameToKey: Record<string, string> = {};
    for (var k in FACTIONS_META) nameToKey[FACTIONS_META[k].nameEn.toLowerCase()] = k;
    var foundKey = nameToKey[fm[1].toLowerCase()] || fm[1].toLowerCase();
    if (FACTIONS_META[foundKey]) sel.value = foundKey;
  }
  // No eager filterCreatures() here: the ~1300-card grid (16k+ <img>) renders lazily on the
  // tab's first activation (navigation.ts TAB_RENDERERS), not at startup on every route.
}

function tryOpenCreature(name: string): boolean {
  if (name && isCreatureSysName(name)) {
    openCreatureModal(name);
    return true;
  }
  return false;
}

var _creatureListCache: string[] | null = null;

function getCreatureList(): string[] {
  if (!_creatureListCache && allData.units) _creatureListCache = Object.keys(allData.units).sort();
  return _creatureListCache || [];
}

function navigateCreature(dir: number): void {
  var inp = document.getElementById('creature-nav-input') as HTMLInputElement | null;
  if (!inp) return;
  var current = inp.value;
  var list = getCreatureList();
  var idx = list.indexOf(current);
  if (idx === -1) idx = list.indexOf(appPath().split('/units/')[1]);
  if (idx === -1) return;
  var next = (idx + dir + list.length) % list.length;
  var sysName = list[next];
  if (sysName) navigateTo('/units/' + sysName);
}

function openCreatureModal(sysName: string): void {
  var u = allData.units && allData.units[sysName];
  if (!u) return;
  nanoState = { atk: 0, def: 0, ini: 0 };
  setNanoLevel('naa', 0);
  setNanoLevel('nad', 0);
  setNanoLevel('nai', 0);
  loadNanoState(sysName, function(saved) {
    if (saved) {
      nanoState = saved;
      setNanoLevel('naa', nanoState.atk);
      setNanoLevel('nad', nanoState.def);
      setNanoLevel('nai', nanoState.ini);
      reloadAnimWithNano();
    }
  });
  var nanoPanel = document.getElementById('show_army_nano');
  if (nanoPanel) {
    nanoPanel.style.display = 'block';
    nanoPanel.querySelectorAll('.nano-row').forEach(function(r) { (r as HTMLElement).style.display = ''; });
  }
  var modal = document.getElementById('creature-modal');
  if (!modal) return;
  modal.style.display = 'flex';
  updateAnimSoundButton();
  const nameEl = document.getElementById('creature-modal-name');
  if (nameEl) nameEl.textContent = u.nameRu || u.sysName || sysName;
  var subHtml = (u.fraction ? factionName(u.fraction) : '');
  if (u.fraction && FACTIONS_META[u.fraction]) subHtml = '<span class="faction-link" onclick="event.stopPropagation();navigateTo(\'/factions/'+FACTIONS_META[u.fraction].nameEn+'\')">'+subHtml+'</span>';
  const subEl = document.getElementById('creature-modal-sub');
  if (subEl) subEl.innerHTML = subHtml + (u.lvl ? ' • Уровень ' + u.lvl : '');
  var statsHtml = [
    {icon:'attack', label:'Нападение', val: u.attack||0},
    {icon:'defense', label:'Защита', val: u.defense||0},
    {icon:'damage', label:'Урон', val: (u.minDmg||0) + '-' + (u.maxDmg||0)},
    {icon:'hit_points', label:'Ед. жизни', val: u.hp||0},
    {icon:'initiative', label:'Инициатива', val: u.ini||0},
    {icon:'speed', label:'Скорость', val: u.speed||0},
    {icon:'leadership', label:'Лидерство', val: u.leadership||0},
    {icon:'exp', label:'Опыт', val: u.exp||0},
    // Мана — только у колдующих существ: у остальных она ноль, и строка «Мана 0»
    // в карточке крестьянина ничего не значит. У колдуна это его запас на
    // заклинания, и считается он за каждого в отряде.
  // Выстрелы и дальность — только стрелкам: у рукопашника это нули, которые
  // читаются как характеристика, хотя означают «не применимо».
  ].concat(isShooterUnit(u) ? [
    {icon:'shoots', label:'Выстрелы', val: u.shoots||0},
    {icon:'distance', label:'Дальность', val: unitDistance(u as any) as any},
  ] : []
  ).concat(u.mana ? [{icon:'mana', label:'Мана', val: u.mana as any}] : []
  ).map(function(s) { return '<div class="modal-stat"><img src="'+statIcon(s.icon)+'" class="stat-icon"><span class="label">'+s.label+'</span><span class="value">'+s.val+'</span></div>'; }).join('');
  const statsEl = document.getElementById('creature-modal-stats');
  if (statsEl) statsEl.innerHTML = statsHtml;
  var skillsHtml = '';
  if (Array.isArray(u.skills) && u.skills.length) {
    skillsHtml = u.skills.map(function(s) { var n=abilityName(s),d=abilityDesc(s); return '<span class="tag" onclick="event.stopPropagation();navigateTo(\'/abilities/'+s+'\')"'+(d?' data-label="'+d.replace(/"/g,'&quot;')+'"':'')+'>'+n+'</span>'; }).join('');
  }
  const skillsEl = document.getElementById('creature-modal-skills');
  if (skillsEl) skillsEl.innerHTML = skillsHtml;
  // Заклинания колдуна (как в справочнике daily-help): иконка, название и цена
  // в мане из записи существа (`magic[].mana`), клик ведёт на страницу заклинания.
  var spells = Array.isArray((u as any).magic) ? (u as any).magic : [];
  var spellsEl = document.getElementById('creature-modal-spells');
  var spellsWrap = document.getElementById('creature-modal-spells-wrap');
  if (spellsEl && spellsWrap) {
    if (spells.length) {
      var levelNames = ['', '1-й уровень', '2-й уровень', '3-й уровень', '4-й уровень', '5-й уровень'];
      spellsEl.innerHTML = spells.map(function(sp: any) {
        var meta = (allData.magics || {})[sp.sysName] as any;
        var name = (meta && (meta.nameRu || meta.name)) || sp.sysName;
        var icon = meta ? magicIconUrl(meta) : '';
        var lvl = sp.lvl ? (levelNames[sp.lvl] || (sp.lvl + '-й уровень')) : '';
        return '<span class="spell-tag" data-sys="' + sp.sysName + '" onclick="navigateTo(\'/magics/' + sp.sysName + '\')">' +
          (icon ? '<img class="spell-tag-icon" src="' + icon + '" loading="lazy" onerror="this.style.display=\'none\'">' : '') +
          '<span class="spell-tag-name">' + name + '</span>' +
          (lvl ? '<span class="spell-tag-lvl">' + lvl + '</span>' : '') +
          (sp.mana ? '<span class="spell-tag-mana"><img src="' + cdnImg('https://dcdn.heroeswm.ru/i/magic/mana.gif') + '" alt="" onerror="this.style.display=\'none\'">' + sp.mana + '</span>' : '') +
          '</span>';
      }).join('');
      spellsEl.style.display = 'block';
      spellsWrap.style.display = 'block';
    } else {
      spellsEl.innerHTML = '';
      spellsEl.style.display = 'none';
      spellsWrap.style.display = 'none';
    }
  }
  var dl = document.getElementById('creature-nav-datalist') as HTMLDataListElement | null;
  if (dl && !dl.options.length && allData.units) {
    dl.innerHTML = Object.keys(allData.units).sort().map(function(k) {
      var nu = allData.units![k];
      return '<option value="' + k + '">' + (nu.nameRu || k) + '</option>';
    }).join('');
  }
  const navInput = document.getElementById('creature-nav-input') as HTMLInputElement | null;
  if (navInput) navInput.value = sysName;
  document.querySelectorAll('#anim-controls button').forEach(function(b) {
    (b as HTMLElement).style.display = '';
  });
  var shootBtn = document.querySelector('#anim-controls button[onclick*="shoot"]') as HTMLElement | null;
  if (shootBtn) shootBtn.style.display = (!u.shoots || u.shoots <= 0) ? 'none' : '';
  var castBtn = document.querySelector('#anim-controls button[onclick*="cast"]') as HTMLElement | null;
  if (castBtn) castBtn.style.display = (!Array.isArray(u.magic) || u.magic.length === 0) ? 'none' : '';
  var animUnit = (u as any).animUnit || (u as any).anim_unit || '';
  if (animUnit && !/^https?:\/\//i.test(animUnit) && !/\.(png|jpe?g|gif|webp)(\?.*)?$/i.test(animUnit)) {
    var sa = document.getElementById('show_army');
    if (sa) {
      sa.innerHTML = '';
      sa.classList.remove('loaded'); // Reset loading spinner
    }
    var controls = document.getElementById('anim-controls');
    if (controls) controls.style.display = 'none';
    var localFallback = staticsIconUrl(animUnit) || '/images/portraits/' + animUnit + 'p60.png';
    waitForShowArmyApis(function() {
      if (typeof init_army_info !== 'function' || typeof Konva === 'undefined') {
        var sa2 = document.getElementById('show_army');
        if (sa2) {
          sa2.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;background:rgba(0,0,0,0.15);border-radius:8px"><img src="' + localFallback + '" style="max-width:100%;max-height:100%;object-fit:contain;image-rendering:pixelated"></div>';
          sa2.classList.add('loaded');
        }
        return;
      }
      try {
        configureCardEffects();
        init_army_info("show_army", animUnit, CARD_ANIM_OBJ_VER, "0", CARD_ANIM_FON_VER, CARD_ANIM_SUBPATH, 300, 300, 2, {naa:{effect:0}, nad:{effect:0}, nai:{effect:0}});
        if (controls) controls.style.display = 'flex';
        // Звук кадров поднимаем вместе с анимацией: звук есть — только если
        // playsound/soundeff выставлены, а движок мог ещё не догрузиться раньше.
        applyAnimSoundState();
        startArmyUiWatcher();
      } catch(e) {
        console.error('Animation error:', e);
        var sa3 = document.getElementById('show_army');
        if (sa3) {
          sa3.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;background:rgba(0,0,0,0.15);border-radius:8px"><img src="' + localFallback + '" style="max-width:100%;max-height:100%;object-fit:contain;image-rendering:pixelated"></div>';
          sa3.classList.add('loaded');
        }
      }
    });
  } else if (animUnit) {
    var sa = document.getElementById('show_army');
    if (sa) {
      sa.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:var(--text-dim);font-size:14px"><img src="' + animUnit + '" style="max-width:100%;max-height:100%;object-fit:contain"></div>';
      sa.classList.add('loaded');
    }
  }
  setTimeout(startArmyUiWatcher, 100);
}

function closeCreatureModal(): void {
  const modal = document.getElementById('creature-modal');
  if (modal) modal.style.display = 'none';
  var sa = document.getElementById('show_army');
  if (sa) {
    destroyCardAnimation();
    sa.innerHTML = '';
    sa.classList.remove('loaded');
  }
  // Звук: стоп играющих кадров и возврат глобалок движка. Без этого
  // playsound/soundeff оставались поднятыми навсегда, и анимация доигрывала
  // со звуком после закрытия карточки.
  try { sndStopAllSfx(); } catch(e) {}
  restoreEngineSound();
  var path = appPath();
  var m = path.match(/^\/(creatures|units)\/(.+)/);
  if (m && isCreatureSysName(m[2])) {
    history.replaceState(null, '', siteUrl('/units'));
    const tabEl = document.getElementById('tab-creatures');
    if (tabEl && tabEl.classList.contains('active')) {
      filterCreatures();
    }
  }
}

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') { closeCreatureModal(); closeArtifactModal(); closeMagicModal(); closeReplayCard(); }
  if (e.key === 'ArrowLeft') navigateCreature(-1);
  if (e.key === 'ArrowRight') navigateCreature(1);
});

document.getElementById('creature-modal')?.addEventListener('click', function(e) {
  if (e.target === this) closeCreatureModal();
});

(globalThis as any).setNanoLevel = setNanoLevel;

export {
  renderCreatureCard,
  renderUnitStats,
  renderCreatures,
  filterCreatures,
  initCreatures,
  tryOpenCreature,
  openCreatureModal,
  closeCreatureModal,
  navigateCreature,
  getCreatureList,
  doAnimAction,
  unitAnimAction,
  toggleAnimationSound,
  setNano,
  setNanoLevel,
  saveNanoState,
  loadNanoState,
  updateModalStats,
  nanoState,
  _creatureListCache,
};
