/**
 * Панель проверки способностей внутри вкладки «Бой».
 *
 * Отладочный инструмент, к самому бою отношения не имеющий: грузит список
 * существ, даёт отключать отдельные умения и расставляет пару отрядов для
 * проверки. Держать его в battle.ts не было причин, кроме истории.
 *
 * Связь с battle.ts обоюдная и намеренно узкая: отсюда нужны пять имён, обратно
 * — предзагрузка списка и таблица отключённых умений (`tacTestOverrides`),
 * которую bat­tle.ts подмешивает в запрос к серверу.
 */
import { allData, ALT_HEADER, FACTIONS_META, PIC_TO_SYSNAME, PLAYABLE } from './data.js';
import { stripHtmlSimple } from './utils.js';
import { TACTIC_UNITS, tacCfg, tacClearAll, tacPutUnit, tacToggleSettings } from './battle.js';

// ===== ABILITY TEST PANEL (inside Battle tab) =====

let _tacTestCreatures: any[] = [];
let _tacTestAllCreatures: any[] = [];
let _tacTestSelectedSysName: any = null;
let _tacTestData: Record<string, any> = {};
let _tacTestFilterTimer: any = null;
let _tacTestLoadPromise: any = null;

/** Существа, которые проверять нечего: `statix` — неподвижная обстановка поля
 * (камни, ёлки, башни). Умений у них нет в том смысле, в каком они есть у
 * отрядов, а список они забивали сотней записей. */
function tacTestTestable(u: any): boolean {
  const skills = u?.skills || [];
  return skills.length > 0 && skills.indexOf('statix') === -1;
}

async function tacTestLoadData() {
  try {
    const resp = await fetch('/api/abilitytest/load');
    if (!resp.ok) return {};
    return await resp.json();
  } catch(e) {
    return {};
  }
}

async function tacTestSaveData() {
  try {
    const resp = await fetch('/api/abilitytest/save', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(_tacTestData),
    });
    return resp.ok;
  } catch(e) {
    return false;
  }
}

export function tacTestPreload() {
  // Загружаем список существ заранее — без ожидания
  if (!_tacTestLoadPromise) {
    const listPromise = Promise.resolve().then(() => {
      // Первичная фильтрация без рендера (просто кешируем)
      const all = Object.values(allData.units!).filter(tacTestTestable);
      all.sort((a, b) => (a.nameRu || '').localeCompare(b.nameRu || ''));
      return all;
    });
    _tacTestLoadPromise = Promise.all([
      listPromise,
      tacTestLoadData(),
    ]).then(([list, data]) => {
      _tacTestAllCreatures = list;
      _tacTestData = data;
      // Панель РАСКРЫТА с самого начала, а наполняли её только в
      // `tacToggleTestPanel` — то есть на смену состояния. На свежей загрузке
      // панель выглядела открытой и пустой: ни списка существ, ни выбора армий,
      // пока не свернёшь и не развернёшь её обратно.
      const body = document.getElementById('tac-test-body');
      if (body && body.style.display !== 'none') {
        tacTestFillFactions();
        tacTestFilterNow();
      }
    });
  }
}

export async function tacToggleTestPanel() {
  const body = document.getElementById('tac-test-body');
  const toggle = document.getElementById('tac-test-toggle');
  if (!body) return;
  const hidden = body.style.display === 'none';
  body.style.display = hidden ? '' : 'none';
  if (toggle) toggle.textContent = hidden ? '▾' : '▸';
  if (hidden) {
    // Показываем "загрузку..." сразу
    const container = document.getElementById('tac-test-list');
    if (container && _tacTestAllCreatures.length === 0) {
      container.innerHTML = '<div style="color:var(--text-dim);padding:8px;text-align:center;font-size:11px">⏳ загрузка...</div>';
    }
    // Загружаем данные, если ещё не
    tacTestPreload();
    await _tacTestLoadPromise;
    tacTestFillFactions();
    tacTestFilterNow();
  }
}

export function tacTestFilter() {
  clearTimeout(_tacTestFilterTimer);
  _tacTestFilterTimer = setTimeout(tacTestFilterNow, 100);
}

function tacTestFilterNow() {
  // Списки армий наполняются здесь же: панель открыта с самого начала, а
  // `tacToggleTestPanel` срабатывает только на СМЕНУ состояния — до первого
  // сворачивания-разворачивания выбор фракции стоял пустым.
  tacTestFillFactions();
  const q = ((document.getElementById('tac-test-search') as HTMLInputElement | null)?.value || '').toLowerCase();
  let list = _tacTestAllCreatures;

  if (list.length === 0) {
    // Если ещё не загрузились — фильтруем на лету из всех юнитов
    list = Object.values(allData.units!).filter(tacTestTestable);
    list.sort((a, b) => (a.nameRu || '').localeCompare(b.nameRu || ''));
    _tacTestAllCreatures = list;
  }

  // Поиск ищет и по СПОСОБНОСТЯМ: «Стрелок» находит всех стрелков, а не одно
  // существо с таким именем. Без этого проверять умение приходилось, вспоминая
  // его носителей по памяти.
  if (q) {
    const abilityHit = (u: any) => (u.skills || []).some((sk: string) => {
      if (sk.toLowerCase().indexOf(q) !== -1) return true;
      const a = allData.abilities && allData.abilities[sk];
      return !!a && (a.name || '').toLowerCase().indexOf(q) !== -1;
    });
    list = list.filter(u =>
      (u.nameRu || '').toLowerCase().indexOf(q) !== -1 ||
      (u.sysName || '').toLowerCase().indexOf(q) !== -1 ||
      abilityHit(u)
    );
  }

  // Limit results for performance
  const limit = 60;
  if (list.length > limit) list = list.slice(0, limit);

  _tacTestCreatures = list;

  const container = document.getElementById('tac-test-list');
  if (!container) return;

  if (list.length === 0) {
    container.innerHTML = '<div style="color:var(--text-dim);padding:8px;text-align:center;font-size:11px">Ничего не найдено</div>';
    return;
  }

  // Use DocumentFragment for faster rendering
  const frag = document.createDocumentFragment();
  list.forEach(u => {
    const sysName = u.sysName || u.sys_name || '';
    const div = document.createElement('div');
    div.className = 'tac-test-creature';
    if (_tacTestSelectedSysName === sysName) {
      div.style.background = 'var(--card-hover)';
      div.style.borderColor = 'var(--gold)';
    }
    div.dataset.sysname = sysName;
    div.onclick = function() { tacTestSelect(sysName); };

    const nameSpan = document.createElement('span');
    nameSpan.style.fontSize = '13px';
    nameSpan.textContent = u.nameRu || sysName;
    div.appendChild(nameSpan);

    const countSpan = document.createElement('span');
    countSpan.style.fontSize = '10px';
    countSpan.style.color = 'var(--text-dim)';
    countSpan.textContent = (u.skills ? u.skills.length + ' способ.' : '');
    div.appendChild(countSpan);

    frag.appendChild(div);
  });
  container.innerHTML = '';
  container.appendChild(frag);
}

export function tacTestSelect(sysName: any) {
  _tacTestSelectedSysName = sysName;

  document.querySelectorAll<HTMLElement>('.tac-test-creature').forEach(el => {
    el.style.background = '';
    el.style.borderColor = '';
    if (el.dataset.sysname === sysName) {
      el.style.background = 'var(--card-hover)';
      el.style.borderColor = 'var(--gold)';
    }
  });

  const u = allData.units![sysName];
  if (!u || !u.skills) return;

  // Показать способности с индивидуальными переключателями
  const abilsContainer = document.getElementById('tac-test-abilities');
  const actionsContainer = document.getElementById('tac-test-actions');
  if (abilsContainer) {
    abilsContainer.style.display = 'block';
    const status = _tacTestData[sysName] || {};
    var html = '<div style="font-size:11px;color:var(--gold);margin-bottom:6px">Способности:</div>';
    u.skills.forEach(function(sk: any) {
      const aData = allData.abilities && allData.abilities[sk];
      const name = aData ? (aData.name || sk) : sk;
      const desc = aData ? stripHtmlSimple(aData.desc || '') : '';
      const s = status[sk];
      const checked = s === true ? 'checked' : '';
      const label = s === true ? '🟢 работает' : (s === false ? '🔴 не работает' : '⚪ не тест.');
      html += '<div class="tac-test-ability-item">' +
        '<div class="tac-test-ability-header">' +
          '<div class="tac-test-ability-name">' + name + '</div>' +
          '<label class="tac-toggle">' +
            '<input type="checkbox" ' + checked + ' onchange="tacTestToggleAbility(\'' + sysName + '\', \'' + sk + '\', this.checked)">' +
            '<span class="tac-toggle-slider"></span>' +
            '<span class="tac-toggle-label">' + label + '</span>' +
          '</label>' +
        '</div>' +
        (desc ? '<div class="tac-test-ability-desc">' + desc + '</div>' : '') +
      '</div>';
    });
    abilsContainer.innerHTML = html;
  }
  if (actionsContainer) actionsContainer.style.display = 'flex';
  document.getElementById('tac-test-save-status')!.textContent = '';

  // Автоматически выставить на поле
  tacTestPlace();
}

function tacTestGetOrCreateTacticIdx(sysName: any) {
  // Пробуем найти существующий индекс в TACTIC_UNITS
  for (let i = 0; i < TACTIC_UNITS.length; i++) {
    const tu = TACTIC_UNITS[i];
    const mapped = PIC_TO_SYSNAME[tu.pic];
    if (mapped === sysName || tu.pic === sysName) {
      return i;
    }
  }

  // Не нашли — добавляем временную запись в TACTIC_UNITS
  const u = allData.units![sysName];
  if (!u) return -1;

  // Извлекаем pic из портрета
  const portrait = u.portrait || '';
  const m = portrait.match(/\/portraits\/(.+?)anip/);
  const pic = m ? m[1] : sysName;

  // Убеждаемся что PIC_TO_SYSNAME знает про этот pic
  if (!PIC_TO_SYSNAME[pic]) {
    PIC_TO_SYSNAME[pic] = sysName;
  }

  // Создаём запись в TACTIC_UNITS
  const isBig = u.skills && u.skills.indexOf('big') !== -1;
  const entry = { name: u.nameRu || sysName, pic: pic, big: isBig ? 1 : 0, r: 0 };
  const idx = TACTIC_UNITS.length;
  TACTIC_UNITS.push(entry);
  return idx;
}

export function tacTestPlace() {
  const sysName = _tacTestSelectedSysName;
  if (!sysName) return;

  const idx = tacTestGetOrCreateTacticIdx(sysName);
  if (idx === -1) {
    document.getElementById('tac-test-save-status')!.textContent = '❌ нет на поле боя';
    return;
  }

  tacClearAll();

  const tu = TACTIC_UNITS[idx];
  const isBig = tu && tu.big;
  const midRow = Math.floor(tacCfg.row / 2);
  const p1Row = isBig ? Math.max(midRow - 1, 1) : midRow;
  const p1Col = 1;
  const p2Row = p1Row;
  // Враг — в первую колонку своей зоны высадки
  // Для field_type=1 зона врага: колонки col-1 и col (11 и 12)
  const p2Col = isBig ? Math.max(tacCfg.col - 2, 1) : Math.max(tacCfg.col - 1, 1);

  tacPutUnit(p1Row, p1Col, idx, 100, 1);
  tacPutUnit(p2Row, p2Col, idx, 100, 2);

  const statusEl = document.getElementById('tac-test-save-status');
  if (statusEl) statusEl.textContent = '🎯 команды 1 и 2';
}

/** Все существа, у которых есть это умение. */
function tacTestCarriers(abilityKey: string): string[] {
  return Object.values(allData.units || {})
    .filter((u: any) => tacTestTestable(u) && (u.skills || []).indexOf(abilityKey) !== -1)
    .map((u: any) => u.sysName || '')
    .filter(Boolean);
}

/** Ряд существ фракции по колонке справочника: 0 — базовые, 1 — улучшенные,
 *  2 и 3 — альтернативные классы (у варваров их два). По одному на тир. */
function tacTestFactionRow(faction: string, col: number): string[] {
  const tiers = (allData.unitsByFaction || {})[faction] || {};
  const out: string[] = [];
  for (const tier of Object.keys(tiers).sort((a, b) => Number(a) - Number(b))) {
    for (const sysName of (tiers[tier] || {})[String(col)] || []) {
      const u = allData.units && allData.units[sysName];
      if (u && tacTestTestable(u) && out.indexOf(sysName) === -1) out.push(sysName);
    }
  }
  return out;
}

/** Настоящее имя класса фракции по номеру колонки существ.
 *
 *  Колонки в справочнике: 0 — базовые, 1 — улучшенные, 2 и дальше —
 *  альтернативные классы (у варваров их два). Имя берётся из справочника
 *  (`classes`), а не из заголовка таблицы: у рыцарей это «Рыцарь света», у
 *  эльфов — «Эльф-заклинатель», и аббревиатура «Улучшения РС» из заголовка
 *  понятна не всякому. Заголовок остаётся запасным вариантом. */
function tacTestClassName(faction: string, col: number): string {
  if (col === 0) return 'базовые';
  if (col === 1) return 'улучшенные';
  const classes = (allData.factions || {})[faction]?.classes || [];
  const header = (ALT_HEADER[faction] || [])[col - 2];
  return classes[col - 1]?.nameRu || (header || '').replace(/^Улучшения\s*/i, '') || `класс ${col}`;
}

/** Сколько колонок существ есть у фракции: базовые, улучшенные и альт-классы. */
function tacTestFactionCols(faction: string): number[] {
  const cols = [0, 1];
  (ALT_HEADER[faction] || []).forEach((_h, i) => cols.push(2 + i));
  return cols.filter(c => tacTestFactionRow(faction, c).length > 0);
}

/** Наполнить выбор фракции. Что именно выставлять — во втором списке
 *  (`tacTestFillArmies`): вариантов на фракцию полдюжины, и одним плоским
 *  списком на все двенадцать фракций пользоваться было бы нечем. */
export function tacTestFillFactions() {
  const sel = document.getElementById('tac-test-faction') as HTMLSelectElement | null;
  if (!sel || sel.options.length) return;
  for (const faction of PLAYABLE) {
    const opt = document.createElement('option');
    opt.value = faction;
    opt.textContent = FACTIONS_META[faction]?.nameRu || faction;
    sel.appendChild(opt);
  }
  tacTestFillArmies();
}

/** Наполнить выбор армии для текущей фракции.
 *
 *  Два рода проверок, и оба нужны:
 *  — «базовые ↔ X» ставит РАЗНЫЕ армии друг против друга: у базового и
 *    улучшенного существа умения расходятся, и в одном бою видно, что даёт
 *    улучшение;
 *  — «зеркало» ставит ОДНУ И ТУ ЖЕ армию с обеих сторон: так проверяют умения
 *    самого класса, не путая их с чужими.
 *  Отдельным пунктом — вся фракция целиком (базовые + улучшенные + альт), когда
 *  надо прогнать все существа разом. */
export function tacTestFillArmies() {
  const fsel = document.getElementById('tac-test-faction') as HTMLSelectElement | null;
  const sel = document.getElementById('tac-test-army') as HTMLSelectElement | null;
  if (!fsel || !sel) return;
  const faction = fsel.value || PLAYABLE[0];
  const prev = sel.value;
  const cols = tacTestFactionCols(faction);
  sel.innerHTML = '';
  const add = (value: string, text: string) => {
    const o = document.createElement('option');
    o.value = value; o.textContent = text; sel.appendChild(o);
  };
  for (const col of cols) {
    if (col === 0) continue;
    add(`cmp:${col}`, `базовые ↔ ${tacTestClassName(faction, col)}`);
  }
  for (const col of cols) {
    add(`mirror:${col}`, `зеркало: ${tacTestClassName(faction, col)}`);
  }
  add('all', `все существа фракции (${cols.reduce((n, c) => n + tacTestFactionRow(faction, c).length, 0)})`);
  if (prev && [...sel.options].some(o => o.value === prev)) sel.value = prev;
}

/** Существа одной стороны для выбранного режима. */
function tacTestArmyFor(faction: string, mode: string, side: 1 | 2): string[] {
  const [kind, colRaw] = mode.split(':');
  const col = Number(colRaw || 0);
  if (kind === 'all') {
    const out: string[] = [];
    for (const c of tacTestFactionCols(faction)) {
      for (const name of tacTestFactionRow(faction, c)) {
        if (out.indexOf(name) === -1) out.push(name);
      }
    }
    return out;
  }
  if (kind === 'mirror') return tacTestFactionRow(faction, col);
  return tacTestFactionRow(faction, side === 1 ? 0 : col);
}

/**
 * Выставить армии фракции для проверки — по СОТНЕ каждого существа.
 *
 * Отряды встают в три крайних колонки своей половины: тридцать клеток на
 * сторону, туда влезает и вся фракция целиком (двадцать один отряд), не
 * наползая на середину поля. Большие существа занимают 2×2 и учитываются.
 */
export function tacTestPlaceArmy(): boolean {
  const fsel = document.getElementById('tac-test-faction') as HTMLSelectElement | null;
  const asel = document.getElementById('tac-test-army') as HTMLSelectElement | null;
  const statusEl = document.getElementById('tac-test-save-status');
  const faction = fsel?.value || '';
  const mode = asel?.value || 'cmp:1';
  const left = tacTestArmyFor(faction, mode, 1);
  const right = tacTestArmyFor(faction, mode, 2);
  if (!left.length || !right.length) {
    if (statusEl) statusEl.textContent = '❌ нет существ такого класса';
    return false;
  }
  tacClearAll();

  // Клетки берутся С ПОЛЯ, а не считаются колонками: зона расстановки — это
  // ровно те клетки, что размечены как `drop` (две от края, три при взятой
  // «Тактике», а у полей особой раскладки — своя геометрия). Считая колонки
  // руками, тест выставлял армию за пределами зоны, где её в бою быть не может.
  const zoneOf = (team: number): Array<[number, number]> => {
    const cells: Array<[number, number]> = [];
    document.querySelectorAll<HTMLElement>(`#tac-field td.drop[data-pl="${team}"]`)
      .forEach(td => cells.push([Number(td.dataset.row), Number(td.dataset.col)]));
    // Порядок обхода — по рядам сверху вниз, внутри ряда от края к центру: так
    // армия встаёт плотным строем у своей кромки, а не рассыпается.
    const edge = team % 2 === 1 ? (c: number) => c : (c: number) => -c;
    cells.sort((a, b) => a[0] - b[0] || edge(a[1]) - edge(b[1]));
    return cells;
  };

  const placeSide = (names: string[], team: number) => {
    const zone = zoneOf(team);
    const free = new Set(zone.map(([r, c]) => `${r}:${c}`));
    let placed = 0;
    for (const sysName of names) {
      const idx = tacTestGetOrCreateTacticIdx(sysName);
      if (idx === -1) continue;
      const big = !!TACTIC_UNITS[idx]?.big;
      for (const [r, c] of zone) {
        const cells = big ? [[r, c], [r + 1, c], [r, c + 1], [r + 1, c + 1]] : [[r, c]];
        if (!cells.every(([rr, cc]) => free.has(`${rr}:${cc}`))) continue;
        cells.forEach(([rr, cc]) => free.delete(`${rr}:${cc}`));
        tacPutUnit(r, c, idx, 100, team);
        placed++;
        break;
      }
    }
    return placed;
  };

  const put1 = placeSide(left, 1);
  const put2 = placeSide(right, 2);
  if (statusEl) {
    const short = (put1 < left.length || put2 < right.length) ? ' (часть не поместилась)' : '';
    statusEl.textContent = `🎯 слева ${put1}, справа ${put2} — по 100 каждого${short}`;
    statusEl.style.color = 'var(--text-dim)';
  }
  return true;
}

/** Галочка «Выставить»: армия стоит на поле, пока она включена.
 *
 * Кнопкой это был разовый жест — нажал и дальше гадай, та ли армия сейчас на
 * поле: сменил класс в списке, а на доске осталась прежняя. Галочка показывает
 * СОСТОЯНИЕ: пока стоит, поле идёт за списками (см. tacTestArmyChange), снятая —
 * очищает поле. Очистка не страшнее прежней кнопки: выставление и так стирало
 * расстановку целиком (tacClearAll внутри tacTestPlaceArmy).
 */
export function tacTestToggleArmy(on: boolean): void {
  const box = document.getElementById('tac-test-army-on') as HTMLInputElement | null;
  if (on) {
    // Класса без существ на поле не выставить — галочка не должна врать,
    // что армия стоит: снимаем её обратно, причина уже в строке состояния.
    if (!tacTestPlaceArmy() && box) box.checked = false;
    return;
  }
  tacClearAll();
  const statusEl = document.getElementById('tac-test-save-status');
  if (statusEl) {
    statusEl.textContent = 'поле очищено';
    statusEl.style.color = 'var(--text-dim)';
  }
}

/** Сменили фракцию или класс при включённой галочке — на поле встаёт новая
 *  армия. Без этого списки и доска расходились молча. */
export function tacTestArmyChange(): void {
  const box = document.getElementById('tac-test-army-on') as HTMLInputElement | null;
  if (box && box.checked) tacTestToggleArmy(true);
}

export async function tacTestToggleAbility(sysName: any, abilityKey: any, working: any) {
  if (!_tacTestData[sysName]) _tacTestData[sysName] = {};
  _tacTestData[sysName][abilityKey] = working;
  if (Object.keys(_tacTestData[sysName]).length === 0) delete _tacTestData[sysName];

  // Умение реализовано ОДНО на всех: проверив «Стрелка» у лучника, мы проверили
  // его и у арбалетчиков. Поэтому зелёная отметка расходится по всем носителям —
  // иначе один и тот же код пришлось бы отмечать сотню раз.
  //
  // Красная НЕ расходится: «не работает» часто про конкретное существо (не то
  // взаимодействие, не тот случай), и гасить чужие проверки по одной неудаче
  // значило бы терять уже сделанную работу.
  let spread = 0;
  if (working === true) {
    for (const other of tacTestCarriers(abilityKey)) {
      if (other === sysName) continue;
      if (!_tacTestData[other]) _tacTestData[other] = {};
      if (_tacTestData[other][abilityKey] !== true) {
        _tacTestData[other][abilityKey] = true;
        spread++;
      }
    }
  }

  const ok = await tacTestSaveData();
  const statusEl = document.getElementById('tac-test-save-status');
  if (statusEl) {
    statusEl.textContent = ok
      ? (spread ? `✔ сохранено, отмечено ещё у ${spread}` : '✔ сохранено')
      : '❌ ошибка';
    statusEl.style.color = ok ? '#4caf50' : '#f44336';
  }

  // Обновить отображение
  const abilsContainer = document.getElementById('tac-test-abilities');
  if (abilsContainer && abilsContainer.style.display !== 'none') {
    tacTestSelect(sysName);
  }
}

export async function tacTestAllWork(working: any) {
  const sysName = _tacTestSelectedSysName;
  if (!sysName) return;
  const u = allData.units![sysName];
  if (!u || !u.skills) return;

  if (!_tacTestData[sysName]) _tacTestData[sysName] = {};
  u.skills.forEach(sk => {
    _tacTestData[sysName][sk] = working;
  });

  const ok = await tacTestSaveData();
  const statusEl = document.getElementById('tac-test-save-status');
  if (statusEl) {
    statusEl.textContent = ok
      ? '✔ сохранено в tests/ability_tests.json'
      : '❌ ошибка сохранения';
    statusEl.style.color = ok ? '#4caf50' : '#f44336';
  }

  tacTestSelect(sysName);
}

