/**
 * Пошаговый бой: отдельный режим, где ход отправляется на сервер по кнопке, а
 * ответ проигрывается тем же кодом, что и обычный реплей. Сюда же автопрокрутка
 * и выбор заклинания героя на шаге.
 *
 * Всё состояние режима — сессия, активный отряд, флаг автопрокрутки, выбранное
 * заклинание — принадлежит только ему, поэтому переехало вместе с функциями.
 */
import { allData, PIC_TO_SYSNAME } from './data.js';
import { battleBoard } from './battleState.js';
import { TACTIC_UNITS, getCell, tacById } from './battle.js';
import { tacGetHeroData, tacGetEnemyHeroData } from './battleHero.js';
import { tacPlaybackRunning } from './battleState.js';

export let tacStepMode = false;
export let tacSessionId = null;
export let tacActiveUnit = null;
export let tacAutoPlaying = false;
export let tacSelectedSpellStep = null;

// ── Один бой, два режима управления ──
// Раньше это были две несводимые ветки: «в бой» уходила на /api/simulate и
// проигрывала бой целиком, а хотсит держал сессию на /api/battle/step. Переключить
// их посреди боя было нельзя — у /api/simulate нет состояния, с которого можно
// продолжить. Теперь бой ВСЕГДА идёт сессией /api/battle/step (hotseat: true), а
// «автобой» — это выбор клиента на каждом ходу: либо ждём клик человека, либо
// просим сервер отыграть ход штатным ИИ (действие {type:'auto'}). Отсюда и
// переключение в обе стороны на любом ходу.

export function tacToggleStepMode() {
  tacStepMode = !tacStepMode;
  const btn = tacById('tac-step-btn');
  const info = tacById('tac-turn-info');
  const bar = tacById('tac-model-bar');
  btn.style.borderColor = tacStepMode ? '#4fc3f7' : '';
  btn.style.background = tacStepMode ? 'rgba(79,195,247,0.2)' : '';
  info.style.display = tacStepMode ? 'inline' : 'none';
  bar.style.display = tacStepMode ? 'flex' : 'none';
  if (tacStepMode) {
    document.querySelectorAll<HTMLElement>('#tac-field td.drop').forEach(td => {
      td.style.cursor = td.classList.contains('pl1') || td.classList.contains('pl3') || td.classList.contains('pl5') ? 'pointer' : '';
    });
  } else {
    document.querySelectorAll<HTMLElement>('#tac-field td').forEach(td => { td.style.cursor = ''; });
  }
  tacSessionId = null;
  tacActiveUnit = null;
  tacAutoPlaying = false;
  info.textContent = '👣 Пошаговый режим';
}

export function tacModelChange(sel: HTMLSelectElement, which: string) {
  const customInput = tacById<HTMLInputElement>(`tac-model-${which}-custom`);
  if (!customInput) return;
  if (sel.value === '__custom__') {
    customInput.style.display = 'inline-block';
  } else {
    customInput.style.display = 'none';
  }
}

function tacGetModel(which: string) {
  const sel = tacById<HTMLSelectElement>(`tac-model-${which}`);
  const custom = tacById<HTMLInputElement>(`tac-model-${which}-custom`);
  if (sel?.value === '__custom__') {
    return custom?.value.trim() || null;
  }
  return sel?.value || null;
}

export async function tacStartStepBattle() {
  if (tacPlaybackRunning()) return;
  tacSessionId = null;
  tacActiveUnit = null;
  const stacks = [];
  for (let r = 0; r < battleBoard.data.length; r++) {
    if (!battleBoard.data[r]) continue;
    for (let c = 0; c < battleBoard.data[r].length; c++) {
      const cell = battleBoard.data[r][c];
      if (!cell || cell === true || cell === false || cell.id === undefined) continue;
      const u = TACTIC_UNITS[cell.id];
      const side = (cell.team === 1 || cell.team === 3 || cell.team === 5) ? 'player' : 'enemy';
      const sysName = PIC_TO_SYSNAME[u.pic] || u.pic;
      stacks.push({ side, sysName, count: cell.cnt, row: r, col: c, team: cell.team, pic: u.pic, name: u.name });
    }
  }
  if (!stacks.some(s => s.side === 'player') || !stacks.some(s => s.side === 'enemy')) {
    tacById('tac-status').textContent = '❌ Добавьте отряды с обеих сторон';
    return;
  }
  const playerStacks = stacks.filter(s => s.side === 'player').map(s => ({ sysName: s.sysName, count: s.count }));
  const enemyStacks = stacks.filter(s => s.side === 'enemy').map(s => ({ sysName: s.sysName, count: s.count }));
  const playerHero = tacGetHeroData();
  const enemyHero = tacGetEnemyHeroData();
  const payload: any = { player: playerHero ? { hero: playerHero, stacks: playerStacks } : playerStacks };
  payload.enemy = enemyHero ? { hero: enemyHero, stacks: enemyStacks } : { stacks: enemyStacks };
  const p1Model = tacGetModel('p1');
  const p2Model = tacGetModel('p2');
  if (p1Model) payload.player_model = p1Model;
  if (p2Model) payload.enemy_model = p2Model;
  const status = tacById('tac-status');
  status.textContent = '⏳ Создание сессии...';
  try {
    const res = await fetch('/api/battle/step', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (data.error) { status.textContent = `❌ ${data.error}`; return; }
    tacSessionId = data.session_id;
    tacRenderStepState(data);
  } catch (e) {
    status.textContent = `❌ ${(e as Error)?.message || e}`;
  }
}

export async function tacStepAction(action: any) {
  if (!tacSessionId || tacAutoPlaying) return;
  const status = tacById('tac-status');
  status.textContent = '⏳ Выполнение...';
  try {
    const res = await fetch('/api/battle/step', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ session_id: tacSessionId, action }),
    });
    const data = await res.json();
    if (data.error) { status.textContent = `❌ ${data.error}`; return; }
    tacRenderStepState(data);
    // If auto-playing, continue
    if (tacAutoPlaying && data.phase === 'player_turn') {
      await tacAutoPlayNext(data);
    }
  } catch (e) {
    status.textContent = `❌ ${(e as Error)?.message || e}`;
    tacAutoPlaying = false;
  }
}

async function tacAutoPlayNext(state: any) {
  const actions = state.available_actions || [];
  if (actions.length === 0) return;
  // Pick first attack action, or wait
  const attack = actions.find((a: any) => a.type === 'attack');
  if (attack) {
    await tacStepAction(attack);
  } else {
    await tacStepAction({ type: 'wait' });
  }
}

export function tacToggleAutoPlay() {
  tacAutoPlaying = !tacAutoPlaying;
  if (tacAutoPlaying && tacSessionId) {
    tacStepAction(null);
  }
}

export function tacSelectStepSpell(index: any) {
  tacSelectedSpellStep = tacSelectedSpellStep === index ? null : index;
  // Re-render highlights
  const status = tacById('tac-status');
  status.textContent = tacSelectedSpellStep !== null ? '🎯 Выберите цель для заклинания' : '🎯 Ваш ход';
}

function tacRenderStepState(data: any) {
  const status = tacById('tac-status');
  const info = tacById('tac-turn-info');
  if (data.winner !== null && data.winner !== undefined) {
    status.textContent = data.winner === 0 ? '✅ Победа игрока!' : data.winner === 1 ? '❌ Поражение' : '🤝 Ничья';
    info.textContent = '🏁 Бой окончен';
    tacSessionId = null;
    tacActiveUnit = null;
    tacAutoPlaying = false;
    return;
  }
  const round = data.round || 1;
  const turn = data.turn || 0;
  const isPlayer = data.phase === 'player_turn';
  const active = data.active_stack;
  tacActiveUnit = isPlayer ? active : null;
  // Update stacks on grid from positions
  const statusMsg = isPlayer ? `🎯 Ваш ход (R${round})` : `⏳ Ход противника...`;
  status.textContent = statusMsg;
  info.textContent = `👣 R${round} T${turn} ${isPlayer ? '🔵 Ваш ход' : '🔴 Противник'}`;
  // Clear cell highlights
  document.querySelectorAll<HTMLElement>('#tac-field td').forEach(td => td.classList.remove('tac-active', 'tac-targetable', 'tac-fp'));
  // Highlight active unit
  if (active !== null && data.stacks) {
    const activeStack = data.stacks.find((s: any) => s.idx === active);
    if (activeStack && activeStack.position) {
      const cell = getCell(activeStack.position[1], activeStack.position[0]);
      if (cell) cell.classList.add('tac-active');
    }
  }
  // Highlight targetable enemies
  if (isPlayer && data.available_actions) {
    // Build spell list
    const spells = data.available_actions.filter((a: any) => a.type === 'spell');
    const attacks = data.available_actions.filter((a: any) => a.type === 'attack');
    // Clear magic book and show available spells
    const spellsEl = tacById('tac-magic-spells');
    const magicBook = tacById('tac-magic-book');
    if (spells.length > 0) {
      magicBook.style.display = 'block';
      spellsEl.innerHTML = spells.map((a: any, i: any) => {
        const isActive = tacSelectedSpellStep === i;
        const sp = allData.magics!?.[a.spell_name];
        const manaCost = sp?.mana || '?';
        return `<button class="tac-btn" style="${isActive ? 'border-color:#ce93d8;background:rgba(206,147,216,0.2)' : ''}" onclick="tacSelectStepSpell(${i})">📜 ${a.spell_name} (${manaCost} маны)</button>`;
      }).join('');
      tacById('tac-magic-mana').textContent = `Мана: ?`;
      // Площадное заклинание наводится на клетку, а не на отряд: подсказка об
      // этом приходит вместе с самим предложением (`cell_aim`).
      const picked = tacSelectedSpellStep === null ? null : spells[tacSelectedSpellStep];
      tacById('tac-magic-status').textContent = picked?.cell_aim
        ? 'Выберите заклинание, затем клетку'
        : 'Выберите заклинание, затем цель';
    } else {
      magicBook.style.display = 'none';
      tacSelectedSpellStep = null;
    }
    // Highlight targets based on selected spell or attack
    for (const a of data.available_actions) {
      if (a.type === 'attack' && tacSelectedSpellStep === null) {
        // Show attack targets
        const targetStack = data.stacks.find((s: any) => s.idx === a.target_idx);
        if (targetStack && targetStack.position) {
          const cell = getCell(targetStack.position[1], targetStack.position[0]);
          if (cell) {
            cell.classList.add('tac-targetable');
            cell.style.cursor = 'pointer';
            cell.onclick = null;
            cell.addEventListener('click', async function handler(e: any) {
              e.stopPropagation();
              await tacStepAction({ type: 'attack', target_idx: a.target_idx });
            }, { once: true });
          }
        }
      } else if (a.type === 'spell' && tacSelectedSpellStep !== null && spells[tacSelectedSpellStep]?.spell_name === a.spell_name) {
        // Show spell targets for selected spell
        const targetStack = data.stacks.find((s: any) => s.idx === a.target_idx);
        if (targetStack && targetStack.position) {
          const cell = getCell(targetStack.position[1], targetStack.position[0]);
          if (cell) {
            cell.classList.add('tac-targetable');
            cell.style.cursor = 'pointer';
            cell.onclick = null;
            cell.addEventListener('click', async function handler(e: any) {
              e.stopPropagation();
              tacSelectedSpellStep = null;
              await tacStepAction({ type: 'spell', target_idx: a.target_idx, spell_name: a.spell_name });
            }, { once: true });
          }
        }
      }
    }
    // Площадное заклинание: цель не нужна вовсе — кликают по любой клетке, в том
    // числе пустой (шар между двумя стеками). Сервер клетку проверяет сам.
    if (tacSelectedSpellStep !== null) {
      const chosen = spells[tacSelectedSpellStep];
      if (chosen?.cell_aim) {
        for (let r = 0; r < battleBoard.data.length; r++) {
          const line = battleBoard.data[r];
          if (!line) continue;
          for (let c = 0; c < line.length; c++) {
            if (!line[c]) continue;
            const cell = getCell(r, c);
            if (!cell) continue;
            cell.classList.add('tac-targetable');
            cell.style.cursor = 'pointer';
            cell.onclick = null;
            cell.addEventListener('click', async function handler(e: any) {
              e.stopPropagation();
              tacSelectedSpellStep = null;
              await tacStepAction({ type: 'spell', spell_name: chosen.spell_name, cell: [c, r] });
            }, { once: true });
          }
        }
      }
    }
  }
  // Show log
  const logEl = tacById('tac-debug');
  const logContainer = logEl.parentElement;
  if (!logContainer) return;
  if (data.full_log && data.full_log.length > 0) {
    logEl.style.display = 'block';
    logEl.style.maxHeight = '400px';
    // Build name→color map from stack data
    const nameColors: Record<string, string> = {};
    for (const s of (data.stacks || [])) {
      if (s.name) nameColors[s.name] = s.side === 0 ? '#ff6b6b' : '#4fc3f7';
    }
    const colorize = (msg: any) => {
      let r = msg;
      for (const [name, color] of Object.entries(nameColors)) {
        const re = new RegExp(name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
        r = r.replace(re, `<span style="color:${color}">${name}</span>`);
      }
      return r;
    };
    const indent = (e: any) => e.type === 'detail' ? 'padding-left:16px' : '';
    logEl.innerHTML = data.full_log.map((e: any) =>
      `<div style="padding:1px 0;${indent(e)}">${colorize(e.message)}</div>`
    ).join('');
    logEl.scrollTop = logEl.scrollHeight;
    // Remove old copy button if any, then append
    const oldBtn = logContainer.querySelector('.tac-copy-step-log');
    if (oldBtn) oldBtn.remove();
    const btn = document.createElement('div');
    btn.className = 'tac-copy-step-log';
    btn.style.cssText = 'text-align:center;padding:4px 0 2px';
    btn.innerHTML = `<button onclick="tacCopyStepLog()" style="padding:4px 12px;background:rgba(201,168,76,0.15);border:1px solid var(--gold);border-radius:4px;color:var(--gold);font-size:12px;cursor:pointer;font-family:inherit">📋 Копировать лог</button>`;
    logContainer.appendChild(btn);
  }
}

export function tacCopyStepLog() {
  const logEl = tacById('tac-debug');
  if (!logEl) return;
  const text = Array.from(logEl.children)
    .map((el: any) => el.textContent)
    .join('\n');
  navigator.clipboard.writeText(text).then(() => {
    const btn = logEl.parentElement?.querySelector('.tac-copy-step-log button');
    if (btn) { const orig = btn.textContent; btn.textContent = '✅ Скопировано!'; setTimeout(() => { btn.textContent = orig; }, 2000); }
  }).catch(() => {
    const ta = document.createElement('textarea');
    ta.value = text; ta.style.position = 'fixed'; ta.style.left = '-9999px';
    document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta);
  });
}

// ── Unified battle log ──
// One log, built live during the replay from actions (the post-battle dump of the raw
// server log used to duplicate every event in a second format). Unit names are colored
// by TEAM, not by name — with identical creatures on both sides («Арбалетчики света»
// vs «Арбалетчики света») name-based coloring couldn't tell attacker from defender.
