/**
 * Поле расстановки: построение таблицы и подписка обработчиков на клетки.
 *
 * Раньше это была одна функция на 329 строк с тридцатью внешними связями — она
 * строила сетку и тут же вешала на клетки девять слушателей: клик, контекстное
 * меню, перетаскивание с доски и из палитры, наведение с предпросмотром следа
 * 2×2. Вынести её было нельзя, пока обработчики писали прямо в переменные
 * battle.ts; после переезда этого состояния в `battleEditorState` осталась
 * обычная зависимость по чтению.
 *
 * Здесь те же 329 строк, но двумя названными частями: `tacCreateGrid` собирает
 * разметку по типу поля, `bindDropCellHandlers` навешивает поведение.
 */
import { destroyAllStackAnims } from './creatureAnim.js';
import { battleBoard, tacAnchorAt, tacPlaybackRunning } from './battleState.js';
import { hs } from './battleHotseatState.js';
import { editor } from './battleEditorState.js';
import { tacDecode, tacSyncCode } from './battleCode.js';
import { resetFieldFitCache, tacDestroyHeroSprites, tacFitField, tacMountFieldSprite } from './battleFieldSprites.js';
import { sceneInvalidateAnchors } from './fieldScene.js';
import { tacUpdateHeroArtsCount, tacUpdateHeroPerksCount } from './battleHero.js';
import {
  tacClearOver, tacClearPaletteDrag, tacNumClass, tacPaletteDragIndex,
  tacPaletteSelected, tacPortraitUrl, tacSetDragImage, tacShowUnitPreview,
} from './battlePalette.js';
import {
  TACTIC_UNITS, tacById, tacCfg, tacCloseUnitInfo, tacFootprintFits,
  tacDropDepth, tacInitTerrainSelect, tacOpenUnitModal, tacPutUnit, tacQuery, tacRemoveUnit,
  tacRenderInitiative, tacSyncNumbers, tacUnitTooltip, tacUpdateMuteBtn, tacFieldSprites,
} from './battle.js';

/** «Свободная расстановка» (галочка в настройках): TRUE — отряды можно ставить
 * на любую клетку поля, а не только в штатные два ряда у краёв. Клетку читает
 * DOM, поэтому функцию нельзя заинлайнить в цикле — берём один раз на поле. */
export function tacFreePlacement(): boolean {
  const box = tacQuery<HTMLInputElement>('#tac-free-placement') as HTMLInputElement | null;
  return !!box && box.checked;
}

/** Команда клетки в свободной расстановке: левая половина поля — 1/3/5, правая —
 * 2/4/6; по вертикали — та же разбивка, что у штатной зоны (середина/трети).
 * Границу по центру решаем в пользу левой половины, как у штатных зон. */
export function tacFreePlaceRegion(row: number, col: number, colCount: number,
                                   rowCount: number, mode: 1 | 2 | 3): number {
  const left = col <= colCount / 2;
  if (mode === 1) return left ? 1 : 2;
  const mid = rowCount / 2;
  if (mode === 2) return left ? (row <= mid ? 1 : 3) : (row <= mid ? 2 : 4);
  const third = rowCount / 3;
  return left
    ? (row <= third ? 1 : row <= third * 2 ? 3 : 5)
    : (row <= third ? 2 : row <= third * 2 ? 4 : 6);
}

export function tacCreateGrid(code?: any, rollLand = true) {
  if (code) tacDecode(code);
  // The table below gets fully rebuilt (innerHTML replace) — any sprites mounted on the old
  // <td> elements are about to become orphaned, so tear them down first instead of leaking them.
  destroyAllStackAnims();
  tacFieldSprites.clear();
  // Спрайты героев живут на той же сцене и тем же пересозданием уносятся —
  // держать на них ссылку после этого нельзя (tacRenderHeroFigures смонтирует
  // их заново, когда сетка будет готова).
  tacDestroyHeroSprites();
  const isSmall = tacCfg.row >= 18;
  // Широкие поля оригинала (13×10 / 14×10 — как в реальных боях HWM): та же
  // расстановка «1x1», что у типа 1, и «2x2», как у типов 10..19.
  const isWide1pl = tacCfg.field_type >= 40 && tacCfg.field_type < 50;
  const isWide2pl = tacCfg.field_type >= 50 && tacCfg.field_type < 60;
  const is1pl = tacCfg.field_type === 1 || isWide1pl;
  const is2pl = (tacCfg.field_type >= 10 && tacCfg.field_type < 20) || isWide2pl;
  const is3pl = tacCfg.field_type >= 20 && tacCfg.field_type < 30;
  const isGv = tacCfg.field_type === 8 || tacCfg.field_type === 9;
  const isKszs = tacCfg.field_type === 30 || tacCfg.field_type === 31;

  let html = `<table id="tac-field" class="${isSmall ? 'tac-small' : ''}">`;
  // «Свободная расстановка»: обычные поля линии (1×1, 2×2 и 6-командное)
  // принимают армию НА ЛЮБОЙ клетке — не только в двух рядах у краёв. Особым
  // полям (ГВ, КШ/ЗС, круговое) своя раскладка, и галочка их не трогает.
  const freePlacement = tacFreePlacement() && (is1pl || is2pl || is3pl);
  const freePlMode = is1pl ? 1 : is2pl ? 2 : 3;
  // Column header row
  html += '<tr><td class="tac-cr"></td>';
  for (let c = 1; c <= tacCfg.col; c++) html += `<td class="tac-cr">${c}</td>`;
  html += '</tr>';
  for (let r = 1; r <= tacCfg.row; r++) {
    // Row header
    html += `<tr><td class="tac-cr">${r}</td>`;
    for (let c = 1; c <= tacCfg.col; c++) {
      let pl = 0, cls = 'stone';
      // Глубина зоны расстановки в обычном бою: две клетки от края, три — если
      // взята «Тактика» (см. tacDropDepth). Полей особой раскладки ниже это не
      // касается: у ГВ, КШ/ЗС и кругового поля зоны свои.
      const depth = tacDropDepth();
      if (freePlacement) {
        // «Свободная расстановка» — отряды встают НА ЛЮБОЙ клетке поля, команда
        // берётся по половинам/третям (см. tacFreePlaceRegion).
        pl = tacFreePlaceRegion(r, c, tacCfg.col, tacCfg.row, freePlMode);
        cls = `pl${pl} drop`;
      } else if (is1pl && c <= depth) { pl = 1; cls = 'pl1 drop'; }
      else if (is1pl && c > tacCfg.col - depth) { pl = 2; cls = 'pl2 drop'; }
      else if (is2pl) { const mid = tacCfg.row / 2;
        if (c <= depth) { pl = r <= mid ? 1 : 3; cls = (r <= mid ? 'pl1' : 'pl3') + ' drop'; }
        else if (c > tacCfg.col - depth) { pl = r <= mid ? 2 : 4; cls = (r <= mid ? 'pl2' : 'pl4') + ' drop'; }
      } else if (is3pl) { const third = tacCfg.row / 3;
        if (c <= depth) { pl = r <= third ? 1 : r <= third*2 ? 3 : 5; cls = (r <= third ? 'pl1' : r <= third*2 ? 'pl3' : 'pl5') + ' drop'; }
        else if (c > tacCfg.col - depth) { pl = r <= third ? 2 : r <= third*2 ? 4 : 6; cls = (r <= third ? 'pl2' : r <= third*2 ? 'pl4' : 'pl6') + ' drop'; }
      } else if (isGv) {
        if ((c >= 8 && c <= 11 && r >= 8 && r <= 11) || (c >= 5 && c <= 8 && r >= 6 && r <= 9)) { pl = 2; cls = 'pl2 drop'; }
        else if (c === 1 || c === tacCfg.col || r === 1 || r === tacCfg.row) { pl = 1; cls = 'pl1 drop'; }
      } else if (isKszs) {
        if (c <= 4 && r <= 4) { pl = 1; cls = 'pl1 drop ks'; }
        else if (c > tacCfg.col - 4 && r <= 4) { pl = 4; cls = 'pl4 drop ks'; }
        else if (c <= 4 && r > tacCfg.row - 4) { pl = 3; cls = 'pl3 drop ks'; }
        else if (c > tacCfg.col - 4 && r > tacCfg.row - 4) { pl = 2; cls = 'pl2 drop ks'; }
      } else if (tacCfg.field_type === 7) {
        if (c >= 5 && c <= 8 && r >= 5 && r <= 8) { pl = 1; cls = 'pl1 drop'; }
        else if ((c === 1 || c === tacCfg.col) && r === 6 || (r === 1 || r === tacCfg.row) && c === 6) { pl = 2; cls = 'pl2 drop'; }
      }

      if (cls === 'stone') html += `<td class="stone" data-row="${r}" data-col="${c}"><div></div></td>`;
      else html += `<td class="${cls}" data-row="${r}" data-col="${c}" data-pl="${pl}"><div></div></td>`;
    }
    html += '</tr>';
  }
  html += '</table>';
  tacById('tac-field-wrap').innerHTML = html;
  // Таблица пересоздана — inline --cellw/--cellh потеряны; сброс ключа и масштаба
  // раскладки, иначе гвард в tacFitField пропустит пересчёт и поле откатится к
  // дефолту из CSS.
  resetFieldFitCache();
  tacFitField();
  // Кэш якорей чистим ТОЛЬКО после фита; сразу после innerHTML это ломает 2×2:
  // tacFitField (через tacSyncNumbers) успевает измерить клетку большого существа,
  // когда класс `tac-big-anchor` ещё не выставлен (его ставит цикл расстановки
  // НИЖЕ) — и кэш запоминал якорь 6_4 как одной клетки (628.6), а монтаж большого
  // спрайта получал этот отравленный кэш-хит вместо центра квадрата ~685 и стоял
  // на полклетки левее. После фита измерения остаются только от настоящего
  // монтажа расстановки — им и надо попасть в кэш.
  sceneInvalidateAnchors();
  tacUpdateMuteBtn();
  // Грунт перекатывается только для НОВОЙ доски (вход в редактор, смена поля,
  // загрузка кода из URL). Переключение галочек palетры/свободной расстановки
  // лишь перестраивает ту же доску — фон остаётся тем, что игрок уже видит.
  tacInitTerrainSelect(rollLand);
  tacUpdateHeroArtsCount();
  tacUpdateHeroPerksCount();
  bindDropCellHandlers();
}

/** Слить два отряда, если это одно и то же существо одной команды.
 *
 * Оригинал (`exchangestek`, show_polep.js :17948) на одинаковых `stekid`
 * складывает численность во ВТОРОЙ слот и опустошает первый, а на разных —
 * меняет отряды местами. Здесь та же развилка: слияние — при совпадении
 * существа и команды, иначе вызывающий делает обычный обмен.
 *
 * `shift` повторяет гейт оригинала (`KeyisDown(16)` гасит ветку слияния): с
 * зажатым Shift одинаковые отряды не сливаются. Оригинал в этом случае не делает
 * ничего, у нас — обычный обмен: поменять местами 20 и 5 одинаковых существ
 * осмысленно, а «молча ничего» игрок читает как поломку.
 *
 * Возвращает `true`, если слияние произошло.
 */
export function tacMergeStacks(src: { row: number; col: number },
                               dst: { row: number; col: number },
                               shift: boolean): boolean {
  if (shift) return false;
  if (src.row === dst.row && src.col === dst.col) return false;
  const a = battleBoard.data[src.row]?.[src.col];
  const b = battleBoard.data[dst.row]?.[dst.col];
  if (!a || a.id === undefined || !b || b.id === undefined) return false;
  if (a.id !== b.id || (a.team || 1) !== (b.team || 1)) return false;
  const total = (a.cnt || 0) + (b.cnt || 0);
  tacRemoveUnit(src.row, src.col, true);
  tacRemoveUnit(dst.row, dst.col, true);
  tacPutUnit(dst.row, dst.col, b.id, total, b.team);
  return true;
}

/** Поведение клеток зоны высадки: клик, правка, перетаскивание, наведение. */
function bindDropCellHandlers() {
    document.querySelectorAll<HTMLElement>('#tac-field .drop').forEach(td => {
    td.addEventListener('dragover', e => e.preventDefault());
    td.addEventListener('drop', e => {
      e.preventDefault();
      const row = parseInt(td.dataset.row || '');
      const col = parseInt(td.dataset.col || '');
      const idx = parseInt(e.dataTransfer!.getData('text/plain'));
      if (editor.dragSrc) {
        const src = editor.dragSrc;
        editor.dragSrc = null;
        if (src.row === row && src.col === col) return;
        const srcCell = battleBoard.data[src.row]?.[src.col];
        if (!srcCell || srcCell.id === undefined) return;
        // Одинаковые отряды одной команды складываются в один (Shift — обмен).
        if (tacMergeStacks(src, { row, col }, e.shiftKey)) { tacClearPaletteDrag(); return; }
        const srcId = srcCell.id, srcCnt = srcCell.cnt, srcTeam = srcCell.team;
        const srcU = TACTIC_UNITS[srcId];
        // Validate target placement for source unit
        if (srcU.big && (row + 1 > tacCfg.row || col + 1 > tacCfg.col)) return;
        // Save target data
        let tgtId = null, tgtData = null;
        const tgtCell = battleBoard.data[row]?.[col];
        if (tgtCell && tgtCell.id !== undefined) {
          tgtId = tgtCell.id;
          const tgtU = TACTIC_UNITS[tgtId];
          tgtData = { id: tgtId, cnt: tgtCell.cnt, team: tgtCell.team, big: tgtU.big };
        }
        // Remove source (frees all source cells including big ones)
        tacRemoveUnit(src.row, src.col, true);
        // Remove target if any (frees target cells)
        if (tgtId) {
          tacRemoveUnit(row, col, true);
        }
        // Place source at target
        tacPutUnit(row, col, srcId, srcCnt, srcTeam);
        // Place swapped unit at source if any
        if (tgtData) {
          tacPutUnit(src.row, src.col, tgtData.id, tgtData.cnt, tgtData.team);
        }
      } else if (!isNaN(idx)) {
        const u = TACTIC_UNITS[idx];
        // Та же проверка, что рисует предпросмотр — иначе подсветка обещала бы посадку,
        // которой не будет. Прежняя пропускала маркеры хвостов 2x2 (`cell.id !== undefined`),
        // то есть большое существо могло встать поверх чужого хвоста.
        if (u && !tacFootprintFits(row, col, !!u.big)) return;
        tacPutUnit(row, col, idx, 1, parseInt(td.dataset.pl || ''));
      }
      tacClearPaletteDrag();
    });
    td.addEventListener('dragenter', e => {
      e.preventDefault();
      // Тащить можно двумя способами: отряд с доски (editor.dragSrc) и новое существо из
      // палитры (tacPaletteDragIdx). Предпросмотр следа 2x2 раньше работал только для
      // первого — из палитры большое существо вставало «по одной клетке», как маленькое.
      let u = null;
      if (editor.dragSrc) {
        const srcCell = battleBoard.data[editor.dragSrc.row]?.[editor.dragSrc.col];
        u = srcCell && srcCell.id !== undefined ? TACTIC_UNITS[srcCell.id] : null;
      } else if (tacPaletteDragIndex() !== null) {
        u = TACTIC_UNITS[tacPaletteDragIndex()!];
      }
      if (!u) return;
      const row = parseInt(td.dataset.row || '');
      const col = parseInt(td.dataset.col || '');
      tacClearOver();
      if (u.big) {
        const fits = tacFootprintFits(row, col, true, editor.dragSrc || undefined);
        for (let dr = 0; dr <= 1; dr++) {
          for (let dc = 0; dc <= 1; dc++) {
            const t = tacQuery(`#tac-field td[data-row="${row + dr}"][data-col="${col + dc}"]`);
            if (t) {
              t.classList.add('tac-over', 'tac-big-hover');
              if (fits) {
                t.style.backgroundImage = `url(${tacPortraitUrl(u.pic)})`;
                t.style.backgroundSize = '200% 200%';
                t.style.backgroundPosition = `${dc ? 'right' : 'left'} ${dr ? 'bottom' : 'top'}`;
                t.style.opacity = '0.6';
              } else {
                t.classList.add('tac-over-bad'); // след не помещается — видно до отпускания
              }
            }
          }
        }
      } else {
        td.classList.add('tac-over');
      }
    });
    td.addEventListener('dragleave', () => {
      // Will be handled by dragend or next dragenter
    });
    // Клик-перемещение: отряд выбран кликом, и курсор ходит по доске без drag-события.
    // Без этого большой отряд «прицеливался» по одной клетке — тот же перекос, что был
    // при перетаскивании из палитры.
    td.addEventListener('mouseover', () => {
      if (editor.dragSrc || tacPaletteDragIndex() !== null) return;
      // Два источника «прицела» без drag-события: отряд, выбранный на поле, и
      // существо, выбранное в палитре для постановки кликом.
      let u = null, ignore;
      if (tacPaletteSelected !== null) {
        u = TACTIC_UNITS[tacPaletteSelected];
      } else if (editor.selectedUnit) {
        const srcCell = battleBoard.data[editor.selectedUnit.row]?.[editor.selectedUnit.col];
        u = srcCell && srcCell.id !== undefined ? TACTIC_UNITS[srcCell.id] : null;
        ignore = editor.selectedUnit;
      } else {
        return;
      }
      tacClearOver();
      if (!u || !u.big) return;
      const row = parseInt(td.dataset.row || '');
      const col = parseInt(td.dataset.col || '');
      const fits = tacFootprintFits(row, col, true, ignore);
      for (let dr = 0; dr <= 1; dr++) {
        for (let dc = 0; dc <= 1; dc++) {
          const t = tacQuery(`#tac-field td[data-row="${row + dr}"][data-col="${col + dc}"]`);
          if (!t) continue;
          t.classList.add('tac-over', 'tac-big-hover');
          if (!fits) t.classList.add('tac-over-bad');
        }
      }
    });
    td.addEventListener('click', () => {
      let row = parseInt(td.dataset.row || '');
      let col = parseInt(td.dataset.col || '');
      // Клик по хвостовой клетке 2×2 — это клик по самому отряду. Раньше четыре
      // клетки были слиты в один `td` и приходили координаты якоря; слияния больше
      // нет, поэтому владельца ищем сами.
      const owner = tacAnchorAt(row, col);
      if (owner) {
        row = owner.row; col = owner.col;
        td = tacQuery(`#tac-field td[data-row="${row}"][data-col="${col}"]`) || td;
      }
      const cell = battleBoard.data[row]?.[col];
      function clearSel() {
        document.querySelectorAll<HTMLElement>('#tac-field td.tac-selected').forEach(t => t.classList.remove('tac-selected'));
        editor.selectedUnit = null;
      }
      // Существо выбрано в палитре — ставим его сюда. Проверка помещаемости та же,
      // что у перетаскивания (tacFootprintFits), чтобы клик и перенос вели себя
      // одинаково и большое существо не вставало на занятый хвост чужого.
      if (tacPaletteSelected !== null) {
        const u = TACTIC_UNITS[tacPaletteSelected];
        if (!td.classList.contains('drop')) return;   // вне зоны высадки — молчим
        if (u && !tacFootprintFits(row, col, !!u.big)) return;
        tacPutUnit(row, col, tacPaletteSelected, 1, parseInt(td.dataset.pl || ''));
        return;   // выбор остаётся взведённым: удобно заполнять сторону подряд
      }
      if (td.classList.contains('tac-has-unit')) {
        if (editor.selectedUnit && editor.selectedUnit.row === row && editor.selectedUnit.col === col) {
          // Click same unit → open edit modal
          tacOpenUnitModal(row, col, td);
          if (cell && cell.id !== undefined && cell.id !== true && cell.id !== false) {
            tacShowUnitPreview(cell);
          }
        } else if (editor.selectedUnit) {
          // Click different unit while another is selected → swap (или слияние
          // одинаковых — то же правило, что и при перетаскивании).
          const src = editor.selectedUnit;
          const srcCell = battleBoard.data[src.row]?.[src.col];
          if (srcCell && srcCell.id !== undefined && row !== src.row && col !== src.col) {
            const u = TACTIC_UNITS[srcCell.id];
            if (u && !u.big) {
              if (tacMergeStacks(src, { row, col }, false)) {
                clearSel();
                return;
              }
              tacRemoveUnit(src.row, src.col, true);
              tacRemoveUnit(row, col, true);
              tacPutUnit(row, col, srcCell.id, srcCell.cnt, srcCell.team);
              if (cell && cell.id !== undefined) {
                tacPutUnit(src.row, src.col, cell.id, cell.cnt, cell.team);
              }
              clearSel();
            }
          } else {
            clearSel();
            td.classList.add('tac-selected');
            editor.selectedUnit = { row, col };
          }
        } else {
          // First click → select unit for movement
          clearSel();
          td.classList.add('tac-selected');
          editor.selectedUnit = { row, col };
        }
      } else if (editor.selectedUnit && td.classList.contains('drop') && !td.classList.contains('tac-has-unit')) {
        // Click empty cell with selected unit → move unit there
        const src = editor.selectedUnit;
        const srcCell = battleBoard.data[src.row]?.[src.col];
        if (srcCell && srcCell.id !== undefined) {
          const u = TACTIC_UNITS[srcCell.id];
          // Раньше здесь стояло `!u.big`: клик по пустой клетке с выбранным БОЛЬШИМ
          // отрядом молча не делал ничего — редактор обращался с ним как с маленьким и
          // просто отказывал. Теперь ход разрешён, если помещается весь след (свои же
          // клетки не считаются занятыми — отряд с них уходит).
          if (u && tacFootprintFits(row, col, !!u.big, src)) {
            tacRemoveUnit(src.row, src.col, true);
            tacPutUnit(row, col, srcCell.id, srcCell.cnt, srcCell.team);
            clearSel();
          }
        }
      } else {
        clearSel();
      }
    });
    td.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      const row = parseInt(td.dataset.row || '');
      const col = parseInt(td.dataset.col || '');
      if (td.classList.contains('tac-has-unit')) {
        // В БОЮ правая кнопка осматривает отряд — как в оригинале, где карточка
        // существа вызывается именно ею. Редакторская модалка («сколько», «чей»,
        // «разделить») там бессмысленна: расстановка уже сдана серверу, и её
        // правки в бой не попадут.
        if (hs.state || tacPlaybackRunning()) {
          tacUnitTooltip(td);
          return;
        }
        // В расстановке правая кнопка по-прежнему открывает окно отряда: там она
        // единственный путь к разделению стека.
        tacOpenUnitModal(row, col, td);
        const cell = battleBoard.data[row]?.[col];
        if (cell && cell.id !== undefined && cell.id !== true && cell.id !== false) {
          tacShowUnitPreview(cell);
        }
      }
      document.querySelectorAll<HTMLElement>('#tac-field td.tac-selected').forEach(t => t.classList.remove('tac-selected'));
      editor.selectedUnit = null;
    });
  });

  for (let r = 0; r < battleBoard.data.length; r++) {
    if (!battleBoard.data[r]) continue;
    for (let c = 0; c < battleBoard.data[r].length; c++) {
      const cell = battleBoard.data[r][c];
      if (cell === true || cell === false || !cell) continue;
      if (cell.id === undefined) continue;
      const td = tacQuery(`#tac-field td[data-row="${r}"][data-col="${c}"]`);
      if (td) {
        const u = TACTIC_UNITS[cell.id];
        if (!u) continue;
        td.style.backgroundImage = `url(${tacPortraitUrl(u.pic)})`;
        // Пометка 2×2 — ДО маунта: якорь спрайта считается по всему футпринту
        // (sceneCellAnchor находит его по классу `tac-big-anchor`), и без пометки
        // большое существо цеплялось бы за свою верхне-левую четверть — стояло бы
        // на пол-клетки выше и левее футпринта.
        td.classList.toggle('tac-big-anchor', !!u.big);
        if (u.big) {
          const cells = [[r, c+1], [r+1, c], [r+1, c+1]];
          cell.big_cells = cells;
          if (!battleBoard.data[r+1]) battleBoard.data[r+1] = [];
          battleBoard.data[r][c+1] = true; battleBoard.data[r+1][c] = true; battleBoard.data[r+1][c+1] = true;
          for (const [br, bc] of cells) {
            const btd = tacQuery(`#tac-field td[data-row="${br}"][data-col="${bc}"]`);
            if (btd) btd.classList.add('tac-big-tail');
          }
        }
        tacMountFieldSprite(r, c, u.pic, td, cell.team || 1, u.big);
        td.classList.add('tac-has-unit');
        td.draggable = true;
        td.addEventListener('dragstart', (e: any) => {
          e.dataTransfer!.setData('text/plain', 'move');
          tacSetDragImage(e, u.pic);
          editor.dragSrc = { row: r, col: c };
        });
        td.addEventListener('dragend', () => {
          document.querySelectorAll<HTMLElement>('#tac-field td.tac-over').forEach(t => t.classList.remove('tac-over'));
        });
        td.querySelector('div')!.textContent = cell.cnt;
        td.querySelector('div')!.className = tacNumClass(cell.team || 1, u.big);
        td.setAttribute('data-cnt', cell.cnt);
        td.dataset.pl = cell.team || 1;
      }
    }
  }
  tacRenderInitiative();
  tacSyncNumbers(); // обёртку поля только что пересоздали — слой чисел вместе с ней
  // Keep the «Код:» input filled from the very first render (and after field-type changes /
  // code loads), not only after the first manual placement.
  tacSyncCode();
}
