    tacAdvanceTurnRibbon: BattleAnimDeps['tacAdvanceTurnRibbon'];
let dep: BattleAnimDeps;

export function initBattleAnim(deps: BattleAnimDeps) {
  ({ TACTIC_UNITS, getCell, tacAnimHas, tacApplyStackState, tacCfg, tacDestroyFieldSprite, tacDetachFieldSprite, tacFieldSprites, tacHighlightInitiative, tacLogLine, tacMountFieldSprite, tacNameSpan, tacPortraitUrl, tacPutUnit, tacRemoveUnit, tacRenderInitiative, tacRenderUnits, tacShootLaunchFraction, tacSpriteSize, tacUnitMsPerCell, tacAdvanceTurnRibbon } = deps);
  dep = deps;
}

// Клетка, с которой ходивший отряд начал атаку, — нужна, чтобы вернуть его назад
// после удара. Состояние сугубо анимационное, снаружи блока не читается.
let tacLastAttackerPos: any = null;

/** Строка в `_movLines` — текстовый журнал боя «для копирования».
 *
 * Массив глобальный и появляется не всегда: его заводит начало реплея
 * (`battle.ts`), а в сессионном бою до первого движения или удара его нет
 * вовсе. Каждая ветка анимации заводила его сама, и та, что забыла (залп
 * навесом), роняла ВЕСЬ показ действия: `_movLines is not defined` вылетал
 * посреди `tacAnimateAction`, урон на доску не попадал, и залп выглядел
 * «выстрелил и ничего не сделал», хотя сервер его честно посчитал. Одна
 * функция вместо шести проверок — забыть её нельзя. */
export function movLine(text: string): void {
  if (!window._movLines) window._movLines = [];
  window._movLines.push(text);
}

/** Включена ли галочка «Клетки в логе» (#tac-log-target-cells): к ней
 * привязаны и координаты атак, и координаты движения. Вне боя (тесты,
 * расстановка) чекбокса в DOM нет — выключено. */
export function tacLogCellsEnabled(): boolean {
  const box = document.getElementById('tac-log-target-cells') as HTMLInputElement | null;
  return !!box && box.checked;
}

/** Координаты атакованной клетки для журнала под галочкой «Клетки в логе»
 * (#tac-log-target-cells). Формат тот же, что у движения, — `(колонка;ряд)`
 * (`getxa`: «х:у»). Пустая строка, пока галочка выключена, и вне боя (в тестах
 * и расстановке чекбокса в DOM нет): тогда существующие строки лога не меняются
 * ни на символ. */
export function tacCellTag(pos: { row: number; col: number } | null | undefined): string {
  if (!pos) return '';
  return tacLogCellsEnabled() ? ` (${pos.col};${pos.row})` : '';
}

/** Клетка цели под ударом из события AttackEvent (`aim_cell` — [колонка, ряд],
 * клик игрока). Для больших (2×2) целей это конкретная клетка следа, а не
 * якорь слева-сверху. null — события без прицельной клетки (ответка, зонные
 * добавки, удары ИИ): тогда журнал пишет якорь цели. */
export function tacAimCell(act: { aim_cell?: unknown }): { row: number; col: number } | null {
  const c = act && act.aim_cell;
  if (!Array.isArray(c) || c.length !== 2) return null;
  return { col: c[0], row: c[1] };
}

/** Фактическая клетка следа цели, по которой пришёлся ближний удар: клетка, к
 * которой атакующий подошёл вплотную. Мера — то же расстояние между следами,
 * что у сервера (`grid.footprint_distance`) и подхода (`tacFootprintTouch`), по
 * каждой клетке следа цели: у больших (2×2) целей якорь — левый-верхний угол,
 * а удар падает на клетку у атакующего, а не туда, куда указывал курсор.
 * При ничьей (две клетки следа ровно на одинаковом расстоянии — диагональное
 * касание в «середину» следа) берём ближайшую по Манхэттену, затем левую. */
export function tacStruckCell(att: { row: number; col: number }, attSize: number,
                              def: { row: number; col: number }, defSize: number): { row: number; col: number } {
  const gap = (a1: number, s1: number, b1: number, s2: number) =>
    Math.max(0, a1 - (b1 + s2 - 1), b1 - (a1 + s1 - 1));
  let best = { row: def.row, col: def.col };
  let bestD = Infinity;
  let bestManhattan = Infinity;
  for (let r = def.row; r < def.row + defSize; r++) {
    for (let c = def.col; c < def.col + defSize; c++) {
      const d = Math.max(gap(att.row, attSize, r, 1), gap(att.col, attSize, c, 1));
      const manhattan = Math.abs(r - att.row) + Math.abs(c - att.col);
      if (d < bestD || (d === bestD && manhattan < bestManhattan)) {
        best = { row: r, col: c };
        bestD = d;
        bestManhattan = manhattan;
      }
    }
  }
  return best;
}

