/**
 * Состояние партии в хотсите: сессия, ответ сервера и текущий выбор игрока.
 *
 * Собрано в объект по той же причине, что и доска в `battleState`: ввод и игровой
 * цикл пишут почти одни и те же переменные (замер: из тринадцати десять пишутся
 * обеими группами), а импортированную привязку ESM переприсвоить нельзя. Пока это
 * были отдельные `let` внутри `setupTacSimulate`, разделить ввод и цикл было
 * нечем.
 *
 * Модуль ничего не импортирует — состояние лежит ниже всех.
 */

export const hs: {
  /** Идентификатор серверной сессии боя. */
  session: string | null;
  /** Последний ответ /api/battle/step: чей ход, что можно сделать. */
  state: any;
  /** Ход отправлен, ответ ещё не проигран — ввод заблокирован. */
  busy: boolean;
  /** Выбранное заклинание героя: ждём клик по цели. */
  spell: string | null;
  /** Следующий выстрел — навесом (активируемое умение). */
  scatter: boolean;
  /** Выбранное активируемое умение отряда: ждём клик по цели. */
  ability: string | null;
  /** Раскрыт список «Заклинание/Умение». */
  bookOpen: boolean;
  /** Выбранное в книге магии заклинание ГЕРОЯ: ждём клик по цели. */
  heroSpell: string | null;
  /** Раскрыта книга магии героя. */
  heroBookOpen: boolean;
  /** Выбранное в СВОЕЙ книге отряда заклинание: ждём клик по цели. */
  unitSpell: string | null;
  /** Раскрыта книга магии ходящего отряда-колдуна. */
  unitBookOpen: boolean;
  /** Раскрыт свиток рун (рунная магия гнома). */
  runesOpen: boolean;
  /** Режим Shift кнопкой на панели (`shift_button` оригинала): у носителей «Удара
   * и возврата» — атака без отхода, у стрелка — рукопашная вместо выстрела. */
  shiftBtn: boolean;
  /** Зажата клавиша Shift. Второй источник того же режима — как `KeyisDown(16)`
   * в оригинале; держится отдельно от кнопки, чтобы отпускание клавиши не гасило
   * включённый кнопкой режим. */
  shiftKey: boolean;
  /** Отряд, выбранный первым кликом для заклинания переноса («Телепорт»):
   * вторым кликом игрок указывает клетку назначения. */
  heroSpellTarget: number | null;
  /** Отряд, выбранный первым кликом для умения со скоупом 'ally_cell'
   * («Переносчик»): вторым кликом игрок указывает клетку, куда нести. */
  abilityCellTarget: number | null;
  /** Взведена кнопка «Атака» в окне героя: ждём клик по врагу. */
  heroAttackArmed: boolean;
  /** Размер ходящего отряда: 2 у больших, для следа 2×2. */
  activeSize: number;
  /** Выбранная курсором сторона подхода: `{ targetIdx, cell, aimRow, aimCol }`.
   * `aimRow/aimCol` — клетка цели под курсором: у дыханий и «Сглаза» она задаёт
   * клетку «за целью» (см. zones.behind_cells), и перемена aim внутри габарита
   * большой цели перерисовывает прогноз зоны. */
  approach: { targetIdx: number; cell: [number, number]; aimRow: number; aimCol: number } | null;
  /** Расстановка на момент старта — для отката по кнопке «в бой». */
  setup: unknown;
  /** Цикл автобоя уже крутится: защита от повторного запуска. */
  autoLoopRunning: boolean;
  /** Расстановка до боя, общая с обычным реплеем. */
  savedSetup: unknown;
  /** Итог боя уже показан — не показывать повторно. */
  endStateShown: boolean;
  /** Ходом распоряжается ИИ: клики по доске игнорируются. */
  autoBattle: boolean;
} = {
  session: null,
  state: null,
  busy: false,
  spell: null,
  scatter: false,
  ability: null,
  bookOpen: false,
  heroSpell: null,
  heroBookOpen: false,
  unitSpell: null,
  unitBookOpen: false,
  runesOpen: false,
  shiftBtn: false,
  shiftKey: false,
  heroSpellTarget: null,
  abilityCellTarget: null,
  heroAttackArmed: false,
  activeSize: 1,
  approach: null,
  setup: null,
  autoLoopRunning: false,
  savedSetup: null,
  endStateShown: false,
  autoBattle: false,
};

/** Подписи сторон в хотсите. */
export const TAC_HS_SIDES = ['Игрок 1 — слева', 'Игрок 2 — справа'];
