import { allData } from './data.js';
import { shuffleArray } from './utils.js';
import { renderCreatureCard } from './creatures.js';
import { navigateTo } from './navigation.js';

interface CreatureRef {
  sysName: string;
  nameRu: string;
}

var _abilityCreatureMap: Record<string, CreatureRef[]> | null = null;

function buildAbilityCreatureMap(): Record<string, CreatureRef[]> {
  var map: Record<string, CreatureRef[]> = {};
  if (!allData.units) return map;
  
  for (var key in allData.units) {
    var u = allData.units[key];
    if (Array.isArray(u.skills)) {
      for (var i = 0; i < u.skills.length; i++) {
        var sk = u.skills[i];
        if (!map[sk]) map[sk] = [];
        map[sk].push({ sysName: key, nameRu: u.nameRu || key });
      }
    }
  }
  return map;
}

function renderAbilities(list: Array<[string, any]>): void {
  if (!_abilityCreatureMap) _abilityCreatureMap = buildAbilityCreatureMap();
  var grid = document.getElementById('ability-grid');
  var countEl = document.getElementById('ability-count');
  if (!grid || !countEl) return;
  
  countEl.textContent = list.length + ' способностей';
  grid.innerHTML = list.map(function(a) {
    var key = a[0], val = a[1];
    var name = val.name || key;
    var desc = val.desc || '';
    var creatures = _abilityCreatureMap![key] || [];
    return '<div class="ability-card" data-key="' + key + '">' +
      '<div class="name">' + name + '</div>' +
      (desc ? '<div class="desc">' + desc + '</div>' : '') +
      '<div class="count">Существа: ' + creatures.length + '</div>' +
      '<div class="creature-tags">' +
      creatures.map(function(c) {
        return '<span class="creature-tag" data-sysname="' + c.sysName + '">' + c.nameRu + '</span>';
      }).join('') +
      '</div></div>';
  }).join('');
  grid.querySelectorAll('.ability-card').forEach(function(card) {
    card.addEventListener('click', function() {
      navigateTo('/abilities/' + (card as HTMLElement).dataset.key);
    });
  });
  grid.querySelectorAll('.creature-tag').forEach(function(tag) {
    tag.addEventListener('click', function(e) {
      e.stopPropagation();
      navigateTo('/units/' + (tag as HTMLElement).dataset.sysname);
    });
  });
}

function filterAbilities(shuffle?: boolean): void {
  var searchEl = document.getElementById('ability-search') as HTMLInputElement;
  if (!searchEl || !allData.abilities) return;
  
  var q = searchEl.value.toLowerCase();
  var list = Object.entries(allData.abilities);
  if (shuffle) shuffleArray(list);
  if (q) {
    list = list.filter(function(a) {
      var val = a[1];
      return (val.name || '').toLowerCase().includes(q) ||
        (val.desc || '').toLowerCase().includes(q) ||
        a[0].toLowerCase().includes(q);
    });
  }
  renderAbilities(list);
}

function initAbilities(): void {
  filterAbilities(true);
}

function renderAbilityDetail(key: string): void {
  if (!_abilityCreatureMap) _abilityCreatureMap = buildAbilityCreatureMap();
  if (!allData.abilities) return;
  
  var gridEl = document.getElementById('ability-grid');
  var searchBar = document.querySelector('#tab-abilities .search-bar') as HTMLElement;
  var detail = document.getElementById('ability-detail');
  
  if (!gridEl || !searchBar || !detail) return;
  
  gridEl.style.display = 'none';
  searchBar.style.display = 'none';
  detail.style.display = 'block';
  
  var val = allData.abilities[key];
  if (!val) {
    detail.innerHTML = '<div style="padding:20px;color:var(--text-dim)">Способность не найдена</div>';
    return;
  }
  var name = val.name || key;
  var desc = val.desc || '';
  var creatures = _abilityCreatureMap![key] || [];
  detail.innerHTML = '<a class="back-link" href="#">← Все способности</a>' +
    '<div class="ad-name">' + name + '</div>' +
    '<div class="ad-key">' + key + '</div>' +
    (desc ? '<div class="ad-desc">' + desc + '</div>' : '') +
    renderImplBlock(key) +
    '<div class="ad-creatures-title">Существа с этой способностью: ' + creatures.length + '</div>' +
    '<div class="ad-creatures">' +
    creatures.map(function(c) {
      return renderCreatureCard(allData.units![c.sysName] || { sysName: c.sysName, nameRu: c.nameRu });
    }).join('') +
    '</div>';
  bindImplBlock(detail, key);
  var backLink = detail.querySelector('.back-link');
  if (backLink) {
    backLink.addEventListener('click', function(e) {
      e.preventDefault();
      closeAbilityDetail();
    });
  }
  detail.querySelectorAll('.creature-card').forEach(function(card) {
    card.addEventListener('click', function() {
      var sysName = (card as HTMLElement).dataset.sysname;
      if (sysName) navigateTo('/units/' + sysName);
    });
  });
}

// ── Раскрываемый блок «Как реализовано у нас» ──────────────────────────────
//
// Содержимое считает сервер по исходникам (battle/effects/introspect.py), а не
// хранит в данных: рукописный список «что чем покрыто» устарел бы на первой же
// правке и обещал бы тест, которого больше нет.

interface ImplEntry {
  triggerRu: string; typeRu: string; stat: string | null;
  value: unknown; text: string | null; parts: string[];
  // Кому эффект достаётся и какую область накрывает. Выводит схема
  // (battle/effects/schema.py) из ключей записи, руками не пишется.
  onRu?: string; areaRu?: string;
  // Что означает число: флаг, множитель, доля, пункты. Голая единица у
  // `has_X` — служебный флажок, и показывать её как игровое число нельзя.
  valueRu?: string; valueKind?: string;
}
// Есть ли у активной способности видимая реакция в бою. Считается по
// исходникам: тип действия в протоколе против веток анимации.
interface ImplVisual {
  needsVisual: boolean; actionTypes: string[];
  animated: string[]; missing: string[]; gap: boolean;
}
// Классификация умения целиком: активная или пассивная, сколько раз, что
// тратит. Уровень умения, а не записи, — поэтому отдельным полем отчёта.
interface ImplClass {
  activation: string; uses: { n: number; per: string } | null;
  cooldown: number | null; cost: string | null; parts: string[];
}
interface ImplRef {
  file: string; line: number; text: string; via: string;
  kind?: string; why?: string;
}
interface ImplTest { file: string; cls: string; name: string; line: number; doc: string; }
interface ImplReport {
  key: string; inRegistry: boolean; isStub: boolean; isNonBattle?: boolean;
  note?: string | null;
  descMismatch?: string | null;
  validated?: boolean;
  classification?: ImplClass;
  visual?: ImplVisual;
  entries: ImplEntry[];
  code: ImplRef[]; codeTotal: number; tests: ImplTest[]; testsTotal: number;
}

var _implCache: Record<string, ImplReport> = {};
// Отметки «реализация описана верно» — ручное подтверждение человеком.
// Загружаются один раз: их немного, и они меняются только по клику здесь же.
var _validated: Set<string> | null = null;

async function loadValidated(): Promise<Set<string>> {
  if (_validated) return _validated;
  try {
    var res = await fetch('/api/abilities/validation');
    var data = await res.json() as { checked: string[] };
    _validated = new Set(data.checked || []);
  } catch {
    _validated = new Set();   // недоступность отметок не должна ломать отчёт
  }
  return _validated;
}

async function setValidated(key: string, checked: boolean): Promise<boolean> {
  var res = await fetch('/api/abilities/' + encodeURIComponent(key) + '/validation', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ checked: checked }),
  });
  if (!res.ok) return false;
  var set = await loadValidated();
  if (checked) set.add(key); else set.delete(key);
  return true;
}

function esc(s: unknown): string {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function renderImplBody(r: ImplReport): string {
  if (!r.inRegistry) {
    return '<div class="impl-empty">Способность не объявлена в реестре эффектов — ' +
      'в бою она не участвует.</div>';
  }
  var out = '';

  // Отметка человека — над всем остальным: она про весь блок целиком,
  // а не про отдельный его раздел.
  out += '<label class="impl-check' + (r.validated ? ' is-on' : '') + '">' +
    '<input type="checkbox" data-key="' + esc(r.key) + '"' +
    (r.validated ? ' checked' : '') + '>' +
    '<span>Реализация описана верно — проверено вручную</span>' +
    '<span class="impl-check-state"></span></label>';

  // Расхождение с игровым описанием — самое важное на странице: читатель
  // только что прочёл описание выше и поверил ему. Поэтому оно идёт до всего
  // остального, включая пояснение.
  if (r.descMismatch) {
    out += '<div class="impl-mismatch"><b>Реализация расходится с описанием выше.</b> ' +
      esc(r.descMismatch) + '</div>';
  }

  // Пояснение идёт ПЕРВЫМ и подписано как написанное человеком: остальные
  // разделы — находки скана, они проверяемы, а этот текст держится на том,
  // что его кто-то поддерживает. Смешивать их было бы нечестно.
  if (r.note) {
    out += '<div class="impl-section-title">Как это работает ' +
      '<span class="impl-byline">пояснение написано вручную</span></div>';
    out += '<div class="impl-note-text">' +
      r.note.split('\n\n').map(function(par) {
        return '<p>' + esc(par).replace(/`([^`]+)`/g, '<code>$1</code>') + '</p>';
      }).join('') + '</div>';
  }

  out += '<div class="impl-section-title">Запись в реестре эффектов</div>';

  // Классификация — до таблицы: она отвечает на первый вопрос читателя
  // («это надо нажимать или оно само?»), а таблица уже на второй.
  if (r.classification) {
    var chips = r.classification.parts.slice();
    // Активной мало счётчика применений: если типа её действия нет в анимации,
    // способность срабатывает молча — в логе строка есть, на поле пусто.
    if (r.visual && r.visual.gap) {
      chips.push(r.visual.actionTypes.length
        ? 'визуальной реакции нет: ' + r.visual.missing.join(', ') + ' не разобран в анимации'
        : 'визуальной реакции нет: действие в протокол не пишется');
    }
    out += '<div class="impl-class impl-class-' + esc(r.classification.activation) + '">' +
      chips.map(function(p, i) {
        var cls = 'impl-chip' + (r.visual && r.visual.gap && i === chips.length - 1
          ? ' impl-chip-warn' : '');
        return '<span class="' + cls + '">' + esc(p) + '</span>';
      }).join('') + '</div>';
  }

  out += '<table class="impl-table"><thead><tr>' +
    '<th>Когда</th><th>Что делает</th><th>На кого</th><th>Область</th>' +
    '<th>Характеристика</th><th>Значение</th><th>Условия</th>' +
    '</tr></thead><tbody>' +
    r.entries.map(function(e) {
      return '<tr>' +
        '<td>' + esc(e.triggerRu) + '</td>' +
        '<td>' + esc(e.typeRu) + '</td>' +
        '<td>' + esc(e.onRu || '—') + '</td>' +
        '<td>' + esc(e.areaRu || '—') + '</td>' +
        '<td>' + (e.stat ? '<code>' + esc(e.stat) + '</code>' : '—') + '</td>' +
        // Показывается разобранное значение («×0.85», «50%», «+3»), сырое
        // число — подсказкой: голая единица у `has_X` не значит ничего.
        '<td title="' + esc(e.value) + '">' +
          esc(e.valueRu !== undefined ? e.valueRu
              : (e.value === undefined || e.value === null ? '—' : e.value)) + '</td>' +
        '<td>' + (e.parts.length ? esc(e.parts.join(' · ')) : '—') + '</td>' +
        '</tr>';
    }).join('') + '</tbody></table>';

  if (r.isNonBattle) {
    // Не заглушка: механика живёт вне боя, и кода в симуляторе у неё нет и не
    // должно быть. Без этой ветки она выглядела бы недоделкой.
    out += '<div class="impl-note">Механика вне боя — очки, популяция и прочее, ' +
      'что считается за пределами сражения. Кода в симуляторе у неё нет и не требуется.</div>';
  } else if (r.isStub) {
    // Ради этого случая блок и появился: запись есть, а кода за ней нет.
    out += '<div class="impl-warn">⚠ Заглушка: запись в реестре есть, но ни одна ' +
      'строка боевого кода её не читает — в бою способность ничего не делает.</div>';
  }

  out += '<div class="impl-section-title">Реализация в коде' +
    (r.codeTotal ? ' <span class="impl-count">' + r.codeTotal + '</span>' : '') + '</div>';
  out += r.code.length
    ? '<ul class="impl-list">' + r.code.map(function(c) {
        // Причина совпадения важна не меньше самой строки: «умение названо
        // прямо» и «общий обработчик этого вида» — доказательства разной силы.
        return '<li class="impl-ref impl-ref-' + esc(c.kind || 'other') + '">' +
          '<span class="impl-loc">' + esc(c.file) + ':' + c.line + '</span>' +
          '<code class="impl-code">' + esc(c.text) + '</code>' +
          '<span class="impl-via">' + esc(c.why || 'совпадение') +
          ' · <code>' + esc(c.via) + '</code></span></li>';
      }).join('') + '</ul>'
    : '<div class="impl-empty">Мест в коде не найдено.</div>';
  if (r.codeTotal > r.code.length) {
    out += '<div class="impl-more">…и ещё ' + (r.codeTotal - r.code.length) + '</div>';
  }

  out += '<div class="impl-section-title">Чем покрыта тестами' +
    (r.testsTotal ? ' <span class="impl-count">' + r.testsTotal + '</span>' : '') + '</div>';
  out += r.tests.length
    ? '<ul class="impl-list">' + r.tests.map(function(t) {
        return '<li><span class="impl-loc">' + esc(t.file) + ':' + t.line + '</span>' +
          '<code class="impl-code">' + esc(t.cls) + '.' + esc(t.name) + '</code>' +
          (t.doc ? '<span class="impl-doc">' + esc(t.doc) + '</span>' : '') + '</li>';
      }).join('') + '</ul>'
    : '<div class="impl-empty">Тестов, упоминающих эту способность, не найдено.</div>';
  if (r.testsTotal > r.tests.length) {
    out += '<div class="impl-more">…и ещё ' + (r.testsTotal - r.tests.length) + '</div>';
  }
  return out;
}

async function loadAbilityImpl(key: string, body: HTMLElement): Promise<void> {
  if (_implCache[key]) {
    body.innerHTML = renderImplBody(_implCache[key]);
    bindValidationCheckbox(body, _implCache[key]);
    return;
  }
  body.innerHTML = '<div class="impl-empty">Считаем по исходникам…</div>';
  try {
    var res = await fetch('/api/abilities/' + encodeURIComponent(key) + '/impl');
    if (!res.ok) throw new Error('HTTP ' + res.status);
    var data = await res.json() as ImplReport;
    data.validated = (await loadValidated()).has(key);
    _implCache[key] = data;
    body.innerHTML = renderImplBody(data);
    bindValidationCheckbox(body, data);
  } catch (e) {
    body.innerHTML = '<div class="impl-empty">Не удалось получить отчёт: ' +
      esc((e as Error)?.message || e) + '</div>';
  }
}

function bindValidationCheckbox(body: HTMLElement, report: ImplReport): void {
  var box = body.querySelector('.impl-check input') as HTMLInputElement | null;
  if (!box) return;
  var label = box.closest('.impl-check') as HTMLElement;
  var state = label.querySelector('.impl-check-state') as HTMLElement;
  var input = box;   // отдельная переменная: внутри замыкания TS теряет сужение типа
  input.addEventListener('change', async function() {
    var want = input.checked;
    input.disabled = true;
    state.textContent = 'сохраняем…';
    var ok = await setValidated(report.key, want);
    input.disabled = false;
    if (ok) {
      report.validated = want;
      label.classList.toggle('is-on', want);
      state.textContent = want ? 'отмечено' : '';
    } else {
      // Откатываем галочку: показывать отметку, которой нет на сервере, —
      // худший вид вранья для страницы, которая ровно про достоверность.
      input.checked = !want;
      state.textContent = 'не сохранилось';
    }
  });
}

function renderImplBlock(key: string): string {
  return '<details class="impl-block" data-key="' + esc(key) + '">' +
    '<summary>Как реализовано у нас</summary>' +
    '<div class="impl-body"></div></details>';
}

function bindImplBlock(detail: HTMLElement, key: string): void {
  var block = detail.querySelector('.impl-block') as HTMLDetailsElement | null;
  if (!block) return;
  var body = block.querySelector('.impl-body') as HTMLElement;
  // Считаем только при раскрытии: индекс по исходникам строится не мгновенно,
  // и платить за него на каждом открытии карточки незачем.
  block.addEventListener('toggle', function() {
    if (block!.open) loadAbilityImpl(key, body);
  });
}

function closeAbilityDetail(): void {
  var gridEl = document.getElementById('ability-grid');
  var searchBar = document.querySelector('#tab-abilities .search-bar') as HTMLElement;
  var detailEl = document.getElementById('ability-detail');
  
  if (gridEl) gridEl.style.display = '';
  if (searchBar) searchBar.style.display = '';
  if (detailEl) detailEl.style.display = 'none';
  
  navigateTo('/abilities');
}

export {
  buildAbilityCreatureMap,
  renderAbilities,
  filterAbilities,
  initAbilities,
  renderAbilityDetail,
  closeAbilityDetail,
};
