export async function loadFittingSets(): Promise<Record<string, FittingSet>> {
  if (fittingSets) return fittingSets;
  try {
    var resp = await fetch('/api/fitting?action=sets');
    if (resp.ok) {
      fittingSets = await resp.json();
      return fittingSets!;
    }
  } catch(e) {}
  // Fallback to hardcoded data (offline mode)
  fittingSets = FITTING_SETS_FALLBACK;
  return fittingSets;
}

// Eagerly load fitting sets from API (falls back to static data)
