// ===== FUNCTIONS =====

export function closeFittingPicker(): void {}

export function initFitting(): void {fittingEquipment={};fittingGems={};renderRoom();}
export function ensureFittingRoom(): void {var c=document.getElementById('tab-fitting');if(c&&!c.innerHTML.trim())initFitting();}
export function loadBuilds(): Record<string, any> {try{return JSON.parse(localStorage.getItem('fitting_builds')||'{}')}catch(e){return{}}}
export function saveBuilds(b: Record<string, any>): void {localStorage.setItem('fitting_builds',JSON.stringify(b))}

export function modAlias(k: string): string {return FITTING_MODIFIER_ALIASES[k]||k}
export function modEntries(mods: Record<string, number | string | null> | undefined): Array<{key: string, value: number}> {var g: Record<string, number>={};if(!mods)return[];for(var k in mods){if(!mods.hasOwnProperty(k))continue;var v=Number(mods[k]);if(!v)continue;var n=modAlias(k);if(n==='sin'){if(!(n in g)||v>g[n])g[n]=v}else g[n]=(g[n]||0)+v}var r: Array<{key: string, value: number}>=[];for(var k in g)if(g.hasOwnProperty(k))r.push({key:k,value:g[k]});return r}

export function getArtCat(a: ArtifactRecord): string {var c=(a.category||a.slot||'').toLowerCase();if(['helm','head'].indexOf(c)!==-1)return'head';if(['neck','necklace'].indexOf(c)!==-1)return'neck';if(['weapon','weapon_left','weapon_right'].indexOf(c)!==-1)return'weapon';if(['body','cuirass'].indexOf(c)!==-1)return'body';if(['cloak','cloack'].indexOf(c)!==-1)return'cloak';if(['ring','ringtop','ringbot'].indexOf(c)!==-1)return'ring';if(['boots'].indexOf(c)!==-1)return'boots';if(['shield'].indexOf(c)!==-1)return'shield';if(['backpack'].indexOf(c)!==-1)return'backpack';if(['potion'].indexOf(c)!==-1)return'potion';return'other'}
export function slotMatch(art: ArtifactRecord, slot: string): boolean {var sn=String(art.slot||'').toLowerCase(),cat=String(art.category||'').toLowerCase(),tp=String((art as any).type||'').toLowerCase();if(!sn&&!cat&&!tp)return slot==='artifact';if(slot==='helmet')return sn==='helm'||cat==='helm'||tp==='head';if(slot==='amulet')return sn==='neck'||cat==='necklace'||tp==='neck';// The original has no dedicated shield cell: shields occupy the left hand.
if(slot==='weapon_left')return sn==='weapon_left'||sn==='shield'||cat==='shield'||sn==='weapon'||cat==='weapon';
if(slot==='weapon_right')return (sn==='weapon'||cat==='weapon')&&cat!=='shield';if(slot==='body')return sn==='body'||sn==='cuirass'||cat==='body'||cat==='cuirass';if(slot==='mantle')return sn==='cloak'||sn==='cloack'||cat==='cloak'||cat==='cloack';if(slot==='ring_top'||slot==='ring_bottom')return sn==='ring'||cat==='ring'||tp==='ringtop'||tp==='ringbot';if(slot==='boots')return sn==='boots'||cat==='boots';if(slot==='shield')return sn==='shield'||cat==='shield';if(slot==='backpack')return sn==='backpack'||cat==='backpack';if(slot==='potion')return sn==='potion'||cat==='potion'||sn==='other'||cat==='other'||tp==='other';return sn===slot||cat===slot}
export function getSlotCat(s: string): string {var m: Record<string, string>={helmet:'head',amulet:'neck',weapon_left:'weapon',weapon_right:'weapon',body:'body',mantle:'cloak',ring_top:'ring',ring_bottom:'ring',boots:'boots',backpack:'backpack',potion:'potion'};return m[s]||'all'}
export function findArt(k: string): ArtifactRecord | null {var a: ArtifactRecord[]=Array.isArray(allData.artifacts)?allData.artifacts:Object.values(allData.artifacts || {});for(var i=0;i<a.length;i++){if(a[i].key===k)return a[i]}return null}

