export function renderDoll(): void {
  var w=document.getElementById('fit-doll');
  if (!w) return;
  var prox=function(u: string){return '/api/img?url='+encodeURIComponent(u)};
  w.style.width=DOLL_W+'px';
  w.style.height=DOLL_H+'px';
  w.style.backgroundImage='url('+prox('https://dcdn.heroeswm.ru/i/kukla_png/'+(FRACTION_IMG[fittingFaction]||'kukla1.png'))+')';
  w.innerHTML='';
  for(var i=0;i<SLOT_DOLL.length;i++){
    var info=SLOT_DOLL[i],slot=info[0],art=fittingEquipment[slot];
    var el=document.createElement('div');
    el.className='fitting-doll-slot'+(art?' equipped':'');
    // Absolute px placement — the original board is a fixed 230x200 bitmap, so
    // percentages would drift the slots off the figure.
    el.style.left=info[1]+'px';el.style.top=info[2]+'px';el.dataset.slot=slot;
    if(art){
      el.innerHTML=(art.icon?'<img src="'+prox(artIconB(art.icon))+'" onerror="this.style.display=\'none\'">':'')+ 
        '<span class="doll-remove" onclick="event.stopPropagation();remSlot(\''+slot+'\')">&times;</span>';
    }else{
      // Empty slots show the original silhouette stub image, not a "?".
      el.style.backgroundImage='url('+prox(SLOT_STUB_BASE+info[3])+')';
    }
    el.onclick=function(s: string){return function(){var e=document.getElementById('br-s') as HTMLInputElement | null;if(e)e.value='';_brQuery='';_brCat=getSlotCat(s);renderCats();renderGrid()}}(slot);
    w.appendChild(el);
  }
  var clr=document.createElement('div');
  clr.className='fitting-doll-clear';
  clr.title='снять всё';
  clr.style.left=DOLL_CLEAR_POS[0]+'px';clr.style.top=DOLL_CLEAR_POS[1]+'px';
  clr.innerHTML='<img src="'+prox('https://dcdn.heroeswm.ru/i/inv_im/btn_art_rem.png')+'" alt="снять всё">';
  clr.onclick=function(){clearDoll()};
  w.appendChild(clr);
}

/** Empties every doll slot ("снять всё" button on the original). */
export function clearDoll(): void {
  for(var i=0;i<SLOT_DOLL.length;i++) delete fittingEquipment[SLOT_DOLL[i][0]];
  renderDoll();renderGrid();renderEffects();
}

export function onFaction(): void {fittingFaction=parseInt((document.getElementById('fit-faction') as HTMLSelectElement).value);renderDoll()}
export function onLevel(): void {fittingLevel=parseInt((document.getElementById('fit-level') as HTMLSelectElement).value)}
export function onGuild(): void {}

export function renderCats(): void {
  var el=document.getElementById('br-cats');
  if (!el) return;
  el.innerHTML=BR_CATS.map(function(c){return'<span class="cat'+(c.id===_brCat?' active':'')+'" onclick="setBrCat(\''+c.id+'\')">'+c.label+'</span>'}).join('');
}
export function setBrCat(c: string): void {_brCat=c;renderCats();renderGrid()}
export function onBrSearch(): void {_brQuery=((document.getElementById('br-s') as HTMLInputElement | null)?.value)||'';renderGrid()}

export function renderGrid(): void {
  var g=document.getElementById('br-grid');
  if (!g) return;
  var arts: ArtifactRecord[]=Array.isArray(allData.artifacts)?allData.artifacts:Object.values(allData.artifacts || {});
  var flt=arts.filter(function(a){if(_brCat!=='all'&&getArtCat(a)!==_brCat)return false;if(_brQuery){var n=((a as any).nameRu||a.name||'').toLowerCase();if(n.indexOf(_brQuery)===-1)return false}return true});
  flt.sort(function(a,b){return(b.level||0)-(a.level||0)||((a as any).nameRu||a.name||'').localeCompare((b as any).nameRu||b.name||'')});
  if(!flt.length){g.innerHTML='<div class="no-items">Нет артефактов</div>';return}
  var h='';
  for(var i=0;i<flt.length;i++){
    var a=flt[i],eq=0;for(var s in fittingEquipment){if(fittingEquipment[s]&&fittingEquipment[s].key===a.key){eq=1;break}}
    h+='<div class="br-item'+(eq?' equipped':'')+'" onclick="onBrClk(\''+a.key+'\')" title="'+((a as any).nameRu||a.name)+' Lv'+(a.level||'?')+'">'+
      (a.icon&&a.icon_ok!==false?'<img src="/api/img?url='+encodeURIComponent(artIconB(a.icon))+'" onerror="this.style.display=\'none\'">':'<span class="doll-empty">?</span>')+'</div>';
  }
  g.innerHTML=h;
}

export function onBrClk(key: string): void {
  var art=findArt(key);if(!art)return;
  var ts: string | null=null;for(var s in fittingEquipment){if(fittingEquipment[s]&&fittingEquipment[s].key===key){ts=s;break}}
  if(ts){delete fittingEquipment[ts];delete fittingGems[ts]}
  else{
    var bs: string | null=null;
    for(var i=0;i<SLOT_DOLL.length;i++){var sl=SLOT_DOLL[i][0];if(slotMatch(art,sl)&&!fittingEquipment[sl]){bs=sl;break}}
    if(!bs)for(var i=0;i<SLOT_DOLL.length;i++){var sl=SLOT_DOLL[i][0];if(slotMatch(art,sl)){bs=sl;break}}
    if(bs){if(fittingEquipment[bs])delete fittingGems[bs];fittingEquipment[bs]=art}else return
  }
  renderDoll();renderEffects();renderGrid();renderBld()
}

export function renderEffects(): void {
  var tb=document.querySelector('#fit-ef-t tbody');if(!tb)return;
  var totals: Record<string, number>={};for(var i=0;i<FITTING_STATS.length;i++)totals[FITTING_STATS[i]]=0;
  var specs: string[]=[],setC: Record<string, number>={};
  var fb=FITTING_FACTION[fittingFaction]||{};
  for(var bk in fb)if(FITTING_STATS.indexOf(bk)!==-1)totals[bk]+=fb[bk];
  var sel=document.querySelectorAll('.fg-g');
  for(var si=0;si<sel.length;si++){
    var k=sel[si].getAttribute('data-k'),v=parseInt((sel[si] as HTMLSelectElement).value);
    if(v>0&&FITTING_GUILD[k!]&&FITTING_GUILD[k!][v]){
      for(var gk in FITTING_GUILD[k!][v])if(FITTING_STATS.indexOf(gk)!==-1)totals[gk]+=FITTING_GUILD[k!][v][gk];
    }
  }
  for(var slot in fittingEquipment){
    if(!fittingEquipment.hasOwnProperty(slot))continue;
    var art=fittingEquipment[slot],am: Record<string, number>={};
    if(art.modifiers)for(var mk in art.modifiers)if(art.modifiers.hasOwnProperty(mk))am[mk]=(am[mk]||0)+Number(art.modifiers[mk]);
    var sg=fittingGems[slot]||[];
    for(var gi=0;gi<sg.length;gi++){var gm=GEM_STATS[sg[gi]]&&GEM_STATS[sg[gi]].modifiers;if(gm)for(var gk in gm)if(gm.hasOwnProperty(gk))am[gk]=(am[gk]||0)+Number(gm[gk])}
    var ents=modEntries(am);
    for(var e=0;e<ents.length;e++){if(FITTING_STATS.indexOf(ents[e].key)!==-1)totals[ents[e].key]+=ents[e].value}
    if(Array.isArray(art.specials))for(var j=0;j<art.specials.length;j++){var sp=art.specials[j] as {text_ru?: string} | string;specs.push(typeof sp==='string'?sp:(sp.text_ru||''))}
    if(art.set&&art.set>0)setC[art.set]=(setC[art.set]||0)+1;
  }
  var mainKeys=['attack','defence','spellpower','knowledge','initiative','luck','morale','oa'];
  var h='<tr><td colspan="2" style="font-size:10px;color:var(--gold);padding-bottom:4px"><b>Основные</b></td></tr>';
  for(var mi=0;mi<mainKeys.length;mi++){var key=mainKeys[mi],t=totals[key]||0;var c=t>0?' pos':(t<0?' neg':'');h+='<tr><td class="ef-label">'+(FITTING_STAT_LABELS[key]||key)+'</td><td class="ef-val'+c+'">'+t+'</td></tr>'}
  h+='<tr><td colspan="2" style="font-size:10px;color:var(--gold);padding:4px 0"><b>Бой</b></td></tr>';
  var combatKeys=['attack_percent','defence_percent','attack_war','defence_war','defence_range','attack_range','reload','critical','magic_resist','magic_immunity','mbf','mkf','mua','hp','muw','sin','ign','pdi','pat','tactics','petrify'];
  for(var ci=0;ci<combatKeys.length;ci++){var key=combatKeys[ci],t=totals[key];if(!t)continue;var c=t>0?' pos':(t<0?' neg':'');var sx=FITTING_STAT_PCT[key]?'%':'';h+='<tr><td class="ef-label">'+(FITTING_STAT_LABELS[key]||key)+'</td><td class="ef-val'+c+'">'+(t>0?'+':'')+t+sx+'</td></tr>'}
  h+='<tr><td colspan="2" style="font-size:10px;color:var(--gold);padding:4px 0"><b>Прочее</b></td></tr>';
  var otherKeys=['attack_nature','defence_nature','initiative_hero','initiative_percent','spellpower_percent','knowledge_percent','luck_percent','morale_percent'];
  for(var oi=0;oi<otherKeys.length;oi++){var key=otherKeys[oi],t=totals[key];if(!t)continue;var c=t>0?' pos':(t<0?' neg':'');var sx=FITTING_STAT_PCT[key]?'%':'';h+='<tr><td class="ef-label">'+(FITTING_STAT_LABELS[key]||key)+'</td><td class="ef-val'+c+'">'+(t>0?'+':'')+t+sx+'</td></tr>'}
  tb.innerHTML=h;
  var spEl=document.getElementById('fit-sp-s'),spL=document.getElementById('fit-sp');
  if(specs.length){spEl!.style.display='';spL!.innerHTML=specs.map(function(s){return'<div style="font-size:9px;padding:1px 0">✦ '+s+'</div>'}).join('')}else spEl!.style.display='none';
  var stEl=document.getElementById('fit-set-s'),stL=document.getElementById('fit-set'),has=!1,sH='';
  if(fittingSets) for(var sid in setC){var sd=fittingSets[sid];if(!sd)continue;var cnt=setC[sid],best: Record<string, number> | null=null,bc=0;for(var bc2 in sd.bonuses){var bc3=parseInt(bc2);if(bc3<=cnt&&bc3>=bc){bc=bc3;best=sd.bonuses[bc2]}}if(best){has=!0;sH+='<div style="font-size:9px;padding:1px 0"><b>'+sd.name+'</b> ('+cnt+'/'+bc+'): ';var fst=!0;for(var bk in best){if(!fst)sH+=', ';fst=!1;sH+=(FITTING_STAT_LABELS[bk]||bk)+': +'+best[bk]}sH+='</div>'}}
  if(has){stEl!.style.display='';stL!.innerHTML=sH}else stEl!.style.display='none';
  // Re-render when fitting sets arrive from API
  if(!fittingSets) loadFittingSets().then(function(){renderEffects()});
}

export function remSlot(s: string): void {delete fittingEquipment[s];delete fittingGems[s];renderDoll();renderEffects();renderGrid();renderBld()}

export function serverSaveBld(): void {
  var inp=document.getElementById('bld-inp') as HTMLInputElement | null,name=inp?.value.trim();
  if(!name){showToast('Введите название сета', true);return}
  var hasItems=false;for(var s in fittingEquipment){if(fittingEquipment.hasOwnProperty(s)&&fittingEquipment[s]){hasItems=true;break}}
  if(!hasItems){showToast('Сначала экипируйте артефакты', true);return}
  serverSave(name);
}

export function renderBld(): void {
  var builds=loadBuilds(),sel=document.getElementById('bld-sel') as HTMLSelectElement | null,del=document.getElementById('bld-del');
  if(!sel)return;sel.innerHTML='<option value="">— Загрузить —</option>';var ks=Object.keys(builds);
  for(var i=0;i<ks.length;i++){var o=document.createElement('option');o.value=ks[i];o.textContent=ks[i];sel.appendChild(o)}
  sel.style.display=ks.length?'':'none';if(del)(del as HTMLElement).style.display='none'
  serverList(function(){renderBldServer()})
}

export function saveBld(): void {
  var inp=document.getElementById('bld-inp') as HTMLInputElement | null,name=inp?.value.trim();if(!name){alert('Введите название сета');return}
  var data: Record<string, string>={};for(var s in fittingEquipment)if(fittingEquipment.hasOwnProperty(s))data[s]=fittingEquipment[s].key;
  if(!Object.keys(data).length){alert('Сначала экипируйте артефакты');return}
  var builds=loadBuilds();builds[name]={items:data,gems:JSON.parse(JSON.stringify(fittingGems)),faction:fittingFaction,level:fittingLevel};saveBuilds(builds);if(inp)inp.value='';renderBld();const selEl = document.getElementById('bld-sel') as HTMLSelectElement | null;if(selEl)selEl.value=name;var d=document.getElementById('bld-del');if(d)(d as HTMLElement).style.display=''
}

export function loadBld(name: string): void {
  if(!name){var d=document.getElementById('bld-del');if(d)(d as HTMLElement).style.display='none';return}
  var builds=loadBuilds(),bd=builds[name];if(!bd)return;var data=bd.items||bd,gems=bd.gems||{};
  if(bd.faction){fittingFaction=bd.faction;const el = document.getElementById('fit-faction') as HTMLSelectElement | null;if(el)el.value=String(fittingFaction)}
  if(bd.level){fittingLevel=bd.level;const el = document.getElementById('fit-level') as HTMLSelectElement | null;if(el)el.value=String(fittingLevel)}
  fittingEquipment={};fittingGems={};
  for(var slot in data){if(data.hasOwnProperty(slot)){var art=findArt(data[slot]);if(art&&slotMatch(art,slot)){fittingEquipment[slot]=art;if(gems[slot])fittingGems[slot]=gems[slot].slice()}}}
  renderDoll();renderEffects();renderGrid();var d=document.getElementById('bld-del');if(d)(d as HTMLElement).style.display=''
}

export function delBld(): void {var sel=document.getElementById('bld-sel') as HTMLSelectElement | null,name=sel?.value;if(!name)return;if(!confirm('Удалить сет "'+name+'"?'))return;var builds=loadBuilds();delete builds[name];saveBuilds(builds);if(sel)sel.value='';renderBld()}

interface ServerBuild {
  name: string;
  updated_at: number;
}

export function renderBldServer(): void {
  var wrap=document.getElementById('fit-server-builds'),list=document.getElementById('fit-server-list');
  if(!wrap||!list)return;
  if(!_serverBuilds.length){wrap.style.display='none';return}
  wrap.style.display='';
  // DOM API вместо конкатенации в innerHTML: имя сборки приходит с сервера
  // (его может сохранить кто угодно) — b.name как текст, не как разметка.
  list.innerHTML='';
  for(var i=0;i<_serverBuilds.length;i++){
    var b=_serverBuilds[i];
    var item=document.createElement('div');item.className='server-build-item';
    var nameEl=document.createElement('span');nameEl.className='srv-name';
    nameEl.title='\u0417\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044c';nameEl.textContent=b.name;
    nameEl.onclick=function(name:string){return function(){serverLoad(name)}}(b.name);
    var dateEl=document.createElement('span');dateEl.className='srv-date';
    dateEl.textContent=new Date(b.updated_at*1000).toLocaleDateString();
    var delEl=document.createElement('button');delEl.className='srv-del';delEl.innerHTML='&times;';
    delEl.title='\u0423\u0434\u0430\u043b\u0438\u0442\u044c';
    delEl.onclick=function(name:string){return function(){serverDelete(name)}}(b.name);
    item.appendChild(nameEl);item.appendChild(dateEl);item.appendChild(delEl);
    list.appendChild(item);
  }
}

// ===== SERVER BUILD FUNCTIONS =====

export var _serverBuilds: ServerBuild[] = [];

export function serverList(callback?: () => void): void {
  fetch('/api/fitting?action=list').then(function(r){return r.json()}).then(function(data){
    _serverBuilds = data||[];
    if(callback) callback();
  }).catch(function(err){
    console.warn('serverList error:', err);
    _serverBuilds = [];
    if(callback) callback();
  });
}
(window as any).serverList = serverList;

export function serverLoad(name: string): void {
  fetch('/api/fitting?action=get&name='+encodeURIComponent(name)).then(function(r){return r.json()}).then(function(data){
    if(!data||data.error){showToast('Ошибка загрузки: '+(data?data.error:'unknown'), true);return}
    // Apply build to equipment
    var items = data.data||{};
    for(var slot in items){
      if(items.hasOwnProperty(slot)){
        var art = findArt(items[slot]);
        if(art&&slotMatch(art,slot)) fittingEquipment[slot]=art;
      }
    }
    fittingGems = data.gems||{};
    fittingFaction = data.faction||1;
    fittingLevel = data.level||1;
    renderDoll();renderEffects();renderGrid();renderBld();
    showToast('Сборка "'+name+'" загружена с сервера');
  }).catch(function(err){
    showToast('Ошибка загрузки с сервера: '+err.message, true);
  });
}
(window as any).serverLoad = serverLoad;

export function serverSave(name: string): void {
  var data: Record<string, string> = {};for(var s in fittingEquipment){if(fittingEquipment.hasOwnProperty(s)&&fittingEquipment[s]){data[s]=fittingEquipment[s].key}}
  fetch('/api/fitting',{
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({name:name,data:data,gems:fittingGems,faction:fittingFaction,level:fittingLevel})
  }).then(function(r){return r.json()}).then(function(resp){
    if(resp&&resp.error){showToast('Ошибка: '+resp.error, true);return}
    showToast('Сборка "'+name+'" сохранена на сервер');
    serverList(function(){renderBldServer()});
  }).catch(function(err){
    showToast('Ошибка сохранения: '+err.message, true);
  });
}
(window as any).serverSave = serverSave;

export function serverDelete(name: string): void {
  if(!confirm('Удалить сборку "'+name+'" с сервера?')) return;
  fetch('/api/fitting?name='+encodeURIComponent(name),{method:'DELETE'}).then(function(r){return r.json()}).then(function(resp){
    if(resp&&resp.error){showToast('Ошибка: '+resp.error, true);return}
    showToast('Сборка "'+name+'" удалена с сервера');
    serverList(function(){renderBldServer()});
  }).catch(function(err){
    showToast('Ошибка удаления: '+err.message, true);
  });
}
(window as any).serverDelete = serverDelete;

function showToast(message: string, isError?: boolean): void {
  (window as any).showToast?.(message, isError);
}
